Here is an example of a C function that allocates memory for and initializes two arrays: one for 'long' offset values and one for 'int' keys, as well as an array of 'record' structures, where each record contains a single 'int' value. The function also includes functions to manage the lifecycle of these allocated resources by providing functions to safely allocate, initialize, update, and free the allocated memory.
```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Data structure for records
typedef struct {
    int value;
} record;

// Function to allocate memory for the arrays and initialize them with default values
void init_arrays(long** offset_array, int** key_array, record** record_array) {
    // Allocate memory for the offset array
    *offset_array = malloc(sizeof(long));
    if (*offset_array == NULL) {
        printf("Error: unable to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with default values
    *(*offset_array) = 0;

    // Allocate memory for the key array
    *key_array = malloc(sizeof(int));
    if (*key_array == NULL) {
        printf("Error: unable to allocate memory for key array\n");
        return;
    }

    // Initialize the key array with default values
    *(*key_array) = 0;

    // Allocate memory for the record array
    *record_array = malloc(sizeof(record));
    if (*record_array == NULL) {
        printf("Error: unable to allocate memory for record array\n");
        return;
    }

    // Initialize the record array with default values
    *(*record_array) = (record){0};
}

// Function to safely update the offset and key arrays
void update_arrays(long* offset_array, int* key_array, record* record_array) {
    // Update the offset array with new values
    *offset_array += 1;
    *key_array = (int)(*offset_array % 10);

    // Update the record array with new values
    (*record_array).value = *key_array;
}

// Function to safely free the allocated memory for the arrays and record array
void free_arrays(long** offset_array, int** key_array, record** record_array) {
    // Free the memory allocated for the offset array
    if (*offset_array != NULL) {
        free(*offset_array);
        *offset_array = NULL;
    }

    // Free the memory allocated for the key array
    if (*key_array != NULL) {
        free(*key_array);
        *key_array = NULL;
    }

    // Free the memory allocated for the record array
    if (*record_array != NULL) {
        free(*record_array);
        *record_array = NULL;
    }
}

// Main function to demonstrate the use of the functions
int main() {
    long* offset_array = NULL;
    int* key_array = NULL;
    record* record_array = NULL;

    // Initialize the arrays and the record array
    init_arrays(&offset_array, &key_array, &record_array);

    // Update the arrays with new values
    update_arrays(offset_array, key_array, record_array);

    // Free the allocated memory for the arrays and the record array
    free_arrays(&offset_array, &key_array, &record_array);

    return 0;
}
```
