public class PokemonWeaknesses {

    public static String getWeaknesses(Pokemon pokemon) {
        // Assume getType() and getName() are library functions
        String name = pokemon.getName();
        String type = pokemon.getType();

        StringBuilder weaknesses = new StringBuilder();

        switch (type) {
            case "Water":
                weaknesses.append("Electric, Grass");
                break;
            case "Fire":
                weaknesses.append("Water, Ground");
                break;
            case "Grass":
                weaknesses.append("Fire, Ice");
                break;
            default:
                // Handle unknown types
                return "Unknown Type";
        }

        return name + "'s Weaknesses: " + weaknesses.toString();
    }
}
