    // Check if the module is already loaded
    CryptoModule *module = find_module(modules, module_name);
    if (module != NULL) {
        // Module is already loaded, update its usage count and return
        module->usage_count++;
        pthread_mutex_unlock(&modules->lock);
        return;
    }

    // Load the module using dlopen
    void (*func)() = dlopen(module_name, RTLD_LAZY);
    if (func == NULL) {
        // Handle error
        pthread_mutex_unlock(&modules->lock);
        return;
    }

    // Create a new module structure and add it to the list of available modules
    CryptoModule *new_module = malloc(sizeof(CryptoModule));
    strcpy(new_module->name, module_name);
    new_module->func = func;
    new_module->usage_count = 1;

    // Add the new module to the list of available modules
    if (modules->head == NULL) {
        modules->head = new_module;
    } else {
        CryptoModule *current = modules->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_module;
    }

    // Unlock the list of available modules
    pthread_mutex_unlock(&modules->lock);
}

// Function to find a specific module in the list of available modules
CryptoModule *find_module(struct CryptoModuleList *modules, const char *module_name) {
    // Lock the list of available modules to prevent race conditions
    pthread_mutex_lock(&modules->lock);

    // Search for the module in the list
    CryptoModule *current = modules->head;
    while (current != NULL) {
        if (strcmp(current->name, module_name) == 0) {
            // Found the module, return it
            pthread_mutex_unlock(&modules->lock);
            return current;
        }
        current = current->next;
    }

    // Module not found, unlock the list and return NULL
    pthread_mutex_unlock(&modules->lock);
    return NULL;
}
