```
// LoggingSystem.cpp
#include "LoggingSystem.h"

namespace LoggingSystem {
    const std::string Logger::DEFAULT_LOGGER_NAME = "logging-system";
    const std::string Logger::DEFAULT_FILE_PATH = "";
    const boost::log::trivial::severity_level Logger::DEFAULT_LEVEL = boost::log::trivial::info;

    // Constructor and destructor
    Logger::Logger(const std::string& loggerName, const std::string& filePath, boost::log::trivial::severity_level level) :
        loggerName_(loggerName), filePath_(filePath), level_(level) {
        setup();
    }
    Logger::~Logger() {
        sink_.reset();
    }

    // Logging functions
    void Logger::logMessage(const std::string& message) {
        boost::log::trivial::severity_level level = getLogLevel();
        BOOST_LOG_SEV(sink_, level) << message;
    }
    void Logger::logError(const std::exception& e) {
        logMessage("An error occurred: " + e.what());
    }
    void Logger::setLogLevel(boost::log::trivial::severity_level level) {
        level_ = level;
    }
    boost::log::trivial::severity_level Logger::getLogLevel() {
        return level_;
    }

    // Setup function
    void Logger::setup() {
        if (filePath_.empty()) {
            filePath_ = DEFAULT_FILE_PATH;
        }
        backend_.open_file(filePath_);
        sink_ = boost::make_shared<boost::log::sinks::synchronous_sink<boost::log::sinks::text_file_backend>>();
        sink_->set_formatter([](const boost::log::record& record) {
            return boost::format("%1% %2% %3%")
                % record.get("logger")
                % record.get("time")
                % record.get("message");
        });
        sink_->locked_backend()->add_stream(boost::log::sinks::sync_frontend::stream_type(&backend_, boost::log::keywords::auto_flush));
    }
}
```
