['```csharp
public IDataReader ExecuteComplexQuery(List<FilterCriteria> criteria, IDbConnection connection, string baseQuery)
{
    if (criteria == null || criteria.Count == 0)
    {
        // No filter criteria specified, execute the base query as is
        return ExecuteQuery(baseQuery, connection);
    }

    var joinConditions = new List<string>();
    foreach (var criterion in criteria)
    {
        if (!criterion.JoinCondition.HasValue())
            continue;

        // Add the join condition to the list of conditions
        joinConditions.Add(criterion.JoinCondition);

        // Add the filter condition to the query
        baseQuery += criterion.FilterCondition + " AND ";
    }

    if (joinConditions.Count == 0)
    {
        // No join conditions specified, execute the base query as is
        return ExecuteQuery(baseQuery, connection);
    }

    // Optimize the generated SQL query for performance by removing any unnecessary AND keywords
    baseQuery = baseQuery.TrimEnd("AND ");

    // Create a parameterized query using the optimized query and join conditions
    var parameterizedQuery = new StringBuilder();
    parameterizedQuery.AppendLine(baseQuery);
    parameterizedQuery.AppendLine("JOIN");
    foreach (var joinCondition in joinConditions)
    {
        parameterizedQuery.AppendLine($"{joinCondition} ON ");
    }

    // Execute the parameterized query and return an IDataReader for the result set
    using var command = new SqlCommand(parameterizedQuery.ToString(), connection);
    return command.ExecuteReader();
}
```
