using System;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

class ConfigurationManager
{
    private const string ConfigEndpoint = "https://example.com/api/config";
    private static readonly HttpClient client = new HttpClient();
    private static readonly SemaphoreSlim semaphore = new SemaphoreSlim(1, 1);
    private static int numWorkers;
    private static int maxQueueSize;
    private static int timeoutDuration;

    public async Task<bool> LoadConfigurationAsync()
    {
        bool success = false;

        // Wait for the semaphore to become available before making a request.
        await semaphore.WaitAsync();

        try
        {
            HttpResponseMessage response = await client.GetAsync(ConfigEndpoint);

            if (response.IsSuccessStatusCode)
            {
                // Read the JSON response and validate the configuration settings.
                string json = await response.Content.ReadAsStringAsync();
                dynamic config = JsonConvert.DeserializeObject(json);

                if (!ValidateConfigurationSettings(config))
                {
                    throw new Exception("Invalid configuration settings.");
                }

                // Apply the configuration settings to the thread pool.
                numWorkers = (int)config.numWorkers;
                maxQueueSize = (int)config.maxQueueSize;
                timeoutDuration = (int)config.timeoutDuration;

                success = true;
            }
        }
        catch (Exception e)
        {
            Console.WriteLine($"Failed to load configuration: {e.Message}");
        }
        finally
        {
            // Release the semaphore, even if an exception is thrown.
            semaphore.Release();
        }

        return success;
    }

    private bool ValidateConfigurationSettings(dynamic config)
    {
        // Validate that the configuration settings are within acceptable ranges.
        return (config.numWorkers >= 1 && config.numWorkers <= 100) &&
               (config.maxQueueSize >= 1 && config.maxQueueSize <= 50) &&
               (config.timeoutDuration >= 1 && config.timeoutDuration <= 30);
    }
}
```
This code uses the `HttpClient` class to make a GET request to the remote JSON API endpoint and deserialize the response using the `JsonConvert` class from Newtonsoft.Json. It then validates the configuration settings using a custom validation method before applying them to the thread pool.

The `LoadConfigurationAsync` method uses a semaphore to ensure that only one request is made at a time, as multiple requests could be made simultaneously if the configuration was being updated frequently. The method also handles potential network failures, invalid JSON responses, and server timeouts gracefully by catching any exceptions thrown during the request or deserialization process and providing meaningful error messages to the user.

To handle high-frequency updates to configuration settings efficiently, the code uses a semaphore to limit the number of requests made simultaneously. This ensures that the thread pool is not overwhelmed by frequent updates to the configuration settings.']

