<?php

function manageUserAccounts($_REQUEST) {
    // Rate limiting (10 requests per minute per IP address)
    $ip = $_SERVER['REMOTE_ADDR'];
    if (isset($_SESSION['rateLimit'][$ip]) && count($_SESSION['rateLimit'][$ip]) >= 10) {
        return json_encode(['message' => 'error', 'data' => ['Rate limit exceeded.']]);
    } else {
        $_SESSION['rateLimit'][$ip][] = time();
    }

    // Validate inputs
    $id = isset($_REQUEST['id']) ? $_REQUEST['id'] : null;
    $name = isset($_REQUEST['name']) ? $_REQUEST['name'] : null;
    $email = isset($_REQUEST['email']) ? $_REQUEST['email'] : null;
    $password = isset($_REQUEST['password']) ? $_REQUEST['password'] : null;
    $sub_action = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : null;

    if (!isValidInput($name, $email, $password)) {
        return json_encode(['message' => 'error', 'data' => ['Invalid inputs.']]);
    }

    // Handle request
    if ($id) {
        if ($sub_action == 'delete') {
            deleteUserAccount($id);
        } else {
            updateUserAccount($id, $name, $email, $password);
        }
    } else {
        createUserAccount($name, $email, $password);
    }

    // Return response
    return json_encode(['message' => 'success', 'data' => ['User account updated.']]);
}

function isValidInput($name, $email, $password) {
    // Validate name
    if (!isValidName($name)) {
        return false;
    }

    // Validate email
    if (!isValidEmail($email)) {
        return false;
    }

    // Validate password
    if (!isValidPassword($password)) {
        return false;
    }

    return true;
}

function isValidName($name) {
    // Check length
    if (strlen($name) < 2 || strlen($name) > 50) {
        return false;
    }

    // Check for invalid characters
    if (!preg_match('/^[a-zA-Z ]+$/', $name)) {
        return false;
    }

    return true;
}

function isValidEmail($email) {
    // Check format
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return false;
    }

    return true;
}

function isValidPassword($password) {
    // Check length
    if (strlen($password) < 8) {
        return false;
    }

    // Check for uppercase letter
    if (!preg_match('/[A-Z]/', $password)) {
        return false;
    }

    // Check for lowercase letter
    if (!preg_match('/[a-z]/', $password)) {
        return false;
    }

    // Check for digit
    if (!preg_match('/\d/', $password)) {
        return false;
    }

    // Check for special character
    if (!preg_match('/[^\w\s]/', $password)) {
        return false;
    }

    return true;
}

function deleteUserAccount($id) {
    try {
        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

        // Prepare query
        $stmt = $db->prepare("DELETE FROM users WHERE id = :id");

        // Bind parameters
        $stmt->bindParam(':id', $id, PDO::PARAM_INT);

        // Execute query
        $stmt->execute();
    } catch (PDOException $e) {
        return json_encode(['message' => 'error', 'data' => ['Failed to delete user account.']]);
    }
}

function updateUserAccount($id, $name, $email, $password) {
    try {
        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

        // Prepare query
        $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");

        // Bind parameters
        $stmt->bindParam(':id', $id, PDO::PARAM_INT);
        $stmt->bindParam(':name', $name);
        $stmt->bindParam(':email', $email);
        $stmt->bindParam(':password', $password);

        // Execute query
        $stmt->execute();
    } catch (PDOException $e) {
        return json_encode(['message' => 'error', 'data' => ['Failed to update user account.']]);
    }
}

function createUserAccount($name, $email, $password) {
    try {
        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

        // Prepare query
        $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");

        // Bind parameters
        $stmt->bindParam(':name', $name);
        $stmt->bindParam(':email', $email);
        $stmt->bindParam(':password', $password);

        // Execute query
        $stmt->execute();
    } catch (PDOException $e) {
        return json_encode(['message' => 'error', 'data' => ['Failed to create user account.']]);
    }
}
