    [ApiController]
    [Route("api/[controller]")]
    public class ElementController : ControllerBase
    {
        private readonly ILogger<ElementController> _logger;
        private readonly IElementService _elementService;

        public ElementController(ILogger<ElementController> logger, IElementService elementService)
        {
            _logger = logger;
            _elementService = elementService;
        }

        [HttpPost]
        [Route("update-element")]
        public async Task<ActionResult> UpdateElementAsync(int pageSectionId, int elementId, string content)
        {
            // Rate limiting to prevent abuse
            var rateLimit = _elementService.GetRateLimit();
            if (rateLimit.HasValue && rateLimit.Value < DateTime.UtcNow)
            {
                return BadRequest("You have reached the maximum number of updates per minute.");
            }

            // Update element HTML content using service class
            var updatedElement = await _elementService.UpdateElementAsync(pageSectionId, elementId, content);
            if (updatedElement == null)
            {
                return BadRequest("Failed to update element.");
            }

            // Log all updates for auditing purposes
            _logger.LogInformation($"Updated element {updatedElement.Id} in page section {pageSectionId} with content: {content}");

            // Return response indicating that the page should be refreshed
            return Ok("Page refresh required.");
        }
    }
}
```

