function getLanguages(text) {
  // Define regular expressions for identifying programming languages
  const languageRegexes = [
    /JavaScript/,
    /Python/,
    /Java/,
    /C\+\+/,
    /PHP/,
    /Ruby/,
    /Go/,
    /Swift/
  ];

  // Initialize an empty object to store language names and counts
  const languages = {};

  // Loop through the text, searching for matches using the regular expressions
  for (const regex of languageRegexes) {
    let match;
    while ((match = regex.exec(text)) !== null) {
      // Ignore any punctuation or special characters in the match
      const language = match[0].replace(/[^A-Za-z ]/g, "");

      // Filter out languages that are not commonly used in web development
      if (isCommonWebDevLanguage(language)) {
        // Increment the count for the matched language name
        languages[language] = languages[language] ? languages[language] + 1 : 1;
      }
    }
  }

  return languages;
}

// Helper function to check if a language is commonly used in web development
function isCommonWebDevLanguage(language) {
  // Use an external API to fetch lists of commonly used web development languages dynamically
  const commonLanguages = [
    "JavaScript",
    "Python",
    "Java",
    "PHP",
    "Ruby",
    "Go",
    "Swift"
  ];

  return commonLanguages.includes(language);
}
