public class FileUniqueChecker {
    public static int getUniqueFiles(List<String> filePaths) {
        long startTime = System.currentTimeMillis();

        HashSet<String> uniqueFiles = new HashSet<>();
        for (String filePath : filePaths) {
            if (!uniqueFiles.contains(filePath)) {
                uniqueFiles.add(filePath);
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Number of unique files: " + uniqueFiles.size());
        System.out.println("Time taken to check for uniqueness: " + (endTime - startTime) + " milliseconds");

        return uniqueFiles.size();
    }
}
