```java
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Logger;

public class ServiceManager {
    private static final Logger LOGGER = Logger.getLogger(ServiceManager.class.getName());

    // Configuration parameters
    private final String serviceCommand;
    private final long startInterval;
    private final long stopInterval;
    private final int monitoringFrequency;

    public ServiceManager(String serviceCommand, long startInterval, long stopInterval, int monitoringFrequency) {
        this.serviceCommand = serviceCommand;
        this.startInterval = startInterval;
        this.stopInterval = stopInterval;
        this.monitoringFrequency = monitoringFrequency;
    }

    public void run() throws InterruptedException {
        // Initialize messaging system and monitoring system
        MessageQueue messageQueue = new MessageQueue();
        MonitoringSystem monitoringSystem = new MonitoringSystem(messageQueue);

        // Start service with random start interval
        long initialDelay = ThreadLocalRandom.current().nextLong(startInterval);
        LOGGER.info("Starting service with initial delay of " + initialDelay + " ms.");
        ProcessBuilder processBuilder = new ProcessBuilder();
        processBuilder.command(serviceCommand);
        Process process = processBuilder.start();
        Thread.sleep(initialDelay);

        // Monitor service health and handle interruptions gracefully
        while (true) {
            try {
                if (!process.isAlive()) {
                    LOGGER.info("Service has terminated unexpectedly. Restarting...");
                    process = processBuilder.start();
                }

                // Send message to messaging system and log details about start event
                String message = "Started service with PID: " + process.pid();
                messageQueue.sendMessage(message);
                LOGGER.info("Sent message to messaging system: " + message);

                // Monitor service health periodically
                if (monitoringSystem.isServiceHealthy()) {
                    LOGGER.info("Service is healthy.");
                } else {
                    LOGGER.severe("Service has encountered an error. Shutting down...");
                    break;
                }

                // Stop service with random stop interval
                long delay = ThreadLocalRandom.current().nextLong(stopInterval);
                LOGGER.info("Stopping service with delay of " + delay + " ms.");
                process.destroy();
                Thread.sleep(delay);
            } catch (InterruptedException e) {
                // Handle interruption gracefully
                LOGGER.warning("Service management operation interrupted. Shutting down...");
                break;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ServiceManager serviceManager = new ServiceManager(args[0], Long.parseLong(args[1]), Long.parseLong(args[2]), Integer.parseInt(args[3]));
        serviceManager.run();
    }
}
```
The program takes the following configuration parameters:

* `serviceCommand`: the command to start and stop the external service
* `startInterval`: the random interval between starting the service and monitoring its health
* `stopInterval`: the random interval between stopping the service and restarting it if necessary
* `monitoringFrequency`: the frequency at which the service's health should be monitored

