    $config['external_api_key'] = 'your_api_key';
}

// Use dependency injection to decouple the configuration loading logic from other parts of the application
$container = new \DI\Container();
$container->set('config', $config);
$container->set('cache', $cache);
$container->set('logger', $logger);

// Support multilingual content by loading language-specific configuration files based on user preferences or browser settings
