    if (isset($argv) && isset($argv[1]) && in_array($argv[1], ['--language', '-l'])) {
        if (!is_string($argv[2]) || !file_exists(__DIR__ . '/../config/' . $env_vars['APP_ENV'] . '_' . $argv[2] . '.php')) {
            throw new \Exception('Invalid language code: ' . $argv[2]);
