                $config = require __DIR__ . '/../config/' . $env_vars['APP_ENV'] . '_' . $lang . '.php';
            }
        } elseif (isset($_SERVER['HTTP_ACCEPT_LANGUAGE']) && !empty($_SERVER['HTTP_ACCEPT_LANGUAGE'])) {
            $languages = explode(',', $_SERVER['HTTP_ACCEPT_LANGUAGE']);
            foreach ($languages as $language) {
                if (file_exists(__DIR__ . '/../config/' . $env_vars['APP_ENV'] . '_' . substr($language, 0, 2) . '.php')) {
                    $config = require __DIR__ . '/../config/' . $env_vars['APP_ENV'] . '_' . substr($language, 0, 2) . '.php';
                }
            }
        }
    }
}

// Implement a rate limiting mechanism to prevent abuse of the external API
$rateLimit = new \Symfony\Component\RateLimiter\TokenBucketLimiter();
$rateLimit->setLimit(10);
$rateLimit->setInterval('PT1M');
$rateLimit->addHandler('my_logger', $logger);

// Handle the requests and responses in parallel, utilizing the rate limiting mechanism
$responses = [];
foreach ($processes as $process) {
    $responses[] = $process->start();
}
foreach ($responses as $response) {
    $response->wait();
}
?>
