function updateUserStatus($userID, $status, $ipAddress) {
    // Check if user exists in database
    $userExists = false;
    try {
        $stmt = $conn->prepare("SELECT 1 FROM users WHERE id = ?");
        $stmt->bind_param('i', $userID);
        $stmt->execute();
        $result = $stmt->get_result();
        if ($result->num_rows > 0) {
            $userExists = true;
        }
    } catch (Exception $e) {
        // Handle exception
    } finally {
        $stmt->close();
    }

    // Update user status and last modified IP address
    if ($userExists) {
        try {
            $stmt = $conn->prepare("UPDATE users SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
            $stmt->bind_param('iss', $status, $ipAddress, $userID);
            $stmt->execute();
            return "Successfully updated user status";
        } catch (Exception $e) {
            // Handle exception
        } finally {
            $stmt->close();
        }
    } else {
        return "User does not exist";
    }
}
```
