using namespace std;

// Struct for representing an octree node
struct OctreeNode {
    // Vector to store the data for this node
    vector<int> data;
    // Pointers to child nodes
    OctreeNode* children[8];
};

// Function to initialize an octree with a given feature size, number of leaf nodes, and data capacity
bool initializeOctree(int featureSize, int numLeafNodes, int dataCapacity) {
    // Check for invalid input parameters
    if (featureSize < 1 || numLeafNodes < 1 || dataCapacity < 0) {
        return false;
    }

    // Calculate the number of levels in the octree
    int numLevels = log2(numLeafNodes) + 1;

    // Allocate memory for the octree nodes and leaf nodes
    OctreeNode* root = new OctreeNode();
    root->data.resize(featureSize * featureSize);
    root->children[0] = new OctreeNode();
    root->children[1] = new OctreeNode();
    root->children[2] = new OctreeNode();
    root->children[3] = new OctreeNode();
    root->children[4] = new OctreeNode();
    root->children[5] = new OctreeNode();
    root->children[6] = new OctreeNode();
    root->children[7] = new OctreeNode();

    // Initialize the data capacity of the octree
    int currentCapacity = 0;

    // Loop through each level of the octree, allocating memory for nodes and leaf nodes
    for (int i = 0; i < numLevels; i++) {
        // Allocate memory for the nodes in this level
        for (int j = 0; j < 8; j++) {
            root->children[j] = new OctreeNode();
            root->children[j]->data.resize(featureSize * featureSize);
        }

        // Increase the data capacity of the octree
        currentCapacity += (featureSize * featureSize) * 8;

        // Check if the current capacity is greater than the desired capacity
        if (currentCapacity > dataCapacity) {
            // Reallocate memory for the data array to reduce wasted space
            root->data.resize(dataCapacity);

            // Update the data capacity of the octree
