// Define a structure to represent the configuration file
typedef struct {
    char *path; // path of the configuration file
    int num_sections; // number of sections in the configuration file
    Section **sections; // array of section pointers
} Configuration;

// Define a structure to represent each section of the configuration file
typedef struct {
    char *name; // name of the section
    int num_keys; // number of keys in the section
    KeyValuePair **key_values; // array of key-value pairs
} Section;

// Define a structure to represent each key-value pair in a section
typedef struct {
    char *key; // key of the key-value pair
    char *value; // value of the key-value pair
} KeyValuePair;

int load_configuration(const char *path, Configuration **config) {
    // Check if the path is valid and accessible
    if (!path || !access(path, R_OK)) {
        return -1;
    }

    // Open the configuration file for reading
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("fopen");
        return -2;
    }

    // Initialize a pointer to hold the configuration structure
    Configuration *config_ptr = NULL;

    // Parse the configuration file and allocate memory for the sections
    Section **sections = NULL;
    int num_sections = 0;
    while (1) {
        char line[256];
        if (!fgets(line, sizeof(line), file)) {
            break;
        }

        // Skip comments and empty lines
        if (line[0] == '#' || strlen(line) <= 1) {
            continue;
        }

        // Parse the section name and allocate memory for it
        char *section_name = strtok(line, "=");
        Section *section = malloc(sizeof(Section));
        if (!section) {
            perror("malloc");
            return -3;
        }

        // Set the name of the section and allocate memory for the key-value pairs
        section->name = strdup(section_name);
        section->num_keys = 0;
        section->key_values = NULL;

        // Parse the key-value pairs and allocate memory for them
        while (1) {
            char *key = strtok(NULL, "=");
            if (!key) {
                break;
            }

            char *value = strtok(NULL, "\n");
            if (!value) {
                break;
            }

            // Allocate memory for the key-value pair and add it to the section
            KeyValuePair *key_value = malloc(sizeof(KeyValuePair));
            if (!key_value) {
                perror("malloc");
                return -4;
            }

            key_value->key = strdup(key);
            key_value->value = strdup(value);
            section->num_keys++;
            section->key_values = realloc(section->key_values, sizeof(KeyValuePair) * section->num_keys);
            if (!section->key_values) {
                perror("realloc");
                return -5;
            }

            section->key_values[section->num_keys - 1] = key_value;
        }

        // Add the section to the list of sections
        num_sections++;
        sections = realloc(sections, sizeof(Section) * num_sections);
        if (!sections) {
            perror("realloc");
            return -6;
        }

        sections[num_sections - 1] = section;
    }

    // Close the configuration file and allocate memory for the configuration structure
    fclose(file);
    config_ptr = malloc(sizeof(Configuration));
    if (!config_ptr) {
        perror("malloc");
        return -7;
    }

    // Set the path of the configuration file, the number of sections, and the array of section pointers
    config_ptr->path = strdup(path);
    config_ptr->num_sections = num_sections;
    config_ptr->sections = sections;

    *config = config_ptr;

    return 0;
}
```
This code uses the `access` function to check if the configuration file exists and is accessible. If it doesn't exist or cannot be accessed, it returns an error code.

The code then opens the configuration file for reading using the `fopen` function. It checks if the file was successfully opened, and if not, prints an error message and returns an error code.

The code then initializes a pointer to hold the configuration structure and parses the configuration file line by line. For each section, it allocates memory for the name of the section and the key-value pairs using `malloc`. If memory cannot be allocated, it prints an error message and returns an error code.

The code then adds each section to the list of sections using `realloc` and sets the number of keys in the section to zero. It also sets the name of the section and allocates memory for the key-value pairs. If memory cannot be allocated, it prints an error message and returns an error code.

After parsing all the lines in the file, the code closes the configuration file using `fclose` and allocate memory for the configuration structure using `malloc`. It then sets the path of the configuration file, the number of sections, and the array of section pointers to the appropriate values.

Finally, it returns an error code if any errors occurred during parsing or allocation, and 0 if no errors occurred.']

