char* append_slash(const char* input, size_t limit) {
    if (strlen(input) > limit) {
        return NULL;
    }

    // Allocate memory for the output string
    char* output = malloc(limit + 1);
    if (!output) {
        return NULL;
    }

    // Copy the input string to the output string
    strcpy(output, input);

    // Append a slash to the end of the output string
    output[strlen(input)] = '/';
    output[strlen(input) + 1] = '\0';

    return output;
}
