    long http_code;

    // Initialize curl session
    curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Failed to initialize curl session\n");
        return NULL;
    }

    // Set URL and other options for the request
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows; U; Windows NT 6.1; rv:2.2) Gecko/20110201");
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 3);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 3);
    curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);

    // Perform the request and get the response
    res = curl_easy_perform(curl);
    if(res != CURLE_OK) {
        fprintf(stderr, "Failed to perform curl request: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Get the HTTP response code and check for success
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if((http_code < 200) || (http_code >= 300)) {
        fprintf(stderr, "Request failed with HTTP status code: %ld\n", http_code);
        return NULL;
    }

    // Clean up and return the response body
    curl_easy_cleanup(curl);
    return error;
}

