    int i;
    double average;
    char* theme_name = NULL;
    char* theme_path = NULL;
    FILE* cache_file = NULL;

    // Fetch the web page for the given URL
    void* response = fetch_page(url);
    if(!response) {
        fprintf(stderr, "Failed to fetch web page for %s\n", url);
        return NULL;
    }

    // Extract the average from the HTML content
    const char* html_content = (const char*)response;
    char* endptr;
    double num1 = strtod(html_content, &endptr);
    if(*endptr == '\0') {
        fprintf(stderr, "Failed to extract number from HTML content\n");
        return NULL;
    }
    html_content = endptr;
    double num2 = strtod(html_content, &endptr);
    if(*endptr != '\0') {
        fprintf(stderr, "Failed to extract second number from HTML content\n");
        return NULL;
    }
    average = (num1 + num2) / 2.0;

    // Check if the theme name is already in the cache
    theme_name = get_theme_name(url);
    if(!theme_name) {
        fprintf(stderr, "Failed to extract theme name from URL\n");
        return NULL;
    }
    theme_path = get_theme_path(theme_name);
    if(!theme_path) {
        fprintf(stderr, "Failed to generate theme path for %s\n", theme_name);
        return NULL;
    }

    // Open the cache file and write the results
    cache_file = fopen(cache_path, "a");
    if(!cache_file) {
        fprintf(stderr, "Failed to open cache file for %s\n", url);
        return NULL;
    }
    fprintf(cache_file, "%s\t%s\t%f\n", url, theme_name, average);
    fclose(cache_file);

    // Clean up and return
    free(response);
    return NULL;
}

// Function to process a list of URLs in parallel using threads
void* process_urls(char** urls) {
    int i;
    pthread_t thread[theme_cache_size];
    void* status = NULL;

    // Initialize semaphore and mutex for thread synchronization
    sem_init(&semaphore, 0, theme_cache_size);
    pthread_mutex_init(&lock, NULL);

    // Create a thread for each URL in the list
    for(i = 0; i < theme_cache_size; i++) {
        char* url = urls[i];
        if(!url) {
            break;
        }
        pthread_create(&thread[i], NULL, process_url, (void*)url);
    }

    // Wait for all threads to complete
    for(i = 0; i < theme_cache_size; i++) {
        if(!thread[i]) {
            break;
        }
        pthread_join(thread[i], &status);
    }

    // Clean up semaphore and mutex
    sem_destroy(&semaphore);
    pthread_mutex_destroy(&lock);

    // Return the status of all threads
    return (void*)status;
}

