using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public struct TiffInfo {
    public int BitsPerSample;
    public int SamplesPerPixel;
    public int ExtraSamplesCount;
    public string[] ExtraSamples;
}

public static class TiffParser {
    private const int MaxBitsPerSample = 16; // maximum bits per sample supported by the function
    private const int MinBitsPerSample = 1; // minimum bits per sample supported by the function

    public static TiffInfo ParseTiff(string filePath) {
        if (!File.Exists(filePath)) {
            throw new FileNotFoundException("Input file path is not accessible or readable.", filePath);
        }

        using (var stream = File.OpenRead(filePath)) {
            var tiffReader = new TiffReader(stream);
            int bitsPerSample = tiffReader.GetBitsPerSample();
            if (bitsPerSample < MinBitsPerSample || bitsPerSample > MaxBitsPerSample) {
                throw new ArgumentException($"Invalid number of bits per sample: {bitsPerSample}. Must be between {MinBitsPerSample} and {MaxBitsPerSample}.");
            }

            int samplesPerPixel = tiffReader.GetSamplesPerPixel();
            int extraSamplesCount = 0;
            string[] extraSamples = null;

            if (samplesPerPixel > 1) {
                extraSamplesCount = samplesPerPixel - 1;
                extraSamples = new string[extraSamplesCount];
                for (int i = 0; i < extraSamplesCount; i++) {
                    extraSamples[i] = tiffReader.GetExtraSample(i);
                }
            }

            return new TiffInfo {
                BitsPerSample = bitsPerSample,
                SamplesPerPixel = samplesPerPixel,
                ExtraSamplesCount = extraSamplesCount,
                ExtraSamples = extraSamples
            };
        }
    }
}

public class TiffReader : IDisposable {
    private readonly BinaryReader _reader;
    private int _bitsPerSample;
    private int _samplesPerPixel;

    public TiffReader(Stream stream) {
        _reader = new BinaryReader(stream, Encoding.UTF8);
    }

    public void Dispose() {
        _reader.Dispose();
    }

    public int GetBitsPerSample() {
        // Read the TIFF header and extract the number of bits per sample
        _reader.ReadUInt16(); // Skip the first two bytes (Byte Order Mark)
        _reader.ReadUInt16(); // Skip the second two bytes (TIFF magic number)
        _reader.ReadUInt32(); // Skip the third four bytes (offset to the image data directory)
        _bitsPerSample = _reader.ReadUInt16(); // Read the number of bits per sample
        return _bitsPerSample;
    }

    public int GetSamplesPerPixel() {
        _samplesPerPixel = _reader.ReadUInt16(); // Read the number of samples per pixel
        return _samplesPerPixel;
    }

    public string GetExtraSample(int index) {
        var extraSampleBytes = new byte[_samplesPerPixel - 1];
        for (int i = 0; i < extraSampleBytes.Length; i++) {
            extraSampleBytes[i] = _reader.ReadByte(); // Read the extra samples
        }
        return Encoding.UTF8.GetString(extraSampleBytes);
    }
}
```
