#include <string.h>

// Define the hash function to use for key derivation
#define HASH_FUNCTION SHA256

// Define the fixed IV length and key length to use
#define IV_LENGTH 16
#define KEY_LENGTH 32

// Structure to hold the cipher context and theme cache
struct ThemeCache {
    AES_KEY* aes;
    unsigned char iv[IV_LENGTH];
    unsigned char key[KEY_LENGTH];
    bool recycled;
};

// Function to initialize the cipher context and set up the theme cache
void initThemeCache(struct ThemeCache* themeCache, const char* password) {
    // Generate a key from the given password using the specified hash function
    unsigned char* key = SHA256((const unsigned char*)password, strlen(password), NULL);

    // Set the IV length and key length to fixed values
    AES_set_iv(&themeCache->aes, IV_LENGTH, themeCache->iv);
    AES_set_key(&themeCache->aes, KEY_LENGTH, themeCache->key);

    // Recycle the theme cache if necessary
    if (themeCache->recycled) {
        AES_encrypt(NULL, NULL, &themeCache->aes);
        memset(themeCache->iv, 0, IV_LENGTH);
        memset(themeCache->key, 0, KEY_LENGTH);
        themeCache->recycled = false;
    }

    // Set the default theme directory if not already set
    if (!themeCache->aes) {
        themeCache->aes = AES_encrypt(NULL, NULL, &themeCache->aes);
        themeCache->recycled = true;
    }
}

// Function to clean up and disable the cipher context and clear the theme cache
void cleanupThemeCache(struct ThemeCache* themeCache) {
    // Clear the theme cache if it is not already recycled
    if (!themeCache->recycled) {
        memset(themeCache->iv, 0, IV_LENGTH);
        memset(themeCache->key, 0, KEY_LENGTH);
        AES_encrypt(NULL, NULL, &themeCache->aes);
    }

    // Disable the cipher context
    AES_decrypt(NULL, NULL, &themeCache->aes);
}

// Function to parse a PNG file from the cache root directory and put it in the theme cache
void parsePngFileFromCacheRootDirectory(struct ThemeCache* themeCache, const char* pngFileName) {
    // Open the PNG file for reading
    FILE* pngFile = fopen(pngFileName, "rb");

    // Check if the file could be opened successfully
    if (!pngFile) {
        printf("Error: Could not open PNG file %s\n", pngFileName);
        return;
    }

    // Read the PNG file and put it in the theme cache
    unsigned char* data = malloc(sizeof(unsigned char) * 1024);
    size_t readSize = fread(data, sizeof(unsigned char), 1024, pngFile);
    while (readSize > 0) {
        AES_encrypt(NULL, NULL, &themeCache->aes);
        memcpy(themeCache->iv, data, readSize);
        free(data);
    }

    // Close the PNG file
    fclose(pngFile);
}
