using namespace std;

class PDFObject {
    private:
        string filename;
        vector<char> data;

    public:
        PDFObject(string filename) {
            this->filename = filename;
            data.clear();
        }

        void readFile() {
            ifstream file(filename, ios::binary);

            // Check if file exists
            if (!file.is_open()) {
                cout << "Error: Unable to open PDF file" << endl;
                return;
            }

            // Read file into vector of chars
            while (true) {
                char c = file.get();

                // Check if end of file reached
                if (file.eof()) {
                    break;
                }

                data.push_back(c);
            }

            // Close file
            file.close();
        }

        void convertToPDF() {
            // Convert JPEG to PDF using third-party tool
            string command = "convert -density 300x300 " + filename + " " + filename + ".pdf";

            // Execute command and check for errors
            if (system(command.c_str()) != 0) {
                cout << "Error: Unable to convert JPEG file to PDF" << endl;
                return;
            }
        }

        void deserialize() {
            // Deserialize PDF file into object of specific class
            ifstream file(filename + ".pdf", ios::binary);

            // Check if file exists
            if (!file.is_open()) {
                cout << "Error: Unable to open PDF file" << endl;
                return;
            }

            // Read file into vector of chars
            while (true) {
                char c = file.get();

                // Check if end of file reached
                if (file.eof()) {
                    break;
                }

                data.push_back(c);
            }

            // Close file
            file.close();
        }

        void logError() {
            // Log any errors or warnings during the conversion and deserialization processes for easier debugging and monitoring
            cout << "Error: Unable to convert JPEG file to PDF" << endl;
            return;
        }
};

int main(int argc, char** argv) {
    // Check if input and output files are provided as arguments
    if (argc < 3) {
        cout << "Usage: convert_jpeg_to_pdf <input file> <output file>" << endl;
        return -1;
    }

    string inputFile = argv[1];
    string outputFile = argv[2];

    // Create object of PDFObject class and initialize with input file name
    PDFObject pdfObj(inputFile);

    // Convert JPEG to PDF using third-party tool
    pdfObj.convertToPDF();

    // Read resulting PDF file into vector of chars
    pdfObj.readFile();

    // Deserialize PDF file into object of specific class
    pdfObj.deserialize();

    // Check if any errors occurred during the conversion and deserialization processes
    if (pdfObj.data.empty()) {
        cout << "Error: Unable to convert JPEG file to PDF" << endl;
        return -1;
    }

    // Log any errors or warnings during the conversion and deserialization processes for easier debugging and monitoring
    pdfObj.logError();

    // Save object of specific class into output file
    ofstream outFile(outputFile, ios::binary);

    // Check if output file is successfully created
    if (!outFile.is_open()) {
        cout << "Error: Unable to create output PDF file" << endl;
        return -1;
    }

    for (char c : pdfObj.data) {
        outFile.put(c);
    }

    // Close output file
    outFile.close();

    return 0;
