#include <json-c/json.h>

bool validate_access_token(const char* json) {
    json_object* obj = json_tokener_parse(json);
    if (!obj) {
        // JSON parsing failed, access token is invalid
        return false;
    }

    const char* access_token = json_object_get_string(obj, "access_token");
    if (!access_token) {
        // access_token field missing, access token is invalid
        json_object_put(obj);
        return false;
    }

    const char* token_type = json_object_get_string(obj, "token_type");
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        // token_type field missing or invalid, access token is invalid
        json_object_put(obj);
        return false;
    }

    const char* expires_in = json_object_get_string(obj, "expires_in");
    if (!expires_in) {
        // expires_in field missing, access token is invalid
        json_object_put(obj);
        return false;
    }

    int expires_in_int = atoi(expires_in);
    if (expires_in_int <= 0) {
        // expires_in field is not a positive integer, access token is invalid
        json_object_put(obj);
        return false;
    }

    const char* refresh_token = json_object_get_string(obj, "refresh_token");
    if (refresh_token) {
        // refresh_token field present, access token is valid
        json_object_put(obj);
        return true;
    }

    // Validate access_token format and length
    size_t len = strlen(access_token);
    if (len < 32 || len > 64) {
        // access_token has invalid length, access token is invalid
        json_object_put(obj);
        return false;
    }

    for (size_t i = 0; i < len; i++) {
        if (!isalnum(access_token[i]) && access_token[i] != '_') {
            // access_token has invalid characters, access token is invalid
            json_object_put(obj);
            return false;
        }
    }

    // Validate expires_in value range
    if (expires_in_int < 3600 || expires_in_int > 86400) {
        // expires_in value is out of range, access token is invalid
        json_object_put(obj);
        return false;
    }

    // Access token is valid
    json_object_put(obj);
    return true;
}
```
