using System;
using System.Data;
using System.Data.SqlClient;

namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly int _minimum;
        private readonly int _maximum;

        public RandomValueGenerator(int minimum, int maximum)
        {
            if (minimum > maximum)
                throw new ArgumentException("The minimum value must be less than or equal to the maximum value");

            _minimum = minimum;
            _maximum = maximum;
        }

        public float GenerateRandomFloat()
        {
            return (float)(_minimum + (_maximum - _minimum) * new Random().NextDouble());
        }

        public int GenerateRandomInt()
        {
            return new Random().Next(_minimum, _maximum);
        }

        public override string ToString()
        {
            return $"RandomValueGenerator: Min={_minimum}, Max={_maximum}";
        }

        public int GenerateRandomIntWithBias(double bias)
        {
            if (bias < 0 || bias > 1)
                throw new ArgumentException("The bias factor must be between 0 and 1");

            return (int)(_minimum + (_maximum - _minimum) * bias);
        }

        public int GenerateRandomIntWithPerformanceOptimization()
        {
            int randomValue = new Random().Next(_minimum, _maximum);

            // Use a cache to reduce the number of calls to GenerateRandomInt
            var cache = new Dictionary<int, bool>();

            while (true)
            {
                if (!cache.ContainsKey(randomValue))
                {
                    cache[randomValue] = true;
                    return randomValue;
                }

                // If the value is already in the cache, generate a new one and try again
                randomValue = new Random().Next(_minimum, _maximum);
            }
        }
    }
}
```
