    HttpClient client = new HttpClient();
    try {
        HttpResponseMessage response = await client.GetAsync("https://example.com/config");
        response.EnsureSuccessStatusCode();
        string jsonString = await response.Content.ReadAsStringAsync();
        dynamic configJson = JsonConvert.DeserializeObject(jsonString);
        List<string> knownHashes = configJson["hashes"];

        // Check if the generated hash is in the list of known hashes
        return knownHashes.Contains(hash);
    } catch (Exception ex) {
        Console.WriteLine($"Error verifying hash: {ex.Message}");
        return false;
    } finally {
        client.Dispose();
    }
}
