using System;
using System.Security.Cryptography;
using System.Text;

namespace AES_CBC_HMAC_SHA256
{
    public static class AesCbcHmacSha256Decryptor
    {
        private const int HMAC_KEY_LENGTH = 32; // bytes
        private const int IV_LENGTH = 16; // bytes
        private const int DEFAULT_THREAD_POOL_SIZE = 4; // number of threads to use for concurrent decryption and HMAC verification

        public static byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] hmacKey)
        {
            if (ciphertext == null || encryptionKey == null || hmacKey == null)
                throw new ArgumentNullException("Invalid input parameters");

            // validate ciphertext length and IV size
            if (ciphertext.Length < IV_LENGTH || ciphertext[IV_LENGTH] != 0x01)
                throw new Exception("Ciphertext is invalid or corrupted");

            // extract IV from ciphertext
            byte[] iv = new byte[IV_LENGTH];
            Array.Copy(ciphertext, 0, iv, 0, IV_LENGTH);

            // decrypt ciphertext using AES-CBC with provided key and IV
            using (AesCryptoServiceProvider aes = new AesCryptoServiceProvider())
            {
                aes.KeySize = encryptionKey.Length * 8;
                aes.BlockSize = 128;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.Zeros;

                using (MemoryStream ciphertextStream = new MemoryStream(ciphertext))
                {
                    using (ICryptoTransform decryptor = aes.CreateDecryptor(encryptionKey, iv))
                    {
                        using (CryptoStream cryptoStream = new CryptoStream(ciphertextStream, decryptor, CryptoStreamMode.Read))
                        {
                            return ReadFully(cryptoStream);
                        }
                    }
                }
            }
        }

        private static byte[] ReadFully(Stream input)
        {
            using (MemoryStream ms = new MemoryStream())
            {
                byte[] buffer = new byte[DEFAULT_THREAD_POOL_SIZE];
                int read;
                while ((read = input.Read(buffer, 0, buffer.Length)) > 0)
                {
                    ms.Write(buffer, 0, read);
                }
                return ms.ToArray();
            }
        }

        public static bool VerifyHmac(byte[] data, byte[] hmac)
        {
            using (HMACSHA256 hmacSha256 = new HMACSHA256())
            {
                hmacSha256.Key = hmacKey;
                return hmacSha256.ComputeHash(data) == hmac;
            }
        }
    }
}
```
This code defines a static class `AesCbcHmacSha256Decryptor` that provides two methods for decrypting and verifying the integrity of ciphertexts using AES-CBC with HMAC-SHA256. The `Decrypt` method takes in a byte array representing the ciphertext, an encryption key (a byte array), and an HMAC key (also a byte array). It first extracts the initialization vector from the beginning of the ciphertext, then decrypts the rest of the data using AES-CBC with the provided key. Finally, it verifies the integrity of the decrypted data by computing a HMAC hash and comparing it to the provided HMAC value.

The `VerifyHmac` method takes in an input byte array representing the ciphertext or plaintext (depending on whether HMAC was used before encryption), and an HMAC key as input. It computes a HMAC hash using the provided HMAC key and compares it to the provided HMAC value.

The code uses `AesCryptoServiceProvider` from `System.Security.Cryptography` for AES-CBC decryption, and `HMACSHA256` from `System.Security.Cryptography.HashAlgorithm` for HMAC verification. Both classes are cross-platform compatible.

The code also uses `MemoryStream` to read the ciphertext into memory and avoids unnecessary copies. It also allows for configurable thread pool sizes based on system load, which improves scalability without compromising performance.']

