```csharp
using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;

public class DataLoader
{
    public static CustomDataStructure LoadCompressedData(string filePath, int compressionLevel = 6)
    {
        // Check if the file exists and is readable
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The specified file does not exist or is not readable.", filePath);
        }

        // Open the file for reading and get its length
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        {
            var fileLength = fileStream.Length;

            // Use a binary reader to read the compressed data from the file
            using (var binaryReader = new BinaryReader(fileStream))
            {
                // Read the compressed data from the file stream
                var compressedData = binaryReader.ReadBytes((int)fileLength);

                // Decompress the data using the specified compression level
                using (var decompressionStream = new MemoryStream())
                {
                    var decompressor = new DeflateStream(decompressionStream, CompressionMode.Decompress, true);
                    decompressor.Write(compressedData, 0, compressedData.Length);

                    // Deserialize the decompressed data into a custom data structure
                    using (var deserializer = new BinaryFormatter())
                    {
                        return (CustomDataStructure)deserializer.Deserialize(decompressionStream);
                    }
                }
            }
        }
    }
}
```
This implementation uses the `BinaryReader` class to read the compressed data from the file stream, and then uses a `DeflateStream` object to decompress the data using the specified compression level. The decompressed data is then deserialized into a custom data structure using the `BinaryFormatter` class.

