    if (list == NULL) {
        printf("Error: Failed to allocate memory for LTE_PHY_RACH_PDU_LIST\n");
        return NULL;
    }

    // Initialize the list struct
    list->count = num_elements;
    list->array = malloc(sizeof(LTE_PHY_RACH_PDU) * num_elements);
    if (list->array == NULL) {
