// Function to add an element to the list of LTE_PHY_RACH_PDU structures
int add_rach_pdu(LTE_PHY_RACH_PDU_LIST *list, LTE_PHY_RACH_PDU rach_pdu) {
    // Acquire the lock on the list mutex
    pthread_mutex_lock(&list_mutex);

    // Check if the list is full and needs to be resized
    if (list->count == list->size) {
        // Allocate more memory for the array
        LTE_PHY_RACH_PDU *new_array = realloc(list->array, sizeof(LTE_PHY_RACH_PDU) * (list->size + 1));
        if (new_array == NULL) {
            printf("Error: Failed to resize LTE_PHY_RACH_PDU array\n");
            pthread_mutex_unlock(&list_mutex);
            return -1;
        }
        list->array = new_array;
        list->size++;
    }

    // Add the element to the end of the list
    list->array[list->count] = rach_pdu;
    list->count++;

    // Release the lock on the list mutex
    pthread_mutex_unlock(&list_mutex);

    return 0;
}

