// Function to remove an element from the list of LTE_PHY_RACH_PDU structures by index
int remove_rach_pdu(LTE_PHY_RACH_PDU_LIST *list, int index) {
    // Acquire the lock on the list mutex
    pthread_mutex_lock(&list_mutex);

    // Check if the index is valid
    if (index < 0 || index >= list->count) {
        printf("Error: Invalid index specified\n");
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    // Remove the element at the specified index from the list
    for (int i = index; i < list->count - 1; i++) {
        list->array[i] = list->array[i + 1];
    }
    list->count--;

    // Release the lock on the list mutex
