using namespace std;
using namespace boost;
using namespace boost::asio;
using namespace boost::lexical_cast;

// Define the graph structure
typedef adjacency_list<vecS, vecS, undirectedS> Graph;

// Define a vertex property to store the IP address and VM UUID
struct VertexProperty {
  string ip;
  boost::uuids::uuid uuid;
};

int main() {
  // Initialize the graph with the specified number of vertices and edges
  Graph g(10, 20);

  // Add vertices and edges to the graph
  for (int i = 0; i < 10; ++i) {
    g.add_vertex(VertexProperty{string{"IP_" + boost::lexical_cast<string>(i)}, boost::uuids::uuid()});
  }

  // Set the properties of the vertices and edges
  for (auto v : g.vertices()) {
    auto& prop = g[v];
    cout << "IP: " << prop.ip << ", UUID: " << prop.uuid << endl;
  }

  // Query the graph to find connected components
  vector<vector<int>> components(connected_components(g));
  for (auto& component : components) {
    cout << "Connected component: ";
    for (auto v : component) {
      cout << g[v].ip << ", ";
    }
    cout << endl;
  }

  // Print out the metrics of the graph
  auto n_requests = boost::get(boost::vertex_bundle_t(), g).n_requests;
  auto n_proxy_sessions = boost::get(boost::vertex_bundle_t(), g).n_proxy_sessions;
  auto n_internal_errors = boost::get(boost::vertex_bundle_t(), g).n_internal_errors;
  cout << "Metrics: requests=" << n_requests << ", proxy sessions=" << n_proxy_sessions << ", internal errors=" << n_internal_errors << endl;

  return 0;
}
