```c
#include <curl/curl.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

struct RequestBuilder {
  char* url;
  int num_records;
  int min_val;
  int max_val;
  record* records;
};

struct Record {
  int value;
};

// Function to create a HTTP client and allocate memory for an array of records.
struct RequestBuilder* create_client_and_records(const char* url, int num_records, int min_val, int max_val) {
  // Check if the URL is valid and not empty.
  if (url == NULL || strlen(url) == 0) {
    return NULL;
  }

  // Initialize a new RequestBuilder object.
  struct RequestBuilder* builder = malloc(sizeof(struct RequestBuilder));
  if (builder == NULL) {
    return NULL;
  }

  // Allocate memory for the array of records.
  builder->records = malloc(num_records * sizeof(struct Record));
  if (builder->records == NULL) {
    free(builder);
    return NULL;
  }

  // Set the URL and number of records in the RequestBuilder object.
  builder->url = url;
  builder->num_records = num_records;

  // Set the minimum and maximum values for the random range.
  builder->min_val = min_val;
  builder->max_val = max_val;

  // Generate a random value for each record.
  srand(time(NULL));
  for (int i = 0; i < num_records; i++) {
    int random_value = rand() % (builder->max_val - builder->min_val + 1) + builder->min_val;
    builder->records[i].value = random_value;
  }

  return builder;
}

// Function to clean up memory allocated for the RequestBuilder object.
void destroy_client(struct RequestBuilder* builder) {
  if (builder == NULL) {
    return;
  }

  // Free the array of records.
  free(builder->records);

  // Free the URL string.
  free(builder->url);

  // Finally, free the RequestBuilder object itself.
  free(builder);
}
```
