    // Use Union-Find data structure to efficiently check for disjointness between RNTI values
    vector<string> disjoint_rx_ue_information_tags;
    UnionFind uf(rx_ue_information_tags.size());
    for (int i = 0; i < rx_ue_information_tags.size(); i++) {
        string rnti = rx_ue_information_tags[i];
        for (int j = i + 1; j < rx_ue_information_tags.size(); j++) {
            if (uf.find(i) != uf.find(j)) {
                disjoint_rx_ue_information_tags.push_back(rnti);
                uf.union_(i, j);
            }
        }
    }

    // Print the number of milliseconds taken to perform each check and the number of requests, proxy sessions, and internal errors
