#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "nfapi_types.h"
#include "memory_pool.h"

// Memory pool manager integration
static void* memory_pool = NULL;
static size_t memory_pool_size = 0;

void initialize_memory_pool(void* mem_pool, size_t size) {
    memory_pool = mem_pool;
    memory_pool_size = size;
}

void* allocate_memory(size_t size) {
    void* ptr = NULL;
    if (size <= memory_pool_size) {
        ptr = memory_pool + (memory_pool_size - size);
        memory_pool_size -= size;
    }
    return ptr;
}

void free_memory(void* ptr, size_t size) {
    if (ptr != NULL && memory_pool != NULL) {
        memory_pool_size += size;
    }
}

// CRC indication PDU structure
typedef struct NFAPI_CRC_INDICATION_PDU {
  NFAPI_CRC_INDICATION_REL8_TAG crc_indication_rel8;
  uint16_t rx_ue_information_tag;
  uint16_t rnti;
} NFAPI_CRC_INDICATION_PDU_T;

void create_and_populate_crc_indication_pdus(uint32_t num_pdu, size_t memory_limit) {
  // Check input parameters
  if (num_pdu == 0 || memory_limit == 0) {
    return;
  }

  // Initialize memory pool
  initialize_memory_pool(memory_pool, memory_limit);

  // Allocate memory for the CRC indication PDUs
  NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdu);
  if (pdu == NULL) {
    return;
  }

  // Populate the CRC indication PDUs with random values
  for (uint32_t i = 0; i < num_pdu; ++i) {
    pdu[i].rx_ue_information_tag = rand();
    pdu[i].rnti = rand();
    pdu[i].crc_indication_rel8.crci = rand() % 2 ? 1 : 0;
  }

  // Free memory if the total memory usage exceeds the specified limit
  size_t total_memory_usage = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdu;
  if (total_memory_usage > memory_limit) {
    free_memory((void*)pdu, total_memory_usage);
    pdu = NULL;
  }

  // Return the populated CRC indication PDUs
  return pdu;
}
