    NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *) realloc(*list, total_size);
    if (!new_list) {
        return;
    }

    // Update the list pointer and size variables to reflect the new memory allocation
