    unsigned char plaintext[] = { 0x68, 0x65, 0x6c, 0x6c, 0x6f, 0x20, 0x77, 0x6f, 0x72, 0x6c, 0x64 };
    unsigned char ciphertext[16];

    // Encrypt the plaintext with CBC mode and a random initialization vector
    unsigned char *encrypted = aes_encrypt(plaintext, 13, key, AES_CBC, iv);

    // Print the encrypted data in hexadecimal format
    for (int i = 0; i < 16; i++) {
        printf("%02x", encrypted[i]);
    }

