#include <stdlib.h> // for malloc(), calloc() and free()
#include <stdio.h> // for printf() and scanf()
#include <time.h> // for srand() and rand()
#include <string.h> // for strdup()

struct node {
    int value;
    struct node* next;
};

struct record {
    int value;
};

int main() {
    // set random seed for generating random values
    srand(time(NULL));

    // allocate memory for arrays
    double* doubles = (double*)calloc(3, sizeof(double));
    char** strings = (char**)calloc(3, sizeof(char*));
    struct node** nodes = (struct node**)calloc(3, sizeof(struct node*));
    struct record* records = (struct record*)calloc(3, sizeof(struct record));

    // initialize arrays with random values
    for (int i = 0; i < 3; i++) {
        doubles[i] = rand() % 100;
        strings[i] = strdup("Hello World");
        records[i].value = rand() % 100;
    }

    // initialize linked list with nodes
    for (int i = 0; i < 3; i++) {
        struct node* new_node = malloc(sizeof(struct node));
        new_node->value = records[i].value;
        new_node->next = NULL;

        if (nodes[i] == NULL) {
            nodes[i] = new_node;
        } else {
            struct node* current = nodes[i];
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    // print arrays and linked list
    printf("Doubles: ");
    for (int i = 0; i < 3; i++) {
        printf("%.2f ", doubles[i]);
    }
    printf("\n");
    printf("Strings: ");
    for (int i = 0; i < 3; i++) {
        printf("%s ", strings[i]);
    }
    printf("\n");
    printf("Records: ");
    for (int i = 0; i < 3; i++) {
        printf("{%d} ", records[i].value);
    }
    printf("\n");
    printf("Linked list: ");
    for (int i = 0; i < 3; i++) {
        struct node* current = nodes[i];
        while (current != NULL) {
            printf("%d->", current->value);
            current = current->next;
        }
    }
    printf("\n");

    // free memory
    for (int i = 0; i < 3; i++) {
        free(doubles[i]);
        free(strings[i]);
        while (nodes[i] != NULL) {
            struct node* tmp = nodes[i];
            nodes[i] = nodes[i]->next;
            free(tmp);
        }
    }

    return 0;
}

// insert_node function to insert a new node in the linked list
// in such a way that the list remains sorted based on the integer values
void insert_node(struct node** head_ref, int value) {
    // allocate memory for new node
    struct node* new_node = malloc(sizeof(struct node));
    new_node->value = value;
    new_node->next = NULL;

    if (*head_ref == NULL) {
        *head_ref = new_node;
    } else {
        struct node* current = *head_ref;
        struct node* previous = NULL;
        while (current != NULL && value > current->value) {
            previous = current;
            current = current->next;
        }
        if (previous == NULL) {
            new_node->next = current;
            *head_ref = new_node;
        } else {
            previous->next = new_node;
            new_node->next = current;
        }
    }
}

// trade-offs between efficiency, usability, maintainability, and scalability

Efficiency:
The solution should be as efficient as possible while still ensuring thread safety and memory management. To achieve this, we can use a single lock for all operations on the linked list, which will ensure that only one thread can access the list at a time. We can also use a more efficient data structure such as a binary search tree to store the records in sorted order.

Usability:
The solution should be easy to understand and use for other developers who may need to maintain or modify it in the future. To achieve this, we can use clear and descriptive variable names, and provide detailed comments throughout the code explaining what each function does. We can also use a modular design with separate functions for memory allocation, linked list insertion, and record initialization to make the code more maintainable.

Maintainability:
The solution should be easy to modify or extend in the future without breaking existing functionality. To achieve this, we can use a modular design with separate functions for each part of the program, which will allow developers to add new features or fix bugs without affecting the rest of the code. We can also use version control systems like Git to track changes and collaborate with other developers.

Scalability:
The solution should be able to handle large amounts of data without degrading performance. To achieve this, we can use a more efficient data structure such as a binary search tree to store the records in sorted order, which will allow for faster insertion and retrieval of records. We can also use a more memory-efficient approach by using smaller data types for values where possible, and only allocating memory for the arrays when they are first used.

External Data Sources:
To handle external data sources securely and efficiently, we can use a combination of techniques such as input validation, error handling, and data masking. For example, we can validate that the input values from the external data source are within the expected range before using them to initialize the arrays, and we can handle errors gracefully by providing clear error messages to the user. We can also use data masking techniques such as encryption or obfuscation to protect sensitive data from unauthorized access.

Limited Available Memory:
To ensure that the solution does not exceed this constraint, we can use more efficient memory management techniques such as freeing unused memory and avoiding unnecessary allocations. We can also optimize the code for smaller devices or low-end hardware by using lighterweight data types and algorithms.']

