#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

// Define constants for the supported encryption modes
#define MODE_ECB 1
#define MODE_CBC 2
#define MODE_CFB 3

// Define a structure to represent an AES cipher
typedef struct {
    EVP_CIPHER_CTX *ctx;
    int mode;
} AES_Cipher;

// Define functions for key expansion and encryption/decryption using AES
void key_expansion(char *password, unsigned char *key) {
    // Use PBKDF2 to derive a 32-byte key from the given password
    PKCS5_PBKDF2_HMAC_SHA1((unsigned char *)password, strlen(password), NULL, 0, 32, key);
}

AES_Cipher *encrypt(char *plaintext, unsigned char *key) {
    // Create a new AES cipher object
    AES_Cipher *cipher = (AES_Cipher *)malloc(sizeof(AES_Cipher));
    if (!cipher) {
        fprintf(stderr, "Error: Failed to allocate memory for AES cipher\n");
        return NULL;
    }

    // Initialize the cipher object with the given key
    EVP_EncryptInit_ex(&cipher->ctx, EVP_aes_256_cbc(), NULL, key, NULL);
    if (!EVP_EncryptInit_ex(cipher->ctx)) {
        fprintf(stderr, "Error: Failed to initialize AES cipher\n");
        free(cipher);
        return NULL;
    }

    // Set the encryption mode to ECB
    cipher->mode = MODE_ECB;

    // Return the initialized cipher object
    return cipher;
}

AES_Cipher *decrypt(char *ciphertext, unsigned char *key) {
    // Create a new AES cipher object
    AES_Cipher *cipher = (AES_Cipher *)malloc(sizeof(AES_Cipher));
    if (!cipher) {
        fprintf(stderr, "Error: Failed to allocate memory for AES cipher\n");
        return NULL;
    }

    // Initialize the cipher object with the given key
    EVP_DecryptInit_ex(&cipher->ctx, EVP_aes_256_cbc(), NULL, key, NULL);
    if (!EVP_DecryptInit_ex(cipher->ctx)) {
        fprintf(stderr, "Error: Failed to initialize AES cipher\n");
        free(cipher);
        return NULL;
    }

    // Set the decryption mode to ECB
    cipher->mode = MODE_ECB;

    // Return the initialized cipher object
    return cipher;
}

// Implement a function to handle encryption using the AES algorithm in ECB mode
void encrypt_ecb(char *plaintext, unsigned char *key) {
    // Create an AES cipher object for the given key and mode
    AES_Cipher *cipher = encrypt(plaintext, key);
    if (!cipher) {
        fprintf(stderr, "Error: Failed to create AES cipher\n");
        return;
    }

    // Encrypt the plaintext using the cipher object
    EVP_EncryptUpdate(&cipher->ctx, NULL, NULL, (unsigned char *)plaintext, strlen(plaintext));
    if (!EVP_EncryptFinal_ex(&cipher->ctx, NULL, NULL)) {
        fprintf(stderr, "Error: Failed to encrypt plaintext\n");
        EVP_CIPHER_CTX_cleanup(&cipher->ctx);
        free(cipher);
        return;
    }

    // Print the ciphertext
    printf("Encrypted text: %s\n", (char *)EVP_CIPHER_CTX_buf(&cipher->ctx));

    // Clean up the AES cipher object
    EVP_CIPHER_CTX_cleanup(&cipher->ctx);
    free(cipher);
}

// Implement a function to handle decryption using the AES algorithm in ECB mode
void decrypt_ecb(char *ciphertext, unsigned char *key) {
    // Create an AES cipher object for the given key and mode
    AES_Cipher *cipher = decrypt(ciphertext, key);
    if (!cipher) {
        fprintf(stderr, "Error: Failed to create AES cipher\n");
        return;
    }

    // Decrypt the ciphertext using the cipher object
    EVP_DecryptUpdate(&cipher->ctx, NULL, NULL, (unsigned char *)ciphertext, strlen(ciphertext));
    if (!EVP_DecryptFinal_ex(&cipher->ctx, NULL, NULL)) {
        fprintf(stderr, "Error: Failed to decrypt ciphertext\n");
        EVP_CIPHER_CTX_cleanup(&cipher->ctx);
        free(cipher);
        return;
    }

    // Print the plaintext
    printf("Decrypted text: %s\n", (char *)EVP_CIPHER_CTX_buf(&cipher->ctx));

    // Clean up the AES cipher object
    EVP_CIPHER_CTX_cleanup(&cipher->ctx);
    free(cipher);
}

int main() {
    char plaintext[] = "Hello, world!";
    unsigned char key[32] = {};

    // Generate a random 32-byte key using the RAND_bytes function
    if (!RAND_bytes(key, 32)) {
        fprintf(stderr, "Error: Failed to generate random key\n");
        return 1;
    }

    // Print the generated key
    printf("Generated key: ");
    for (int i = 0; i < 32; ++i) {
        printf("%02x", key[i]);
    }
    printf("\n");

    // Encrypt the plaintext using the ECB mode
    encrypt_ecb(plaintext, key);

    // Decrypt the ciphertext using the ECB mode
    decrypt_ecb("Encrypted text: 7c68291105b7e843f9a07782d2afc429", key);

    return 0;
}
```
This implementation includes a key expansion function to handle key derivation from a given password using PBKDF2. The `encrypt` and `decrypt` functions use the AES algorithm in ECB mode with a 32-byte key. The `main` function demonstrates how to generate a random 32-byte key, encrypt a plaintext message using ECB mode, decrypt the ciphertext using ECB mode, and print the resulting plaintext.

Please note that this is just an example implementation of AES encryption in ECB mode, and should not be used for actual security purposes without proper error handling, input validation, and key management.']

