    while ((opt = getopt(argc, argv, "i:o:c:")) != -1) {
        switch (opt) {
            case 'i':
                input_file = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'c':
                decompress_format = optarg;
                break;
        }
    }

    // Check if any required arguments are missing
    if (input_file == NULL || decompress_format == NULL) {
        ERROR("Missing input file or decompression format");
        return 1;
    }

    // Open input file and check for errors
    fptr = fopen(input_file, "r");
    if (fptr == NULL) {
        ERROR("Error opening input file");
        return 1;
    }

    // Decompress the input file if necessary
    if (strcmp(decompress_format, "gz") == 0) {
        int ret = 0;
        z_stream strm;
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;
        ret = inflateInit2(&strm, 15 + 32); // window size and gzip header
        if (ret != Z_OK) {
            ERROR("Error initializing decompression");
            return 1;
        }
        char inbuf[BUFSIZ];
        unsigned have = fread(inbuf, 1, BUFSIZ, fptr);
        if (have == 0) {
            ERROR("Error reading input file");
            inflateEnd(&strm);
            return 1;
        }
        strm.next_in = inbuf;
        strm.avail_in = have;
        char outbuf[BUFSIZ];
        unsigned char *outbufptr = (unsigned char *)outbuf;
        do {
            strm.next_out = outbufptr;
            strm.avail_out = BUFSIZ;
            ret = inflate(&strm, Z_NO_FLUSH);
            if (ret == Z_STREAM_END) break;
            have = fwrite(outbufptr, 1, BUFSIZ - strm.avail_out, stdout);
            if (have != BUFSIZ - strm.avail_out) {
                ERROR("Error writing decompressed data");
                inflateEnd(&strm);
                return 1;
            }
        } while (ret == Z_OK);
        inflateEnd(&strm);
    }

    // Count the number of lines and words in the input file
    char line[BUFSIZ];
    while (fgets(line, BUFSIZ, fptr) != NULL) {
        num_lines++;
        total_words += strlen(line);
    }

    // Print usage information if no output file is provided
    if (output_file == NULL) {
        printf("Usage: %s -i <input_file> [-o <output_file>] [-c <decompress_format>]\n", argv[0]);
        return 1;
    }

    // Open output file and check for errors
    FILE *fout = fopen(output_file, "w");
    if (fout == NULL) {
        ERROR("Error opening output file");
        return 1;
    }

    // Write the number of lines and words to the output file
    fprintf(fout, "Number of lines: %ld\n", num_lines);
    fprintf(fout, "Total number of words: %ld\n", total_words);

    // Close files and return success
    fclose(fptr);
    fclose(fout);
    return 0;
}
```
This program uses the `getopt` function to parse command line arguments, and it assumes that the input file is a gzip compressed file. If an output file is provided, it writes the number of lines and words to the output file. It also provides usage information if no input file is provided or if any other error occurs during execution.']

