void* create_http_client(char* url, int disable_certificate_validation) {
    // Initialize curl handle and set URL
    CURL* curl = curl_easy_init();
    if (!curl) {
        printf("Failed to initialize curl handle\n");
        return NULL;
    }
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Disable certificate validation if requested
    if (disable_certificate_validation) {
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
    }

    // Initialize arrays for offset and keys
    long* offsets = malloc(sizeof(long) * 10);
    int* keys = malloc(sizeof(int) * 10);
    if (!offsets || !keys) {
        printf("Failed to allocate memory for arrays\n");
        return NULL;
    }

    // Initialize record array with random values within given range
    record* records = malloc(sizeof(record) * 10);
    if (!records) {
        printf("Failed to allocate memory for record array\n");
        return NULL;
    }
    for (int i = 0; i < 10; i++) {
        records[i].value = rand() % 100 + 1;
    }

    // Connect to database using username and password
    sqlite3* db = NULL;
    char* query = "SELECT * FROM employees";
    int result = sqlite3_open("employees.db", &db);
    if (result != SQLITE_OK) {
        printf("Failed to connect to database: %s\n", sqlite3_errmsg(db));
        return NULL;
    }
    result = sqlite3_exec(db, query, callback, NULL, NULL);
    if (result != SQLITE_OK) {
        printf("Failed to execute query: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Clean up and return http client handle
    curl_easy_cleanup(curl);
    free(offsets);
    free(keys);
    free(records);
    sqlite3_close(db);
    return curl;
}

int callback(void* data, int argc, char** argv, char** azColName) {
    // Display query statement and result set
    printf("Query: %s\n", query);
    for (int i = 0; i < argc; i++) {
        printf("%s = %s\n", azColName[i], argv[i] ? argv[i] : "NULL");
    }
    return 0;
}
