    // open input and output files
    int fd_in = open(input_filename, O_RDONLY);
    if (fd_in < 0) {
        printf("Error opening input file: %s\n", strerror(errno));
        return;
    }
    int fd_out = open(output_filename, O_WRONLY | O_CREAT, 0644);
    if (fd_out < 0) {
        printf("Error opening output file: %s\n", strerror(errno));
        close(fd_in);
        return;
    }

    // allocate memory for input and output buffers
    size_t bufsize = 1024;
    char *input_buf = malloc(bufsize);
    if (input_buf == NULL) {
        printf("Error allocating memory for input buffer\n");
        close(fd_in);
        close(fd_out);
        return;
    }
    char *output_buf = malloc(bufsize);
    if (output_buf == NULL) {
        printf("Error allocating memory for output buffer\n");
        free(input_buf);
        close(fd_in);
        close(fd_out);
        return;
    }

    // parse input file and apply rules to generate output
    while (1) {
        // read from input file in chunks
        ssize_t nread = read(fd_in, input_buf, bufsize - 1);
        if (nread < 0) {
            printf("Error reading from input file: %s\n", strerror(errno));
            break;
        } else if (nread == 0) {
            // end of file reached
            break;
        }
        input_buf[nread] = '\0';

        // apply rules to generate output
        for (int i = 0; i < nread; i++) {
            char c = input_buf[i];
            if (c == 'a' || c == 'A') {
                output_buf[i] = '4';
            } else if (c == 'b' || c == 'B') {
                output_buf[i] = '8';
            } else {
                output_buf[i] = c;
            }
        }

        // write to output file in chunks
        ssize_t nwritten = write(fd_out, output_buf, nread);
        if (nwritten < 0) {
            printf("Error writing to output file: %s\n", strerror(errno));
            break;
        }
    }

    // close input and output files
    close(fd_in);
    close(fd_out);

    // free memory for input and output buffers
    free(input_buf);
    free(output_buf);
}

int main(int argc, char **argv) {
    if (argc < 4) {
        printf("Usage: %s <input file> <output file> <rules>\n", argv[0]);
        return 1;
    }
    parse_file(argv[1], argv[2], argv[3]);
    return 0;
}
