#include <time.h>

struct node {
    int value;
    struct node* next;
};

struct record {
    int key;
    long offset;
};

void insert_node(struct node** head, int value) {
    struct node* new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    new_node->value = value;
    new_node->next = NULL;

    struct node* current = *head;
    while (current != NULL && current->value < value) {
        current = current->next;
    }

    if (current == NULL) {
        new_node->next = *head;
        *head = new_node;
    } else {
        new_node->next = current->next;
        current->next = new_node;
    }
}

void initialize_data(struct record* records, int num_records, struct node** head) {
    for (int i = 0; i < num_records; ++i) {
        int key = rand() % 100 + 1;
        long offset = rand() % 10000 + 1;
        records[i].key = key;
        records[i].offset = offset;

        insert_node(head, key);
    }
}

void free_memory(struct node** head) {
    struct node* current = *head;
    while (current != NULL) {
        struct node* next = current->next;
        free(current);
        current = next;
    }
}
