typedef struct {
    int int_value;
} record;

void init_records(long *offsets, int *keys, record **records, size_t max_limit) {
    // Initialize the random seed
    srand(time(NULL));

    // Allocate memory for the offset array
    offsets = (long *)malloc(sizeof(long) * max_limit);
