    for (size_t i = 0; i < size; i++) {
        arr[i].value = random_number;
    }
}

// Function to create an EVP_CIPHER structure representing a chosen AES cipher
EVP_CIPHER* createAesCipher(int mode, int padding_scheme) {
    // Define the appropriate parameters for the selected AES mode and padding scheme
    const EVP_CIPHER* aes_cipher = NULL;
    switch (mode) {
        case MODE_ECB:
            switch (padding_scheme) {
                case PADDING_PKCS7:
                    aes_cipher = EVP_aes_128_ecb();
                    break;
            }
            break;
        case MODE_CBC:
            switch (padding_scheme) {
                case PADDING_PKCS7:
                    aes_cipher = EVP_aes_128_cbc();
                    break;
            }
            break;
        case MODE_CFB:
            switch (padding_scheme) {
                case PADDING_PKCS7:
                    aes_cipher = EVP_aes_128_cfb();
                    break;
            }
            break;
        case MODE_OFB:
            switch (padding_scheme) {
                case PADDING_PKCS7:
                    aes_cipher = EVP_aes_128_ofb();
                    break;
            }
            break;
    }
    return aes_cipher;
}

// Function to encrypt data using AES in the selected mode and padding scheme
void encryptData(record* records, size_t record_count, int mode, int padding_scheme) {
    // Allocate memory for the encryption output buffer
    unsigned char* encrypted_data = (unsigned char*)malloc(record_count * sizeof(record));
    if (!encrypted_data) {
        // Handle error: Could not allocate memory for encryption output buffer
        return;
    }
    memset(encrypted_data, 0, record_count * sizeof(record));

    // Initialize the EVP_CIPHER structure representing the chosen AES cipher
    EVP_CIPHER* aes_cipher = createAesCipher(mode, padding_scheme);
    if (!aes_cipher) {
        // Handle error: Could not initialize AES cipher
        return;
    }

    // Set the IV for the encryption operation using a secure random number generator
    unsigned char iv[EVP_CIPHER_iv_length(aes_cipher)];
    RAND_bytes(iv, EVP_CIPHER_iv_length(aes_cipher));

    // Encrypt each record in the input array using AES encryption and the selected mode and padding scheme
    for (size_t i = 0; i < record_count; i++) {
        size_t encrypted_data_length = sizeof(encrypted_data);
        int ret = EVP_EncryptUpdate(aes_cipher, encrypted_data, &encrypted_data_length, (unsigned char*)&records[i], sizeof(record));
        if (ret == 0) {
            // Handle error: AES encryption failed
            return;
        }
    }

    // Free the EVP_CIPHER structure and the encryption output buffer
    free(aes_cipher);
    free(encrypted_data);
}

// Function to decrypt data using AES in the selected mode and padding scheme
void decryptData(record* records, size_t record_count, int mode, int padding_scheme) {
    // Allocate memory for the decryption output buffer
    unsigned char* decrypted_data = (unsigned char*)malloc(record_count * sizeof(record));
    if (!decrypted_data) {
        // Handle error: Could not allocate memory for decryption output buffer
        return;
    }
    memset(decrypted_data, 0, record_count * sizeof(record));

    // Initialize the EVP_CIPHER structure representing the chosen AES cipher
    EVP_CIPHER* aes_cipher = createAesCipher(mode, padding_scheme);
    if (!aes_cipher) {
        // Handle error: Could not initialize AES cipher
        return;
    }

    // Set the IV for the decryption operation using a secure random number generator
    unsigned char iv[EVP_CIPHER_iv_length(aes_cipher)];
    RAND_bytes(iv, EVP_CIPHER_iv_length(aes_cipher));

    // Decrypt each record in the input array using AES decryption and the selected mode and padding scheme
    for (size_t i = 0; i < record_count; i++) {
        size_t decrypted_data_length = sizeof(decrypted_data);
        int ret = EVP_DecryptUpdate(aes_cipher, decrypted_data, &decrypted_data_length, (unsigned char*)&records[i], sizeof(record));
        if (ret == 0) {
            // Handle error: AES decryption failed
            return;
        }
    }

    // Free the EVP_CIPHER structure and the decryption output buffer
    free(aes_cipher);
    free(decrypted_data);
}
```

