#include <stdlib.h>
#include <stdint.h>
#include <time.h>

// Memory pool manager integration
#define MEMORY_POOL_SIZE 1024 * 1024 * 1024 // 1GB
#define RECORD_SIZE sizeof(struct record)

typedef struct {
    int key;
    long offset;
} record;

int create_and_populate_array(record **records, size_t count, size_t max_size, int min, int max) {
    // Initialize random seed for generating random values
    srand(time(NULL));

    // Allocate memory pool from the manager
    void *pool = get_memory_pool(MEMORY_POOL_SIZE);
    if (!pool) {
        return -1; // Error: failed to allocate memory pool
    }

    // Initialize array of records with random values
    for (size_t i = 0; i < count; i++) {
        record *rec = (record *)pool + i * RECORD_SIZE;
        rec->key = rand() % max + min; // Generate random value within specified range
        rec->offset = 0; // Initialize offset to default value
    }

    // Return pointer to the start of the array
    return (int)(records - pool);
}

void free_array(record **records) {
    void *pool = get_memory_pool((char *)records - records);
    if (!pool) {
        return; // Error: failed to free memory pool
    }

    // Free the memory pool
    free_memory_pool(pool);
}
```
