Here is the web API function that updates an existing resource using the HTTP PUT method and returns the updated resource:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Function to update a resource using the HTTP PUT method
int update_resource(char *resource_id, char *request_body) {
    // Initialize variables
    int sock = -1;
    struct sockaddr_in server_address;
    char response[4096];

    // Create a socket and connect to the server
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        printf("Error creating socket\n");
        return -1;
    }
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr("localhost");
    server_address.sin_port = htons(8080);
    if (connect(sock, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        printf("Error connecting to server\n");
        return -1;
    }

    // Construct the HTTP PUT request
    char *request = malloc(sizeof(char) * (strlen(resource_id) + strlen(request_body) + 20));
    sprintf(request, "PUT /%s HTTP/1.1\r\nContent-Length: %d\r\nContent-Type: application/json\r\n\r\n%s", resource_id, strlen(request_body), request_body);

    // Send the request to the server and receive the response
    if (send(sock, request, strlen(request), 0) < 0) {
        printf("Error sending request\n");
        return -1;
    }
    if (recv(sock, response, sizeof(response), 0) < 0) {
        printf("Error receiving response\n");
        return -1;
    }

    // Close the socket and return the response
    close(sock);
    return strlen(response);
}
```
