Here is the Rust function that creates a new directory with a given name if it does not already exist, and sets an environment variable to the path of the directory:
```rust
use std::env;
use std::fs;
use std::path::PathBuf;

fn create_directory(name: &str) -> PathBuf {
    // Initialize variables
    let mut path = env::current_dir().unwrap();
    let mut directory_exists = false;

    // Check if the directory already exists
    if fs::metadata(path.join(name)).is_ok() {
        directory_exists = true;
    }

    // Create a new directory if it does not exist
    if !directory_exists {
        fs::create_dir(path.join(name)).unwrap();
    }

    // Set the environment variable to the path of the directory
    env::set_var("MY_DIRECTORY", path.join(name).to_str().unwrap());

    // Return the path of the new directory
    return path.join(name);
}
