#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_records(record **records, long *offsets, int *keys, int num_records) {
    // Allocate memory for the arrays
    records = (record**)malloc(num_records * sizeof(record));
    offsets = (long*)malloc(num_records * sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));

    // Initialize the arrays with random values within a given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(record));
        offsets[i] = rand() % (1 << 24); // Randomly generate offset values between 0 and 2^24
        keys[i] = rand() % 1000;         // Randomly generate key values between 0 and 999
    }

    // Save the initialized records to a file in binary format
    FILE *file = fopen("records.bin", "wb");
    for (int i = 0; i < num_records; i++) {
        record *record = records[i];
        fwrite(&record->value, sizeof(int), 1, file);
        fwrite(&offsets[i], sizeof(long), 1, file);
    }
    fclose(file);
}
