/**
 * Initializes an array of records with random int values within a given range.
 * @param num_records The number of records to initialize
 * @param min_key The minimum value for the int field
 * @param max_key The maximum value for the int field
 * @return An array of record structures, or NULL if memory allocation failed
 */
record_t* init_records(int num_records, int min_key, int max_key) {
    // Allocate memory for the records and offset values arrays
    long* offsets = malloc(num_records * sizeof(long));
    record_t* records = malloc(num_records * sizeof(record_t));
    if (offsets == NULL || records == NULL) {
        // Memory allocation failed, return NULL
        printf("Memory allocation failed\n");
        free(offsets);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    // Initialize the offset values array with random values within the given range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Initialize the record structures with the offset values and random int keys
    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
    }

    free(offsets);
    return records;
}

/**
 * Searches for a specific key in an array of records and returns the corresponding record if found.
 * @param records The array of records to search
 * @param num_records The number of records in the array
 * @param key The key to search for
 * @return The record with the matching key, or NULL if not found
 */
record_t* find_key(record_t* records, int num_records, int key) {
    // Iterate through the records and check for a match
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            return &records[i];
        }
    }

    // If no match is found, return NULL
    return NULL;
}

int main() {
    int num_records = 10;
    int min_key = 0;
    int max_key = 100;

    record_t* records = init_records(num_records, min_key, max_key);
    if (records == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Search for a specific key in the array of records
    int search_key = 50;
    record_t* match = find_key(records, num_records, search_key);
