}

// Function to encrypt a string and write it to a file
void encrypt_string_to_file(const char *input, const char *output) {
    unsigned char *encrypted = encrypt(input);
    if (!encrypted) {
        syslog(LOG_ERR, "Error encrypting string: %s", strerror(errno));
        return;
    }
    FILE *f = fopen(output, "wb");
    if (!f) {
        syslog(LOG_ERR, "Error opening output file: %s", strerror(errno));
        free(encrypted);
        return;
    }
    fwrite(encrypted, 1, strlen(encrypted), f);
    fclose(f);
}

// Function to decrypt a string from a file and write it to another file
void decrypt_string_from_file_to_another(const char *input, const char *output) {
    unsigned char *decrypted = decrypt(input);
    if (!decrypted) {
        syslog(LOG_ERR, "Error decrypting string: %s", strerror(errno));
        return;
    }
    FILE *f = fopen(output, "wb");
    if (!f) {
        syslog(LOG_ERR, "Error opening output file: %s", strerror(errno));
        free(decrypted);
        return;
    }
    fwrite(decrypted, 1, strlen(decrypted), f);
    fclose(f);
}

// Function to print the usage of the program
void print_usage() {
    printf("Usage: ./program [command] [arguments]\n");
    printf("\tcommand: encrypt | decrypt\n");
    printf("\targuments:\n");
    printf("\t\tencrypt: [string to encrypt] [output file]\n");
    printf("\t\tdecrypt: [input file] [output file]\n");
}
```']

