['Here is an example of a C function that dynamically allocates memory for and initializes three arrays: one for `long` offset values, one for `int` keys, and one for `record` structures. Each `record` structure contains a single `int` value. The function also includes features to save the initialized records to a file in both binary and text formats, and load them back into memory when needed.
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// structure for record data
typedef struct {
    int value;
} Record;

// function to allocate and initialize arrays
void init_arrays(long* offsets, int* keys, Record** records, int num_records) {
    // dynamically allocate memory for arrays
    offsets = (long*)malloc(sizeof(long) * num_records);
    keys = (int*)malloc(sizeof(int) * num_records);
    records = (Record**)malloc(sizeof(Record *) * num_records);

    // initialize offset values to zero
    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0;
    }

    // initialize key values to random numbers within the given range
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100 + 1;
    }

    // allocate memory for each record structure and set its value
    for (int i = 0; i < num_records; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = rand() % 100 + 1;
    }
}

// function to save arrays to file in binary format
void save_binary(long* offsets, int* keys, Record** records, int num_records) {
    // open a file for writing in binary mode
    FILE* fp = fopen("record_data.bin", "wb");
    if (fp == NULL) {
        printf("Error: failed to open file\n");
        return;
    }

    // write offsets array to file
    fwrite(offsets, sizeof(long), num_records, fp);

    // write keys array to file
    fwrite(keys, sizeof(int), num_records, fp);

    // write records array to file
    for (int i = 0; i < num_records; i++) {
        Record* record = records[i];
        fwrite(&record->value, sizeof(int), 1, fp);
    }

    // close the file
    fclose(fp);
}

// function to save arrays to file in text format
void save_text(long* offsets, int* keys, Record** records, int num_records) {
    // open a file for writing in text mode
    FILE* fp = fopen("record_data.txt", "wt");
    if (fp == NULL) {
        printf("Error: failed to open file\n");
        return;
    }

    // write offsets array to file
    for (int i = 0; i < num_records; i++) {
        fprintf(fp, "%ld\n", offsets[i]);
    }

    // write keys array to file
    for (int i = 0; i < num_records; i++) {
        fprintf(fp, "%d\n", keys[i]);
    }

    // write records array to file
    for (int i = 0; i < num_records; i++) {
        Record* record = records[i];
        fprintf(fp, "%d\n", record->value);
    }

    // close the file
    fclose(fp);
}

// function to load arrays from file in binary format
void load_binary(long** offsets, int** keys, Record*** records, int* num_records) {
    // open a file for reading in binary mode
    FILE* fp = fopen("record_data.bin", "rb");
    if (fp == NULL) {
        printf("Error: failed to open file\n");
        return;
    }

    // read offsets array from file
    fread(offsets, sizeof(long), *num_records, fp);

    // read keys array from file
    fread(keys, sizeof(int), *num_records, fp);

    // allocate memory for each record structure and set its value
    for (int i = 0; i < *num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        records[i] = record;
        fread(&record->value, sizeof(int), 1, fp);
    }

    // close the file
    fclose(fp);
}

// function to load arrays from file in text format
void load_text(long** offsets, int** keys, Record*** records, int* num_records) {
    // open a file for reading in text mode
    FILE* fp = fopen("record_data.txt", "rt");
    if (fp == NULL) {
        printf("Error: failed to open file\n");
        return;
    }

    // read offsets array from file
    for (int i = 0; i < *num_records; i++) {
        fscanf(fp, "%ld", &offsets[i]);
    }

    // read keys array from file
    for (int i = 0; i < *num_records; i++) {
        fscanf(fp, "%d", &keys[i]);
    }

    // allocate memory for each record structure and set its value
    for (int i = 0; i < *num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        records[i] = record;
        fscanf(fp, "%d", &record->value);
    }

    // close the file
    fclose(fp);
}

// function to print arrays
void print_arrays(long* offsets, int* keys, Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        printf("Offsets: %ld\n", offsets[i]);
        printf("Keys: %d\n", keys[i]);
        printf("Records: %d\n", records[i]->value);
    }
}

int main() {
    int num_records = 5;
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    Record** records = malloc(num_records * sizeof(Record));

    init_arrays(offsets, keys, records, num_records);
    save_binary(offsets, keys, records, num_records);
    save_text(offsets, keys, records, num_records);
    load_binary(offsets, keys, records, &num_records);
    load_text(offsets, keys, records, &num_records);
    print_arrays(offsets, keys, records, num_records);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```

