// function to check the uniqueness of pairs of elements in an array using a hash table data structure
int check_unique_pairs(int **arr, int size) {
    int unique_pairs = 0;
    struct timeval start, end; // for measuring time taken by the function
    gettimeofday(&start, NULL); // start timing the function

    // create a hash table to store keys and their corresponding indices
    unsigned long long *hash_table = malloc(size * sizeof(unsigned long long));
    for (int i = 0; i < size; i++) {
        hash_table[i] = arr[i];
    }

    // loop through the array and check if each pair is unique using the hash table
    for (int i = 0; i < size - 1; i++) {
        int key1 = arr[i][0];
        int key2 = arr[i][1];
        unsigned long long index1 = hash_table[key1];
        unsigned long long index2 = hash_table[key2];
        if (index1 != index2) {
            unique_pairs++;
            hash_table[key1] = i; // update the hash table with the new index for key1
            hash_table[key2] = i; // update the hash table with the new index for key2
        }
    }

    gettimeofday(&end, NULL); // end timing the function
    double time_taken = ((double) (end.tv_sec - start.tv_sec)) + ((double) (end.tv_usec - start.tv_usec)) / 1000000; // calculate the time taken by the function in microseconds

    printf("Time taken to check for unique pairs: %f seconds\n", time_taken); // print the time taken

    return unique_pairs;
}

