    for (int i = 0; i < num_records; i++) {
        Record *record1 = &records[i]; // Get the first record
        for (int j = i + 1; j < num_records; j++) {
            Record *record2 = &records[j]; // Get the second record
            if (!union_find(uf, record1->value, record2->value)) { // Check if the two records are disjoint using Union-Find
                printf("Disjoint pair found: %d and %d\n", record1->value, record2->value);
            }
        }
    }
}

// Function to merge two groups within a Union-Find data structure if their elements are found to be disjoint
void union_groups(Record *records, int num_records, int group1, int group2) {
    UnionFind uf = init_unionfind(num_records); // Initialize a Union-Find data structure for keeping track of disjoint sets
    for (int i = 0; i < num_records; i++) {
        Record *record = &records[i]; // Get the current record
        if (group1 == group2) { // If the two records are in the same group, merge them
            union_find(uf, record->value, record->value);
        } else { // Otherwise, check if the two records are disjoint using Union-Find and merge them if necessary
            if (!union_find(uf, record->value, record->value)) {
                union_find(uf, group1, group2);
            }
        }
    }
}

// Function to find all disjoint pairs within each group separately using a Union-Find data structure
void find_disjoint(Record *records, int num_records, int group) {
    UnionFind uf = init_unionfind(num_records); // Initialize a Union-Find data structure for keeping track of disjoint sets
    for (int i = 0; i < num_records; i++) {
        Record *record1 = &records[i]; // Get the first record
        for (int j = i + 1; j < num_records; j++) {
            Record *record2 = &records[j]; // Get the second record
            if (!union_find(uf, record1->value, record2->value)) { // Check if the two records are disjoint using Union-Find
                printf("Disjoint pair found within group %d: %d and %d\n", group, record1->value, record2->value);
            }
        }
    }
}

int main() {
    // Initialize an array of records with 10 elements
    int num_records = 10;
    Record *records = init_records(num_records);

    // Check the disjointness of pairs of elements in the array using a Union-Find data structure
    check_disjoint(records, num_records);

    // Merge two groups within the Union-Find data structure if their elements are found to be disjoint
    union_groups(records, num_records, 0, 1);

    // Find all disjoint pairs within each group separately using a Union-Find data structure
    for (int i = 0; i < num_records; i++) {
        find_disjoint(records, num_records, i);
    }

    return 0;
}
