// Function to create an HTTP client using curl and return a RequestBuilder for the given URL
RequestBuilder *create_http_client(const char *url, bool disable_certificate_validation) {
  // Initialize the curl session and set the URL
  CURL *curl = curl_easy_init();
  if (curl == NULL) {
    fprintf(stderr, "Failed to initialize curl session\n");
    return NULL;
  }
  curl_easy_setopt(curl, CURLOPT_URL, url);

  // Set the HTTP timeout and maximum number of retries based on environment variables
  const char *timeout = getenv("HTTP_TIMEOUT");
  if (timeout != NULL) {
    curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, atoi(timeout));
  }
  const char *retries = getenv("MAX_RETRIES");
  if (retries != NULL) {
    curl_easy_setopt(curl, CURLOPT_MAXREDIRS, atoi(retries));
  }

  // Set the random seed for generating record values based on environment variables
  const char *seed = getenv("RANDOM_SEED");
  if (seed != NULL) {
    srand(atoi(seed));
  }

  // Initialize two arrays to store 'long' and 'int' keys, respectively
  long *keys = malloc(sizeof(long) * num_records);
  int *values = malloc(sizeof(int) * num_records);
  if (keys == NULL || values == NULL) {
    fprintf(stderr, "Failed to allocate memory for key and value arrays\n");
    return NULL;
  }

  // Initialize an array of 'record' structures, each with a single int field
  Record *records = malloc(sizeof(Record) * num_records);
  if (records == NULL) {
    fprintf(stderr, "Failed to allocate memory for record array\n");
    return NULL;
  }

  // Set the value of each record's int field to a random value within the specified range
  set_random_record_values(records, num_records, min_value, max_value);

  // Configure curl session with the given URL and options
  curl_easy_setopt(curl, CURLOPT_URL, url);
  curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);
  if (disable_certificate_validation) {
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
  }

  // Return the initialized RequestBuilder object
  return &(RequestBuilder) {
    .curl = curl,
    .keys = keys,
    .values = values,
    .records = records,
  };
}
```
