int initialize(int num_records, long max_memory) {
    // Check if the input parameters are valid
    if (num_records < 0 || num_records > MAX_RECORDS) {
        return -1;
    }

    // Calculate the total memory required for all arrays
    long total_memory = sizeof(record) * num_records + sizeof(metadata) * num_records;

    // Check if the total memory exceeds the maximum allowed
    if (total_memory > max_memory) {
        return -2;
    }

    // Allocate memory for the record and metadata arrays
    record* records = malloc(sizeof(record) * num_records);
    metadata* metadata = malloc(sizeof(metadata) * num_records);

