int create_http_client(char *url, int num_elements, int disable_certificate_validation) {
  // Initialize curl handle and set options
  CURL *curl = curl_easy_init();
  if (!curl) {
    fprintf(stderr, "Failed to initialize curl handle\n");
    return -1;
  }

  // Set URL and disable certificate validation if necessary
  if (disable_certificate_validation) {
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
  }

  // Set the URL for the request
  curl_easy_setopt(curl, CURLOPT_URL, url);

  // Allocate memory for offset and key arrays
  long *offset_array = malloc(num_elements * sizeof(long));
  int *key_array = malloc(num_elements * sizeof(int));
  if (!offset_array || !key_array) {
    fprintf(stderr, "Failed to allocate memory for offset and key arrays\n");
    return -1;
  }

  // Initialize arrays with random values within a given range
  srand(time(NULL));
  for (int i = 0; i < num_elements; i++) {
    offset_array[i] = rand() % 100 + 1;
    key_array[i] = rand() % 100 + 1;
  }

  // Allocate memory for record structure array
  Record *record_array = malloc(num_elements * sizeof(Record));
  if (!record_array) {
    fprintf(stderr, "Failed to allocate memory for record array\n");
    return -1;
  }

  // Initialize record structure array with random values
  for (int i = 0; i < num_elements; i++) {
    record_array[i].key = key_array[i];
    record_array[i].offset = offset_array[i];
  }

  // Perform HTTP request and handle errors
  CURLcode res = curl_easy_perform(curl);
  if (res != CURLE_OK) {
    fprintf(stderr, "Failed to perform HTTP request: %s\n", curl_easy_strerror(res));
    return -1;
  }

  // Free memory for offset and key arrays
  free(offset_array);
  free(key_array);

  // Return record structure array
  return record_array;
}
