typedef struct {
    int value;
} record;

// Global variables for managing memory and threads
static long *offsets = NULL;
static int *keys = NULL;
static record *records = NULL;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Allocate and initialize records with random values within the specified range
void allocateAndInitializeRecords(long *offsets, int *keys, record *records) {
    // Allocate memory for offsets, keys, and records
    if ((offsets = (long *)malloc((sizeof(long) * 5))) == NULL ||
        (keys = (int *)malloc((sizeof(int) * 5))) == NULL ||
        (records = (record *)malloc((sizeof(record) * 5))) == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize offsets, keys, and records with random values within the specified range
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 5; i++) {
        offsets[i] = rand() % 10 + 1; // Random value between 1 and 10
        keys[i] = rand() % 26 + 97; // Random value between 'a' and 'z'
        records[i].value = rand() % 100; // Random value between 0 and 99
    }
}

// Initialize records with a single value
void initializeRecords(record *records) {
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 5; i++) {
        records[i].value = rand() % 100; // Random value between 0 and 99
    }
}

// Update a record with a new value
void updateRecord(record *record, int newValue) {
    pthread_mutex_lock(&lock);
    record->value = newValue;
    pthread_mutex_unlock(&lock);
}

// Free records allocated memory
void freeRecords(long *offsets, int *keys, record *records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}

// Test functions
void testAllocateAndInitializeRecords() {
    long offsets[5] = {0};
    int keys[5] = {0};
    record records[5] = {{0}};
    allocateAndInitializeRecords(offsets, keys, records);
    for (int i = 0; i < 5; i++) {
        printf("Record %d: Offset=%ld Key=%c Value=%d\n", i, offsets[i], keys[i], records[i].value);
    }
    freeRecords(offsets, keys, records);
}

void testInitializeRecords() {
    record records[5] = {{0}};
    initializeRecords(records);
    for (int i = 0; i < 5; i++) {
        printf("Record %d: Value=%d\n", i, records[i].value);
    }
}

void testUpdateRecord() {
    record records[1] = {{0}};
    updateRecord(records, 42);
    printf("Record 0: Value=%d\n", records[0].value);
}
```
