// Define constants for API key and timeout values
#define API_KEY "your_api_key"
#define FILE_READ_TIMEOUT 10
#define HTTP_REQUEST_TIMEOUT 5

// Function to perform HTTP GET requests to a given URL using standard library functions
int http_get(char *url, char **response) {
    // Define variables for CURL and JSON parsing
    CURL *curl;
    json_object *json;
    size_t len = 0;
    long code = 0;

    // Initialize CURL handle with URL and API key
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Authorization: Bearer " API_KEY);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, HTTP_REQUEST_TIMEOUT);
    } else {
        return -1;
    }

    // Perform GET request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "HTTP GET request failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    // Get response code and check for errors
    code = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
    if (code != 200) {
        fprintf(stderr, "HTTP GET request failed with response code %ld\n", code);
        return -1;
    }

    // Get response data and check for errors
    curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &len);
    if (len <= 0) {
        fprintf(stderr, "HTTP GET request returned no data\n");
        return -1;
    }
    *response = malloc(len + 1);
    if (*response == NULL) {
        fprintf(stderr, "Failed to allocate memory for HTTP response\n");
        return -1;
    }
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, *response);
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to read HTTP response data: %s\n", curl_easy_strerror(res));
        return -1;
    }

    // Parse JSON data and extract specific fields
    json = json_tokener_parse(*response);
    if (json == NULL) {
        fprintf(stderr, "Failed to parse JSON response: %s\n", json_tokener_error_text(json_tokener_get_error(json)));
        return -1;
    }
    struct json_object *temperature = json_object_object_get(json, "temperature");
    if (temperature == NULL) {
        fprintf(stderr, "JSON response missing 'temperature' field\n");
        return -1;
    }
    int temperature_value = json_object_get_int(temperature);
    printf("Temperature: %d\n", temperature_value);

    // Free memory and return success
    curl_easy_cleanup(curl);
    free(*response);
    return 0;
}

// Function to read a text file line by line, dynamically allocate memory for each line, and free it after use
char **read_file(const char *filename, int *num_lines) {
    // Define variables for file descriptor, buffer size, and line count
    int fd = -1;
    size_t bufsize = 0;
    long len = 0;
    int nlines = 0;

    // Open file with read-only permissions and check for errors
    fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open file");
        return NULL;
    }

    // Read file line by line and dynamically allocate memory for each line
    char *line = NULL;
    while ((len = getdelim(&line, &bufsize, '\n', fd)) > 0) {
        nlines++;
        char **new_lines = realloc(lines, (nlines + 1) * sizeof(char*));
        if (new_lines == NULL) {
            perror("Failed to allocate memory for lines");
            break;
        }
        lines = new_lines;
        lines[nlines - 1] = line;
    }

    // Close file descriptor and return number of lines read
    close(fd);
    *num_lines = nlines;
    return lines;
}

// Function to parse JSON data from the HTTP response and extract specific fields
void parse_json(char *response) {
    // Define variables for JSON parsing
    json_object *json = NULL;
    struct json_object *temperature = NULL;
    int temperature_value = 0;

    // Parse JSON data from HTTP response and extract specific fields
    json = json_tokener_parse(response);
    if (json == NULL) {
        fprintf(stderr, "Failed to parse JSON response: %s\n", json_tokener_error_text(json_tokener_get_error(json)));
        return;
    }
    temperature = json_object_object_get(json, "temperature");
    if (temperature == NULL) {
        fprintf(stderr, "JSON response missing 'temperature' field\n");
        return;
    }
    temperature_value = json_object_get_int(temperature);
    printf("Temperature: %d\n", temperature_value);
}

// Function to free memory and close file descriptor after use
void cleanup(char **lines, int num_lines) {
    // Free memory allocated for each line
    for (int i = 0; i < num_lines; i++) {
        free(lines[i]);
    }
    // Close file descriptor and free memory allocated for the lines array
    close(fd);
    free(lines);
}

// Main function to demonstrate HTTP GET request integration with JSON parsing and file reading
int main() {
    // Define variables for HTTP response, file name, and number of lines read
    char *response = NULL;
    const char *filename = "input.txt";
    int num_lines = 0;

    // Read text file line by line and dynamically allocate memory for each line
    char **lines = read_file(filename, &num_lines);

    // Loop through each line and make an HTTP GET request to retrieve JSON data
    for (int i = 0; i < num_lines; i++) {
        printf("Making HTTP GET request for %s...\n", lines[i]);
        int ret = http_get(lines[i], &response);
        if (ret != 0) {
            fprintf(stderr, "Failed to make HTTP GET request: %d\n", ret);
            continue;
        }
        // Parse JSON data and extract specific fields
        parse_json(response);
    }

    // Free memory and close file descriptor after use
    cleanup(lines, num_lines);
    return 0;
}
