using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Microsoft.VisualStudio.Threading;

namespace LoadCsvData {
    class Program {
        static void Main(string[] args) {
            // Initialize the list with predefined items
            initList();

            // Load data from a CSV file into the managed list of items
            using (var reader = new StreamReader("file.csv")) {
                string line;
                while ((line = reader.ReadLine()) != null) {
                    // Parse the current line
                    var values = line.Split(',');
                    if (values.Length == 3) {
                        // Create a new item with the parsed coordinates and ID
                        var item = new Item();
                        item.coord = float.Parse(values[0]);
                        item.id = int.Parse(values[1]);
                        item.label = values[2];

                        // Add the new item to the list
                        addItem(item);
                    } else {
                        // Skip this line and continue with the next one
                        continue;
                    }
                }
            }
        }
    }
}
