Here is an example implementation of the C function that dynamically allocates memory for and initializes three arrays: one for 'double' precision floating-point numbers, one for 'int' keys, and one for 'struct data_point' structures. Each 'struct data_point' contains a 'double' value and an 'int' timestamp.
```c
#include <stdlib.h>
#include <time.h>

// Structure to store data point information
typedef struct {
    double value;
    int timestamp;
} data_point_t;

// Function to allocate and initialize the arrays
void init_arrays(double** dbl_arr, int** key_arr, data_point_t*** data_pt_arr) {
    // Allocate memory for the double array
    *dbl_arr = malloc(sizeof(double) * 3);
    if (*dbl_arr == NULL) {
        printf("Error: Failed to allocate memory for the double array\n");
        exit(1);
    }

    // Allocate memory for the int key array
    *key_arr = malloc(sizeof(int) * 3);
    if (*key_arr == NULL) {
        printf("Error: Failed to allocate memory for the int key array\n");
        exit(1);
    }

    // Allocate memory for the data point array
    *data_pt_arr = malloc(sizeof(data_point_t*) * 3);
    if (*data_pt_arr == NULL) {
        printf("Error: Failed to allocate memory for the data point array\n");
        exit(1);
    }

    // Initialize the double array with random values within a given range
    srand(time(NULL));
    for (int i = 0; i < 3; ++i) {
        (*dbl_arr)[i] = (double)(rand() % 100) / 100.0;
    }

    // Initialize the int key array with random values within a given range
    for (int i = 0; i < 3; ++i) {
        (*key_arr)[i] = rand() % 100;
    }

    // Initialize the data point array with random values within a given range
    for (int i = 0; i < 3; ++i) {
        (*data_pt_arr)[i]->value = (double)(rand() % 100) / 100.0;
        (*data_pt_arr)[i]->timestamp = rand() % 100;
    }
}

// Function to free the allocated memory for the arrays
void free_arrays(double** dbl_arr, int** key_arr, data_point_t*** data_pt_arr) {
    free(*dbl_arr);
    *dbl_arr = NULL;
    free(*key_arr);
    *key_arr = NULL;
    for (int i = 0; i < 3; ++i) {
        free((*data_pt_arr)[i]);
        (*data_pt_arr)[i] = NULL;
    }
    free(*data_pt_arr);
    *data_pt_arr = NULL;
}

// Function to set the value of each record's data point's double field to a random value within a given range
void set_random_values(double** dbl_arr, int** key_arr, data_point_t*** data_pt_arr) {
    srand(time(NULL));
    for (int i = 0; i < 3; ++i) {
        (*dbl_arr)[i] = (double)(rand() % 100) / 100.0;
        (*key_arr)[i] = rand() % 100;
        (*data_pt_arr)[i]->value = (*dbl_arr)[i];
        (*data_pt_arr)[i]->timestamp = (*key_arr)[i];
    }
}
```
