// Define data structures for HTTP client and SSL context
struct http_client {
    CURL *curl;
    struct curl_slist *headers;
};

struct ssl_ctx {
    SSL_CTX *ssl_context;
    int cipher_suite;
};

// Define function to create an HTTP client with optional certificate validation
struct http_client *create_http_client(const char *url, bool validate_cert) {
    // Create a new HTTP client structure
    struct http_client *client = (struct http_client *) malloc(sizeof(struct http_client));
    if (!client) {
        fprintf(stderr, "Failed to allocate memory for HTTP client\n");
        return NULL;
    }

    // Initialize the HTTP client structure
    client->curl = curl_easy_init();
    if (!client->curl) {
        fprintf(stderr, "Failed to initialize cURL handle\n");
        free(client);
        return NULL;
    }

    // Set URL for the HTTP client
    curl_easy_setopt(client->curl, CURLOPT_URL, url);

    // Enable or disable certificate validation based on provided mode
    if (validate_cert) {
        curl_easy_setopt(client->curl, CURLOPT_SSL_VERIFYPEER, 1L);
        curl_easy_setopt(client->curl, CURLOPT_SSL_VERIFYHOST, 2L);
    } else {
        curl_easy_setopt(client->curl, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(client->curl, CURLOPT_SSL_VERIFYHOST, 0L);
    }

    // Initialize the headers for the HTTP client
    client->headers = NULL;

    return client;
}

// Define function to create an SSL context with a specified cipher suite
struct ssl_ctx *create_ssl_context(int cipher_suite) {
    // Create a new SSL context structure
    struct ssl_ctx *ctx = (struct ssl_ctx *) malloc(sizeof(struct ssl_ctx));
    if (!ctx) {
        fprintf(stderr, "Failed to allocate memory for SSL context\n");
        return NULL;
    }

    // Initialize the SSL context structure
    ctx->ssl_context = SSL_CTX_new(TLSv1_2_client_method());
    if (!ctx->ssl_context) {
        fprintf(stderr, "Failed to initialize SSL context\n");
        free(ctx);
        return NULL;
    }

    // Set the cipher suite for the SSL context
    switch (cipher_suite) {
        case TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256:
            SSL_CTX_set_cipher_list(ctx->ssl_context, "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256");
            break;
        case TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384:
            SSL_CTX_set_cipher_list(ctx->ssl_context, "TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384");
            break;
        default:
            fprintf(stderr, "Invalid cipher suite specified\n");
            SSL_CTX_free(ctx->ssl_context);
            free(ctx);
            return NULL;
    }

    // Set the cipher suite for the SSL context
    ctx->cipher_suite = cipher_suite;

    return ctx;
}

// Define function to handle logging of HTTP request details to a file
void log_http_request(const char *url, int status) {
    // Open or create a log file for the specified URL
    FILE *log_file = fopen("http_requests.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    // Write the HTTP request details to the log file
    fprintf(log_file, "%s %d\n", url, status);

    // Close the log file
    fclose(log_file);
}
