// Define the EVP_CIPHER structure to represent the chosen cipher
typedef struct {
    const EVP_CIPHER *cipher;
} EVP_CIPHER_T;

// Define the record structure for storing random int values
typedef struct {
    int value;
} RECORD_T;

// Function to generate a secure random IV using the given password and CBC mode
void generate_iv(char *password, unsigned char *iv, size_t iv_len) {
    // Generate a 128-bit hash of the password using SHA-512
    unsigned char hash[64];
    SHA512((unsigned char *)password, strlen(password), hash);

    // Use the first 128 bits as the IV
    memcpy(iv, hash, iv_len);
}

// Function to generate a secure random key using the given password and CBC mode
void generate_key(char *password, unsigned char *key, size_t key_len) {
    // Generate a 128-bit hash of the password using SHA-512
    unsigned char hash[64];
    SHA512((unsigned char *)password, strlen(password), hash);

    // Use the first 128 bits as the key
    memcpy(key, hash, key_len);
}

// Function to encrypt data using AES in CBC mode with a random IV and securely generated keys
EVP_CIPHER *encrypt_data(unsigned char *data, size_t data_len, unsigned char *key, size_t key_len, unsigned char *iv) {
    // Initialize the EVP_CIPHER structure to represent the chosen cipher
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Set the encryption mode and padding scheme
    int mode = EVP_CIPH_CBC_MODE;
    int padding = EVP_CIPH_PKCS7_PADDING;

    // Initialize the cipher context using the chosen mode and padding scheme
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing encryption context: %s\n", ERR_error_string(ERR_get_error(), NULL));
    }

    // Set the IV for CBC mode
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 16, NULL)) {
        fprintf(stderr, "Error setting IV length: %s\n", ERR_error_string(ERR_get_error(), NULL));
    }

    // Allocate memory for the output buffer and set its size to the input data length + 16 bytes (for the IV)
    unsigned char *output = malloc(data_len + 16);

