    if (!EVP_EncryptUpdate(ctx, output, &data_len, data, data_len)) {
        fprintf(stderr, "Error encrypting data: %s\n", ERR_error_string(ERR_get_error(), NULL));
    }

    // Set the output length to the input data length + 16 bytes (for the IV)
    *data_len += 16;

    // Free the cipher context and return the encrypted data
    EVP_CIPHER_CTX_free(ctx);
    return output;
}

// Function to decrypt data using AES in CBC mode with a random IV and securely generated keys
EVP_CIPHER *decrypt_data(unsigned char *data, size_t data_len, unsigned char *key, size_t key_len, unsigned char *iv) {
    // Initialize the EVP_CIPHER structure to represent the chosen cipher
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Set the decryption mode and padding scheme
    int mode = EVP_CIPH_CBC_MODE;
    int padding = EVP_CIPH_PKCS7_PADDING;

    // Initialize the cipher context using the chosen mode and padding scheme
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
