    if (!EVP_DecryptUpdate(ctx, output, &data_len, data, data_len)) {
        fprintf(stderr, "Error decrypting data: %s\n", ERR_error_string(ERR_get_error(), NULL));
    }

    // Set the output length to the input data length - 16 bytes (for the IV)
    *data_len -= 16;

    // Free the cipher context and return the decrypted data
    EVP_CIPHER_CTX_free(ctx);
    return output;
