    int* ids = malloc(num_items * sizeof(int));
    char** labels = malloc(num_items * sizeof(char*));

    // Initialize the arrays with random values within given ranges
    srand(time(NULL));
    for (int i = 0; i < num_items; i++) {
        coordinates[i] = ((float)rand() / RAND_MAX) * (max_coordinate - min_coordinate) + min_coordinate;
        ids[i] = ((int)rand() % max_id) + min_id;

        // Initialize the labels array with random characters within a predefined set of characters
        strcpy(labels[i], "");
        for (int j = 0; j < strlen(labels); j++) {
            labels[i][j] = labels[rand() % (strlen(labels) - 1)];
        }
    }

    // Allocate memory for the items array and initialize it with random values
    item* items = malloc(num_items * sizeof(item));
    for (int i = 0; i < num_items; i++) {
        items[i].coordinate = coordinates[i];
        items[i].id = ids[i];
        strcpy(items[i].label, labels[i]);
