int init_arrays(long *offset_arr, int *key_arr, record **records, size_t max_size) {
    pthread_mutex_lock(&mem_mutex);

    // allocate memory for offset and key arrays
    offset_arr = (long*)malloc(sizeof(long)*max_size);
    if (offset_arr == NULL) {
        perror("Failed to allocate memory for offset array");
        pthread_mutex_unlock(&mem_mutex);
        return -1;
    }

    key_arr = (int*)malloc(sizeof(int)*max_size);
    if (key_arr == NULL) {
        perror("Failed to allocate memory for key array");
        free(offset_arr);
        pthread_mutex_unlock(&mem_mutex);
        return -1;
    }

    // allocate memory for records array
    records = (record**)malloc(sizeof(record*)*max_size);
    if (records == NULL) {
        perror("Failed to allocate memory for records array");
        free(offset_arr);
        free(key_arr);
        pthread_mutex_unlock(&mem_mutex);
        return -1;
    }

    // initialize offset and key arrays with random values within range
    srand(time(NULL));
    for (size_t i = 0; i < max_size; i++) {
        offset_arr[i] = rand() % 10000;
        key_arr[i] = rand() % 1000;

        // allocate memory for each record and initialize its int field with a random value within range
        records[i] = (record*)malloc(sizeof(record));
        if (records[i] == NULL) {
            perror("Failed to allocate memory for record");
            free(offset_arr);
            free(key_arr);
            for (size_t j = 0; j < i; j++) {
                free(records[j]);
            }
            pthread_mutex_unlock(&mem_mutex);
            return -1;
        }

        records[i]->key = rand() % 1000;
    }

    // log memory allocation success or failure to file for debugging purposes
    FILE *log_file = fopen("memory_allocation.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file for writing");
        free(offset_arr);
        free(key_arr);
        for (size_t i = 0; i < max_size; i++) {
            free(records[i]);
        }
        pthread_mutex_unlock(&mem_mutex);
        return -1;
    }

    fprintf(log_file, "Allocated memory for arrays of size %zu\n", max_size);
    fclose(log_file);

    // unlock the mutex to allow other threads to access the memory
    pthread_mutex_unlock(&mem_mutex);

    return 0;
}
