    key[index] = (int)(rand() % 100);

    // Set the value of the value array at the specified index to a random double value within a given range
    value[index] = (double)((rand() % 100) / 10.0);

    // Update the record at the specified index with new values for both key and value
    records[index].key = key[index];
    records[index].value = value[index];
}

