#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Define the data structure for records
typedef struct {
    long offset;
    int key;
    int value;
} record_t;

int main() {
    // Read the offset and key files
    FILE *offsets = fopen("offsets.txt", "r");
    FILE *keys = fopen("keys.txt", "r");

    if (!offsets || !keys) {
        printf("Error reading input files\n");
        return 1;
    }

    // Initialize the offset and key arrays
    long *offset_arr = NULL;
    int *key_arr = NULL;
    size_t num_records = 0;
    while (!feof(offsets)) {
        long offset;
        fscanf(offsets, "%ld", &offset);
        if (offset == 0) break; // stop reading when encountering a zero value
        num_records++;
    }
    offset_arr = malloc(sizeof(long) * num_records);
    key_arr = malloc(sizeof(int) * num_records);
    if (!offset_arr || !key_arr) {
        printf("Error allocating memory for arrays\n");
        return 1;
    }

    // Read the offset and key values into the arrays
    size_t i = 0;
    while (fscanf(offsets, "%ld", &offset_arr[i]) != EOF) {
        if (offset_arr[i] == 0) break; // stop reading when encountering a zero value
        fscanf(keys, "%d", &key_arr[i]);
        i++;
    }

    // Set the record values to random values within the given range
    srand(time(NULL));
    for (size_t j = 0; j < num_records; j++) {
        long offset = offset_arr[j];
        int key = key_arr[j];
        int value = rand() % (offset + key); // random value between 1 and offset + key
        record_t *record = &(record_arr[j]);
        record->offset = offset;
        record->key = key;
        record->value = value;
    }

    // Free the memory allocated for the arrays
    free(offset_arr);
    free(key_arr);

    return 0;
}

// Function to perform DNS resolution using standard library functions
u_char *dnsResolve(const char *hostname) {
    struct addrinfo hints, *res;
    int error;
    u_char ip[INET6_ADDRSTRLEN];

    // Initialize the hints structure with default values
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error) {
        // Handle DNS resolution errors
        printf("Error resolving hostname: %s\n", gai_strerror(error));
        return NULL;
    }

    // Return the first IP address found for the given hostname
    struct addrinfo *ptr = res;
    while (ptr != NULL) {
        getnameinfo(ptr->ai_addr, ptr->ai_addrlen, ip, INET6_ADDRSTRLEN, NULL, 0, NI_NUMERICHOST);
        freeaddrinfo(res);
        return ip;
    }

    // Handle DNS resolution errors
    printf("Error resolving hostname: %s\n", gai_strerror(error));
    return NULL;
}']

