// C function to dynamically allocate memory for and initialize three arrays: offset, key, and record
void init_arrays(const char *offsets_filepath, const char *keys_filepath) {
    // Define variables to store file pointers and array sizes
    FILE *offsets_fp = NULL;
    FILE *keys_fp = NULL;
    size_t num_offsets = 0;
    size_t num_keys = 0;

    // Open the files for reading
    offsets_fp = fopen(offsets_filepath, "r");
    keys_fp = fopen(keys_filepath, "r");

    // Check if files were opened successfully
    if (offsets_fp == NULL || keys_fp == NULL) {
        printf("Error opening file(s)\n");
        return;
    }

    // Count the number of lines in each file to determine array sizes
    while (!feof(offsets_fp)) {
        if (fgets(buffer, MAX_BUFFER_SIZE, offsets_fp) != NULL) {
            num_offsets++;
        }
    }
    rewind(offsets_fp);
    while (!feof(keys_fp)) {
        if (fgets(buffer, MAX_BUFFER_SIZE, keys_fp) != NULL) {
            num_keys++;
        }
    }
    rewind(keys_fp);

    // Allocate memory for the arrays
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    record *records = malloc(num_offsets * sizeof(record));

    // Check if memory was allocated successfully
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error allocating memory\n");
        return;
    }

    // Read the offset and key values from the files into the arrays
    size_t i = 0;
    while (!feof(offsets_fp)) {
        if (fgets(buffer, MAX_BUFFER_SIZE, offsets_fp) != NULL) {
            offsets[i] = strtol(buffer, NULL, 10);
            i++;
        }
    }
    size_t j = 0;
    while (!feof(keys_fp)) {
        if (fgets(buffer, MAX_BUFFER_SIZE, keys_fp) != NULL) {
            keys[j] = strtol(buffer, NULL, 10);
            j++;
        }
    }

    // Initialize the record structures with the appropriate values from the offset and key arrays
    for (i = 0; i < num_offsets; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i % num_keys];
        records[i].int_field = rand() % (records[i].offset + records[i].key); // Set random int field value within range
    }

    // Close the files and free memory
    fclose(offsets_fp);
    fclose(keys_fp);
    free(offsets);
    free(keys);
    free(records);
}

// C function to perform DNS resolution for a given hostname using standard library functions
int resolve_hostname(const char *hostname) {
    // Define variables to store IP address and error code
    struct addrinfo hints;
    struct addrinfo *result = NULL;
    int error = 0;

    // Initialize the hint structure with default values
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // Use IPv4 for now
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    // Call the getaddrinfo function to resolve the hostname and retrieve an addrinfo structure
    error = getaddrinfo(hostname, NULL, &hints, &result);
    if (error != 0) {
        printf("Error resolving hostname: %s\n", gai_strerror(error));
        return -1;
    }

    // Extract the IP address from the addrinfo structure and return it
    struct in_addr *ip = &((struct sockaddr_in *)(result->ai_addr))->sin_addr;
    char *ip_str = inet_ntoa(*ip);
    if (ip_str == NULL) {
        printf("Error converting IP address to string\n");
        return -1;
    }
    freeaddrinfo(result); // Free the memory allocated by getaddrinfo
    return strtol(ip_str, NULL, 10); // Return the IP address as a long integer
}

