// Function to initialize a new session with the given parameters
session_t *init_session(int mode, int padding, unsigned char *key, unsigned char *iv) {
    // Check input arguments for validity
    if (mode != ECB && mode != CBC && mode != CFB && mode != OFB) {
        return NULL;
    }
    if (padding != NO_PADDING && padding != PKCS7) {
        return NULL;
    }
    // Allocate memory for the session structure
    session_t *session = malloc(sizeof(session_t));
    if (!session) {
        return NULL;
    }
    // Initialize the cipher context and set the mode and padding scheme
    EVP_CIPHER_CTX_init(&session->ctx);
    session->mode = mode;
    session->padding = padding;
    // Set the key and IV for the cipher context
    if (key) {
        memcpy(session->key, key, AES_KEYLEN);
        EVP_CIPHER_CTX_set_key(&session->ctx, session->key, AES_KEYLEN * 8);
    } else {
        generate_secure_random(session->key, AES_KEYLEN);
        EVP_CIPHER_CTX_set_key(&session->ctx, session->key, AES_KEYLEN * 8);
    }
    if (iv) {
        memcpy(session->iv, iv, AES_IVLEN);
        EVP_CIPHER_CTX_set_iv(&session->ctx, session->iv, AES_IVLEN);
    } else {
        generate_secure_random(session->iv, AES_IVLEN);
        EVP_CIPHER_CTX_set_iv(&session->ctx, session->iv, AES_IVLEN);
    }
    // Return the initialized session structure
    return session;
}

// Function to encrypt data using the given session
int encrypt(session_t *session, unsigned char *data, int len) {
    // Check input arguments for validity
    if (!session || !data || len <= 0) {
        return -1;
    }
    // Set the mode and padding scheme for the cipher context
    EVP_CIPHER_CTX_init(&session->ctx);
    EVP_CIPHER_CTX_set_padding(&session->ctx, session->padding);
    // Encrypt the data using the chosen cipher mode
    switch (session->mode) {
        case ECB:
            return EVP_EncryptUpdate(&session->ctx, data, len);
        case CBC:
            return EVP_EncryptUpdate(&session->ctx, data, len);
        case CFB:
            return EVP_EncryptUpdate(&session->ctx, data, len);
        case OFB:
            return EVP_EncryptUpdate(&session->ctx, data, len);
    }
}

// Function to decrypt data using the given session
int decrypt(session_t *session, unsigned char *data, int len) {
    // Check input arguments for validity
    if (!session || !data || len <= 0) {
        return -1;
    }
    // Set the mode and padding scheme for the cipher context
    EVP_CIPHER_CTX_init(&session->ctx);
    EVP_CIPHER_CTX_set_padding(&session->ctx, session->padding);
    // Decrypt the data using the chosen cipher mode
    switch (session->mode) {
        case ECB:
            return EVP_DecryptUpdate(&session->ctx, data, len);
        case CBC:
            return EVP_DecryptUpdate(&session->ctx, data, len);
        case CFB:
            return EVP_DecryptUpdate(&session->ctx, data, len);
        case OFB:
            return EVP_DecryptUpdate(&session->ctx, data, len);
    }
}

// Function to handle edge cases where the input data length is not a multiple of the block size by padding or truncating data during encryption and decryption
int handle_block_size(session_t *session, unsigned char *data, int len) {
    // Check input arguments for validity
    if (!session || !data || len <= 0) {
        return -1;
    }
    // Handle edge cases where the input data length is not a multiple of the block size by padding or truncating data during encryption and decryption
    switch (session->mode) {
        case ECB:
            // Pad the data to make it a multiple of the block size if necessary
            return EVP_EncryptUpdate(&session->ctx, data, len);
        case CBC:
            // Truncate the data to make it a multiple of the block size if necessary
            return EVP_DecryptUpdate(&session->ctx, data, len);
        case CFB:
            // Pad the data to make it a multiple of the block size if necessary
            return EVP_EncryptUpdate(&session->ctx, data, len);
        case OFB:
            // Truncate the data to make it a multiple of the block size if necessary
            return EVP_DecryptUpdate(&session->ctx, data, len);
    }
}
