// Function to dynamically allocate memory for and initialize three arrays: one for 'long' offsets, one for 'int' keys, and one for 'record' structures
void initArrays(long** offsetPtr, int** keyPtr, record*** recordPtr) {
    // Read offsets from file
    ifstream inFile("offsets.txt");
    string line;
    vector<long> offsets;
    while (getline(inFile, line)) {
        offsets.push_back(stol(line));
    }
    inFile.close();

    // Read keys from file
    ifstream inFile2("keys.txt");
    vector<int> keys;
    while (getline(inFile2, line)) {
        keys.push_back(stoi(line));
    }
    inFile2.close();

    // Initialize arrays
    *offsetPtr = new long[offsets.size()];
    for (int i = 0; i < offsets.size(); ++i) {
        (*offsetPtr)[i] = offsets[i];
    }

    *keyPtr = new int[keys.size()];
    for (int i = 0; i < keys.size(); ++i) {
        (*keyPtr)[i] = keys[i];
    }

    // Initialize record structures
    *recordPtr = new record*[offsets.size()];
    for (int i = 0; i < offsets.size(); ++i) {
        record** records = new record*[keys.size()];
        for (int j = 0; j < keys.size(); ++j) {
            int value = *offsetPtr + *keyPtr;
            if (value > 100) {
                break;
            }
            records[j] = new record(value);
        }
        (*recordPtr)[i] = records;
    }
}

// Function to set the value of each record's int field to a random value within a given range
void setRandomValues(int min, int max) {
    for (int i = 0; i < offsets.size(); ++i) {
        for (int j = 0; j < keys.size(); ++j) {
            (*recordPtr)[i][j]->setValue(rand() % (max - min + 1) + min);
        }
    }
}

// Function to perform DNS resolution for a given hostname and return the IP address in a u_char array
void dnsResolution(const string& hostname, u_char* ip) {
    // Use standard library functions to resolve DNS
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname.c_str(), NULL, &hints, &res)) != 0) {
        cout << "DNS resolution error: " << gai_strerror(status) << endl;
        return;
    }

    // Iterate through the results and pick the first one that is a valid IPv4 address
    for (struct addrinfo *rp = res; rp != NULL; rp = rp->ai_next) {
        void *addr;
        if (rp->ai_family == AF_INET && rp->ai_addrlen >= sizeof(struct sockaddr_in)) {
            addr = &((struct sockaddr_in*)rp->ai_addr)->sin_addr;
            break;
        }
    }

    // If an IPv4 address was found, convert it to a string and store it in the u_char array
    if (addr != NULL) {
        const char* ipStr = inet_ntoa((struct in_addr) * (struct sockaddr_in*) addr);
        strcpy(ip, ipStr);
    }
}
