    Record *records; // Pointer to an array of record structures
} DataSet;

// Memory management functions

// Allocate memory for a new record structure and initialize it with random values within the given range
Record* create_record(int min, int max) {
    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        return NULL;
    }

    // Generate a random integer between min and max
    record->key = rand() % (max - min + 1) + min;

    return record;
}

// Allocate memory for an array of records and initialize each one with a random value within the given range
Record* create_records(int count, int min, int max) {
    Record *records = malloc(sizeof(Record) * count);
    if (records == NULL) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i] = create_record(min, max);
    }

    return records;
}

// Free the memory allocated by create_records()
void free_records(Record *records) {
    if (records == NULL) {
        return;
    }

    for (int i = 0; i < count; i++) {
        free(records[i]);
    }

    free(records);
}

// Allocate memory for an array of offsets and initialize each one with the offset of a record in the data set
Offset* create_offsets(DataSet *data) {
    Offset *offsets = malloc(sizeof(Offset) * data->count);
    if (offsets == NULL) {
        return NULL;
    }

    for (int i = 0; i < data->count; i++) {
        offsets[i] = &data->records[i];
    }

    return offsets;
}

// Allocate memory for an array of keys and initialize each one with the key value of a record in the data set
Key* create_keys(DataSet *data) {
    Key *keys = malloc(sizeof(Key) * data->count);
    if (keys == NULL) {
        return NULL;
    }

    for (int i = 0; i < data->count; i++) {
        keys[i] = &data->records[i].key;
    }

    return keys;
}

// Update the value of a record in the data set using the given offset and new key value
void update_record(DataSet *data, Offset offset, int new_key) {
    Record *record = (Record *)offset;
    if (record == NULL) {
        return;
    }

    record->key = new_key;
}

// Sort the records in the data set based on their offset values in ascending order using a quicksort algorithm
void sort_records(DataSet *data) {
    if (data == NULL || data->count <= 1) {
        return;
    }

    // Partition function for quicksort
    void partition(Record *low, Record *high, int pivot) {
        Record *i = low;
        Record *j = high - 1;

        while (true) {
            while ((i < high) && (*i).key <= pivot) {
                i++;
            }
            while ((j >= low) && (*j).key > pivot) {
                j--;
            }
            if (i >= j) {
                break;
            }
            Record temp = *i;
            *i = *j;
            *j = temp;
        }
    }

    // Recursive quicksort function
    void quicksort(Record *low, Record *high) {
        if (low < high) {
            int pivot = (*low).key;
            partition(low, high, pivot);
            quicksort(low, j);
            quicksort(i + 1, high);
        }
    }

    // Call the quicksort function to sort the records in the data set
    quicksort(data->records, data->count);
}

// Free the memory allocated by create_offsets() and create_keys()
void free_offsets_and_keys(Offset *offsets, Key *keys) {
    if (offsets == NULL || keys == NULL) {
        return;
    }

    for (int i = 0; i < data->count; i++) {
        free(offsets[i]);
        free(keys[i]);
    }

    free(offsets);
    free(keys);
}

// Return a copy of the sorted records in the data set using the given offset array
Record* sort_records_by_offset(DataSet *data, Offset *offsets) {
    if (data == NULL || offsets == NULL) {
        return NULL;
    }

    Record *sorted = malloc(sizeof(Record) * data->count);
    if (sorted == NULL) {
        return NULL;
    }

    for (int i = 0; i < data->count; i++) {
        sorted[i] = *offsets[i];
    }

    return sorted;
}

// Free the memory allocated by sort_records_by_offset()
void free_sorted_records(Record *sorted) {
    if (sorted == NULL) {
        return;
    }

    free(sorted);
}
