        // Dynamically resize the array by 50% when it's full
        int new_capacity = array->capacity * 1.5;
        record_t** new_records = realloc(array->records, new_capacity * sizeof(record_t*));
        if (!new_records) {
            perror("Failed to resize record array");
            exit(EXIT_FAILURE);
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }
    // Allocate memory for the new record
    int index = array->size++;
    array->records[index] = malloc(sizeof(record_t));
    if (!array->records[index]) {
        perror("Failed to allocate memory for new record");
