    array->records[index]->value = value;
    array->records[index]->string_value = strdup(string_value);
}

// Search for a record by key within the record array
record_t* record_array_search(record_array_t* array, int key) {
    for (int i = 0; i < array->size; i++) {
        if (array->records[i]->key == key) {
            return array->records[i];
        }
    }
    return NULL;
}

// Sort the record array based on the keys
