    qsort(array->records, array->size, sizeof(record_t), compare_keys);
}

// Free all memory allocated by the record array
void record_array_free(record_array_t* array) {
    for (int i = 0; i < array->size; i++) {
        free(array->records[i]->string_value);
        free(array->records[i]);
    }
    free(array->records);
    free(array);
}

// Function to compare keys for sorting records
int compare_keys(const void* a, const void* b) {
    record_t** record_a = (record_t**)a;
    record_t** record_b = (record_t**)b;
    return (*record_a)->key - (*record_b)->key;
}
