    char* string_value;
};

// Define the dynamic data structure for storing records
typedef struct {
    struct Record** records;
    size_t capacity; // number of slots in the array
    size_t size;     // current number of records
} DynamicDataStructure;

// Function to initialize a new dynamic data structure with an initial capacity
DynamicDataStructure* init(size_t capacity) {
    DynamicDataStructure* ds = malloc(sizeof(DynamicDataStructure));
    if (!ds) {
        fprintf(stderr, "Failed to allocate memory for the dynamic data structure\n");
        return NULL;
    }
    ds->records = malloc(capacity * sizeof(struct Record*));
    if (!ds->records) {
        fprintf(stderr, "Failed to allocate memory for the record array\n");
        free(ds);
        return NULL;
    }
    ds->capacity = capacity;
    ds->size = 0;
    return ds;
}

// Function to insert a new record into the dynamic data structure
void insert_record(DynamicDataStructure* ds, int int_value, double double_value, char* string_value) {
    // Check if the data structure needs to be resized
    if (ds->size == ds->capacity) {
        // Double the capacity of the data structure
        size_t new_capacity = 2 * ds->capacity;
        struct Record** new_records = realloc(ds->records, new_capacity * sizeof(struct Record*));
        if (!new_records) {
            fprintf(stderr, "Failed to allocate memory for the record array\n");
            return;
        }
        ds->records = new_records;
        ds->capacity = new_capacity;
    }
    // Insert the new record into the data structure
    struct Record* new_record = malloc(sizeof(struct Record));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for the new record\n");
        return;
    }
    new_record->int_value = int_value;
    new_record->double_value = double_value;
    new_record->string_value = string_value;
    ds->records[ds->size++] = new_record;
}

// Function to update an existing record in the dynamic data structure
void update_record(DynamicDataStructure* ds, size_t index, int int_value, double double_value, char* string_value) {
    // Check if the index is out of bounds
    if (index >= ds->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    // Update the record at the specified index
    struct Record* record = ds->records[index];
    record->int_value = int_value;
    record->double_value = double_value;
    record->string_value = string_value;
}

// Function to delete an existing record from the dynamic data structure
void delete_record(DynamicDataStructure* ds, size_t index) {
    // Check if the index is out of bounds
    if (index >= ds->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    // Delete the record at the specified index
    struct Record* record = ds->records[index];
    free(record);
    // Shift all subsequent records to fill the gap
    for (size_t i = index + 1; i < ds->size; ++i) {
        ds->records[i - 1] = ds->records[i];
    }
    --ds->size;
}

// Function to free all memory associated with the dynamic data structure
void free_dynamic_data_structure(DynamicDataStructure* ds) {
    for (size_t i = 0; i < ds->capacity; ++i) {
        free(ds->records[i]);
    }
    free(ds->records);
}
