    TemperatureReading* reading = malloc(sizeof(TemperatureReading));
    if (reading == NULL) {
        return NULL;
    }
    return reading;
}

// Function to initialize a temperature reading with given location and timestamp
void init_temperature_reading(TemperatureReading* reading, char* location, int timestamp) {
    strcpy(reading->location, location);
    reading->timestamp = timestamp;
    reading->temperature = 0.0f;
}

// Function to update the temperature value of a temperature reading
void update_temperature_reading(TemperatureReading* reading, float temperature) {
    reading->temperature = temperature;
}

// Function to free memory for a temperature reading
void free_temperature_reading(TemperatureReading* reading) {
    free(reading);
}

// Higher-level structure to manage an array of temperature readings
typedef struct TemperatureReadings {
    int num_readings;
    TemperatureReading** readings;
} TemperatureReadings;

// Function to allocate memory for a new temperature readings structure
TemperatureReadings* alloc_temperature_readings() {
    TemperatureReadings* readings = malloc(sizeof(TemperatureReadings));
    if (readings == NULL) {
        return NULL;
    }
    readings->num_readings = 0;
    readings->readings = NULL;
    return readings;
}

// Function to initialize a temperature readings structure with given capacity
void init_temperature_readings(TemperatureReadings* readings, int capacity) {
    readings->num_readings = 0;
    readings->readings = malloc(capacity * sizeof(TemperatureReading*));
    if (readings->readings == NULL) {
        free(readings);
        return NULL;
    }
}

// Function to add a new temperature reading to the array of temperature readings
void add_temperature_reading(TemperatureReadings* readings, char* location, int timestamp, float temperature) {
    if (readings->num_readings == 0) {
        init_temperature_readings(readings, 1);
    } else if (readings->num_readings >= readings->capacity) {
        TemperatureReading** new_readings = realloc(readings->readings, (readings->capacity + 1) * sizeof(TemperatureReading*));
        if (new_readings == NULL) {
            free_temperature_readings(readings);
            return;
        }
        readings->readings = new_readings;
        readings->capacity++;
    }
    TemperatureReading* reading = alloc_temperature_reading();
    if (reading == NULL) {
        free_temperature_readings(readings);
        return;
    }
    init_temperature_reading(reading, location, timestamp);
    update_temperature_reading(reading, temperature);
    readings->readings[readings->num_readings++] = reading;
}

// Function to free memory for a temperature readings structure
void free_temperature_readings(TemperatureReadings* readings) {
    if (readings == NULL) {
        return;
    }
    for (int i = 0; i < readings->num_readings; i++) {
        free_temperature_reading(readings->readings[i]);
    }
    free(readings->readings);
    free(readings);
}
```
