    }

    // Allocate memory for the ID array
    *ids = (int *)malloc(sizeof(int) * MAX_ITEMS);
    if (*ids == NULL) {
        fprintf(stderr, "Failed to allocate memory for IDs\n");
        exit(EXIT_FAILURE);
    }

