void init_items(Item **items) {
    // Allocate memory for the items array
    *items = (Item *)malloc(sizeof(Item) * MAX_ITEMS);
    if (*items == NULL) {
        fprintf(stderr, "Failed to allocate memory for items\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the items array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < MAX_ITEMS; ++i) {
        (*items)[i].coord = ((float)rand() / (float)RAND_MAX) * 200.0 - 100.0;
        (*items)[i].id = rand() % 100 + 1;
        (*items)[i].label = predefined_chars[rand() % 26];
    }
}

// Function to update an item in the array of items
void update_item(Item **items, int index, float coord, int id, char label) {
    // Check if the index is valid
    if (index < 0 || index >= MAX_ITEMS) {
        fprintf(stderr, "Invalid index %d\n", index);
        return;
    }

    // Update the item's fields with the new values
    (*items)[index].coord = coord;
    (*items)[index].id = id;
    (*items)[index].label = label;
}

// Function to free the memory allocated for the arrays of coordinates, IDs, and labels
void free_arrays(float **coords, int **ids, char ***labels) {
    // Check if the pointers are NULL
    if (*coords == NULL || *ids == NULL || *labels == NULL) {
        return;
    }

    // Free the memory for each array
    free(*coords);
    free(*ids);
    for (int i = 0; i < MAX_ITEMS; ++i) {
        free((*labels)[i]);
    }
    free(*labels);
}

