    // Check if the pointer is NULL
    if (*items == NULL) {
        return;
    }

    // Free the memory for each item in the array
    for (int i = 0; i < MAX_ITEMS; ++i) {
        free((*items)[i].coord);
        free((*items)[i].id);
        free((*items)[i].label);
    }
    free(*items);
}
