    size_t num_offsets;
} offset_values_t;

typedef struct {
    int *keys;
    size_t num_keys;
} key_values_t;

typedef struct {
    int value;
} record_t;

// Function to generate random values within specified ranges
void generate_random_values(offset_values_t *offsets, key_values_t *keys) {
    // Seed the random number generator with the current time
    srand((unsigned int)time(NULL));

    // Allocate memory for offset values and initialize them randomly
    offsets->num_offsets = 100;
    offsets->offsets = malloc(sizeof(long) * offsets->num_offsets);
    for (size_t i = 0; i < offsets->num_offsets; i++) {
        offsets->offsets[i] = rand() % 1000000;
    }

    // Allocate memory for key values and initialize them randomly
    keys->num_keys = 100;
    keys->keys = malloc(sizeof(int) * keys->num_keys);
    for (size_t i = 0; i < keys->num_keys; i++) {
        keys->keys[i] = rand() % 1000000;
    }
}

// Function to update an existing record using the HTTP PUT method and return the updated record
record_t *update_record(const char *id, const char *body) {
    // Find the record with the given ID in the records array
    for (size_t i = 0; i < num_records; i++) {
        if (strcmp(records[i].id, id) == 0) {
            // Update the record using the given body data
            records[i].value = atoi(body);
            return &records[i];
        }
    }

    // If no matching record was found, create a new one and return it
    record_t *new_record = malloc(sizeof(record_t));
    new_record->id = strdup(id);
    new_record->value = atoi(body);
    records[num_records++] = new_record;
    return new_record;
}

// Function to free the memory allocated for the offset values, key values, and records
void free_memory(offset_values_t *offsets, key_values_t *keys, record_t **records) {
    // Free the memory allocated for the offset values
    if (offsets->offsets != NULL) {
        free(offsets->offsets);
        offsets->num_offsets = 0;
    }

    // Free the memory allocated for the key values
    if (keys->keys != NULL) {
        free(keys->keys);
        keys->num_keys = 0;
    }

    // Free the memory allocated for the records
    for (size_t i = 0; i < num_records; i++) {
        record_t *record = records[i];
