// Define the data structure to store items
typedef struct {
    float coordinate;
    int id;
    char label;
} Item;

// Function to safely allocate and initialize a new item
Item* create_item(float coordinate, int id, char label) {
    // Allocate memory for the item
    Item *new_item = (Item*) malloc(sizeof(Item));
    if (new_item == NULL) {
        return NULL;
    }

    // Initialize the item's fields
    new_item->coordinate = coordinate;
    new_item->id = id;
    new_item->label = label;

    return new_item;
}

// Function to safely update an existing item
void update_item(Item *item, float coordinate, int id, char label) {
    // Update the item's fields
    item->coordinate = coordinate;
    item->id = id;
    item->label = label;
}

// Function to safely free an allocated item
void free_item(Item *item) {
    if (item != NULL) {
        free(item);
    }
}

// Define the collection data structure
typedef struct {
    Item items[MAX_ITEMS];
    int size;
} Collection;

// Function to safely allocate and initialize a new collection
Collection* create_collection() {
    // Allocate memory for the collection
    Collection *new_collection = (Collection*) malloc(sizeof(Collection));
    if (new_collection == NULL) {
        return NULL;
    }

    // Initialize the collection's size to 0
    new_collection->size = 0;

    return new_collection;
}

// Function to safely add an item to a collection
void add_item(Collection *collection, Item *item) {
    // Check if the collection is full
    if (collection->size >= MAX_ITEMS) {
        return;
    }

    // Add the item to the collection
    collection->items[collection->size] = *item;
    collection->size++;
}

// Function to safely remove an item from a collection
void remove_item(Collection *collection, int index) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        return;
    }

    // Remove the item at the specified index
    collection->items[index] = collection->items[collection->size - 1];
    collection->size--;
}

// Function to safely retrieve an item from a collection by its index
Item* get_item(Collection *collection, int index) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        return NULL;
    }

    // Return the item at the specified index
    return &collection->items[index];
}

// Function to safely retrieve the size of a collection
int get_size(Collection *collection) {
    return collection->size;
}

// Function to safely free a collection
void free_collection(Collection *collection) {
    if (collection != NULL) {
        for (int i = 0; i < collection->size; i++) {
            free_item(&collection->items[i]);
        }
        free(collection);
    }
}

