    struct RequestBuilder* request_builder = malloc(sizeof(struct RequestBuilder));
    if (!request_builder) {
        // Handle memory allocation failure gracefully
        return NULL;
    }
    struct Record* records = malloc(num_records * sizeof(struct Record));
    if (!records) {
        // Handle memory allocation failure gracefully
        free(request_builder);
        return NULL;
    }

    // Initialize the request builder and records
