int load_resource_bundle(const char *filepath) {
    // Allocate memory for the resource bundle
    struct ResourceBundle *bundle = malloc(sizeof(struct ResourceBundle));
    if (!bundle) {
        // Handle memory allocation failure gracefully
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Open the file containing the resource bundle
    FILE *file = fopen(filepath, "r");
    if (!file) {
        // Handle file opening failure gracefully
        free(bundle);
        return FILE_OPEN_FAILURE;
    }

    // Read the number of items in the resource bundle from the file
    int num_items = 0;
    fscanf(file, "%d", &num_items);

    // Allocate memory for the items in the resource bundle
    bundle->items = malloc(sizeof(struct ResourceItem) * num_items);
    if (!bundle->items) {
        // Handle memory allocation failure gracefully
        free(bundle);
        fclose(file);
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Read the items from the file into the resource bundle
    for (int i = 0; i < num_items; i++) {
        struct ResourceItem *item = &bundle->items[i];
        fscanf(file, "%d %s %s", &item->id, item->name, item->description);
    }

    // Close the file and return the number of items in the resource bundle
    fclose(file);
    return num_items;
}

