#include <stdlib.h>
#include <time.h>
#include <stdio.h>

// Define a structure for the record
struct record {
    int value;
};

// Define a function to generate a random integer within a given range
int random_integer(int min, int max) {
    // Generate a random number between min and max using the rand() function from stdlib.h
    return min + (rand() % (max - min + 1));
}

// Define a function to allocate and initialize memory for an array of 'record' structures
struct record* allocate_records(int num_records, int min_value, int max_value) {
    // Check if the number of records is valid
    if (num_records <= 0 || max_value - min_value < num_records) {
        printf("Error: Invalid number of records\n");
        return NULL;
    }

    // Allocate memory for the array of 'record' structures
    struct record* records = (struct record*)malloc(num_records * sizeof(struct record));
    if (!records) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize each record with a random integer value within the given range
    for (int i = 0; i < num_records; i++) {
        records[i].value = random_integer(min_value, max_value);
    }

    return records;
}

// Define a function to allocate and initialize memory for two arrays: one for 'long' offset values and one for 'int' keys
void* allocate_arrays(int num_records, int min_offset, int max_offset, int min_key, int max_key) {
    // Check if the number of records is valid
    if (num_records <= 0 || max_offset - min_offset < num_records || max_key - min_key < num_records) {
        printf("Error: Invalid number of records\n");
        return NULL;
    }

    // Allocate memory for the two arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!offsets || !keys) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize each offset and key with a random value within the given range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = random_integer(min_offset, max_offset);
        keys[i] = random_integer(min_key, max_key);
    }

    return (void*)offsets;
}

// Main function that demonstrates how to use the allocate_records() and allocate_arrays() functions
int main() {
    // Allocate an array of records with 100 elements, each with a random integer value within the range [0, 10]
    struct record* records = allocate_records(100, 0, 10);
    if (!records) {
        printf("Error: Failed to allocate memory\n");
        return 1;
    }

    // Allocate an array of two arrays with 20 elements each, each with a random integer value within the range [0, 5]
