```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the data structures
typedef struct Record {
    int key;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
} LinkedList;

// Define the function signature
void initialize_records(int num_records, int min_value, int max_value, struct LinkedList *list) {
    // Check if the number of records is valid
    if (num_records < 0) {
        printf("Invalid number of records\n");
        return;
    }

    // Check if the range for the random values is valid
    if (max_value <= min_value) {
        printf("Invalid range for random values\n");
        return;
    }

    // Allocate memory for the offset array
    long *offset_array = (long *)malloc(num_records * sizeof(long));
    if (!offset_array) {
        // Memory allocation failed
        printf("Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    int *key_array = (int *)malloc(num_records * sizeof(int));
    if (!key_array) {
        // Memory allocation failed
        printf("Failed to allocate memory for key array\n");
        free(offset_array);
        return;
    }

    // Allocate memory for the record array
    Record *record_array = (Record *)malloc(num_records * sizeof(Record));
    if (!record_array) {
        // Memory allocation failed
        printf("Failed to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Initialize the offset array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize the key array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key_array[i] = rand() % max_value;
    }

    // Initialize the record array with the key and value arrays
    for (int i = 0; i < num_records; i++) {
        record_array[i].key = key_array[i];
        record_array[i].value = offset_array[i];
    }

    // Insert the records into the linked list in sorted order based on their keys
    Node *current = list->head;
    for (int i = 0; i < num_records; i++) {
        while (current != NULL && current->record.key > record_array[i].key) {
            current = current->next;
        }
        if (current == NULL) {
            // No matching key found, insert new node at end of list
            Node *new_node = create_node(record_array[i]);
            list->head = new_node;
        } else {
            // Matching key found, update existing node with new value
            current->record.value = record_array[i].value;
        }
    }

    // Free memory for the offset array, key array, and record array
    free(offset_array);
    free(key_array);
    free(record_array);
}
```
This implementation uses a combination of `malloc` and `free` to allocate and release memory dynamically. It also uses `srand` and `rand` to generate random values for the offset array, key array, and record array. The `initialize_records` function checks if the number of records is valid and if the range for the random values is valid before proceeding with allocation and initialization.

