typedef struct record {
    int key;
    double value;
    struct record* next;
} record_t;

// Functions to manage memory for arrays of records
void init_records(record_t** records, size_t num_records);
void update_records(record_t** records, size_t index, int key, double value);
void traverse_records(record_t* records);
void free_records(record_t** records);

