void init_linked_list(record_t** head_ref);
void insert_at_head(record_t** head_ref, int key, double value);
void insert_at_position(record_t** head_ref, size_t index, int key, double value);
void traverse_linked_list(record_t* head);
void free_linked_list(record_t** head_ref);

int main() {
    // Initialize arrays for offsets, keys, and values
    long* offsets = NULL;
    int* keys = NULL;
    double* values = NULL;

    // Initialize linked list of records
    record_t* head = NULL;

    // Allocate memory for arrays
    size_t num_records = 1000000;
    init_records(&records, num_records);

    // Allocate memory for linked list
    init_linked_list(&head);

    // Initialize random values for arrays and linked list
