        keys[i] = rand() % 100;
        values[i] = ((double)rand()) / RAND_MAX;
        insert_at_head(&head, keys[i], values[i]);
    }

    // Traverse linked list and print records
    traverse_linked_list(head);

    // Free memory for arrays and linked list
    free_records(&records);
    free_linked_list(&head);

    return 0;
}

void init_records(record_t** records, size_t num_records) {
    *records = (record_t*)my_malloc(sizeof(record_t) * num_records);
    if (*records == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for records\n");
        exit(1);
    }
    memset(*records, 0, sizeof(record_t) * num_records);
}

void update_records(record_t** records, size_t index, int key, double value) {
    if (index >= 0 && index < num_records) {
        (*records)[index].key = key;
        (*records)[index].value = value;
    } else {
        // Handle invalid input
        printf("Error: Invalid record index\n");
    }
}

void traverse_records(record_t* records) {
    for (size_t i = 0; i < num_records; i++) {
        printf("%d, %f, %p\n", (*records)[i].key, (*records)[i].value, (*records)[i].next);
    }
}

void free_records(record_t** records) {
    if (*records != NULL) {
        my_free(*records);
        *records = NULL;
    }
}

void init_linked_list(record_t** head_ref) {
    *head_ref = (record_t*)my_malloc(sizeof(record_t));
    if (*head_ref == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for linked list\n");
        exit(1);
    }
    memset(*head_ref, 0, sizeof(record_t));
}

void insert_at_head(record_t** head_ref, int key, double value) {
    record_t* new_node = (record_t*)my_malloc(sizeof(record_t));
    if (new_node == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for linked list\n");
        exit(1);
    }
    new_node->key = key;
    new_node->value = value;
    new_node->next = *head_ref;
    *head_ref = new_node;
}

void insert_at_position(record_t** head_ref, size_t index, int key, double value) {
    if (index == 0) {
        // Insert at head of linked list
        insert_at_head(head_ref, key, value);
    } else {
        record_t* temp = *head_ref;
        for (size_t i = 0; i < index - 1; i++) {
            if (temp->next != NULL) {
                temp = temp->next;
            } else {
