{
    int n = 0; // number of nodes to allocate

    printf("Enter the number of nodes: ");
    scanf("%d", &n);

    if (n <= 0)
    {
        printf("Invalid input. The number of nodes must be greater than zero.");
        return 1;
    }

    initializeLinkedList(n);

    traverseLinkedList();

    return 0;
}

void initializeLinkedList(int n)
{
    // allocate memory for the linked list nodes and initialize them
    Node *nodes = (Node *)malloc(sizeof(Node) * n);

    if (!nodes)
    {
        printf("Memory allocation failed. Could not create the linked list.");
        return;
    }

    // initialize the random number generator with the current time
    srand(time(NULL));

    for (int i = 0; i < n; i++)
    {
        nodes[i].value = rand() % 100;
        nodes[i].next = NULL;
    }
}

void traverseLinkedList()
{
    // declare a variable to keep track of the current node
    Node *currentNode = head;

    while (currentNode)
    {
        printf("%d ", currentNode->value);
        currentNode = currentNode->next;
    }
}
