typedef struct {
    double value;
} data_point;

// Function to initialize an array of data points with random values
void initialize_data_points(data_point **points, int count) {
    // Allocate memory for the arrays
    *points = (data_point *)malloc(count * sizeof(data_point));

    // Initialize the random number generator
    srand((unsigned)time(NULL));

    // Loop through each data point and set a random value within the specified range
