// Function to validate and set a value for a data point
void validate_and_set_value(data_point *point) {
    // Ensure the value is within the specified range
    if (point->value >= 0.0 && point->value <= 100.0) {
        // Check if the value contains any repeated digits when represented as a string
        char str[20];
        sprintf(str, "%f", point->value);
        int j = 0;
        for (int i = 0; i < strlen(str); i++) {
            if (j > 0 && str[i] == str[j]) {
                break;
            } else {
                j++;
            }
        }
        // If the value does not contain any repeated digits, set it to the random value
        if (j == strlen(str)) {
            point->value = ((double)rand() / (RAND_MAX)) * 100.0;
        }
    } else {
