// Function to convert data to a JSON string
void convert_to_json(struct record* records, size_t num_records) {
    // Create a JSON object with the number of records as its root value
    json_object* root = json_object_new_int(num_records);

    // Iterate over each record and add it to the JSON object
    for (size_t i = 0; i < num_records; i++) {
