    if (!root) {
        fprintf(stderr, "Invalid JSON data\n");
        exit(1);
    }

    // Get the number of records from the JSON root value
    size_t num_records = json_object_get_int(root);

    // Allocate memory for the array of records and initialize it with the number of records
    struct record* records = malloc(num_records * sizeof(struct record));

    // Iterate over each JSON object in the root array and create a new instance from its values
    json_object* obj;
    size_t i = 0;
