#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash table as an array of linked lists
struct HashTable {
    int size;
    pthread_mutex_t* mutexes;
    Record** buckets;
};

// Initialize the hash table with a given size and number of mutexes
void initHashTable(int size, struct HashTable* table) {
    // Validate input parameters
    if (size <= 0 || size > 50) {
        printf("Invalid table size\n");
        return;
    }
    int numMutexes = size / 2 + 1;
    table->size = size;
    table->mutexes = (pthread_mutex_t*)malloc(numMutexes * sizeof(pthread_mutex_t));
    for (int i = 0; i < numMutexes; ++i) {
        pthread_mutex_init(&table->mutexes[i], NULL);
    }
    table->buckets = (Record**)malloc(size * sizeof(Record*));
    for (int i = 0; i < size; ++i) {
        table->buckets[i] = NULL;
    }
}

// Add a new record to the hash table
void addRecord(int key, long offset, struct HashTable* table) {
    // Validate input parameters
    if (key < 0 || key > INT_MAX || offset < 0 || offset > LONG_MAX) {
        printf("Invalid key or offset\n");
        return;
    }

    // Calculate the hash value and bucket index
    int hashValue = key % table->size;
    int bucketIndex = hashValue / 2 + 1;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[bucketIndex]);

    // Check if a record with the same key already exists in the table
    Record* existingRecord = findRecord(key, table);
    if (existingRecord != NULL) {
        printf("A record with this key already exists\n");
        pthread_mutex_unlock(&table->mutexes[bucketIndex]);
        return;
    }

    // Create a new record and add it to the bucket
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = offset;
    table->buckets[bucketIndex] = newRecord;

    // Unlock the mutex for the corresponding bucket
    pthread_mutex_unlock(&table->mutexes[bucketIndex]);
}

// Find a record in the hash table by its key
Record* findRecord(int key, struct HashTable* table) {
    if (key < 0 || key > INT_MAX) {
        printf("Invalid key\n");
        return NULL;
    }

    // Calculate the hash value and bucket index
    int hashValue = key % table->size;
    int bucketIndex = hashValue / 2 + 1;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[bucketIndex]);

    // Iterate over the linked list in the bucket and check for a match
    Record* currentRecord = table->buckets[bucketIndex];
    while (currentRecord != NULL) {
        if (currentRecord->key == key) {
            pthread_mutex_unlock(&table->mutexes[bucketIndex]);
            return currentRecord;
        }
        currentRecord = currentRecord->next;
    }

    // If no match is found, return NULL
    pthread_mutex_unlock(&table->mutexes[bucketIndex]);
    return NULL;
}

// Remove a record from the hash table by its key
void removeRecord(int key, struct HashTable* table) {
    if (key < 0 || key > INT_MAX) {
        printf("Invalid key\n");
        return;
    }

    // Calculate the hash value and bucket index
    int hashValue = key % table->size;
    int bucketIndex = hashValue / 2 + 1;

    // Lock the mutex for the corresponding bucket
    pthread_mutex_lock(&table->mutexes[bucketIndex]);

    // Iterate over the linked list in the bucket and check for a match
    Record* currentRecord = table->buckets[bucketIndex];
    Record* previousRecord = NULL;
    while (currentRecord != NULL) {
        if (currentRecord->key == key) {
            if (previousRecord == NULL) {
                // Remove the head of the linked list
                table->buckets[bucketIndex] = currentRecord->next;
            } else {
                // Remove a record in the middle or at the end of the linked list
                previousRecord->next = currentRecord->next;
            }

            // Unlock the mutex for the corresponding bucket
            pthread_mutex_unlock(&table->mutexes[bucketIndex]);

            // Free the record memory
            free(currentRecord);
            return;
        }
        previousRecord = currentRecord;
        currentRecord = currentRecord->next;
    }

    // If no match is found, unlock the mutex for the corresponding bucket and return
    pthread_mutex_unlock(&table->mutexes[bucketIndex]);
}

// Implement error handling for memory allocation failures
void* allocateMemory(size_t size) {
    void* memory = malloc(size);
    if (memory == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return memory;
}

// Implement linear probing for collisions in the hash table
int probeLinear(int hashValue, struct HashTable* table) {
    int bucketIndex = hashValue % table->size;
    while (table->buckets[bucketIndex] != NULL && table->mutexes[bucketIndex].locked) {
        // Increment the hash value and recalculate the bucket index using linear probing
        hashValue++;
        bucketIndex = hashValue % table->size;
    }
    return bucketIndex;
}

// Implement a thread-safe mechanism for accessing and modifying the hash table
void accessHashTable(int op, int key, long offset, struct HashTable* table) {
    switch (op) {
        case 0: // Add record
            addRecord(key, offset, table);
            break;
        case 1: // Find record
            findRecord(key, table);
            break;
        case 2: // Remove record
            removeRecord(key, table);
            break;
    }
}

// Implement a thread-safe mechanism for iterating over the hash table and performing operations on each record
void iterateHashTable(int op, struct HashTable* table) {
    pthread_mutex_lock(&table->mutex);
    // Iterate over all buckets in the hash table
    for (int i = 0; i < table->size; i++) {
        // Iterate over all records in each bucket
        Record* currentRecord = table->buckets[i];
        while (currentRecord != NULL) {
            // Perform an operation on each record, such as printing its key and value
            accessHashTable(op, currentRecord->key, currentRecord->offset, table);
            currentRecord = currentRecord->next;
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

// Implement a thread-safe mechanism for cleaning up the hash table and freeing its memory
void cleanupHashTable(struct HashTable* table) {
    pthread_mutex_lock(&table->mutex);
    // Iterate over all buckets in the hash table and free their memory
    for (int i = 0; i < table->size; i++) {
        Record* currentRecord = table->buckets[i];
        while (currentRecord != NULL) {
            Record* nextRecord = currentRecord->next;
            // Free the record memory
            free(currentRecord);
            currentRecord = nextRecord;
        }
    }
    pthread_mutex_unlock(&table->mutex);
}
```

