int get_record(hash_table_t* table, int key) {
    // Check if the key is within the range of the hash table
    if (key < 0 || key >= table->size) {
        printf("Error: Key is out of range\n");
        return -1;
    }

    // Find the index of the record in the hash table
    int index = key % table->size;

    // Check if a record exists at the specified index
    if (!table->records[index]) {
        printf("Error: Record does not exist for key\n");
        return -1;
    }

    // Return the value of the found record
    return table->records[index]->value;
}

// Remove a record from the hash table with the specified key
