        keys[i] = min_value + rand() % (max_value - min_value + 1);
        records[i].value = keys[i];
    }

    // Insert the initialized records into a linked list in sorted order based on their key values
    struct RecordListNode* head = NULL;
    struct RecordListNode* tail = NULL;
    for (int i = 0; i < num_records; i++) {
        struct RecordListNode* node = malloc(sizeof(struct RecordListNode));
        if (!node) {
            log_error("Failed to allocate memory for record list node");
            break;
        }
        node->record = records[i];
        node->next = NULL;
        if (head == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }

    // Handle duplicate keys by updating the existing record with the new value and maintaining the integrity of the linked list structure
    struct RecordListNode* current = head;
    while (current) {
        if (current->next && current->record.value == current->next->record.value) {
            current->record.value = min_value + rand() % (max_value - min_value + 1);
            current->next->record.value = current->record.value;
        }
        current = current->next;
    }

    // Handle thread safety when accessing the list and ensure that the connection pool limits the maximum number of simultaneous connections while reusing existing connections when possible
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    struct RecordListNode* current = head;
    while (current) {
        pthread_mutex_lock(&mutex);
        // Handle connection establishment and maintenance timeouts
        if (!connect(current->record.value)) {
            log_error("Failed to establish a connection");
            break;
        }
        current = current->next;
    }

    // Free allocated memory for failed or closed connections promptly
    pthread_mutex_destroy(&mutex);
    free(offsets);
    free(keys);
    free(records);
}
