    for (int i = 0; i < size; i++) {
        parents[i] = i;
    }

    // Loop through the records array and find disjoint pairs of elements using the Union-Find algorithm
    for (int i = 0; i < size; i++) {
        int parent1 = parents[i];
        for (int j = i + 1; j < size; j++) {
            int parent2 = parents[j];
            if (parent1 == parent2) {
                // If the two elements are in the same connected component, they are not disjoint
                continue;
            }

            // Find the root of each element's connected component and union them together using the Union-Find algorithm
            while (parents[parent1] != parent1) {
                parent1 = parents[parent1];
            }
            while (parents[parent2] != parent2) {
                parent2 = parents[parent2];
            }
            if (parent1 != parent2) {
                // Union the two elements' connected components together
                parents[parent1] = parent2;
            }
        }
    }

    // Free the memory allocated for the parents array
    free(parents);
}

