#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Structures for storing data
struct record {
    int value;
};

struct product {
    int id;
    float price;
    double discount_rate;
};

// Function to dynamically allocate memory for and initialize arrays
void init_data(int num_records, int num_products, int min_offset, int max_offset) {
    // Allocate memory for the offset arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    int *keys = (int *)malloc(num_products * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return;
    }

    float *offset_values = (float *)malloc(num_records * sizeof(float));
    if (offset_values == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for offset values\n");
        return;
    }

    double *weight = (double *)malloc(num_products * sizeof(double));
    if (weight == NULL) {
        free(offsets);
        free(keys);
        free(offset_values);
        fprintf(stderr, "Failed to allocate memory for weights\n");
        return;
    }

    // Allocate memory for the product arrays
    struct record *records = (struct record *)malloc(num_records * sizeof(struct record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        free(offset_values);
        free(weight);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    struct product *products = (struct product *)malloc(num_products * sizeof(struct product));
    if (products == NULL) {
        free(offsets);
        free(keys);
        free(offset_values);
        free(weight);
        free(records);
        fprintf(stderr, "Failed to allocate memory for products\n");
        return;
    }

    // Generate random values within the specified ranges and store them in the respective structures
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].value = rand();
    }

    for (int j = 0; j < num_products; j++) {
        keys[j] = rand();
        offset_values[j] = (float)rand() / RAND_MAX;
        weight[j] = (double)rand() / RAND_MAX;
    }

    // Save the initialized data to a file in binary format
    FILE *fp = fopen("data.bin", "wb");
    if (fp == NULL) {
        free(offsets);
        free(keys);
        free(offset_values);
        free(weight);
        free(records);
        free(products);
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // Write the data to the file in binary format
    if (fwrite(offsets, sizeof(long), num_records, fp) != num_records ||
            fwrite(keys, sizeof(int), num_products, fp) != num_products ||
            fwrite(offset_values, sizeof(float), num_records, fp) != num_records ||
            fwrite(weight, sizeof(double), num_products, fp) != num_products ||
            fwrite(records, sizeof(struct record), num_records, fp) != num_records ||
            fwrite(products, sizeof(struct product), num_products, fp) != num_products) {
        free(offsets);
        free(keys);
        free(offset_values);
        free(weight);
        free(records);
        free(products);
        fclose(fp);
        fprintf(stderr, "Failed to write data to file\n");
        return;
    }

    // Close the file and free the memory
    fclose(fp);
    free(offsets);
    free(keys);
    free(offset_values);
    free(weight);
    free(records);
    free(products);
}

// Function to load initialized data from a file in binary format
void load_data(int *num_records, int *num_products) {
    // Open the file for reading
    FILE *fp = fopen("data.bin", "rb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    // Read the data from the file in binary format
    long *offsets = (long *)malloc(*num_records * sizeof(long));
    if (fread(offsets, sizeof(long), *num_records, fp) != *num_records) {
        free(offsets);
        fclose(fp);
        fprintf(stderr, "Failed to read data from file\n");
        return;
    }

    int *keys = (int *)malloc(*num_products * sizeof(int));
    if (fread(keys, sizeof(int), *num_products, fp) != *num_products) {
        free(offsets);
        free(keys);
        fclose(fp);
        fprintf(stderr, "Failed to read data from file\n");
        return;
    }

    float *offset_values = (float *)malloc(*num_records * sizeof(float));
    if (fread(offset_values, sizeof(float), *num_records, fp) != *num_records) {
        free(offsets);
        free(keys);
        free(offset_values);
        fclose(fp);
        fprintf(stderr, "Failed to read data from file\n");
        return;
    }

    double *weight = (double *)malloc(*num_products * sizeof(double));
    if (fread(weight, sizeof(double), *num_products, fp) != *num_products) {
        free(offsets);
        free(keys);
        free(offset_values);
        free(weight);
        fclose(fp);
        fprintf(stderr, "Failed to read data from file\n");
        return;
    }

    struct record *records = (struct record *)malloc(*num_records * sizeof(struct record));
    if (fread(records, sizeof(struct record), *num_records, fp) != *num_records) {
        free(offsets);
        free(keys);
        free(offset_values);
        free(weight);
        free(records);
        fclose(fp);
        fprintf(stderr, "Failed to read data from file\n");
        return;
    }

    struct product *products = (struct product *)malloc(*num_products * sizeof(struct product));
    if (fread(products, sizeof(struct product), *num_products, fp) != *num_products) {
        free(offsets);
        free(keys);
        free(offset_values);
        free(weight);
        free(records);
        free(products);
        fclose(fp);
        fprintf(stderr, "Failed to read data from file\n");
        return;
    }

    // Close the file and free the memory
    fclose(fp);
    free(offsets);
    free(keys);
    free(offset_values);
    free(weight);
    free(records);
    free(products);
}
