        return NULL;
    }
    for (int i = 0; i < size; i++) {
        array[i] = i; // Initialize each element with its index value
    }
    return array;
}

// Function to allocate and initialize memory for the record array
Record *allocate_record_array(size_t size) {
    Record *array = malloc(size * sizeof(Record));
    if (array == NULL) {
        printf("Error: failed to allocate memory for record array\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        array[i].value = i; // Initialize each element with its index value
    }
    return array;
}

// Function to dynamically resize the arrays when more space is needed
void resize_arrays(long **offset, int **key, Record ***record) {
    size_t new_size = (*offset)->capacity * 2;
    long *new_offset = realloc(*offset, new_size * sizeof(long));
    if (new_offset == NULL) {
        printf("Error: failed to resize offset array\n");
        return;
    }
    int *new_key = realloc(*key, new_size * sizeof(int));
    if (new_key == NULL) {
        printf("Error: failed to resize key array\n");
        free(new_offset);
        return;
    }
    Record **new_record = realloc(*record, new_size * sizeof(Record*));
    if (new_record == NULL) {
        printf("Error: failed to resize record array\n");
        free(new_offset);
        free(new_key);
        return;
    }
    for (int i = 0; i < new_size; i++) {
        // Initialize each element with its index value
        new_offset[i] = i;
        new_key[i] = i;
        new_record[i] = allocate_record(1);
    }
    *offset = new_offset;
    *key = new_key;
    *record = new_record;
}

// Function to set the value of each record's int field to a random value within a given range
void set_random_values(long *offset, int *key, Record **record) {
    for (int i = 0; i < offset->capacity; i++) {
        // Set the value of each record's int field to a random value within the range [0, 100]
        record[i]->value = rand() % 100;
    }
}

// Function to manage the lifecycle of these allocated resources by providing functions to safely allocate, initialize, update, and free the allocated memory
void initialize_record_array(long *offset, int *key, Record **record) {
