    }
    *labels = (char *)malloc(num_sensors * sizeof(char));
    if (*labels == NULL) {
        printf("Error: failed to allocate memory for sensor labels\n");
        exit(1);
    }

    // Initialize the arrays with random values within specified ranges
    srand(time(NULL));
    for (size_t i = 0; i < num_sensors; ++i) {
        (*coordinates)[i] = rand() % 201 - 100.0;
        (*ids)[i] = rand() % 101 + 1;
        (*labels)[i] = (rand() % 58) + 'A'; // range of characters from A to Z
    }
}

// Function to update the values of the arrays of 'float' coordinates, 'int' IDs, and 'char' labels
void update_sensor_data(float **coordinates, int *ids, char **labels) {
    // Allocate memory for the updated arrays
