        (*updated_coordinates)[i] = rand() % 201 - 100.0;
        (*updated_ids)[i] = rand() % 101 + 1;
        (*updated_labels)[i] = (rand() % 58) + 'A'; // range of characters from A to Z
    }

    // Free the old arrays and assign the updated ones
    free(*coordinates);
    *coordinates = updated_coordinates;
    free(*ids);
    *ids = updated_ids;
