    if (!sensor_data) {
        fprintf(stderr, "Error: Out of memory\n");
        return -1;
    }
    sensor_array->data[sensor_array->size] = sensor_data;
    sensor_array->size++;
    return 0;
}

// Function to remove a sensor data structure from the array
