        if (sensor_array->data[i]->id == id) {
            destroy_sensor_data(sensor_array->data[i]);
            memmove(&sensor_array->data[i], &sensor_array->data[i + 1], (sensor_array->size - i - 1) * sizeof(SensorData*));
            sensor_array->size--;
            return 0;
