// Function to allocate and initialize arrays for timestamp, event type, and sensor reading
void init_arrays(int n) {
    // Allocate memory for timestamp array
    double *timestamps = malloc(sizeof(double) * n);
    if (!timestamps) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    // Initialize timestamp array with current time in seconds
    for (int i = 0; i < n; i++) {
        timestamps[i] = time(NULL);
    }

    // Allocate memory for event type array
    char *event_types = malloc(sizeof(char) * n);
    if (!event_types) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    // Initialize event type array with '0' (unknown event type)
    for (int i = 0; i < n; i++) {
        event_types[i] = '0';
    }

    // Allocate memory for sensor reading array
    int *sensor_readings = malloc(sizeof(int) * n);
    if (!sensor_readings) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    // Initialize sensor reading array with '0' (unknown sensor reading)
    for (int i = 0; i < n; i++) {
        sensor_readings[i] = 0;
    }

    // Allocate memory for an array of sensor data structures
    sensor_data *sensor_data_array = malloc(sizeof(sensor_data) * n);
    if (!sensor_data_array) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    // Initialize each element of the array with a timestamp, event type, and sensor reading
    for (int i = 0; i < n; i++) {
        sensor_data_array[i].timestamp = timestamps[i];
        sensor_data_array[i].event_type = event_types[i];
        sensor_data_array[i].sensor_reading = sensor_readings[i];
    }

    // Free memory allocated for timestamp, event type, and sensor reading arrays
    free(timestamps);
    free(event_types);
    free(sensor_readings);
}
```
