```javascript
// Dependencies
const fs = require('fs');
const path = require('path');

// Function to read multiple files synchronously and return their contents as an array of strings
function read_files(file_paths) {
    // Initialize an empty array to store the file contents
    const file_contents = [];

    // Iterate over the file paths and read each file synchronously
    for (const file_path of file_paths) {
        try {
            // Read the file asynchronously and push its contents to the array
            const data = fs.readFileSync(file_path, 'utf8');
            file_contents.push(data);
        } catch (error) {
            console.error(`Failed to read file ${file_path}: ${error}`);
        }
    }

    // Return the array of file contents
    return file_contents;
}
```

