// Define structure for record data
typedef struct {
    int value;
    char* string;
} Record;

// Function to create and initialize arrays of long, int, and Record structures
int create_arrays(long** offsets, int** keys, Record*** records, int num_records) {
    // Check if input parameters are valid
    if (num_records <= 0 || num_records > 1000) {
        return -1;
    }

    // Allocate memory for arrays of long and int
    *offsets = malloc(sizeof(long) * num_records);
    *keys = malloc(sizeof(int) * num_records);

    // Check if memory allocation succeeded
    if (*offsets == NULL || *keys == NULL) {
        free(*offsets);
        free(*keys);
        return -2;
    }

    // Allocate memory for array of Record structures
    *records = malloc(sizeof(Record*) * num_records);

    // Check if memory allocation succeeded
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3;
    }

    // Initialize arrays of long, int, and Record structures
    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = rand() % 10000;
        (*keys)[i] = rand() % 1000;

        // Allocate memory for string pointer with random length between 1 and 100 characters
        int string_len = rand() % 100 + 1;
        char* string = malloc(string_len * sizeof(char));
        memset(string, '\0', string_len);

        // Check if memory allocation succeeded
        if (string == NULL) {
            free(*offsets);
            free(*keys);
            return -4;
        }

        // Set value of Record structure's int field to a random value within given range
        (*records)[i] = malloc(sizeof(Record));
        (*records)[i]->value = rand() % 1000;
        (*records)[i]->string = string;
    }

    return 0;
}

// Function to free all allocated memory
void free_arrays(long* offsets, int* keys, Record** records) {
    // Free memory for arrays of long and int
    free(offsets);
    free(keys);

    // Free memory for array of Record structures
    for (int i = 0; i < num_records; i++) {
        free((*records)[i]->string);
        free(*records);
    }
}
```
