    long *array = malloc(size * sizeof(long));
    if (array == NULL) {
        return NULL; // Return NULL on error
    }
    // Initialize the offset array with sequential values starting from 0
    for (int i = 0; i < size; i++) {
        array[i] = i * sizeof(long);
    }
