Record* allocate_record_array(int size) {
    Record *array = malloc(size * sizeof(Record));
    if (array == NULL) {
        return NULL; // Return NULL on error
    }
    // Initialize each record with a unique random value within a specified range
    for (int i = 0; i < size; i++) {
        array[i].key = generate_random_key();
        array[i].offset = generate_random_offset();
