bool safe_allocate_record_array(int size, Record** array) {
    if (size <= 0) {
        return false; // Return false on invalid input
    }
    *array = allocate_record_array(size);
    if (*array == NULL) {
        return false; // Return false on error
    }
    return true; // Return true on success
}

// Function to update an existing array of 'Record' structures with new values
bool safe_update_record_array(int size, Record** array) {
    if (size <= 0 || *array == NULL) {
        return false; // Return false on invalid input or error
    }
    for (int i = 0; i < size; i++) {
        (*array)[i].key = generate_random_key();
        (*array)[i].offset = generate_random_offset();
    }
    return true; // Return true on success
}

// Function to safely free an array of 'Record' structures
void safe_free_record_array(int size, Record** array) {
    if (size <= 0 || *array == NULL) {
        return; // Do nothing on invalid input or error
    }
    for (int i = 0; i < size; i++) {
        free((*array)[i].key);
        free((*array)[i].offset);
    }
    free(*array);
}

// Generate a random key within a specified range
int generate_random_key() {
    // Initialize the random seed
    srand(time(NULL));
    int min = 1; // Minimum value for the random key
    int max = 100; // Maximum value for the random key
    return rand() % (max - min + 1) + min;
}

// Generate a random offset within a specified range
long generate_random_offset() {
    // Initialize the random seed
    srand(time(NULL));
    long min = 0; // Minimum value for the random offset
    long max = LONG_MAX; // Maximum value for the random offset
    return (long)(rand() % (max - min + 1) + min);
}
