typedef struct {
    int key;
    long offset;
} record_t;

typedef struct {
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    record_t* records;
} hash_table_t;

/* Initializes a new hash table with the given capacity and initializes it to an empty state. */
hash_table_t* init_hash_table(size_t capacity) {
    hash_table_t* table = (hash_table_t*)malloc(sizeof(hash_table_t));
    table->capacity = capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    table->records = (record_t*)calloc(capacity, sizeof(record_t));
    return table;
}

/* Adds a new record to the hash table with the given key and offset. */
void add_record(hash_table_t* table, int key, long offset) {
    pthread_mutex_lock(&table->lock);
    if (table->size >= table->capacity) {
        /* Resize the hash table to accommodate more records. */
        table = resize_hash_table(table, 2 * table->capacity);
    }
    record_t* new_record = &table->records[table->size++];
    new_record->key = key;
    new_record->offset = offset;
    pthread_mutex_unlock(&table->lock);
}

/* Returns the record with the given key from the hash table, or NULL if no such record exists. */
record_t* get_record(hash_table_t* table, int key) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->size; ++i) {
        if (table->records[i].key == key) {
            record_t* result = &table->records[i];
            pthread_mutex_unlock(&table->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

/* Removes the record with the given key from the hash table. */
void remove_record(hash_table_t* table, int key) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->size; ++i) {
        if (table->records[i].key == key) {
            table->records[i] = table->records[--table->size];
            pthread_mutex_unlock(&table->lock);
            return;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

/* Returns the number of records in the hash table. */
size_t size(hash_table_t* table) {
    return table->size;
}

/* Frees all memory associated with the given hash table. */
void free_hash_table(hash_table_t* table) {
    pthread_mutex_destroy(&table->lock);
    free(table->records);
    free(table);
}

/* Resizes the given hash table to have the given capacity and returns a pointer to the resized table. */
hash_table_t* resize_hash_table(hash_table_t* table, size_t new_capacity) {
    hash_table_t* new_table = init_hash_table(new_capacity);
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->size; ++i) {
        add_record(new_table, table->records[i].key, table->records[i].offset);
    }
    pthread_mutex_unlock(&table->lock);
    free_hash_table(table);
    return new_table;
}
```

