void insert_record(Record *record) {
    if (!record) {
        log_error("Invalid record");
        return;
    }
    // Check if the linked list is empty
    if (head == NULL) {
        head = record;
        tail = record;
        return;
    }
    // Check if the new record has a lower key than the current head
    if (record->key < head->key) {
        record->next = head;
        head = record;
        return;
    }
    // Find the insertion point in the linked list
    Record *current = head;
    while (current->next != NULL && current->next->key < record->key) {
        current = current->next;
    }
    // Insert the new record at the found insertion point
    record->next = current->next;
    current->next = record;
}

// Function to free memory for a record and remove it from the linked list
void remove_record(Record *record) {
    if (!record) {
        log_error("Invalid record");
        return;
    }
    pthread_mutex_lock(&mutex);
    Record *current = head;
    // Check if the head is the record to be removed
    if (head == record) {
        head = head->next;
        free(record);
        pthread_mutex_unlock(&mutex);
        return;
    }
    while (current != NULL && current->next != record) {
        current = current->next;
    }
    // Remove the record from the linked list
    if (current != NULL) {
        Record *next = record->next;
        free(record);
        current->next = next;
        pthread_mutex_unlock(&mutex);
        return;
    }
}
