        operation_params.max_random_value = INT32_MAX;
    }

    // Perform cipher operation on input file and store result in output file
    pthread_t thread;
    if (pthread_create(&thread, NULL, &cryptographer, &operation_params) != 0) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }
    pthread_join(thread, NULL);

    // Close log file and mutex
    fclose(log_file);
    pthread_mutex_destroy(&log_mutex);

    return 0;
}
