class Item {
    public float coordinate;
    public int id;
    public char label;
}

class Config {
    private static string configFile = "config.txt";
    private static Dictionary<string, string> settings = new Dictionary<string, string>();

    // Load configuration settings from a file
    public static void LoadSettings() {
        // Check if the configuration file exists
        if (!File.Exists(configFile)) {
            Console.WriteLine("Configuration file not found");
            return;
        }

        // Read the configuration file and load the settings
        using (StreamReader reader = new StreamReader(configFile)) {
            string line;
            while ((line = reader.ReadLine()) != null) {
                if (line.StartsWith("#") || String.IsNullOrWhiteSpace(line)) {
                    continue;
                }

                // Split the line into key and value parts
                string[] parts = line.Split('=');
                if (parts.Length != 2) {
                    Console.WriteLine("Invalid setting format: " + line);
                    continue;
                }

                // Add the setting to the dictionary
                settings[parts[0].Trim()] = parts[1].Trim();
            }
        }
    }

    // Get a configuration setting by key
    public static string GetSetting(string key) {
        return settings.ContainsKey(key) ? settings[key] : null;
    }
}

class Program {
    private static List<Item> items = new List<Item>();

    static void Main(string[] args) {
        // Load the configuration settings from a file
        Config.LoadSettings();

        // Initialize the item structures based on the configuration settings
        int numItems = Convert.ToInt32(Config.GetSetting("num_items"));
        float coordMin = Convert.ToSingle(Config.GetSetting("coord_min"));
        float coordMax = Convert.ToSingle(Config.GetSetting("coord_max"));
        int idMin = Convert.ToInt32(Config.GetSetting("id_min"));
        int idMax = Convert.ToInt32(Config.GetSetting("id_max"));
        char labelCharset = Config.GetSetting("label_charset")[0];
        for (int i = 0; i < numItems; i++) {
            items.Add(new Item() {
                coordinate = generateCoordinate(coordMin, coordMax),
                id = generateID(idMin, idMax),
                label = generateLabel(labelCharset)
            });
        }

        // Print the initialized item structures
        foreach (var item in items) {
            Console.WriteLine($"Item: Coordinate={item.coordinate}, ID={item.id}, Label={item.label}");
        }
    }

    private static float generateCoordinate(float min, float max) {
        return (float)(min + Math.Random() * (max - min));
    }

    private static int generateID(int min, int max) {
        return min + Convert.ToInt32((Math.Random() * (max - min)));
    }

    private static char generateLabel(char charset) {
        return Convert.ToChar(Convert.ToInt32((Math.Random() * 26)) + 'A');
    }
}
