void init_union_find(Item* items, int num_items) {
    // Initialize each item's rank and parent as itself
    for (int i = 0; i < num_items; i++) {
        items[i].rank = 1;
        items[i].parent = &items[i];
    }
}

// Define the function to find the root of an item in the Union-Find data structure
Item* find_root(Item* item) {
    // If the item's parent is not itself, update its parent recursively
    if (item->parent != item) {
        item->parent = find_root(item->parent);
    }

    return item->parent;
}

// Define the function to union two items in the Union-Find data structure
void union_(Item* item1, Item* item2) {
    // Find the roots of both items
    Item* root1 = find_root(item1);
    Item* root2 = find_root(item2);

    // If the two roots are the same, there is no need to union them
    if (root1 == root2) {
        return;
    }

    // If the rank of the first item is higher than the second item, make the second item a child of the first item
    if (root1->rank > root2->rank) {
        root2->parent = root1;
    } else {
        root1->parent = root2;

        // If the rank of the two items is the same, increase the rank of the second item by 1
        if (root1->rank == root2->rank) {
            root2->rank++;
        }
    }
}

// Define the function to check whether two items are in the same connected component in the Union-Find data structure
bool is_connected(Item* item1, Item* item2) {
    // Find the roots of both items
    Item* root1 = find_root(item1);
    Item* root2 = find_root(item2);

    // If the two roots are the same, return true
    if (root1 == root2) {
        return true;
    }

    return false;
}
