/* Define data structures for the offset, key, and record arrays */
struct offset {
    long value;
};

struct key {
    int value;
};

struct record {
    int value;
};

/* Function to allocate memory for an array of 'size' elements */
void *allocate(int size) {
    void *ptr = NULL;
    if (size > 0) {
        ptr = malloc(sizeof(struct offset) * size);
        if (!ptr) {
            printf("Error: Memory allocation failed\n");
        }
    }
    return ptr;
}

/* Function to initialize an array of 'size' elements with a value */
void initialize(void *array, int size, long value) {
    if (array && size > 0) {
        struct offset *offset_array = (struct offset *)array;
        for (int i = 0; i < size; i++) {
            offset_array[i].value = value;
        }
    }
}

/* Function to update an array of 'size' elements with a new value */
void update(void *array, int size, long value) {
    if (array && size > 0) {
        struct offset *offset_array = (struct offset *)array;
        for (int i = 0; i < size; i++) {
            offset_array[i].value = value;
        }
    }
}

/* Function to safely free memory allocated by allocate() */
void free_memory(void *ptr) {
    if (ptr) {
        free(ptr);
    }
}

/* Thread-safe function to resize an array of 'size' elements */
void resize(void **array, int size, int new_size) {
    void *new_ptr = allocate(new_size);
    if (new_ptr) {
        /* Copy the contents of the old array to the new one */
        struct offset *old_array = (struct offset *)*array;
        struct offset *new_array = (struct offset *)new_ptr;
        for (int i = 0; i < size && i < new_size; i++) {
            new_array[i].value = old_array[i].value;
        }
        free_memory(*array);
        *array = new_ptr;
    } else {
        /* Handle resizing failure gracefully */
        printf("Error: Memory allocation failed\n");
    }
}

