void* allocate_memory(size_t size) {
    void* memory = NULL;
    if (size > 0) {
        memory = malloc(size);
        if (memory == NULL) {
            printf("Error: Failed to allocate %zu bytes of memory\n", size);
            return NULL;
        }
    }
    return memory;
}

void initialize_arrays(long** offset_arr, int** key_arr, record_t*** rec_arr, size_t* num_records) {
    *offset_arr = (long*)allocate_memory(sizeof(long) * (*num_records));
    if (*offset_arr == NULL) {
        return;
    }

    *key_arr = (int*)allocate_memory(sizeof(int) * (*num_records));
    if (*key_arr == NULL) {
        free(*offset_arr);
        *offset_arr = NULL;
        return;
    }

    *rec_arr = (record_t**)allocate_memory(sizeof(record_t*) * (*num_records));
    if (*rec_arr == NULL) {
        free(*offset_arr);
        free(*key_arr);
        *key_arr = NULL;
        return;
    }

    memset(*rec_arr, 0, sizeof(record_t*) * (*num_records));
}

void* thread_safe_allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_mutex);
    void* memory = allocate_memory(size);
    pthread_mutex_unlock(&memory_mutex);
    return memory;
}

void thread_safe_initialize_arrays(long** offset_arr, int** key_arr, record_t*** rec_arr, size_t* num_records) {
