        offset_arr[i] = (long)(offset_min + (offset_max - offset_min) * rand() / (RAND_MAX + 1.0));
        key_arr[i] = (int)(key_min + (key_max - key_min) * rand() / (RAND_MAX + 1.0));
        value_arr[i] = (double)(value_min + (value_max - value_min) * rand() / (RAND_MAX + 1.0));
