        int key = strtol(strtok(NULL, " ,\t"), NULL, 10);
        double value = strtod(strtok(NULL, ",\t"), NULL);

        // Update record arrays with parsed values
        for (int i = 0; i < 3; i++) {
            if (records[i].offset == offset) {
                records[i].key = key;
                records[i].value = value;
            }
        }
    }

    // Close input file and free memory
    fclose(fp);
    free(offset_arr);
