void initializeProducts(size_t num_products) {
    // Allocate memory for the four arrays
    struct product *coordinates = malloc(num_products * sizeof(*coordinates));
    int *ids = malloc(num_products * sizeof(*ids));
    char *labels = malloc(num_products * sizeof(*labels));
    uint32_t *weights = malloc(num_products * sizeof(*weights));

    // Check for memory allocation failures and handle them gracefully
    if (coordinates == NULL || ids == NULL || labels == NULL || weights == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize the arrays with random values within their respective ranges
    for (size_t i = 0; i < num_products; ++i) {
        coordinates[i].coordinate = ((double)rand() / RAND_MAX) * 1000.0 - 1000.0;
        ids[i] = rand() % 1000 + 1;
        labels[i] = 'A' + (rand() % 26);
        weights[i] = rand() % 100 + 1;
    }

    // Allocate memory for the product array
    struct product *products = malloc(num_products * sizeof(*products));

    // Check for memory allocation failures and handle them gracefully
    if (products == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize the product array with the values from the other arrays
