    // Read number of data points from first line of the file
    char buffer[256];
    fgets(buffer, sizeof(buffer), fp);
    int num_data_points = atoi(buffer);

    // Allocate memory for offset array
    *offset_arr = (long*) malloc(num_data_points * sizeof(long));
    if (*offset_arr == NULL) {
        printf("Error allocating memory for offset array\n");
        fclose(fp);
        return;
    }

    // Initialize offset array with file offsets
    long offset = 0;
    for (int i = 0; i < num_data_points; ++i) {
        fseek(fp, offset, SEEK_SET);
        (*offset_arr)[i] = ftell(fp);
        offset += sizeof(long);
    }

    // Allocate memory for key array
    *key_arr = (int*) malloc(num_data_points * sizeof(int));
    if (*key_arr == NULL) {
        printf("Error allocating memory for key array\n");
        free(*offset_arr);
        fclose(fp);
        return;
    }

    // Initialize key array with file keys
    int key = 0;
    for (int i = 0; i < num_data_points; ++i) {
        (*key_arr)[i] = key++;
    }

    // Allocate memory for value array
    *val_arr = (float**) malloc(num_data_points * sizeof(float*));
    if (*val_arr == NULL) {
        printf("Error allocating memory for value array\n");
        free(*offset_arr);
        free(*key_arr);
        fclose(fp);
        return;
    }

    // Initialize value array with file values
    float val = 0.0f;
    for (int i = 0; i < num_data_points; ++i) {
        (*val_arr)[i] = &val;
    }

    // Read data from file and populate arrays
    int idx = 0;
    while (!feof(fp)) {
        fscanf(fp, "%d %f", &((*key_arr)[idx]), &((*val_arr)[idx]));
        (*offset_arr)[idx] = ftell(fp);
        ++idx;
    }

    // Check for I/O errors and handle gracefully
    if (ferror(fp)) {
        printf("Error reading from file %s\n", filepath);
        free(*offset_arr);
        free(*key_arr);
        free(*val_arr);
        fclose(fp);
        return;
    }

    // Close file
    fclose(fp);
}
