// Function to read values from configuration file and initialize arrays
int init_arrays(const char *config_file, data_entry **data) {
    // Open configuration file for reading
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return -1;
    }

    // Count the number of entries in the configuration file
    int num_entries = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (!strncmp(line, "entry", strlen("entry"))) {
            num_entries++;
        }
    }

    // Allocate memory for arrays of double precision floating-point numbers, integers, and strings
    data_entry *entries = malloc(num_entries * sizeof(*entries));
    if (entries == NULL) {
        perror("Error allocating memory for array of data entries");
        return -1;
    }

    // Initialize arrays of double precision floating-point numbers, integers, and strings
    int i = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (!strncmp(line, "entry", strlen("entry"))) {
            entries[i].value = strtod(line + strlen("entry "), NULL);
            entries[i].key = atoi(line + strlen("entry "));
            entries[i].string = strdup(line + strlen("entry ") + 1);
            i++;
        }
    }

    // Close configuration file
    fclose(fp);

    // Log any errors encountered during the process to a file
    FILE *log_file = fopen("error.log", "a");
    if (log_file == NULL) {
        perror("Error opening error log file");
    } else {
        for (i = 0; i < num_entries; i++) {
            if (entries[i].value == 0 && entries[i].key == 0 && entries[i].string == NULL) {
                fprintf(log_file, "Error reading entry %d from configuration file\n", i);
            }
        }
    }

    // Return pointer to array of data entries
    *data = entries;
    return num_entries;
}
