JavaScript Function:
```javascript
const traverseDOM = (node, selector) => {
    // Check if the node is null or not an element
    if (!node || !(node instanceof Element)) {
        return [];
    }

    // Check if the node matches the selector
    if (node.matches(selector)) {
        return [node];
    }

    const children = Array.from(node.childNodes);
    const matchedChildren = children.map(c => traverseDOM(c, selector));
    const flattenedMatchedChildren = matchedChildren.reduce((acc, val) => acc.concat(val), []);
    return [node].concat(flattenedMatchedChildren);
}
```
