data_entry* alloc_init_entries(int num_entries, int max_offset, int min_key, double min_value, double max_value) {
    // Check if the input parameters are valid
    assert(num_entries > 0 && num_entries <= 1000);
    assert(max_offset >= -1000000 && max_offset <= 1000000);
    assert(min_key >= 1 && min_key <= 100);
    assert(min_value >= -1.0e6 && min_value <= 1.0e6);
    assert(max_value >= -1.0e6 && max_value <= 1.0e6);

    // Allocate memory for the array of data entries
    data_entry* entries = (data_entry*)malloc(sizeof(data_entry) * num_entries);
    if (!entries) {
        fprintf(stderr, "Error: Failed to allocate memory for data entries\n");
        return NULL;
    }

    // Initialize the array of data entries with random values
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        entries[i].offset = rand() % max_offset + min_offset;
        entries[i].key = rand() % min_key + 1;
        entries[i].value = ((double)rand()) / RAND_MAX * (max_value - min_value) + min_value;
    }

    return entries;
}

// Function to update an entry in the array of data entries
void update_entry(data_entry* entries, int index, long offset, int key, double value) {
    // Check if the input parameters are valid
    assert(entries != NULL);
    assert(index >= 0 && index < num_entries);
    assert(offset >= -1000000 && offset <= 1000000);
    assert(key >= 1 && key <= 100);
    assert(value >= -1.0e6 && value <= 1.0e6);

    // Update the entry in the array of data entries
    entries[index].offset = offset;
    entries[index].key = key;
    entries[index].value = value;
}

// Function to free the memory allocated for an array of data entries
void free_entries(data_entry* entries) {
    // Check if the input parameter is valid
    assert(entries != NULL);

    // Free the memory allocated for the array of data entries
    free(entries);
}
