```c
#include <stdlib.h>
#include <time.h>
#include <stdio.h>

struct Record {
    int key;
    long offset;
};

void initialize_records(int num_keys, int num_offsets, int random_value_range) {
    struct Record* records = malloc(sizeof(struct Record) * num_keys);
    long* offsets = malloc(sizeof(long) * num_offsets);
    int* keys = malloc(sizeof(int) * num_keys);

    if (records == NULL || offsets == NULL || keys == NULL) {
        fprintf(stderr, "Error allocating memory for records\n");
        exit(1);
    }

    // Initialize the offset array and key array to random values within the given range.
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % random_value_range + 1;
    }

    for (int j = 0; j < num_keys; j++) {
        keys[j] = rand() % random_value_range + 1;
    }

    // Sort the offset array in ascending order.
    qsort(offsets, num_offsets, sizeof(long), compare);

    // Initialize each record with a random value within the given range.
    for (int i = 0; i < num_keys; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i % num_offsets];
    }

    // Free memory allocated for offset array, key array, and record array.
    free(records);
    free(offsets);
    free(keys);
}
