    void* ptr;
    size_t size;
};

// Define the mutex and semaphore for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t sem;

// Define the Python service component
struct python_service {
    int status;
    void* data;
};

// Function to manage the lifecycle of allocated resources
void manage_resources(struct image_data* images, int num_images) {
    // Allocate memory for the arrays of coordinates, IDs, and labels
    float* coordinates = (float*) malloc(num_images * sizeof(float));
    int* ids = (int*) malloc(num_images * sizeof(int));
    char* labels = (char*) malloc(num_images * sizeof(char));

    // Initialize the arrays of coordinates, IDs, and labels with random values within specified ranges
    for (int i = 0; i < num_images; i++) {
        coordinates[i] = RAND_RANGE(-100.0f, 100.0f);
        ids[i] = RAND_INT(1, 100);
        labels[i] = RAND_CHOICE("ABC");
    }

    // Initialize the array of image data structures
    struct image_data* images = (struct image_data*) malloc(num_images * sizeof(struct image_data));

    // Initialize each structure with the random values from the arrays of coordinates, IDs, and labels
    for (int i = 0; i < num_images; i++) {
        images[i].coordinates[0] = coordinates[i];
        images[i].coordinates[1] = coordinates[i];
        images[i].coordinates[2] = coordinates[i];
        images[i].id = ids[i];
        images[i].label = labels[i];
    }

    // Start the Python service component
    struct python_service* python_service = start_python_service();

    // Send messages to the messaging system upon stopping the Python service
    if (python_service->status == 0) {
        send_message("Stopped Python service");
    }

    // Free the memory allocated for the arrays of coordinates, IDs, and labels
    free(coordinates);
    free(ids);
    free(labels);

    // Free the memory allocated for the array of image data structures
    free(images);

    // End the Python service component
    end_python_service();
}

// Function to safely allocate and initialize memory for an image data structure
struct image_data* alloc_image_data() {
    struct image_data* image = (struct image_data*) malloc(sizeof(struct image_data));
    image->coordinates[0] = 0.0f;
    image->coordinates[1] = 0.0f;
    image->coordinates[2] = 0.0f;
    image->id = 0;
    image->label = '\0';
    return image;
}

// Function to safely allocate and initialize memory for an array of image data structures
struct image_data* alloc_image_datas(int num_images) {
    struct image_data* images = (struct image_data*) malloc(num_images * sizeof(struct image_data));
    for (int i = 0; i < num_images; i++) {
        images[i] = alloc_image_data();
    }
    return images;
}

// Function to safely deallocate memory for an image data structure
void free_image_data(struct image_data* image) {
    free(image);
}

// Function to safely deallocate memory for an array of image data structures
void free_image_datas(struct image_data* images, int num_images) {
    for (int i = 0; i < num_images; i++) {
        free_image_data(&images[i]);
    }
}

// Function to handle memory allocation and deallocation efficiently using an existing memory pool manager
void mem_pool_manager(struct image_data* images, int num_images) {
    // Allocate memory for the arrays of coordinates, IDs, and labels from the memory pool manager
    float* coordinates = (float*) malloc(num_images * sizeof(float));
    int* ids = (int*) malloc(num_images * sizeof(int));
    char* labels = (char*) malloc(num_images * sizeof(char));

    // Initialize the arrays of coordinates, IDs, and labels with random values within specified ranges
    for (int i = 0; i < num_images; i++) {
        coordinates[i] = RAND_RANGE(-100.0f, 100.0f);
        ids[i] = RAND_INT(1, 100);
        labels[i] = RAND_CHOICE("ABC");
    }

    // Initialize the array of image data structures from the memory pool manager
    struct image_data* images = (struct image_data*) malloc(num_images * sizeof(struct image_data));

    // Initialize each structure with the random values from the arrays of coordinates, IDs, and labels
    for (int i = 0; i < num_images; i++) {
        images[i].coordinates[0] = coordinates[i];
        images[i].coordinates[1] = coordinates[i];
        images[i].coordinates[2] = coordinates[i];
        images[i].id = ids[i];
        images[i].label = labels[i];
    }

    // Free the memory allocated from the memory pool manager for the arrays of coordinates, IDs, and labels
    free(coordinates);
    free(ids);
    free(labels);

    // Free the memory allocated from the memory pool manager for the array of image data structures
    free(images);
}

// Function to start the Python service component
struct python_service* start_python_service() {
    struct python_service* python_service = (struct python_service*) malloc(sizeof(struct python_service));
    python_service->status = 0;
    return python_service;
}

// Function to end the Python service component
void end_python_service() {
    struct python_service* python_service = (struct python_service*) malloc(sizeof(struct python_service));
    free(python_service);
}

int main() {
