void init_theme_cache(const char *default_theme_dir) {
    // Allocate memory for the cache
    theme_cache = malloc(sizeof(THEME_CACHE));
    if (theme_cache == NULL) {
        printf("Failed to allocate memory for theme cache\n");
        return;
    }

    // Set the default theme directory if specified
    if (default_theme_dir != NULL) {
        strcpy(theme_cache->default_theme_dir, default_theme_dir);
    } else {
        theme_cache->default_theme_dir[0] = '\0';
    }

    // Initialize the list of themes
    theme_cache->themes = malloc(sizeof(THEME_BITMAP) * THEME_CACHE_SIZE);
    if (theme_cache->themes == NULL) {
        printf("Failed to allocate memory for theme cache\n");
        free(theme_cache);
        return;
    }
}

// Deinitialize the theme cache
void deinit_theme_cache() {
    // Free the list of themes
    if (theme_cache->themes != NULL) {
        for (int i = 0; i < THEME_CACHE_SIZE; i++) {
            free(theme_cache->themes[i].data);
        }
        free(theme_cache->themes);
    }

    // Free the cache itself
    free(theme_cache);
}

// Set a new theme as the default
void set_default_theme(const char *theme) {
    if (theme == NULL || theme_cache == NULL) {
        return;
    }

    // Find the index of the theme in the cache
    int i = 0;
    while (i < THEME_CACHE_SIZE && strcmp(theme, theme_cache->themes[i].filename) != 0) {
        i++;
    }

    // Set the default theme if it exists in the cache
    if (i < THEME_CACHE_SIZE) {
        theme_cache->default_theme = i;
    }
}

// Get the default theme
const char *get_default_theme() {
    if (theme_cache == NULL || theme_cache->themes == NULL) {
        return NULL;
    }

    // Return the filename of the default theme
    return theme_cache->themes[theme_cache->default_theme].filename;
}

// Add a new theme to the cache
void add_theme(const char *theme, const uint8_t *data, size_t size) {
    if (theme == NULL || data == NULL || size <= 0 || theme_cache == NULL) {
        return;
    }

    // Find an empty slot in the cache for the new theme
    int i = 0;
    while (i < THEME_CACHE_SIZE && theme_cache->themes[i].filename != NULL) {
        i++;
    }

    // Set the filename and data for the new theme
    if (i < THEME_CACHE_SIZE) {
        strcpy(theme_cache->themes[i].filename, theme);
        theme_cache->themes[i].data = malloc(size);
        memcpy(theme_cache->themes[i].data, data, size);
        theme_cache->themes[i].size = size;
    }
}

// Get a theme from the cache by filename
const uint8_t *get_theme(const char *filename) {
    if (filename == NULL || theme_cache == NULL || theme_cache->themes == NULL) {
        return NULL;
    }

    // Find the index of the theme in the cache
    int i = 0;
    while (i < THEME_CACHE_SIZE && strcmp(filename, theme_cache->themes[i].filename) != 0) {
        i++;
    }

    // Return the data for the requested theme if it exists in the cache
    if (i < THEME_CACHE_SIZE) {
        return theme_cache->themes[i].data;
    }

    return NULL;
}

// Load a PNG file from the cache root directory and add it to the theme cache
void load_theme(const char *filename) {
    if (filename == NULL || theme_cache == NULL) {
        return;
    }

    // Open the PNG file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Failed to open file %s\n", filename);
        return;
    }

    // Read the data from the PNG file
    size_t size = 0;
    uint8_t *data = NULL;
    fseek(file, 0, SEEK_END);
    size = ftell(file);
    rewind(file);
    if (size > 0) {
        data = malloc(size);
        fread(data, 1, size, file);
    }

    // Close the PNG file
    fclose(file);

    // Add the theme to the cache
    add_theme(filename, data, size);
}

// Load all PNG files from a directory and add them to the theme cache
void load_directory(const char *dirname) {
    if (dirname == NULL || theme_cache == NULL) {
        return;
    }

    // Open the directory for reading
    DIR *dir = opendir(dirname);
    if (dir == NULL) {
        printf("Failed to open directory %s\n", dirname);
        return;
    }

    // Read all files in the directory
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char filename[PATH_MAX];
        snprintf(filename, PATH_MAX, "%s/%s", dirname, entry->d_name);

        // Load the PNG file if it is a regular file
        struct stat sb;
        if (stat(filename, &sb) == 0 && S_ISREG(sb.st_mode)) {
            load_theme(filename);
        }
    }
}

// Set up the theme cache
void setup_themes() {
    // Initialize the theme cache
    init_theme_cache();

    // Load all PNG files in the directory
    const char *dirname = "/path/to/directory";
    load_directory(dirname);
}
