// Function to create an HTTP client using libcurl and return a request builder for a given URL
RequestBuilder* createHttpClient(char* url, bool disableCertValidation) {
    // Allocate memory for the request builder struct
    RequestBuilder* request_builder = malloc(sizeof(RequestBuilder));

    if (request_builder == NULL) {
        fprintf(stderr, "Failed to allocate memory for request builder\n");
        return NULL;
    }

    // Initialize the request builder with default values
    request_builder->status_code = 0;
    request_builder->response_data = NULL;

    // Allocate memory for two arrays: one for long offset values and one for int keys
    long* offsets = malloc(sizeof(long) * 2);
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        free(request_builder);
        return NULL;
    }
    int* keys = malloc(sizeof(int) * 2);
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        free(offsets);
        free(request_builder);
        return NULL;
    }

    // Initialize the arrays with default values
    offsets[0] = 0;
    offsets[1] = 0;
    keys[0] = 0;
    keys[1] = 0;

    // Allocate memory for an array of employee records
    EmployeeRecord* records = malloc(sizeof(EmployeeRecord) * 2);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for employee record array\n");
        free(offsets);
        free(keys);
        free(request_builder);
        return NULL;
    }

    // Initialize the records with default values
    records[0].id = 0;
    records[0].name = NULL;
    records[0].city = NULL;
    records[0].address = NULL;
    records[1].id = 0;
    records[1].name = NULL;
    records[1].city = NULL;
    records[1].address = NULL;

    // Set the request builder's response data to the array of employee records
    request_builder->response_data = (char*)records;

    // Set the request builder's status code to 200
    request_builder->status_code = 200;

    return request_builder;
}

// Function to retrieve employee name, city, and address from a database table 'Employees' where the supervisor's ID matches a given input
void getEmployeeData(char* dbUrl, int id) {
    // Allocate memory for a new HTTP client struct using libcurl
    CURL *curl = curl_easy_init();

    if (curl == NULL) {
        fprintf(stderr, "Failed to initialize HTTP client\n");
        return;
    }

    // Set the URL of the HTTP request
    char* url = malloc(sizeof(char) * 1024);
    sprintf(url, "%s/employees?supervisor_id=%d", dbUrl, id);

    // Set the options for the HTTP request
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_response);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, stdout);

    // Perform the HTTP request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform HTTP request: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return;
    }

    // Check the status code of the HTTP response
    long status_code;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
    if (status_code != 200) {
        fprintf(stderr, "HTTP request returned status code %d\n", status_code);
        curl_easy_cleanup(curl);
        return;
    }

    // Clean up the HTTP client struct
    curl_easy_cleanup(curl);

    return;
}

// Function to write the response data from an HTTP request to a file
size_t write_response(void* contents, size_t size, size_t nmemb, void* stream) {
    // Calculate the total number of bytes in the response data
    size_t realsize = size * nmemb;

    // Write the response data to the file
    fwrite(contents, size, nmemb, (FILE*)stream);

    return realsize;
}
