int init_nodes(size_t max_size) {
    // allocate memory for the three arrays
    double* values = malloc(max_size * sizeof(double));
    char** ids = malloc(max_size * sizeof(char*));
    struct node** nodes = malloc(max_size * sizeof(struct node*));

    if (values == NULL || ids == NULL || nodes == NULL) {
        // memory allocation failed, return error code
        return 1;
    }

    // initialize the three arrays with random values and next pointers
    srand(time(NULL));
    for (size_t i = 0; i < max_size; i++) {
        values[i] = (double)rand() / RAND_MAX * 10.0;
        ids[i] = malloc(16);
        snprintf(ids[i], 16, "id-%lu", i);
        nodes[i] = malloc(sizeof(struct node));
        nodes[i]->value = (int)values[i];
        nodes[i]->next = NULL;
    }

    // set the next pointer of each node to point to the next node in the list
    for (size_t i = 0; i < max_size - 1; i++) {
        nodes[i]->next = nodes[i + 1];
    }

    // free any unused memory and return success
    size_t used_memory = max_size * sizeof(double) + max_size * sizeof(char*) + max_size * sizeof(struct node*);
    if (used_memory > max_size * 2) {
        // reduce the number of nodes created and return error code
        used_memory -= max_size * sizeof(struct node*);
        for (size_t i = 0; i < used_memory / sizeof(struct node*); i++) {
            free(nodes[i]);
        }
        return 2;
    } else {
        // all memory is used, return success
        return 0;
    }
}
