int dns_resolve(const char* hostname, uint8_t** ip_address) {
    // Use the standard library functions to perform DNS resolution
    struct addrinfo hints, *result;
    int status;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &result)) != 0) {
        printf("Error: Failed to resolve hostname %s: %s\n", hostname, gai_strerror(status));
        return -1;
    }

    // Allocate memory for the IP address
    uint8_t* ip_address_ptr = malloc(result->ai_addrlen);
    if (!ip_address_ptr) {
        printf("Error: Failed to allocate memory for IP address\n");
        freeaddrinfo(result);
        return -1;
    }

    // Copy the IP address from the addrinfo structure
    memcpy(ip_address_ptr, result->ai_addr, result->ai_addrlen);

    *ip_address = ip_address_ptr;

    freeaddrinfo(result);

    return 0;
}
