        if (!records[i]) {
            return;
        }

        // Initialize the value field with a random integer within the given range
        int min_value = 0, max_value = 1000;
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;

        // Allocate memory for the string and initialize its identifier with a unique value
        char* identifier = malloc(16);
        if (!identifier) {
            return;
        }
        sprintf(identifier, "record-%d", i);
        records[i]->identifier = identifier;
    }

    // Check for memory allocation errors
    if (offsets || keys || records) {
        free(offsets);
        free(keys);
        for (int i = 0; i < num_records; i++) {
            free(records[i]->identifier);
            free(records[i]);
        }
    }
}
