#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

struct temperature_reading {
  float temperature;
  char* location;
  int timestamp;
};

void allocate_temperature_readings(int num_sensors, struct temperature_reading** readings) {
  *readings = (struct temperature_reading*)malloc(sizeof(struct temperature_reading) * num_sensors);
}

void initialize_temperature_readings(int num_sensors, struct temperature_reading* readings) {
  for (int i = 0; i < num_sensors; i++) {
    readings[i].temperature = 0.0;
    readings[i].location = strdup("");
    readings[i].timestamp = 0;
  }
}

void update_temperature_readings(int num_sensors, struct temperature_reading* readings) {
  for (int i = 0; i < num_sensors; i++) {
    readings[i].temperature = readings[i].temperature + 1.0;
  }
}

void free_temperature_readings(struct temperature_reading* readings) {
  for (int i = 0; i < num_sensors; i++) {
    if (readings[i].location != NULL) {
      free(readings[i].location);
    }
  }
  free(readings);
}
