// Macros for defining the maximum number of sensors and the types of sensors supported
#define MAX_NUM_SENSORS 1000
#define NUM_TEMPERATURE_SENSORS 2
#define NUM_PRESSURE_SENSORS 3
#define NUM_HUMIDITY_SENSORS 4

// Enum for the different types of sensors supported
enum sensor_type {
    TEMPERATURE,
    PRESSURE,
    HUMIDITY
};

// Struct for storing data about each sensor
struct sensor {
    int id;
    char label[10];
    enum sensor_type type;
    union {
        float temperature;
        int pressure;
        int humidity;
    } attributes;
};

// Function to initialize a new sensor
int init_sensor(struct sensor *sensor) {
    if (sensor == NULL) {
        return -1;
    }

    // Generate a random ID between 1 and 100
    int id = rand() % 99 + 1;
    while (id_exists(id)) {
        id = rand() % 99 + 1;
    }

    // Generate a random label for the sensor
    char label[10];
    sprintf(label, "Sensor-%d", id);

    // Initialize the sensor type and attributes based on its ID
    switch (id % NUM_TEMPERATURE_SENSORS) {
        case 0:
            sensor->type = TEMPERATURE;
            break;
        case 1:
            sensor->type = PRESSURE;
            break;
        default:
            sensor->type = HUMIDITY;
    }

    switch (sensor->type) {
        case TEMPERATURE:
            sensor->attributes.temperature = (float)(rand() % 201 - 100);
            break;
        case PRESSURE:
            sensor->attributes.pressure = rand() % 101;
            break;
        default:
            sensor->attributes.humidity = rand() % 101;
    }

    return id;
}

// Function to update the data for a specific sensor
void update_sensor(struct sensor *sensor) {
    if (sensor == NULL) {
        return;
    }

    // Generate a random value between -100.0 and 100.0 for temperature sensors
    if (sensor->type == TEMPERATURE) {
        sensor->attributes.temperature = (float)(rand() % 201 - 100);
    }

    // Generate a random value between 0 and 100 for pressure sensors
    if (sensor->type == PRESSURE) {
        sensor->attributes.pressure = rand() % 101;
    }

    // Generate a random value between -50 and 50 for humidity sensors
    if (sensor->type == HUMIDITY) {
        sensor->attributes.humidity = rand() % 101 - 50;
    }
}

// Function to check if an ID exists in the array of sensors
int id_exists(int id) {
    for (int i = 0; i < MAX_NUM_SENSORS; i++) {
        if (sensors[i].id == id) {
            return 1;
        }
    }
    return 0;
}

// Function to allocate memory for an array of sensors
struct sensor *allocate_sensors(int num_sensors) {
    if (num_sensors < 1 || num_sensors > MAX_NUM_SENSORS) {
        return NULL;
    }

    struct sensor *sensors = malloc(sizeof(struct sensor) * num_sensors);
    if (sensors == NULL) {
        return NULL;
    }

    for (int i = 0; i < num_sensors; i++) {
        sensors[i].id = init_sensor(&sensors[i]);
        update_sensor(&sensors[i]);
    }

    return sensors;
}

// Function to free memory for an array of sensors
void free_sensors(struct sensor *sensors) {
    if (sensors == NULL) {
        return;
    }

    for (int i = 0; i < MAX_NUM_SENSORS; i++) {
        free(sensors[i].label);
    }
    free(sensors);
}
