// Function to initialize an array of records with random values within a specified range
void init_record_array(Record* rec_arr, int size, int min, int max) {
    for (int i = 0; i < size; i++) {
        // Generate a random key and offset within the specified range
        int rand_key = min + (rand() % (max - min));
        long rand_offset = min + (rand() % (max - min));

        // Allocate memory for the record
