['Here's a C function that dynamically allocates memory for and initializes four arrays: one for 'long' offset values, one for 'int' keys, one for 'double' precision floating-point numbers, and one for 'char*' strings. Additionally, allocate memory for and initialize an array of 'data_point' structures, where each structure contains a single 'int', a 'double', a pointer to a string, and an additional field for storing metadata as a 'void*'. Each data point should be initialized with random values within specified ranges. Ensure that each string pointer is dynamically allocated with a unique identifier.
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

// Define the data structure to store metadata and string pointers
typedef struct {
  int int_key;
  double float_value;
  char* str_ptr;
  void* metadata;
} data_point;

// Function to dynamically allocate memory for arrays of 'long', 'int', 'double', and 'char *'
void init_arrays(size_t size, long** long_array, int** int_array, double** double_array, char*** str_array) {
  // Allocate memory for the long array
  (*long_array) = (long*)malloc(sizeof(long) * size);
  if (!(*long_array)) {
    printf("Error: Failed to allocate memory for long array\n");
    exit(1);
  }

  // Allocate memory for the int array
  (*int_array) = (int*)malloc(sizeof(int) * size);
  if (!(*int_array)) {
    printf("Error: Failed to allocate memory for int array\n");
    exit(1);
  }

  // Allocate memory for the double array
  (*double_array) = (double*)malloc(sizeof(double) * size);
  if (!(*double_array)) {
    printf("Error: Failed to allocate memory for double array\n");
    exit(1);
  }

  // Allocate memory for the string array
  (*str_array) = (char**)malloc(sizeof(char*) * size);
  if (!(*str_array)) {
    printf("Error: Failed to allocate memory for string array\n");
    exit(1);
  }
}

// Function to dynamically initialize the arrays with random values within specified ranges
void init_values(long* long_array, int* int_array, double* double_array, char** str_array, size_t size) {
  srand(time(NULL)); // Seed the RNG with the current time

  for (size_t i = 0; i < size; i++) {
    long_array[i] = rand() % 1000000000 + 1;
    int_array[i] = rand() % 1000000000 + 1;
    double_array[i] = (double)rand() / RAND_MAX;

    // Allocate memory for the string and initialize it with a random string of length 5
    str_array[i] = malloc(6);
    if (!str_array[i]) {
      printf("Error: Failed to allocate memory for string\n");
      exit(1);
    }
    memset(str_array[i], 0, 6);
    sprintf(str_array[i], "%ld", rand() % 100000 + 1);
  }
}

// Function to safely allocate memory for and initialize an array of 'data_point' structures
void init_data_points(size_t size, data_point** data_points) {
  // Allocate memory for the data points array
  (*data_points) = (data_point*)malloc(sizeof(data_point) * size);
  if (!(*data_points)) {
    printf("Error: Failed to allocate memory for data point array\n");
    exit(1);
  }

  // Initialize each data point with a random int, double, string pointer, and metadata
  for (size_t i = 0; i < size; i++) {
    (*data_points)[i].int_key = rand() % 100000 + 1;
    (*data_points)[i].float_value = (double)rand() / RAND_MAX;
    (*data_points)[i].str_ptr = malloc(6);
    if (!(*data_points)[i].str_ptr) {
      printf("Error: Failed to allocate memory for string pointer\n");
      exit(1);
    }
    memset((*data_points)[i].str_ptr, 0, 6);
    sprintf((*data_points)[i].str_ptr, "%ld", rand() % 100000 + 1);
    (*data_points)[i].metadata = malloc(sizeof(void));
    if (!(*data_points)[i].metadata) {
      printf("Error: Failed to allocate memory for metadata\n");
      exit(1);
    }
  }
}

// Function to update the arrays with new values for each data point
void update_values(long* long_array, int* int_array, double* double_array, char** str_array, size_t size) {
  srand(time(NULL)); // Seed the RNG with the current time

  for (size_t i = 0; i < size; i++) {
    long_array[i] = rand() % 100000 + 1;
    int_array[i] = rand() % 100000 + 1;
    double_array[i] = (double)rand() / RAND_MAX;

    // Update the string pointer with a new random string of length 5
    free(str_array[i]);
    str_array[i] = malloc(6);
    if (!str_array[i]) {
      printf("Error: Failed to allocate memory for string\n");
      exit(1);
    }
    memset(str_array[i], 0, 6);
    sprintf(str_array[i], "%ld", rand() % 100000 + 1);
  }
}

// Function to safely free the allocated memory for each data point
void free_data_points(data_point* data_points, size_t size) {
  for (size_t i = 0; i < size; i++) {
    free(data_points[i].str_ptr);
    free(data_points[i].metadata);
  }
}
```

