// Function to safely allocate memory for an array of floats
void* safe_allocate_floats(size_t size) {
    void* ptr = malloc(sizeof(float) * size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for coordinates.\n");
        return NULL;
    }
    return ptr;
}

// Function to safely allocate memory for an array of ints
void* safe_allocate_ints(size_t size) {
