    if (ptr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for IDs.\n");
        return NULL;
    }
    return ptr;
}

// Function to safely allocate memory for an array of chars
void* safe_allocate_chars(size_t size) {
