    int record;
} Record_t;

// Function prototypes
void create_rach_pdu_list(uint32_t num_ue, uint32_t min_record_val, uint32_t max_record_val);
LTE_PHY_RACH_PDU_t* get_next_rach_pdu();
void free_rach_pdu_list();
void add_new_ue(uint32_t new_ue_id, LTE_PHY_RACH_PDU_t* new_rach_pdu);
void remove_ue(uint32_t ue_id);
void update_ue(uint32_t ue_id, LTE_PHY_RACH_PDU_t* updated_rach_pdu);
Record_t* get_record(uint32_t record_id);
void free_record(Record_t* record);
void update_record(uint32_t record_id, int new_value);

// Global variables
static uint32_t num_uplink_slots = 0;
static LTE_PHY_RACH_PDU_t** rach_pdu_list = NULL;
static Record_t* record_list = NULL;
static uint32_t next_free_record = 0;

void create_rach_pdu_list(uint32_t num_ue, uint32_t min_record_val, uint32_t max_record_val) {
    // Check for valid input parameters
    if (num_ue == 0 || min_record_val >= max_record_val) {
        return;
    }

    // Allocate memory for the rach pdu list and initialize it to NULL
    rach_pdu_list = malloc(sizeof(LTE_PHY_RACH_PDU_t*) * num_ue);
    if (rach_pdu_list == NULL) {
        return;
    }
    memset(rach_pdu_list, 0, sizeof(LTE_PHY_RACH_PDU_t*) * num_ue);

    // Allocate memory for the record list and initialize it to NULL
    record_list = malloc(sizeof(Record_t) * max_record_val);
    if (record_list == NULL) {
        free(rach_pdu_list);
        rach_pdu_list = NULL;
        return;
    }
    memset(record_list, 0, sizeof(Record_t) * max_record_val);

    // Initialize the number of uplink slots and next free record index
    num_uplink_slots = num_ue;
    next_free_record = min_record_val;
}

LTE_PHY_RACH_PDU_t* get_next_rach_pdu() {
    // Check if the rach pdu list is empty
    if (rach_pdu_list == NULL) {
        return NULL;
    }

    // Find the next available UE ID and create a new RACH PDU if necessary
    uint32_t ue_id = 0;
    for (int i = 0; i < num_uplink_slots; i++) {
        if (rach_pdu_list[i] == NULL) {
            // Create a new RACH PDU and update the list
            rach_pdu_list[i] = malloc(sizeof(LTE_PHY_RACH_PDU_t));
            if (rach_pdu_list[i] == NULL) {
                return NULL;
            }
            memset(rach_pdu_list[i], 0, sizeof(LTE_PHY_RACH_PDU_t));
            ue_id = i + 1;
            break;
        }
    }

    // Create a new record and update the list
    Record_t* new_record = malloc(sizeof(Record_t));
    if (new_record == NULL) {
        return NULL;
    }
    memset(new_record, 0, sizeof(Record_t));
    record_list[next_free_record++] = new_record;

    // Populate the RACH PDU and record with random values
    rach_pdu_list[ue_id]->UE_ID = ue_id;
    rach_pdu_list[ue_id]->RACH_CONFIG.preamble_format = rand() % 2 + 1;
    rach_pdu_list[ue_id]->RACH_CONFIG.ra_response_window = rand() % 4 + 1;
    record_list[next_free_record - 1]->record = rand() % (max_record_val - min_record_val) + min_record_val;

    return rach_pdu_list[ue_id];
}

void free_rach_pdu_list() {
    // Check if the list is empty
    if (rach_pdu_list == NULL) {
        return;
    }

    // Free all memory allocated for the rach pdu and record lists
    for (int i = 0; i < num_uplink_slots; i++) {
        free(rach_pdu_list[i]);
    }
    free(rach_pdu_list);
    free(record_list);
}

void add_new_ue(uint32_t new_ue_id, LTE_PHY_RACH_PDU* new_rach_pdu) {
    // Check if the list is full
    if (num_uplink_slots == MAX_NUM_UPLINK_SLOTS) {
        return;
    }

    // Allocate memory for the new UE ID and update the list
    rach_pdu_list[new_ue_id] = malloc(sizeof(LTE_PHY_RACH_PDU));
    if (rach_pdu_list[new_ue_id] == NULL) {
        return;
    }
    memset(rach_pdu_list[new_ue_id], 0, sizeof(LTE_PHY_RACH_PDU));

    // Copy the contents of the new RACH PDU and update the list
    memcpy(rach_pdu_list[new_ue_id], new_rach_pdu, sizeof(LTE_PHY_RACH_PDU));
}

void remove_ue(uint32_t ue_id) {
    // Check if the UE ID is valid
    if (ue_id > num_uplink_slots || rach_pdu_list[ue_id] == NULL) {
        return;
    }

    // Free all memory allocated for the UE ID and update the list
    free(rach_pdu_list[ue_id]);
    rach_pdu_list[ue_id] = NULL;
}

Record* get_record(uint32_t ue_id) {
    // Check if the UE ID is valid
    if (ue_id > num_uplink_slots || record_list[ue_id] == NULL) {
        return NULL;
    }

    // Return the record for the UE ID
    return record_list[ue_id];
}

void update_record(uint32_t ue_id, Record* new_record) {
    // Check if the UE ID is valid
    if (ue_id > num_uplink_slots || record_list[ue_id] == NULL) {
        return;
    }

    // Free all memory allocated for the previous record and update the list
    free(record_list[ue_id]);
    memset(record_list[ue_id], 0, sizeof(Record));

    // Copy the contents of the new record and update the list
    memcpy(record_list[ue_id], new_record, sizeof(Record));
}
