// Union-Find data structure to efficiently check for disjoint pairs of elements in the array of items
typedef struct {
    int id;
    int size;
    int* parents;
    int* ranks;
} UF;

void initUF(UF* uf, int numItems) {
    // Allocate memory for the parent and rank arrays
    uf->parents = (int*)malloc(sizeof(int) * numItems);
    uf->ranks = (int*)malloc(sizeof(int) * numItems);

    // Initialize each element in the parent array to itself, indicating that each item is its own parent
    for (int i = 0; i < numItems; i++) {
        uf->parents[i] = i;
    }
}

void unionUF(UF* uf, int id1, int id2) {
    // Find the parents of the two items to be combined
    int parent1 = find(uf, id1);
    int parent2 = find(uf, id2);

    // If the two items are already in the same component, do nothing
    if (parent1 == parent2) {
        return;
    }

    // Combine the components by making one component's parent point to the other
    if (uf->ranks[parent1] < uf->ranks[parent2]) {
        uf->parents[parent1] = parent2;
    } else if (uf->ranks[parent1] > uf->ranks[parent2]) {
        uf->parents[parent2] = parent1;
    } else {
        uf->parents[parent1] = parent2;
        uf->ranks[parent1]++;
    }
}

int find(UF* uf, int id) {
    // If the item is not in a component, return its ID as its own parent
    if (uf->parents[id] == id) {
        return id;
    }

    // Find the component that the item belongs to by following the chain of parents until it reaches the root
    int parent = find(uf, uf->parents[id]);

    // Make the parent point to itself to indicate that the item is now in a component
    uf->parents[id] = parent;

    return parent;
}

int main() {
    // Initialize the Union-Find data structure with the number of items
    UF uf;
    initUF(&uf, 10);

    // Initialize the arrays for the integers, floats, and characters
