import java.util.Random;

class Item {
    int id;
    double value;

    public Item(int id) {
        this.id = id;
        Random random = new Random();
        this.value = random.nextInt(10) + random.nextDouble() * 0.1;
    }
}

public class UnionFind {
    private int[] parents;
    private int[] ranks;
    private int count;

    public UnionFind(int n) {
        this.parents = new int[n];
        this.ranks = new int[n];
        this.count = 0;
        for (int i = 0; i < n; i++) {
            parents[i] = i;
        }
    }

    public boolean isDisjoint(Item item1, Item item2) {
        return item1.value != item2.value;
    }

    public void union(int id1, int id2) {
        if (isDisjoint(find(id1), find(id2))) {
            int root1 = find(id1);
            int root2 = find(id2);
            if (ranks[root1] < ranks[root2]) {
                parents[root1] = root2;
            } else if (ranks[root1] > ranks[root2]) {
                parents[root2] = root1;
            } else {
                parents[root1] = root2;
                ranks[root1]++;
            }
        }
    }

    public int find(int id) {
        if (parents[id] == id) {
            return id;
        }
        return find(parents[id]);
    }
}

public class Main {
    public static void main(String[] args) {
        UnionFind uf = new UnionFind(10);
        Item item1 = new Item(0);
        Item item2 = new Item(1);
        if (uf.isDisjoint(item1, item2)) {
            uf.union(item1.id, item2.id);
            System.out.println("Union: " + item1.id + " and " + item2.id);
        }
    }
}
