struct Item {
    id: i32,
    value: f64,
}

impl Item {
    fn new(id: i32) -> Self {
        let mut rng = rand::thread_rng();
        let value = rng.gen_range(0.0, 10.0);
        Self { id, value }
    }
}

struct UnionFind {
    parents: Vec<i32>,
    ranks: Vec<i32>,
    count: i32,
}

impl UnionFind {
    fn new(n: i32) -> Self {
        let mut parents = vec![0; n as usize];
        for i in 0..n as usize {
            parents[i] = i as i32;
        }
        Self { parents, ranks: vec![0; n as usize], count: 0 }
    }

    fn is_disjoint(&self, item1: &Item, item2: &Item) -> bool {
        return item1.value != item2.value;
    }

    fn union(&mut self, id1: i32, id2: i32) {
        if self.is_disjoint(&self.parents[id1], &self.parents[id2]) {
            let root1 = self.find(id1);
            let root2 = self.find(id2);
            if self.ranks[root1] < self.ranks[root2] {
                self.parents[root1] = root2;
            } else if self.ranks[root1] > self.ranks[root2] {
                self.parents[root2] = root1;
            } else {
                self.parents[root1] = root2;
                self.ranks[root1] += 1;
            }
        }
    }

    fn find(&self, id: i32) -> i32 {
        if self.parents[id as usize] == id {
            return id;
        }
        self.find(self.parents[id as usize])
    }
}

