// Define a structure to represent a record in the database
typedef struct Record {
    long offset;
    int key;
    double value;
} Record;

// Function to allocate memory for and initialize an array of records
Record* allocate_records(int num_records) {
    if (num_records <= 0 || num_records > 1000) {
        return NULL;
    }

    Record* records = malloc(sizeof(Record) * num_records);
    if (!records) {
        return NULL;
    }

    memset(records, 0, sizeof(Record) * num_records);

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand() % (1000000 - (-1000000 + 1)) + (-1000000);
        records[i].key = rand() % (100 - 1) + 1;
        records[i].value = rand() % ((double)INT_MAX / 1000) + (-1.0e6);
    }

    return records;
}

// Function to update a record in the database
bool update_record(Record* record, int key) {
    if (!record || !key) {
        return false;
    }

    record->offset = rand() % (1000000 - (-1000000 + 1)) + (-1000000);
    record->key = key;
    record->value = rand() % ((double)INT_MAX / 1000) + (-1.0e6);

    return true;
}

// Function to free memory allocated for an array of records
void free_records(Record* records, int num_records) {
    if (!records || num_records <= 0) {
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        memset(&records[i], 0, sizeof(Record));
    }

    free(records);
}
