// Define the record structure
typedef struct {
    int key;
} Record;

// Function to allocate and initialize arrays for offsets and keys
void allocate_and_initialize(int num_records, long offset_min, long offset_max, int key_min, int key_max) {
    // Validate input parameters
    if (num_records < 1 || num_records > 100000) {
        fprintf(stderr, "Invalid number of records: %d\n", num_records);
        return;
    }
    if (offset_min >= offset_max || key_min >= key_max) {
        fprintf(stderr, "Invalid range for offsets and keys\n");
        return;
    }

    // Allocate memory for the arrays
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    Record *records = malloc(num_records * sizeof(Record));
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize the arrays and records
    for (int i = 0; i < num_records; i++) {
        offsets[i] = offset_min + rand() % (offset_max - offset_min);
        keys[i] = key_min + rand() % (key_max - key_min);
        records[i].key = keys[i];
    }

    // Use a thread-safe mechanism to initialize the arrays and records
    pthread_mutex_lock(&array_init_mutex);
    memcpy(offsets, offsets, num_records * sizeof(long));
    memcpy(keys, keys, num_records * sizeof(int));
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
    }
    pthread_mutex_unlock(&array_init_mutex);
}

// Function to free all allocated memory
void free_memory() {
    // Use a thread-safe mechanism to free the arrays and records
    pthread_mutex_lock(&array_free_mutex);
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_unlock(&array_free_mutex);
}
