int init_arrays(const char *config_file, long max_mem_limit, int num_records, record_t **offsets, int **keys, record_t ***records) {
    json_object *root = NULL;
    json_object *conf = NULL;
    const char *path = "./config.json";

    // Parse the JSON configuration file
    if (json_read_file(path, &root)) {
        fprintf(stderr, "Error reading JSON config file: %s\n", path);
        return -1;
    }

    // Get the configuration object from the root node
    conf = json_object_get_object(root, "config");

    // Check if the maximum memory limit is set in the configuration file
    long max_mem_limit = json_object_get_int(conf, "max_mem_limit");

    // Check if the number of records is set in the configuration file
    int num_records = json_object_get_int(conf, "num_records");

    // Allocate memory for the arrays
    *offsets = malloc(sizeof(long) * (num_records + 1));
    *keys = malloc(sizeof(int) * num_records);
    *records = malloc(sizeof(record_t *) * num_records);

    // Initialize the arrays with random values
    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = rand() % max_mem_limit;
        (*keys)[i] = i + 1;
        (*records)[i] = malloc(sizeof(record_t));
        (*records)[i]->value = rand();
    }

    // Set the last element of the arrays to NULL
    (*offsets)[num_records] = NULL;
    (*keys)[num_records] = 0;
    (*records)[num_records] = NULL;

    // Check if the memory usage exceeds the specified limit
    long total_mem_usage = (long)malloc_usable_size(offsets[0]) + (long)malloc_usable_size(keys[0]) + (long)malloc_usable_size(records[0]);
    if (total_mem_usage > max_mem_limit) {
        fprintf(stderr, "Memory usage exceeds the specified limit: %ld\n", total_mem_usage);
        return -1;
    }

    // Clean up and return successfully
    json_object_put(root);
    return 0;
}
