```c
#include <stdlib.h>  // For malloc(), realloc(), and free()
#include <string.h>  // For memset()

void manage_memory(size_t key_count, size_t offset_count) {
    int *keys = NULL;
    long *offsets = NULL;
    record *records = NULL;

    // Allocate memory for keys and offsets in fixed-size chunks
    const size_t chunk_size = 100;
    size_t key_chunk_count = (key_count + chunk_size - 1) / chunk_size;
    size_t offset_chunk_count = (offset_count + chunk_size - 1) / chunk_size;
    keys = malloc(sizeof(int) * key_chunk_count);
    offsets = malloc(sizeof(long) * offset_chunk_count);
    records = malloc(sizeof(record) * key_chunk_count);

    // Initialize keys and offsets
    memset(keys, 0, sizeof(int) * key_chunk_count);
    memset(offsets, 0, sizeof(long) * offset_chunk_count);
    memset(records, 0, sizeof(record) * key_chunk_count);

    // Set random values in records
    for (size_t i = 0; i < key_chunk_count; ++i) {
        records[i].value = rand();
    }

    // Reallocate memory if needed
    const size_t max_key_chunk_count = 1000;
    const size_t max_offset_chunk_count = 1000;
    if (key_chunk_count > max_key_chunk_count || offset_chunk_count > max_offset_chunk_count) {
        keys = realloc(keys, sizeof(int) * max_key_chunk_count);
        offsets = realloc(offsets, sizeof(long) * max_offset_chunk_count);
        records = realloc(records, sizeof(record) * max_key_chunk_count);
    }

    // Clean up memory on failure
    if (keys == NULL || offsets == NULL || records == NULL) {
        free(keys);
        free(offsets);
        free(records);
        return;  // Return early on failure to avoid double-freeing
    }

    // Free all allocated memory when done with it
    free(keys);
    free(offsets);
    free(records);
}
```
This function allocates memory for keys and offsets in fixed-size chunks, using `malloc()` to allocate the initial chunk of memory. It then sets up the arrays with zero values using `memset()`. If the number of keys or offsets is greater than a certain threshold, it reallocates more memory using `realloc()` to avoid fragmentation.

The function also includes error handling for memory allocation failures by checking if any of the allocations failed and returning early on failure to avoid double-freeing. Finally, it frees all allocated memory when done with it using `free()`.

