    // check if record is null
    if (!record) {
        return;
    }

    // update each field to new random value within specified range
    record->offset = rand() % 1000000 + -1000000;
    record->key = rand() % 100 + 1;
    record->value = (double)rand() / RAND_MAX * 1.0e6;
