// Define structure for cache entry
typedef struct CacheEntry {
    char* file_path;
    size_t file_size;
    time_t last_access_time;
} CacheEntry;

// Define function to create a cache manager and entries
struct CacheManager* create_cache_manager_and_entries(int num_entries) {
    // Check if number of entries is valid
    if (num_entries < 0 || num_entries > 1000) {
        fprintf(stderr, "Invalid number of entries: %d\n", num_entries);
        return NULL;
    }

    // Allocate memory for cache manager and array of cache entries
    struct CacheManager* cache_manager = malloc(sizeof(struct CacheManager));
    if (cache_manager == NULL) {
        fprintf(stderr, "Failed to allocate memory for cache manager\n");
        return NULL;
    }
    CacheEntry* cache_entries = calloc(num_entries, sizeof(CacheEntry));
    if (cache_entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for %d cache entries\n", num_entries);
        free(cache_manager);
        return NULL;
    }

    // Initialize cache manager and entries with random values within given ranges
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        cache_entries[i].file_path = generate_random_file_path();
        cache_entries[i].file_size = generate_random_file_size();
        cache_entries[i].last_access_time = time(NULL) - (rand() % 365 * 24 * 60 * 60); // Random timestamp within one year ago to current time
    }

    // Initialize cache manager with number of entries and array of cache entries
    cache_manager->num_entries = num_entries;
    cache_manager->cache_entries = cache_entries;

    return cache_manager;
}

// Define function to generate random file path within given range
char* generate_random_file_path() {
    // Generate random string with length between 1 and 100 characters
    int len = rand() % 100 + 1;
    char* file_path = malloc(len);
    for (int i = 0; i < len; i++) {
        file_path[i] = 'a' + (rand() % 26);
    }
    return file_path;
}

// Define function to generate random file size within given range
size_t generate_random_file_size() {
    // Generate random integer between 1KB and 1MB
    return rand() % (1024 * 1024) + 1024;
}

// Define function to free memory for cache manager and entries
void destroy_cache_manager_and_entries(struct CacheManager* cache_manager) {
    // Check if cache manager is valid
    if (cache_manager == NULL) {
        return;
    }

    // Free memory for array of cache entries
    free(cache_manager->cache_entries);

    // Free memory for cache manager
    free(cache_manager);
}
