    if (num_records > 1000) {
        // Handle error: maximum number of records exceeded
        return NULL;
    }
    int* keys = malloc(sizeof(int) * num_records);
    if (!keys) {
        // Handle error: memory allocation failed
        free(offsets);
        return NULL;
    }
    return keys;
}

double* allocate_values(size_t num_records) {
    if (num_records > 1000) {
        // Handle error: maximum number of records exceeded
        return NULL;
    }
    double* values = malloc(sizeof(double) * num_records);
    if (!values) {
        // Handle error: memory allocation failed
        free(offsets);
        free(keys);
        return NULL;
    }
    return values;
}

record_t* allocate_records(size_t num_records) {
    long* offsets = allocate_offsets(num_records);
    if (!offsets) {
        // Handle error: memory allocation failed for offset array
        return NULL;
    }
    int* keys = allocate_keys(num_records);
