// Allocate memory for the arrays and initialize them to random values within given ranges:
void allocateAndInitializeMemory() {
    // Calculate the total size needed for the arrays:
    numSensors = 500;
    int totalSize = sizeof(float) * numSensors + sizeof(uint16_t) * numSensors + sizeof(char) * numSensors;
    // Allocate memory for the arrays:
    temperatures = (float *)malloc(totalSize);
    sensorIDs = (uint16_t *)malloc(totalSize);
    locations = (char *)malloc(totalSize);
    if (!temperatures || !sensorIDs || !locations) {
        printf("Memory allocation failed. Exiting.\n");
        exit(1);
    }
    // Initialize the arrays with random values:
    srand(time(NULL));
    for (int i = 0; i < numSensors; i++) {
        temperatures[i] = ((float)rand() / RAND_MAX) * 100.0 - 50.0;
        sensorIDs[i] = rand() % 256;
        locations[i] = (char)('A' + (rand() % 3)); // generate a random character within 'ABC'
    }
}
