    int offset = 0;
    for (int i = 0; i < numSensors; i++) {
        sensors[i].temperature = temperatures[offset];
        sensors[i].id = sensorIDs[offset];
        sensors[i].location = locations[offset];
        offset += sizeof(float) + sizeof(uint16_t) + sizeof(char);
