```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_data(int size) {
    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));
    char *buffer = malloc(2 * (size * sizeof(long) + size * sizeof(int) + size * sizeof(record)));

    if (offsets == NULL || keys == NULL || records == NULL || buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 100;
        records[i].value = rand() % 101;
        // Store intermediate results in buffer
        memcpy(buffer + i * (sizeof(long) + sizeof(int) + sizeof(record)), &offsets[i], sizeof(long));
        memcpy(buffer + i * (sizeof(long) + sizeof(int) + sizeof(record)) + sizeof(long), &keys[i], sizeof(int));
        memcpy(buffer + i * (sizeof(long) + sizeof(int) + sizeof(record)) + sizeof(long) + sizeof(int), &records[i], sizeof(record));
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(buffer);
}
