    while (structure->offsetArray[index] != -1) {
        index++;
    }
    structure->offsetArray[index] = record->offset;
    structure->keyArray[index] = record->key;
    structure->valueArray[index] = record->value;
}

void updateRecord(dataStructure* structure, int key, double value) {
    if (!structure) {
        printf("Error: Failed to update record\n");
        return;
    }

    // Find index of record with given key
    int index = 0;
    while (structure->keyArray[index] != -1 && structure->keyArray[index] != key) {
        index++;
    }
    if (index == structure->size) {
        printf("Error: Record not found\n");
        return;
    }

    // Update record with new value
    structure->valueArray[index] = value;
}

