        printf("Error: Failed to delete record\n");
        return;
    }

    // Find index of record with given key
    int index = 0;
    while (structure->keyArray[index] != -1 && structure->keyArray[index] != key) {
        index++;
    }
    if (index == structure->size) {
        printf("Error: Record not found\n");
        return;
