        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize an array of items with random values within specified ranges
void init_items(Item *items, size_t num_items) {
    assert(num_items <= MAX_ITEMS);

    // Generate random coordinates between -150.0 and 150.0
    for (size_t i = 0; i < num_items; i++) {
        items[i].coordinate = ((float)rand() / RAND_MAX) * 300.0 - 150.0;
    }

    // Generate random IDs between 1 and 200
    for (size_t i = 0; i < num_items; i++) {
        items[i].id = rand() % 200 + 1;
    }

    // Generate random labels from the predefined set of characters
    for (size_t i = 0; i < num_items; i++) {
        size_t j = rand() % (strlen(LABEL_CHARS) - 1);
        items[i].label = LABEL_CHARS[j];
    }

    // Generate random weights between 0.0 and 1.0
    for (size_t i = 0; i < num_items; i++) {
        items[i].weight = ((float)rand() / RAND_MAX);
    }
}

// Function to update an array of items with new values
void update_items(Item *items, size_t num_items, float coordinate, int id, char label, double weight) {
    assert(num_items <= MAX_ITEMS);

    // Update coordinates
    for (size_t i = 0; i < num_items; i++) {
        items[i].coordinate = coordinate;
    }

    // Update IDs
    for (size_t i = 0; i < num_items; i++) {
        items[i].id = id;
    }

    // Update labels
    for (size_t i = 0; i < num_items; i++) {
        items[i].label = label;
    }

    // Update weights
    for (size_t i = 0; i < num_items; i++) {
        items[i].weight = weight;
    }
}

// Function to free the allocated memory for an array of items
void free_items(Item *items) {
    if (items != NULL) {
        free(items);
    }
}

