#define OFFSET_MAX 1000000
#define KEY_MIN 1
#define KEY_MAX 100
#define VALUE_MIN -1.0e6
#define VALUE_MAX 1.0e6

// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Function to allocate memory for and initialize an array of records
void init_records(Record** records, size_t num_records) {
    // Allocate memory for the record array
    *records = (Record*) malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the record array
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].offset = OFFSET_MIN + rand() % (OFFSET_MAX - OFFSET_MIN + 1);
        (*records)[i].key = KEY_MIN + rand() % (KEY_MAX - KEY_MIN + 1);
        (*records)[i].value = VALUE_MIN + rand() % (VALUE_MAX - VALUE_MIN + 1);
    }
}

// Function to update a record's fields with new random values
void update_record(Record* record) {
    record->offset = OFFSET_MIN + rand() % (OFFSET_MAX - OFFSET_MIN + 1);
    record->key = KEY_MIN + rand() % (KEY_MAX - KEY_MIN + 1);
    record->value = VALUE_MIN + rand() % (VALUE_MAX - VALUE_MIN + 1);
}

// Function to free the memory allocated for an array of records
void free_records(Record** records) {
    free(*records);
    *records = NULL;
}
