To minimize memory allocations, you can use a combination of static and dynamic allocation for the record array. Static allocation can be used to preallocate fixed-size buffers for the record array, while dynamic allocation can be used to allocate memory for individual records as needed. This approach allows for efficient use of system resources while also ensuring that the memory management functions handle errors gracefully and prevent resource leaks.
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Define the maximum number of records that can be stored
#define MAX_RECORDS 1000

// Define the ranges for generating random values
#define OFFSET_MIN -1000000
#define OFFSET_MAX 1000000
#define KEY_MIN 1
#define KEY_MAX 100
#define VALUE_MIN -1.0e6
#define VALUE_MAX 1.0e6

// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Function to allocate memory for and initialize an array of records using static allocation
void init_records(Record* records, size_t num_records) {
    // Use a fixed-size buffer to store the records
    char* buffer = (char*) malloc(num_records * sizeof(Record));
    if (buffer == NULL) {
        printf("Error: Could not allocate memory for record array\n");
        return;
    }

    // Initialize the records using static allocation
    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = OFFSET_MIN + rand() % (OFFSET_MAX - OFFSET_MIN + 1);
        records[i].key = KEY_MIN + rand() % (KEY_MAX - KEY_MIN + 1);
        records[i].value = VALUE_MIN + rand() % (VALUE_MAX - VALUE_MIN + 1);
    }
}

// Function to update a record's fields with new random values using dynamic allocation
void update_record(Record* record) {
    // Use dynamic allocation to allocate memory for the new record
    char* buffer = (char*) malloc(sizeof(Record));
    if (buffer == NULL) {
        printf("Error: Could not allocate memory for record\n");
        return;
    }

    // Initialize the new record using dynamic allocation
    (*record).offset = OFFSET_MIN + rand() % (OFFSET_MAX - OFFSET_MIN + 1);
    (*record).key = KEY_MIN + rand() % (KEY_MAX - KEY_MIN + 1);
    (*record).value = VALUE_MIN + rand() % (VALUE_MAX - VALUE_MIN + 1);
}

// Function to free the memory allocated for an array of records using dynamic allocation
void free_records(Record* records, size_t num_records) {
    // Use dynamic allocation to free the memory allocated for each record
    for (size_t i = 0; i < num_records; i++) {
        free(records[i]);
    }
}
