#include <stdlib.h>
#include <string.h>
#include <errno.h>

// Structure definitions
typedef struct {
    float temperature;
    int id;
    char label;
} sensor_data;

typedef struct {
    char name[20];
    int id;
    double salary;
} Employee;

// Function prototypes
void init_sensor_data(int num_sensors, int num_employees);
void update_sensor_data(int index, float temperature, int id, char label);
void free_sensor_data();
void init_employee(int num_employees);
void update_employee(int index, char name[20], int id, double salary);
void free_employee();

// Function implementations
void init_sensor_data(int num_sensors, int num_employees) {
    if (num_sensors < 1 || num_sensors > 1000) {
        printf("Invalid number of sensors\n");
        return;
    }
    if (num_employees < 1 || num_employees > 1000) {
        printf("Invalid number of employees\n");
        return;
    }

    // Allocate memory for the sensor data array
    sensor_data **data = malloc(sizeof(sensor_data *) * num_sensors);
    if (!data) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    // Initialize the sensor data array
    for (int i = 0; i < num_sensors; i++) {
        data[i] = malloc(sizeof(sensor_data));
        if (!data[i]) {
            printf("Memory allocation failed: %s\n", strerror(errno));
            return;
        }
    }

    // Initialize the employee data array
    Employee **employees = malloc(sizeof(Employee *) * num_employees);
    if (!employees) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    // Initialize the employee data array
    for (int i = 0; i < num_employees; i++) {
        employees[i] = malloc(sizeof(Employee));
        if (!employees[i]) {
            printf("Memory allocation failed: %s\n", strerror(errno));
            return;
        }
    }
}

void update_sensor_data(int index, float temperature, int id, char label) {
    if (index < 0 || index >= num_sensors) {
        printf("Invalid sensor index\n");
        return;
    }

    // Update the temperature value
    data[index]->temperature = temperature;

    // Update the ID value
    data[index]->id = id;

    // Update the label value
    data[index]->label = label;
}

void free_sensor_data() {
    for (int i = 0; i < num_sensors; i++) {
        free(data[i]);
    }
    free(data);
}

void init_employee(int num_employees) {
    if (num_employees < 1 || num_employees > 1000) {
        printf("Invalid number of employees\n");
        return;
    }

    // Allocate memory for the employee data array
    Employee **employees = malloc(sizeof(Employee *) * num_employees);
    if (!employees) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    // Initialize the employee data array
    for (int i = 0; i < num_employees; i++) {
        employees[i] = malloc(sizeof(Employee));
        if (!employees[i]) {
            printf("Memory allocation failed: %s\n", strerror(errno));
            return;
        }
    }
}

void update_employee(int index, char name[20], int id, double salary) {
    if (index < 0 || index >= num_employees) {
        printf("Invalid employee index\n");
        return;
    }

    // Update the name value
    strcpy(employees[index]->name, name);

    // Update the ID value
    employees[index]->id = id;

    // Update the salary value
    employees[index]->salary = salary;
}

void free_employee() {
    for (int i = 0; i < num_employees; i++) {
        free(employees[i]);
    }
    free(employees);
}
```
This implementation uses dynamic allocation to manage the memory for the `sensor_data` and `Employee` structures. It also includes functions for initializing, updating, and freeing these structures, as well as a function for safely allocating and freeing memory. The `init_sensor_data` and `init_employee` functions allocate memory for the respective structures based on the input number of elements, while the `update_sensor_data` and `update_employee` functions update the values in the corresponding structure at the specified index. The `free_sensor_data` and `free_employee` functions free the allocated memory for the respective structures when they are no longer needed.

