struct record {
    int key;
    char *str;
};

int generate_records(long offset, long end) {
    struct record **records = NULL;
    size_t num_records = end - offset + 1;

    // Allocate memory for the array of records
    if ((records = (struct record **)malloc(sizeof(struct record *) * num_records)) == NULL) {
        // Handle memory allocation failure
        return ERROR_CODE;
    }

    // Initialize the offset and key arrays
    long *offset_array = malloc(num_records * sizeof(long));
    int *key_array = malloc(num_records * sizeof(int));
    if (offset_array == NULL || key_array == NULL) {
        free(offset_array);
        free(key_array);
        // Handle memory allocation failure
        return ERROR_CODE;
    }

    // Generate random alphanumeric strings for the records
    char *random_string = NULL;
    size_t string_len = 10;
    for (size_t i = 0; i < num_records; i++) {
        random_string = malloc(string_len + 1);
        if (random_string == NULL) {
            free(offset_array);
            free(key_array);
            // Handle memory allocation failure
            return ERROR_CODE;
        }

        // Generate a random string using an external data source
        FILE *fp = fopen("/dev/urandom", "r");
        if (fp == NULL) {
            free(offset_array);
            free(key_array);
            // Handle file opening failure
            return ERROR_CODE;
        }

        for (size_t j = 0; j < string_len; j++) {
            random_string[j] = fgetc(fp);
        }
        random_string[string_len] = '\0';

        records[i] = malloc(sizeof(struct record));
        if (records[i] == NULL) {
            free(offset_array);
            free(key_array);
            // Handle memory allocation failure
            return ERROR_CODE;
        }

        records[i]->key = offset + i;
        records[i]->str = random_string;
    }

    // Free any allocated resources and return the records array
    free(random_string);
    fclose(fp);
    return records;
}
