    void* memory;
    size_t size;
} mempool;

// Function to safely allocate memory for audio data structures
void *allocate_audio_data(size_t n) {
    void *memory = malloc(n);
    if (!memory) {
        perror("Memory allocation failed");
        exit(1);
    }
    return memory;
}

// Function to safely initialize audio data structures
void init_audio_data(audio_data *data, size_t n) {
    for (size_t i = 0; i < n; i++) {
        data[i].amplitude = 0.0;
        data[i].timestamp = 0;
        data[i].metadata[0] = '\0';
        data[i].offset = 0;
    }
}

// Function to safely update audio data structures
void update_audio_data(audio_data *data, size_t n) {
    for (size_t i = 0; i < n; i++) {
