    for (size_t i = 0; i < n; i++) {
        rec[i].reading = rand() % 100 + 1;
        snprintf(rec[i].identifier, sizeof(rec[i].identifier), "%d", i);
    }
}

// Function to safely free memory allocated for record structures
void free_record(record *rec, size_t n) {
    free(rec);
}

int main() {
    // Initialize memory pool manager
    mempool pool;
    pool.memory = malloc(sizeof(audio_data) * 1024);
    pool.size = sizeof(audio_data) * 1024;

    // Initialize audio data structures and allocate memory for them
