// Structures for records and logs
typedef struct {
    int key;
    char* string;
} Record;

typedef struct {
    long offset;
    time_t timestamp;
    char* message;
} LogEntry;

// Function to dynamically allocate memory for arrays
void initializeArrays(int numRecords, int numLogEntries) {
    // Allocate memory for arrays
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    LogEntry** logs = (LogEntry**)malloc(numLogEntries * sizeof(LogEntry*));
    if (!logs) {
        fprintf(stderr, "Failed to allocate memory for logs\n");
        free(records);
        return;
    }

    // Initialize arrays with default values
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i);
            free(records);
            free(logs);
            return;
        }
    }

    for (int i = 0; i < numLogEntries; i++) {
        logs[i] = (LogEntry*)malloc(sizeof(LogEntry));
        if (!logs[i]) {
            fprintf(stderr, "Failed to allocate memory for log entry %d\n", i);
            free(records);
            free(logs);
            return;
        }
    }

    // Initialize record and log arrays with default values
    for (int i = 0; i < numRecords; i++) {
        records[i]->key = 0;
        records[i]->string = NULL;
    }

    for (int i = 0; i < numLogEntries; i++) {
        logs[i]->offset = 0;
        logs[i]->timestamp = time(NULL);
        logs[i]->message = NULL;
    }

    // Load records from file
    FILE* recordFile = fopen("records.csv", "r");
    if (!recordFile) {
        fprintf(stderr, "Failed to open records file\n");
        free(records);
        free(logs);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), recordFile)) {
        int key = 0;
        sscanf(line, "%d", &key);
        Record* newRecord = (Record*)malloc(sizeof(Record));
        if (!newRecord) {
            fprintf(stderr, "Failed to allocate memory for new record\n");
            free(records);
            free(logs);
            return;
        }
        records[numRecords++] = newRecord;
        newRecord->key = key;
        newRecord->string = NULL;
    }

    fclose(recordFile);

    // Load logs from file
    FILE* logFile = fopen("logs.csv", "r");
    if (!logFile) {
        fprintf(stderr, "Failed to open logs file\n");
        free(records);
        free(logs);
        return;
    }

    while (fgets(line, sizeof(line), logFile)) {
        long offset = 0;
        time_t timestamp = 0;
        char* message = NULL;
        sscanf(line, "%ld,%lld,%[^\n]", &offset, &timestamp, message);
        LogEntry* newLog = (LogEntry*)malloc(sizeof(LogEntry));
        if (!newLog) {
            fprintf(stderr, "Failed to allocate memory for new log entry\n");
            free(records);
            free(logs);
            return;
        }
        logs[numLogEntries++] = newLog;
        newLog->offset = offset;
        newLog->timestamp = timestamp;
        newLog->message = message;
    }

    fclose(logFile);
}

// Function to free memory for arrays
void freeArrays() {
    // Free record and log arrays
    for (int i = 0; i < numRecords; i++) {
        free(records[i]->string);
        records[i] = NULL;
    }

    for (int i = 0; i < numLogEntries; i++) {
        free(logs[i]->message);
        logs[i] = NULL;
    }

    // Free memory for arrays
    free(records);
    records = NULL;
    free(logs);
    logs = NULL;
}
