// Function to initialize the arrays and generate random strings
int init_arrays(long* offsets, int* keys, Record** records, long offset_range, int key_range) {
    // Check for invalid input parameters
    if (offsets == NULL || keys == NULL || records == NULL || offset_range < 0 || key_range < 0) {
        return -1;
    }

    // Allocate memory for the arrays
    offsets = (long*)malloc(offset_range * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        return -2;
    }

    keys = (int*)malloc(key_range * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return -3;
    }

    records = (Record**)malloc(key_range * sizeof(Record*));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return -4;
    }

    // Initialize the offset and key arrays
    for (long i = 0; i < offset_range; i++) {
        offsets[i] = rand() % offset_range;
    }

    for (int j = 0; j < key_range; j++) {
        keys[j] = rand() % key_range;
    }

    // Initialize the record structures with random strings
    for (int i = 0; i < key_range; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (records[i] == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return -5;
        }

        records[i]->key = keys[i];
        records[i]->value = (char*)malloc(10 * sizeof(char));
        if (records[i]->value == NULL) {
            printf("Error: Failed to allocate memory for record %d's value\n", i);
            free(offsets);
            free(keys);
            free(records[i]);
            records[i] = NULL;
            return -6;
        }

        // Generate a random alphanumeric string of length 10 for the value
        int len = 10;
        while (len--) {
            records[i]->value[len] = 'a' + rand() % 26;
        }
    }

    return 0;
}

// Function to dynamically resize the arrays based on input ranges
int resize_arrays(long* offsets, int* keys, Record** records, long new_offset_range, int new_key_range) {
    // Check for invalid input parameters
    if (offsets == NULL || keys == NULL || records == NULL || new_offset_range < 0 || new_key_range < 0) {
        return -1;
    }

    long* new_offsets = (long*)realloc(offsets, new_offset_range * sizeof(long));
    if (new_offsets == NULL) {
        printf("Error: Failed to reallocate memory for offset array\n");
        return -2;
    }
    offsets = new_offsets;

    int* new_keys = (int*)realloc(keys, new_key_range * sizeof(int));
    if (new_keys == NULL) {
        printf("Error: Failed to reallocate memory for key array\n");
        free(offsets);
        return -3;
    }
    keys = new_keys;

    Record** new_records = (Record**)realloc(records, new_key_range * sizeof(Record*));
    if (new_records == NULL) {
        printf("Error: Failed to reallocate memory for record array\n");
        free(offsets);
        free(keys);
        return -4;
    }
    records = new_records;

    // Initialize the new offset and key arrays
    for (long i = 0; i < new_offset_range; i++) {
