// Function to append a slash to the end of a string if it does not exceed a given size limit, or return NULL otherwise
char* append_slash(const char* str, int size_limit) {
    if (!str || !size_limit) return NULL;

    // Get the length of the input string
    int len = strlen(str);

    // Check if the input string exceeds the size limit
    if (len >= size_limit) return NULL;

    // Allocate memory for the output string
    char* out = malloc(sizeof(char) * (len + 1));
    if (!out) return NULL;

    // Copy the input string to the output string, appending a slash at the end
    strcpy(out, str);
    out[len] = '/';
    out[len + 1] = '\0';

    return out;
}"]

