    size_t written = fwrite(records, sizeof(Record), num_records, file);
    if (written != num_records) {
        fprintf(stderr, "Failed to write %d records to file %s\n", num_records, filename);
        fclose(file);
        free(records);
        return NULL;
    }

    // Close the file and free the memory used for serialization
    if (fclose(file) != 0) {
        fprintf(stderr, "Failed to close file %s\n", filename);
    }

    // Deserialization functionality
    FILE *input_file = fopen(filename, "rb");
    if (input_file == NULL) {
        fprintf(stderr, "Failed to open file %s for reading\n", filename);
        free(records);
        return NULL;
    }

    // Read the data structure from the binary file and assign it to the output parameter
    size_t read = fread(records, sizeof(Record), num_records, input_file);
    if (read != num_records) {
        fprintf(stderr, "Failed to read %d records from file %s\n", num_records, filename);
        fclose(input_file);
        free(records);
        return NULL;
    }

    // Close the file and free the memory used for deserialization
    if (fclose(input_file) != 0) {
        fprintf(stderr, "Failed to close file %s\n", filename);
    }

    // Free the memory used for serialization and deserialization
    free(filename);

    return records;
}

int main() {
    // Test the function by initializing an array of 10 records with values from 1 to 100
    int num_records = 10;
    Record *records = init_records(num_records, 1, 100);
    if (records == NULL) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    // Print the values of each record and free the memory used for the array
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: value = %d, string = %s, offset = %ld\n", i, records[i].value, records[i].string, records[i].offset);
    }
    free(records);

    return EXIT_SUCCESS;
}
```
