// Define the function to load a resource bundle from a file and return it
char* load_resource_bundle(const char* filename) {
    // Open the file for reading in binary mode
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        // Handle error gracefully
        return NULL;
    }

    // Determine the size of the file using ftell and rewind
    long filesize = 0;
    fseek(fp, 0, SEEK_END);
    filesize = ftell(fp);
    rewind(fp);

    // Allocate memory for the resource bundle
    char* bundle = (char*) malloc(filesize + 1);

    // Read the file into the memory allocated for the resource bundle
    fread(bundle, filesize, 1, fp);

    // Close the file and return the resource bundle
    fclose(fp);
    return bundle;
