    long *offset = allocate_memory(offset_size);
    size_t key_size = sizeof(int) * num_records;
    int *key = allocate_memory(key_size);
    size_t record_size = sizeof(Record) * num_records;
    Record *record = allocate_memory(record_size);

    // Initialize the offset array
    for (int i = 0; i < num_records; i++) {
        offset[i] = i * sizeof(Record);
