// Define the structure for each record
typedef struct {
    int key;
    char string[20];
} record_t;

// Define the structure for metadata
typedef struct {
    time_t timestamp;
    bool modified;
} metadata_t;

// Function to allocate memory for an array of long values
void *allocate_long_array(size_t n) {
    // Allocate memory for the array
    long *arr = malloc(n * sizeof(long));
    if (!arr) {
        perror("Error allocating memory for long array");
        exit(EXIT_FAILURE);
    }
    return arr;
}

// Function to initialize an array of int keys
void init_int_keys(int *keys, size_t n) {
    // Generate random values within the given range for each key
    for (size_t i = 0; i < n; i++) {
        keys[i] = rand() % 100 + 1;
    }
}

// Function to initialize an array of record structures
void init_records(record_t *records, size_t n) {
    // Initialize each record with a random value for its int field and a fixed string
    for (size_t i = 0; i < n; i++) {
        records[i].key = rand() % 100 + 1;
        memset(records[i].string, ' ', sizeof(records[i].string));
    }
}

// Function to initialize an array of metadata structures
void init_metadata(metadata_t *metadata, size_t n) {
    // Initialize each metadata structure with a current timestamp and the modified flag set to false
    for (size_t i = 0; i < n; i++) {
        metadata[i].timestamp = time(NULL);
        metadata[i].modified = false;
    }
}

// Function to update the timestamps in each metadata structure based on a given time delta
void update_timestamps(metadata_t *metadata, size_t n, long delta) {
    // Update each timestamp by adding the given time delta
    for (size_t i = 0; i < n; i++) {
        metadata[i].timestamp += delta;
    }
}

// Function to safely allocate memory for and initialize an array of records
void allocate_and_init_records(record_t **records, size_t n) {
    // Allocate memory for the array of records
    *records = malloc(n * sizeof(record_t));
    if (!*records) {
        perror("Error allocating memory for record array");
        exit(EXIT_FAILURE);
    }

    // Initialize each record with a random value for its int field and a fixed string
    init_records(*records, n);
}

// Function to safely allocate memory for and initialize an array of metadata structures
void allocate_and_init_metadata(metadata_t **metadata, size_t n) {
    // Allocate memory for the array of metadata structures
    *metadata = malloc(n * sizeof(metadata_t));
    if (!*metadata) {
        perror("Error allocating memory for metadata array");
        exit(EXIT_FAILURE);
    }

    // Initialize each metadata structure with a current timestamp and the modified flag set to false
    init_metadata(*metadata, n);
}

// Function to safely update the timestamps in an array of metadata structures based on a given time delta
void update_timestamps_threadsafe(metadata_t *metadata, size_t n, long delta) {
    // Use a spinlock to protect the critical section during updates
    pthread_spinlock_t lock;
    pthread_spin_init(&lock, PTHREAD_PROCESS_PRIVATE);

    // Update each timestamp by adding the given time delta
    for (size_t i = 0; i < n; i++) {
        pthread_spin_lock(&lock);
        metadata[i].timestamp += delta;
        pthread_spin_unlock(&lock);
    }

    // Clean up the spinlock
    pthread_spin_destroy(&lock);
}

// Function to safely allocate and initialize an array of records
void allocate_and_init_records_threadsafe(record_t **records, size_t n) {
    // Use a mutex to protect the critical section during memory allocation and initialization
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for the array of records
    *records = malloc(n * sizeof(record_t));
    if (!*records) {
        perror("Error allocating memory for record array");
        exit(EXIT_FAILURE);
    }

    // Initialize each record with a random value for its int field and a fixed string
    init_records(*records, n);

    // Clean up the mutex
    pthread_mutex_destroy(&lock);
}

// Function to safely allocate and initialize an array of metadata structures
void allocate_and_init_metadata_threadsafe(metadata_t **metadata, size_t n) {
    // Use a read-write lock to protect the critical section during memory allocation and initialization
    pthread_rwlock_t *lock = malloc(sizeof(pthread_rwlock_t));
    if (!lock) {
        perror("Error allocating memory for read-write lock");
        exit(EXIT_FAILURE);
    }

    // Initialize the read-write lock with the appropriate attributes
    pthread_rwlock_init(lock, NULL);

    // Allocate memory for the array of metadata structures
    *metadata = malloc(n * sizeof(metadata_t));
    if (!*metadata) {
        perror("Error allocating memory for metadata array");
        exit(EXIT_FAILURE);
    }

    // Initialize each metadata structure with a current timestamp and the modified flag set to false
    init_metadata(*metadata, n);

    // Clean up the read-write lock
    pthread_rwlock_destroy(lock);
}
