        exit(1);
    }
    *array = new_array;
}

void free_long_array(long **array) {
    free(*array);
    *array = NULL;
}

void free_int_array(int **array) {
    free(*array);
    *array = NULL;
}

// DNS resolution function

u_char* resolve_dns(const char* hostname, int* error_code) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // or AF_INET6 to resolve IPv6 addresses as well
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        *error_code = 1; // DNS resolution failed
        return NULL;
    }

    struct in_addr** addr_list = (struct in_addr**) res->ai_addr;
    u_char* ip_address = malloc(sizeof(u_char) * INET_ADDRSTRLEN);
    if (ip_address == NULL) {
        printf("Error: Out of memory!");
        exit(1);
    }

    inet_ntop(AF_INET, addr_list[0]->s_addr, ip_address, INET_ADDRSTRLEN);
    freeaddrinfo(res);
    return ip_address;
}

