#[derive(Debug)]
struct Record {
    int: i32,
}

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 4 {
        println!("Usage: {} <long_offset_count> <int_key_count> <record_count>", args[0]);
        return Ok(());
    }

    let long_offset_count = args[1].parse::<usize>()?;
    let int_key_count = args[2].parse::<usize>()?;
    let record_count = args[3].parse::<usize>()?;

    let mut long_offsets: Vec<i64> = Vec::with_capacity(long_offset_count);
    for _ in 0..long_offset_count {
        long_offsets.push(random());
    }

    let mut int_keys: Vec<i32> = Vec::with_capacity(int_key_count);
    for _ in 0..int_key_count {
        int_keys.push(random());
    }

    let mut records: Vec<Record> = Vec::with_capacity(record_count);
    for _ in 0..record_count {
        let record = Record {
            int: random(),
        };
        records.push(record);
    }

    let long_offsets_ptr = long_offsets.as_mut_ptr();
    let int_keys_ptr = int_keys.as_mut_ptr();
    let record_count_ptr = &records.len() as *const usize;

    spawn_blocking(move || {
        unsafe {
            // Call C function here to allocate memory for arrays and initialize them
            let result = init_arrays(long_offsets_ptr, int_keys_ptr, record_count_ptr);
            if result != 0 {
                eprintln!("Error initializing arrays: {}", result);
            }
        }
    }).await?;

    Ok(())
}
