use std::error::Error;
use std::fs::File;
use std::io::{BufReader, BufRead};
use std::vec::Vec;
use std::ptr::null_mut;
use std::slice::from_raw_parts;
use std::mem::size_of;

extern crate tokio;

struct Config {
    enable_logging: bool,
    range: i32,
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = std::env::args();
    if args.len() < 3 {
        println!("Usage: {} config.txt offsets.txt keys.txt", args[0]);
        return Ok(());
    }

    // Parse configuration settings from `config.txt`
    let config = parse_config(&args[1])?;
    if !config.enable_logging {
        println!("Logging is disabled.");
    }

    // Initialize arrays for 'long' offset values, 'int' keys, and 'record' structures
    let mut offsets: Vec<i64> = Vec::new();
    let mut keys: Vec<i32> = Vec::new();
    let mut records: Vec<Record> = Vec::new();

    // Read offset values from `offsets.txt` file
    let file_offset = File::open(&args[2])?;
    let reader_offset = BufReader::new(file_offset);
    for line in reader_offset.lines() {
        let offset = line?.parse::<i64>()?;
        offsets.push(offset);
    }

    // Read unique integer values from `keys.txt` file
    let file_key = File::open(&args[3])?;
    let reader_key = BufReader::new(file_key);
    for line in reader_key.lines() {
        let key = line?.parse::<i32>()?;
        keys.push(key);
    }

    // Initialize record structures based on offset and key arrays
    let mut i = 0;
    while i < offsets.len() && i < keys.len() {
        records.push(Record::new(offsets[i], keys[i]));
        i += 1;
    }

    // Log initialization process and potential errors
    if config.enable_logging {
        println!("Initialized {} offset values, {} key values, and {} record structures.", offsets.len(), keys.len(), records.len());
    }

    // Set random value to each record's int field within specified range
    for record in &mut records {
        let mut rng = rand::thread_rng();
        record.set_int(rng.gen_range(0..config.range));
    }

    // Clean up memory allocated for arrays
    drop(offsets);
    drop(keys);
    drop(records);

    Ok(())
}

struct Record {
    offset: i64,
    key: i32,
    int: i32,
}

impl Record {
    fn new(offset: i64, key: i32) -> Self {
        Self {
            offset,
            key,
            int: 0,
        }
    }

    fn set_int(&mut self, value: i32) {
        self.int = value;
    }
}

fn parse_config(filename: &str) -> Result<Config, Box<dyn Error>> {
    let file = File::open(filename)?;
    let reader = BufReader::new(file);
    let mut config = Config {
        enable_logging: false,
        range: 0,
    };

    for line in reader.lines() {
        let line = line?;
        if line.starts_with("enable_logging") {
            let parts: Vec<&str> = line.split('=').collect();
            config.enable_logging = parts[1].parse::<bool>()?;
        } else if line.starts_with("range") {
            let parts: Vec<&str> = line.split('=').collect();
            config.range = parts[1].parse::<i32>()?;
        }
    }

    Ok(config)
}
