    if (maxSize <= 0) {
        printf("Invalid maximum size provided\n");
        return;
    }

    // Allocate memory for the arrays of offset values, keys, and records
    long* offsets = malloc(sizeof(long) * maxSize);
    int* keys = malloc(sizeof(int) * maxSize);
    Record* records = malloc(sizeof(Record) * maxSize);

    // Check if memory allocation failed, and handle the error if so
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failure\n");
        return;
    }

    // Set all values in the array of offset values to zero
    for (int i = 0; i < maxSize; i++) {
        offsets[i] = 0;
    }

    // Set all values in the array of keys to a random integer within a given range (0 to 100)
    srand(time(NULL));
    for (int i = 0; i < maxSize; i++) {
        keys[i] = rand() % 100;
