// Struct to hold a record with an integer value, a string, and a timestamp
struct record {
    int value;
    char* str;
    time_t timestamp;
};

int initialize_records(size_t count, int min_value, int max_value) {
    // Check if any of the input parameters are invalid
    if (count <= 0 || min_value < 0 || max_value < 0) {
        return -1;
    }

    // Allocate memory for three arrays: one for integers, one for strings, and one for records
    int* int_array = malloc(count * sizeof(int));
    char** str_array = malloc(count * sizeof(char*));
    struct record** record_array = malloc(count * sizeof(struct record*));

    // Check if memory allocation failed
    if (int_array == NULL || str_array == NULL || record_array == NULL) {
        free(int_array);
        free(str_array);
        free(record_array);
        return -1;
    }

    // Generate random integer values and unique strings for each record
    for (size_t i = 0; i < count; ++i) {
        int_array[i] = rand() % (max_value - min_value + 1) + min_value;

        char* str = generate_unique_string();
        if (str == NULL) {
            free(int_array);
            free(str_array);
            free(record_array);
            return -1;
        }
        str_array[i] = str;
    }

    // Set the timestamp for each record
    time_t current_timestamp = time(NULL);
    for (size_t i = 0; i < count; ++i) {
        record_array[i]->timestamp = current_timestamp;
    }

    // Return 0 on success, -1 on failure
    return 0;
}

// Function to generate a unique string
char* generate_unique_string() {
    char* str = malloc(16);
    if (str == NULL) {
        return NULL;
    }

    // Generate random characters for the string
    for (size_t i = 0; i < 16; ++i) {
        int c = rand() % ('z' - 'a') + 'a';
        str[i] = c;
    }

    // Make sure the string is unique by checking if it already exists in str_array
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(str, str_array[i]) == 0) {
            free(str);
            return NULL;
        }
    }

    // Return the unique string
    return str;
}
```
