record* init_records(long num_records, int min_val, int max_val) {
    // Check if the input parameters are valid
    if (num_records <= 0 || min_val >= max_val) {
        return NULL;
    }

    // Allocate memory for the arrays of offsets and keys
    long* offsets = malloc(sizeof(long) * num_records);
    int* keys = malloc(sizeof(int) * num_records);
    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the arrays of offsets and keys
    for (long i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_val - min_val + 1) + min_val;
        keys[i] = rand() % max_val + 1;
    }

    // Allocate memory for the array of records
    record* records = malloc(sizeof(record) * num_records);
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the array of records with the values from the arrays of offsets and keys
    for (long i = 0; i < num_records; i++) {
        records[i].key = keys[i];
    }

    // Free the memory allocated for the arrays of offsets and keys
    free(offsets);
    free(keys);

    return records;
}
