int start_python_service(int num_sensors) {
    // Allocate memory for the Python service command line arguments
    char** argv = (char**) malloc((num_sensors + 1) * sizeof(char*));
    if (!argv) {
        fprintf(stderr, "Error: Failed to allocate memory for Python service command line arguments\n");
        return -1;
    }

    // Set the first argument as the path to the Python executable
