    if (process_handle < 0) {
        fprintf(stderr, "Error: Failed to start Python service\n");
        free(argv);
        return -1;
    } else if (process_handle == 0) {
        // Child process executes the Python service
        execv("/usr/bin/python3", argv);
        fprintf(stderr, "Error: Failed to execute Python service\n");
        free(argv);
        return -1;
    } else {
        // Parent process waits for the Python service to finish
        waitpid(process_handle, NULL, 0);
        free(argv);
        return process_handle;
    }
}

// Function to stop a Python service, given its process handle
void stop_python_service(int process_handle) {
    // Stop the Python service with the process handle
    kill(process_handle, SIGTERM);
}

// Main function
int main() {
    // Initialize the sensor data structure
    int num_sensors = 4;
    sensor_data_t* sensor_data = init_sensor_data(num_sensors);

    // Start a Python service to process the sensor data
    manage_python_service(num_sensors);

    // Update the sensor data with new readings from the sensors
    update_sensor_data(sensor_data, num_sensors);

    // Send the updated sensor data to the Python service for processing
    send_sensor_data(sensor_data, num_sensors);

    return 0;
}
```

This program uses a `sensor_data_t` structure to store the sensor readings and a function called `update_sensor_data()` to update the data with new readings from the sensors. The `manage_python_service()` function is responsible for starting and stopping the Python service, which processes the updated sensor data using the `process_sensor_data()` function. The program also includes a `send_sensor_data()` function to send the updated sensor data to the Python service.

The program uses a `start_python_service()` function to start the Python service with a random delay between 0 and 10 seconds, using the `fork()`, `execv()`, and `waitpid()` functions to handle the process creation and termination. The `stop_python_service()` function is responsible for stopping the Python service using the `kill()` function.

The program also uses a `free_sensor_data()` function to deallocate memory for the sensor data structure, and a `manage_python_service()` function to start and stop the Python service with random delays.']

