// Define functions for managing the lifecycle of allocated memory
void allocate_memory(size_t num_records, size_t num_values) {
    // Allocate memory for the offset array
    long *offsets = malloc(num_records * sizeof(*offsets));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the key array
    int *keys = malloc(num_records * sizeof(*keys));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the value array
    double *values = malloc(num_records * num_values * sizeof(*values));
    if (!values) {
        perror("Failed to allocate memory for values");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Initialize the offset array with the starting indices of each record in the value array
    size_t i;
    for (i = 0; i < num_records; ++i) {
        offsets[i] = i * num_values;
    }

    // Allocate memory for and initialize the record array
    Record *records = malloc(num_records * sizeof(*records));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        free(values);
        exit(EXIT_FAILURE);
    }

    // Set the value of each record's int field to a random value within a given range and point to the corresponding double value array
    srand((unsigned)time(NULL));
    for (i = 0; i < num_records; ++i) {
        records[i].key = rand() % 100;
        records[i].value = &values[offsets[i]];
    }
}

void free_memory(Record *records, size_t num_records) {
    // Free the memory allocated for the record array
    free(records);

    // Free the memory allocated for the value array
    free(records->value);

    // Free the memory allocated for the key array
    free(records->key);

    // Free the memory allocated for the offset array
    free(offsets);
}

// Define a function to update the double value pointed to by each record based on some external condition or trigger
void update_values(Record *records, size_t num_records) {
    // Check if any of the records have been updated and update their corresponding double values accordingly
    size_t i;
    for (i = 0; i < num_records; ++i) {
        if (records[i].updated) {
            records[i].value[offsets[i]] = records[i].new_value;
            records[i].updated = false;
        }
    }
}

// Define a function to serialize (save) and deserialize (load) these records into a file in a structured format
void serialize(Record *records, size_t num_records, FILE *file) {
    // Write the number of records to the file
    fwrite(&num_records, sizeof(size_t), 1, file);

    // Write each record's key and value to the file
    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i].key, sizeof(int), 1, file);
        fwrite(records[i].value, sizeof(double), num_values, file);
    }
}

void deserialize(Record *records, size_t num_records, FILE *file) {
    // Read the number of records from the file
    fread(&num_records, sizeof(size_t), 1, file);

    // Allocate memory for the record array and initialize it with the read values
    Record *new_records = malloc(num_records * sizeof(*new_records));
    if (!new_records) {
        perror("Failed to allocate memory for new records");
        exit(EXIT_FAILURE);
    }

    // Read each record's key and value from the file and assign it to the corresponding field in the record array
    for (size_t i = 0; i < num_records; ++i) {
        fread(&new_records[i].key, sizeof(int), 1, file);
        fread(new_records[i].value, sizeof(double), num_values, file);
    }
}

