    // Allocate memory for the array of structures
    DataStructure *data_structures = malloc(sizeof(DataStructure) * num_structures);
    if (data_structures == NULL) {
        return NULL;
    }

    // Initialize each structure with pointers to dynamic arrays
    for (int i = 0; i < num_structures; i++) {
        data_structures[i].temperature_readings = malloc(sizeof(TemperatureReading) * max_readings_per_structure);
        data_structures[i].location = malloc(sizeof(Location) * 1);
        data_structures[i].timestamp = malloc(sizeof(Timestamp) * 1);

        // Check for allocation failures and handle them appropriately
        if (data_structures[i].temperature_readings == NULL || data_structures[i].location == NULL || data_structures[i].timestamp == NULL) {
            free(data_structures);
            return NULL;
        }
    }

    // Initialize the arrays with default values
    for (int i = 0; i < num_structures; i++) {
        for (int j = 0; j < max_readings_per_structure; j++) {
            data_structures[i].temperature_readings[j] = 0.0f;
            data_structures[i].location[0] = strdup("");
            data_structures[i].timestamp[0] = 0;
        }
    }

    // Return the initialized array of structures
    return data_structures;
}

// Define a function for freeing dynamically allocated memory
void free_arrays(DataStructure *data_structures, int num_structures) {
    // Free each structure's arrays and the top-level array
    for (int i = 0; i < num_structures; i++) {
        free(data_structures[i].temperature_readings);
        free(data_structures[i].location);
        free(data_structures[i].timestamp);
    }
    free(data_structures);
}

// Define a function for adding temperature readings to the arrays
int add_reading(DataStructure *data_structures, int num_structures, int structure_index, float temperature) {
    // Check if the structure index is valid and the temperature reading is not NaN
    if (structure_index < 0 || structure_index >= num_structures || isnan(temperature)) {
        return -1;
    }

    // Increment the number of readings for the current structure
    data_structures[structure_index].num_readings++;

    // Check if the buffer is full and needs to be resized
    if (data_structures[structure_index].num_readings > max_readings_per_structure) {
        int new_size = data_structures[structure_index].num_readings * 2;
        TemperatureReading *new_temperatures = realloc(data_structures[structure_index].temperature_readings, sizeof(TemperatureReading) * new_size);
        if (new_temperatures == NULL) {
            return -1;
        }
        data_structures[structure_index].temperature_readings = new_temperatures;
    }

    // Add the temperature reading to the buffer
    data_structures[structure_index].temperature_readings[data_structures[structure_index].num_readings - 1] = temperature;
}

// Define a function for setting the location and timestamp of a structure
int set_location(DataStructure *data_structures, int num_structures, int structure_index, const char *location) {
    // Check if the structure index is valid and the location is not NULL
    if (structure_index < 0 || structure_index >= num_structures || location == NULL) {
        return -1;
    }

    // Allocate memory for the new location string
