    // Check if the structure index is valid and the timestamp is not NULL
    if (structure_index < 0 || structure_index >= num_structures || timestamp == NULL) {
        return -1;
    }

    // Set the new timestamp
    data_structures[structure_index].timestamp[0] = timestamp;
}

// Define a function for getting the number of readings in a structure
