    table->memUsage = sizeof(struct HashTable);
    // Allocate memory for the arrays of offset values, keys, and records
    size_t arraySize = maxRecords * sizeof(long);
    table->offsets = malloc(arraySize);
    if (table->offsets == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset array.\n");
        free(table);
        return NULL;
    }
    table->keys = malloc(arraySize);
    if (table->keys == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for key array.\n");
        free(table->offsets);
        free(table);
        return NULL;
    }
    table->records = malloc(arraySize);
    if (table->records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record array.\n");
        free(table->keys);
        free(table->offsets);
        free(table);
        return NULL;
    }
    // Set the initial values for the arrays of offset values and keys
    memset(table->offsets, 0, arraySize);
    memset(table->keys, 0, arraySize);
    // Initialize the random number generator with a custom seed if specified
    if (options.customSeed) {
        srand(options.seed);
    } else {
        srand(time(NULL));
    }
    // Loop over the records and set their values to random integers within the specified range
