    size_t num_records; // Number of records in the cache
    size_t max_size; // Maximum size of the cache in bytes
    size_t cur_size; // Current size of the cache in bytes
    pthread_mutex_t lock; // Lock for synchronizing access to the cache
} Cache;

// Define the function prototypes
void init_cache(Cache *cache, size_t max_size);
void destroy_cache(Cache *cache);
void insert_record(Cache *cache, Record record);
Record* lookup_record(Cache *cache, int key);
void remove_record(Cache *cache, int key);
void evict_records(Cache *cache, size_t num_records);
void cache_resize(Cache *cache, size_t new_size);
void cache_update(Cache *cache, Record record);
void print_cache_info(Cache *cache);

// Implement the function bodies

void init_cache(Cache *cache, size_t max_size) {
    // Initialize the cache structure with zero records and the maximum size
    cache->records = NULL;
    cache->num_records = 0;
    cache->max_size = max_size;
    cache->cur_size = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void destroy_cache(Cache *cache) {
    // Free the memory allocated for the records and destroy the mutex lock
    free(cache->records);
    cache->records = NULL;
    pthread_mutex_destroy(&cache->lock);
}

void insert_record(Cache *cache, Record record) {
    // Acquire the lock for synchronizing access to the cache
    pthread_mutex_lock(&cache->lock);

    // Check if there is enough space in the cache for the new record
    if (cache->cur_size + sizeof(Record) > cache->max_size) {
        // Evict records from the cache to make room for the new record
        evict_records(cache, cache->num_records - 1);
    }

    // Insert the new record into the cache
    Record *new_record = malloc(sizeof(Record));
    memcpy(new_record, &record, sizeof(Record));
    cache->records[cache->num_records++] = new_record;
    cache->cur_size += sizeof(Record);

    // Release the lock
    pthread_mutex_unlock(&cache->lock);
}

Record* lookup_record(Cache *cache, int key) {
    // Acquire the lock for synchronizing access to the cache
    pthread_mutex_lock(&cache->lock);

    // Search for the record in the cache
    Record *found_record = NULL;
    for (size_t i = 0; i < cache->num_records; i++) {
        if (cache->records[i]->key == key) {
            found_record = cache->records[i];
            break;
        }
    }

    // Release the lock
    pthread_mutex_unlock(&cache->lock);

    return found_record;
}

void remove_record(Cache *cache, int key) {
    // Acquire the lock for synchronizing access to the cache
    pthread_mutex_lock(&cache->lock);

    // Search for the record in the cache and remove it if found
    for (size_t i = 0; i < cache->num_records; i++) {
        if (cache->records[i]->key == key) {
            free(cache->records[i]);
            memmove(&cache->records[i], &cache->records[i+1], sizeof(Record) * (cache->num_records - i));
            cache->num_records--;
            cache->cur_size -= sizeof(Record);
            break;
        }
    }

    // Release the lock
    pthread_mutex_unlock(&cache->lock);
}

void evict_records(Cache *cache, size_t num_records) {
    // Acquire the lock for synchronizing access to the cache
    pthread_mutex_lock(&cache->lock);

    // Evict records from the cache starting from the oldest one
    while (num_records > 0 && cache->num_records > 0) {
        free(cache->records[0]);
        memmove(&cache->records[0], &cache->records[1], sizeof(Record) * (cache->num_records - 1));
        cache->num_records--;
        cache->cur_size -= sizeof(Record);
    }

    // Release the lock
    pthread_mutex_unlock(&cache->lock);
}

void cache_resize(Cache *cache, size_t new_size) {
    // Acquire the lock for synchronizing access to the cache
    pthread_mutex_lock(&cache->lock);

    // Check if the new size is smaller than the current size and evict records accordingly
    while (new_size < cache->cur_size) {
        evict_records(cache, cache->num_records - 1);
    }

    // Release the lock
    pthread_mutex_unlock(&cache->lock);
}

void cache_update(Cache *cache, Record record) {
    // Acquire the lock for synchronizing access to the cache
    pthread_mutex_lock(&cache->lock);

    // Search for the record in the cache and update it if found
    for (size_t i = 0; i < cache->num_records; i++) {
        if (cache->records[i]->key == record.key) {
            memcpy(cache->records[i], &record, sizeof(Record));
            break;
        }
    }

    // Release the lock
    pthread_mutex_unlock(&cache->lock);
}

int main() {
    Cache cache = initCache();

    // Insert records into the cache
    Record r1 = {.key = 1, .value = "apple"};
    Record r2 = {.key = 2, .value = "banana"};
