void initialize_data(long *offsets, int *keys, Record **records, size_t max_size, size_t num_records, size_t key_range_min, size_t key_range_max, unsigned long seed, FILE *log_file) {
    // Check input parameters and handle errors appropriately
    if (offsets == NULL || keys == NULL || records == NULL || max_size == 0 || num_records == 0 || key_range_min > key_range_max) {
        return;
    }

    // Allocate memory for the arrays and hash table
    long *offset_memory = malloc(num_records * sizeof(long));
    int *key_memory = malloc(num_records * sizeof(int));
    Record **record_memory = malloc(num_records * sizeof(Record*));
    size_t hash_table_size = (size_t)1 << 16; // 2^16
    void **hash_table = calloc(hash_table_size, sizeof(void*));

    if (offset_memory == NULL || key_memory == NULL || record_memory == NULL || hash_table == NULL) {
        free(offset_memory);
        free(key_memory);
        free(record_memory);
        free(hash_table);
        return;
    }

    // Set the seed for random number generation
    if (seed != 0) {
        srand(seed);
    } else {
        srand((unsigned int)time(NULL));
    }

    // Initialize the arrays and hash table
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        keys[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        record_memory[i] = malloc(sizeof(Record));
