// Define data structures for storing records
struct record {
    int key;
    double *value;
};

// Functions to manage the lifecycle of allocated memory
void allocate_records(int num_records, struct record **records) {
    // Allocate memory for the array of records
    *records = malloc(sizeof(struct record) * num_records);
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each record's key and value fields
    for (int i = 0; i < num_records; i++) {
        (*records)[i].key = rand() % 100 + 1;
        (*records)[i].value = malloc(sizeof(double));
        if ((*records)[i].value == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record value\n");
            exit(EXIT_FAILURE);
        }
    }
}

void free_records(struct record **records) {
    // Free memory for each record's value field
    for (int i = 0; i < num_records; i++) {
        free((*records)[i].value);
    }

    // Free memory for the array of records
    free(*records);
}

// Function to update the value of each record based on some external condition or trigger
