    // Update each record's value field based on some external condition or trigger
    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = malloc(sizeof(double));
        if ((*records)[i].value == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record value\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Functions to serialize and deserialize records to/from a file in a structured format
void save_records(struct record **records, int num_records, const char *filename) {
    // Open the output file for writing
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open output file\n");
        exit(EXIT_FAILURE);
    }

    // Write each record's key and value fields to the output file
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d %lf\n", (*records)[i].key, *((*records)[i].value));
    }

    // Close the output file
    fclose(file);
}

void load_records(struct record **records, int num_records, const char *filename) {
    // Open the input file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open input file\n");
        exit(EXIT_FAILURE);
    }

    // Read each record's key and value fields from the input file
    for (int i = 0; i < num_records; i++) {
        fscanf(file, "%d %lf", &((*records)[i].key), *((*records)[i].value));
    }

    // Close the input file
    fclose(file);
}

int main() {
    int num_records = 10;
    struct record **records = malloc(sizeof(struct record *) * num_records);
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the records using the allocate_records function
    allocate_records(num_records, &records);

    // Update the values of each record based on some external condition or trigger
    update_values(&records, num_records);

    // Serialize the records to a file in a structured format using the save_records function
    char filename[] = "records.txt";
    save_records(&records, num_records, filename);

    // Load the records from a file in a structured format using the load_records function
    load_records(&records, num_records, filename);

    // Free the memory allocated for the records using the free_records function
    free_records(&records);

    return 0;
}
