        return;
    }

    records = (record_t **)malloc(sizeof(record_t *) * 10);
    if (!records) {
        printf("Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the arrays with random values within the specified range
