    for (int i = 0; i < 10; i++) {
        offsets[i] = rand() % 1000 + 1;
        keys[i] = rand() % 1000 + 1;
        records[i] = malloc(sizeof(record_t));
        if (!records[i]) {
            printf("Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }
}

