    record->value = newValue;
}

// Function to free the allocated memory for offsets, keys, and records
void freeRecords(long *offsets, int *keys, record_t **records) {
    // Free the memory for each record structure
    for (int i = 0; i < 10; i++) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }

    // Free the memory for the arrays
    free(offsets);
    offsets = NULL;

    free(keys);
    keys = NULL;

    free(records);
    records = NULL;
}
