    int *values;
    cacheEntry_t *entries;
} cacheArray_t;

// Define the cache management functions
bool allocateAndInitializeCache(cacheArray_t *cache, long *keys, int *values) {
    // Check if the cache is already initialized
    if (cache->entries != NULL) {
        return false;
    }

    // Allocate memory for the keys and values arrays
    cache->keys = malloc(sizeof(long) * cache->size);
    cache->values = malloc(sizeof(int) * cache->size);

    // Initialize the entries array
    cache->entries = calloc(cache->size, sizeof(cacheEntry_t));

    // Initialize the keys and values arrays
    for (int i = 0; i < cache->size; i++) {
        cache->keys[i] = keys[i];
        cache->values[i] = values[i];
        srand(time(NULL));
        int randomValue = rand() % MAX_VALUE + MIN_VALUE;
        cache->entries[i].value = randomValue;
    }

    // Return success
    return true;
}

bool initializeCache(cacheArray_t *cache) {
    // Check if the cache is already initialized
    if (cache->entries != NULL) {
        return false;
    }

    // Allocate memory for the keys and values arrays
    cache->keys = malloc(sizeof(long) * cache->size);
    cache->values = malloc(sizeof(int) * cache->size);

    // Initialize the entries array
    cache->entries = calloc(cache->size, sizeof(cacheEntry_t));

    // Return success
    return true;
}

bool updateCache(cacheArray_t *cache, cacheEntry_t *entry, int newValue) {
    // Check if the entry is valid
    if (entry == NULL || !entry->valid) {
        return false;
    }

    // Update the value in the entries array
    entry->value = newValue;

    // Return success
    return true;
}

void freeCache(cacheArray_t *cache, long *keys, int *values) {
    // Check if the cache is already initialized
    if (cache->entries == NULL) {
        return;
    }

    // Free the keys and values arrays
    free(cache->keys);
    free(cache->values);

    // Free the entries array
    free(cache->entries);

    // Reset the cache
    cache->size = 0;
}
