// Function that takes a string and a size limit as input, and returns a new string that contains the input string with a slash appended to the end if the input string does not exceed the size limit, or returns NULL if it does exceed the size limit. Ensure efficient memory allocation and avoid leaks.
char* append_slash(const char* str, int size) {
    // Check if the input string is NULL or empty
    if (str == NULL || *str == '\0') {
        return NULL;
    }

    // Get the length of the input string
    int len = strlen(str);

    // Check if the input string exceeds the size limit
    if (len >= size) {
        log("Input string exceeds size limit");
        return NULL;
    }

    // Allocate memory for the new string
    char* new_str = (char*)malloc(size * sizeof(char));

    // Copy the input string to the new string
    strcpy(new_str, str);

    // Append a slash to the end of the new string
    new_str[len] = '/';

    return new_str;
}

// Function that takes a DOM tree and a size limit as input, and returns a new DOM tree that contains only the nodes that have a value less than or equal to the size limit. Ensure efficient memory allocation and avoid leaks.
void filter_dom(Node** dom_tree, int size) {
    // Check if the input DOM tree is NULL
    if (*dom_tree == NULL) {
        return;
    }

    // Allocate memory for the new DOM tree
    Node* new_dom_tree = (Node*)malloc(size * sizeof(Node));

    // Initialize the new DOM tree with default values
    for (int i = 0; i < size; i++) {
        new_dom_tree[i].key = NULL;
        new_dom_tree[i].value = NULL;
        new_dom_tree[i].left = NULL;
        new_dom_tree[i].right = NULL;
    }

    // Filter the DOM tree and add nodes to the new DOM tree that have a value less than or equal to the size limit
    filter_node(*dom_tree, new_dom_tree, 0, size);
}

// Recursive function that filters a DOM tree and adds nodes to a new DOM tree that have a value less than or equal to the size limit. Ensure efficient memory allocation and avoid leaks.
void filter_node(Node* node, Node** new_dom_tree, int index, int size) {
    // Check if the current node is NULL
    if (node == NULL) {
        return;
    }

    // Check if the value of the current node is less than or equal to the size limit
    if (node->value <= size) {
        // Add the current node to the new DOM tree
        new_dom_tree[index].key = node->key;
        new_dom_tree[index].value = node->value;
        index++;
    }

    // Recursively filter the left and right subtrees of the current node
    filter_node(node->left, new_dom_tree, index, size);
    filter_node(node->right, new_dom_tree, index, size);
}
