```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Hash table size (number of buckets)
#define TABLE_SIZE 1024
// Maximum number of records to store in the hash table
#define MAX_RECORDS 10000
// Maximum memory allocation limit (in bytes)
#define MAX_MEMORY 50000000

typedef struct record {
    int key;
    long offset;
} record;

void init(record** records, size_t* num_records) {
    // Allocate memory for the array of records and initialize it to NULL
    *records = (record*) malloc(sizeof(record) * MAX_RECORDS);
    memset(*records, 0, sizeof(record) * MAX_RECORDS);
    *num_records = 0;
}

void insert(record** records, size_t* num_records, int key, long offset) {
    // Check if the record already exists in the hash table
    for (size_t i = 0; i < *num_records; i++) {
        if ((*records)[i].key == key) {
            printf("Key %d already exists\n", key);
            return;
        }
    }

    // Check if the total memory allocated exceeds the maximum limit
    size_t mem_usage = sizeof(record) * (*num_records + 1);
    if (mem_usage > MAX_MEMORY) {
        printf("Memory allocation failed: total memory usage exceeds %zu bytes\n", MAX_MEMORY);
        return;
    }

    // Allocate memory for the new record and initialize it
    record* new_record = (record*) malloc(sizeof(record));
    if (!new_record) {
        printf("Memory allocation failed: could not allocate %zu bytes\n", sizeof(record));
        return;
    }
    memset(new_record, 0, sizeof(record));
    new_record->key = key;
    new_record->offset = offset;

    // Insert the record into the hash table and increment the number of records
    int bucket = key % TABLE_SIZE;
    (*records)[*num_records].next = NULL;
    if ((*records)[bucket].key != 0) {
        // Collision: insert the new record after the current head of the list
        record* curr = &(*records)[bucket];
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_record;
    } else {
        // No collision: insert the new record at the head of the list
        (*records)[bucket].key = key;
        (*records)[bucket].offset = offset;
    }
    (*num_records)++;
}

void remove(record** records, size_t* num_records, int key) {
    // Check if the record exists in the hash table
    for (size_t i = 0; i < *num_records; i++) {
        if ((*records)[i].key == key) {
            // Remove the record from the list and decrement the number of records
            if (*num_records > 1) {
                size_t bucket = key % TABLE_SIZE;
                record* curr = &(*records)[bucket];
                while (curr->next != NULL && curr->next->key != key) {
                    curr = curr->next;
                }
                if (curr->next == NULL) {
                    printf("Key %d does not exist\n", key);
                } else {
                    record* to_remove = curr->next;
                    curr->next = to_remove->next;
                    free(to_remove);
                    (*num_records)--;
                }
            } else {
                // Only one record in the hash table: remove it and set the head of the list to NULL
                memset(*records, 0, sizeof(record) * MAX_RECORDS);
                (*num_records) = 0;
            }
            return;
        }
    }
    printf("Key %d does not exist\n", key);
}

void lookup(record** records, size_t* num_records, int key) {
    // Check if the record exists in the hash table
    for (size_t i = 0; i < *num_records; i++) {
        if ((*records)[i].key == key) {
            printf("Key %d found with offset %ld\n", (*records)[i].key, (*records)[i].offset);
            return;
        }
    }
    printf("Key %d does not exist\n", key);
}

void dynamic_resizing(record** records, size_t* num_records) {
    // Check if the total memory usage exceeds the maximum limit
    size_t mem_usage = sizeof(record) * (*num_records + 1);
    if (mem_usage > MAX_MEMORY) {
        printf("Memory allocation failed: total memory usage exceeds %zu bytes\n", MAX_MEMORY);
        return;
    }

    // Reallocate the array of records with a new size that is larger than the current number of records
    record* new_records = (record*) realloc(*records, sizeof(record) * ((*num_records + 1) * 2));
    if (!new_records) {
        printf("Memory allocation failed: could not allocate %zu bytes\n", sizeof(record) * ((*num_records + 1) * 2));
        return;
    }
    *records = new_records;
}

void init_hash_table(record** records, size_t* num_records) {
    // Initialize the hash table with a fixed number of buckets
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        (*records)[i].key = 0;
        (*records)[i].offset = 0;
        (*records)[i].next = NULL;
    }
}
```

