        }
    }

    return name;
}

void add_employee(int id, double salary) {
    // Check if the array is initialized and expand it if necessary
    if (!is_initialized || num_employees == NUM_EMPLOYEES) {
        initialize_employees();
    }

    // Add a new Employee structure to the end of the array
    employees[num_employees].id = id;
    employees[num_employees].salary = salary;
    strcpy(employees[num_employees].name, generate_random_name());

    num_employees++;
}

void remove_employee(int id) {
    // Find the index of the Employee with the given ID in the array
    int index = -1;
    for (int i = 0; i < num_employees; i++) {
        if (employees[i].id == id) {
            index = i;
            break;
        }
    }

    // Check if the Employee was found and remove it from the array
    if (index != -1) {
        for (int i = index; i < num_employees - 1; i++) {
            employees[i] = employees[i + 1];
        }
        num_employees--;
    } else {
        printf("Error: Employee with ID %d not found\n", id);
    }
}

void update_employee(int id, double salary) {
    // Find the index of the Employee with the given ID in the array
    int index = -1;
    for (int i = 0; i < num_employees; i++) {
        if (employees[i].id == id) {
            index = i;
            break;
        }
    }

    // Check if the Employee was found and update its salary
    if (index != -1) {
        employees[index].salary = salary;
    } else {
        printf("Error: Employee with ID %d not found\n", id);
    }
}

void print_employees() {
    for (int i = 0; i < num_employees; i++) {
        printf("%s - ID: %d, Salary: $%.2f\n", employees[i].name, employees[i].id, employees[i].salary);
    }
}

void free_employee(int id) {
    // Find the index of the Employee with the given ID in the array
    int index = -1;
    for (int i = 0; i < num_employees; i++) {
        if (employees[i].id == id) {
            index = i;
            break;
        }
    }

    // Check if the Employee was found and free its memory
    if (index != -1) {
        for (int i = index; i < num_employees - 1; i++) {
            employees[i] = employees[i + 1];
        }
        num_employees--;
    } else {
        printf("Error: Employee with ID %d not found\n", id);
    }
}
