// Generate a random value within the specified range
int generateRandomValue(int min, int max) {
    // Use time() as the seed for generating random values to ensure thread safety
    srand((unsigned int)time(NULL));

    // Return a random value within the specified range
    return rand() % (max - min + 1) + min;
}

// Thread-safe implementation of malloc() using pthread_mutex_lock() and pthread_mutex_unlock() to avoid redundant checks or allocations
