    void *ptr = NULL;
    // Lock the mutex before calling malloc() to ensure thread safety
    pthread_mutex_lock(&mutex);
    ptr = realloc(NULL, size);
    // Unlock the mutex after calling malloc() to release the lock
    pthread_mutex_unlock(&mutex);

    return ptr;
}

// Thread-safe implementation of calloc() using pthread_mutex_lock() and pthread_mutex_unlock() to avoid redundant checks or allocations
void *calloc(size_t nmemb, size_t size) {
    void *ptr = NULL;
    // Lock the mutex before calling calloc() to ensure thread safety
    pthread_mutex_lock(&mutex);
    ptr = realloc(NULL, nmemb * size);
    // Unlock the mutex after calling calloc() to release the lock
    pthread_mutex_unlock(&mutex);

    return ptr;
}

// Thread-safe implementation of realloc() using pthread_mutex_lock() and pthread_mutex_unlock() to avoid redundant checks or allocations
void *realloc(void *ptr, size_t size) {
    // Lock the mutex before calling realloc() to ensure thread safety
    pthread_mutex_lock(&mutex);
    ptr = realloc(ptr, size);
    // Unlock the mutex after calling realloc() to release the lock
    pthread_mutex_unlock(&mutex);

    return ptr;
}
