// Function to connect to a database using a given username and password
int db_connect(const char* username, const char* password) {
    // Connect to the database
    sqlite3* db = NULL;
    int rc = sqlite3_open("example.db", &db);
    if (rc != SQLITE_OK) {
        printf("Error: %s\n", sqlite3_errmsg(db));
        return -1;
