    // Set the username and password for the database connection
    rc = sqlite3_exec(db, "PRAGMA busy_timeout=10000", NULL, NULL, NULL);
    if (rc != SQLITE_OK) {
        printf("Error: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Return the database connection handle
    return db;
}

// Function to execute a query on the database
void db_query(sqlite3* db, const char* query) {
    int rc = sqlite3_exec(db, query, NULL, NULL, NULL);
    if (rc != SQLITE_OK) {
        printf("Error: %s\n", sqlite3_errmsg(db));
    } else {
        // Display the query statement and result set
        char* query_statement = malloc(256 * sizeof(char));
        snprintf(query_statement, 256, "Query: %s", query);
        printf("%s\n", query_statement);
        free(query_statement);
    }
}

// Function to retrieve employee details from the database
void db_retrieve(sqlite3* db) {
    // Query to retrieve employee details
    const char* query = "SELECT id, name FROM employees";
    db_query(db, query);
}

// Function to handle errors when connecting to an external service
void handle_error(CURLcode error) {
    if (error != CURLE_OK) {
        printf("Error: %s\n", curl_easy_strerror(error));
    }
}

// Function to make a request to an HTTP server using the curl library
void http_request(const char* url, int timeout) {
    // Create a new CURL instance
    CURL* curl = curl_easy_init();
    if (curl) {
        // Set the URL and timeout for the request
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);

        // Perform the request
        CURLcode error = curl_easy_perform(curl);
        handle_error(error);

        // Clean up
        curl_easy_cleanup(curl);
    }
}

// Function to return a RequestBuilder for a given URL
RequestBuilder* http_request_builder(const char* url) {
    // Create a new RequestBuilder instance
    RequestBuilder* builder = (RequestBuilder*)malloc(sizeof(RequestBuilder));
    if (!builder) {
        printf("Error: %s\n", "Invalid input");
        return NULL;
    }

    // Set the URL for the request
    builder->url = url;
    builder->timeout = 10000;

    // Return the RequestBuilder instance
    return builder;
}

// Function to disable certificate validation for an HTTPS request
void http_request_disable_certificate_validation(RequestBuilder* builder) {
    // Set the SSL options for the request
    curl_easy_setopt(builder->curl, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(builder->curl, CURLOPT_SSL_VERIFYHOST, 0L);
}

// Function to return a list of random values within a specified range
long* get_random_values(size_t size, int min, int max) {
    // Allocate memory for the array
    long* values = malloc(size * sizeof(long));
    if (!values) {
        printf("Error: %s\n", "Out of memory");
        return NULL;
    }

    // Generate random values within the specified range
    for (size_t i = 0; i < size; i++) {
        values[i] = rand() % (max - min + 1) + min;
    }

    // Return the array of random values
    return values;
}

// Function to return a list of employee details
Employee* get_employee_details(size_t size, const char* username, const char* password) {
    // Connect to the database using the provided credentials
    sqlite3* db = db_connect(username, password);
    if (!db) {
        printf("Error: %s\n", "Unable to connect to the database");
        return NULL;
    }

    // Retrieve employee details from the database
    db_retrieve(db);

    // Disconnect from the database
    sqlite3_close(db);

    // Return the list of employee details
    return (Employee*)malloc(size * sizeof(Employee));
}
