#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define item structure
typedef struct {
    float coord;
    int id;
    char label;
} Item;

// Define memory management functions
void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

// Define item initialization function
Item init_item(float coord, int id, char label) {
    Item item = {.coord = coord, .id = id, .label = label};
    return item;
}

// Define item array initialization function
void initialize_items(Item* items, size_t num_items) {
    srand(time(NULL));
    for (size_t i = 0; i < num_items; ++i) {
        Item item = init_item(
            -100.0 + rand() / (RAND_MAX + 1.0), // random coordinate
            rand() % 100,                       // random ID
            'a' + rand() % ('z' - 'a')          // random label
        );
        items[i] = item;
    }
}

// Define item update function
void update_item(Item* item, float coord, int id, char label) {
    item->coord = coord;
    item->id = id;
    item->label = label;
}

// Define item free function
void free_item(Item* item) {
    free_memory(item);
}

// Define memory management functions for arrays
void allocate_items(Item** items, size_t num_items) {
    *items = (Item*)allocate_memory(num_items * sizeof(Item));
}

void initialize_items_array(Item* items, size_t num_items) {
    initialize_items(items, num_items);
}

void free_items(Item** items, size_t num_items) {
    for (size_t i = 0; i < num_items; ++i) {
        free_item(&items[i]);
    }
    free_memory(items);
}

// Define functions to manage the lifecycle of allocated resources
void allocate_and_initialize_items(Item** items, size_t num_items) {
    allocate_items(items, num_items);
    initialize_items_array(*items, num_items);
}

void update_item_fields(Item* item, float coord, int id, char label) {
    update_item(item, coord, id, label);
}

void free_allocated_resources(Item** items, size_t num_items) {
    free_items(items, num_items);
}

// Define functions to handle errors gracefully
void handle_error(const char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}

void check_for_errors() {
    if (errno != 0) {
        handle_error("Error allocating memory");
    }
}
