#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <pthread.h>

#define MAX_SENSORS 1000
#define MIN_READING -100.0
#define MAX_READING 100.0
#define MIN_ID 1
#define MAX_ID 100
#define LABEL_CHARS "abcdefghijklmnopqrstuvwxyz"

typedef struct {
    float temperature;
    float pressure;
    float humidity;
} sensor_data;

// Sensor data structure for each type of sensor
typedef struct {
    int id;
    char label[10];
    sensor_data *sensor_readings;
} sensor_type_a;

typedef struct {
    int id;
    char label[10];
    float pressure;
} sensor_type_b;

// Global variables for storing sensor data and metadata
static sensor_data *sensor_readings[MAX_SENSORS];
static int num_sensors = 0;
static pthread_mutex_t lock;

// Function to initialize the global variables and allocate memory for sensor readings
void init_sensor_data() {
    // Initialize the mutex lock for thread safety
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for the sensor readings array
    sensor_readings = (sensor_data **) malloc(MAX_SENSORS * sizeof(sensor_data *));
    if (!sensor_readings) {
        printf("Error: failed to allocate memory for sensor readings\n");
        exit(1);
    }

    // Initialize the number of sensors and allocate memory for each type of sensor
    num_sensors = 0;
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (sensor_readings[i] == NULL) {
            // Allocate memory for the sensor readings array for each type of sensor
            switch (i % 2) {
                case 0:
                    sensor_readings[i] = (sensor_data *) malloc(sizeof(sensor_type_a));
                    break;
                case 1:
                    sensor_readings[i] = (sensor_data *) malloc(sizeof(sensor_type_b));
                    break;
            }
            if (!sensor_readings[i]) {
                printf("Error: failed to allocate memory for sensor readings\n");
                exit(1);
            }
        }
    }
}

// Function to add a new sensor and initialize its data
void add_sensor(int id, char *label) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Check if there is still space in the array for adding a new sensor
    if (num_sensors >= MAX_SENSORS) {
        printf("Error: maximum number of sensors reached\n");
        exit(1);
    }

    // Allocate memory for the new sensor readings array and initialize its data
    switch (id % 2) {
        case 0:
            sensor_readings[num_sensors] = (sensor_data *) malloc(sizeof(sensor_type_a));
            break;
        case 1:
            sensor_readings[num_sensors] = (sensor_data *) malloc(sizeof(sensor_type_b));
            break;
    }
    if (!sensor_readings[num_sensors]) {
        printf("Error: failed to allocate memory for new sensor readings\n");
        exit(1);
    }
    strcpy(sensor_readings[num_sensors]->label, label);
    sensor_readings[num_sensors]->id = id;
    // Initialize the type-specific attributes based on the sensor type
    switch (id % 2) {
        case 0:
            sensor_readings[num_sensors]->temperature = MIN_READING + (float)rand() / RAND_MAX * (MAX_READING - MIN_READING);
            break;
        case 1:
            sensor_readings[num_sensors]->pressure = MIN_READING + (float)rand() / RAND_MAX * (MAX_READING - MIN_READING);
            break;
    }
    num_sensors++;

    // Release the lock to ensure thread safety
    pthread_mutex_unlock(&lock);
}

// Function to read sensor data from disk
void read_sensor_data(char *filename) {
    // Open the file for reading and check if it exists
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error: failed to open file %s\n", filename);
        exit(1);
    }

    // Read the number of sensors from the file
    int num_sensors;
    if (fread(&num_sensors, sizeof(int), 1, file) != 1) {
        printf("Error: failed to read number of sensors\n");
        exit(1);
    }

    // Allocate memory for the sensor readings array and initialize its data
    for (int i = 0; i < num_sensors; i++) {
        if (!sensor_readings[i]) {
            switch (i % 2) {
                case 0:
                    sensor_readings[i] = (sensor_data *) malloc(sizeof(sensor_type_a));
                    break;
                case 1:
                    sensor_readings[i] = (sensor_data *) malloc(sizeof(sensor_type_b));
                    break;
            }
            if (!sensor_readings[i]) {
                printf("Error: failed to allocate memory for new sensor readings\n");
                exit(1);
            }
        }
        // Read the sensor data from the file and initialize its type-specific attributes
        switch (i % 2) {
            case 0:
                fread(&sensor_readings[i]->temperature, sizeof(float), 1, file);
                break;
            case 1:
                fread(&sensor_readings[i]->pressure, sizeof(float), 1, file);
                break;
        }
    }

    // Close the file
    fclose(file);
}

// Function to write sensor data to disk
void write_sensor_data(char *filename) {
    // Open the file for writing and create it if it does not exist
    FILE *file = fopen(filename, "w");
    if (!file) {
        printf("Error: failed to open file %s\n", filename);
        exit(1);
    }

    // Write the number of sensors to the file
    int num_sensors = 0;
    while (num_sensors < MAX_SENSORS && sensor_readings[num_sensors]) {
        num_sensors++;
    }
    if (fwrite(&num_sensors, sizeof(int), 1, file) != 1) {
        printf("Error: failed to write number of sensors\n");
        exit(1);
    }

    // Write the sensor data to the file
    for (int i = 0; i < num_sensors; i++) {
        // Write the sensor label and ID to the file
        fwrite(&sensor_readings[i]->label, sizeof(char) * 256, 1, file);
        fwrite(&sensor_readings[i]->id, sizeof(int), 1, file);
        // Write the type-specific attributes to the file
        switch (i % 2) {
            case 0:
                fwrite(&sensor_readings[i]->temperature, sizeof(float), 1, file);
                break;
            case 1:
                fwrite(&sensor_readings[i]->pressure, sizeof(float), 1, file);
                break;
        }
    }

    // Close the file
    fclose(file);
}

int main() {
    init();
    add_sensor(0, "Sensor A");
    add_sensor(1, "Sensor B");
    read_sensor_data("sensors.dat");
    write_sensor_data("new_sensors.dat");
    return 0;
}
```

