use std::time::Instant;
use std::env;
use std::process::Command;
use rustc_driver::{
    catch_with_exit_code,
    early_error,
};
use std::lazy::SyncLazy;

const TIMEOUT: u64 = 10; // in seconds
const MAX_MEMORY: usize = 512 * 1024 * 1024; // in bytes
const RESIDENT_SET_SIZE_THRESHOLD: f64 = 1.0;

fn compile(source: &str) -> Result<(), String> {
    let before = get_resident_set_size();

    let start = Instant::now();
    let exit_code = Command::new("rustc")
        .arg("--color=always")
        .arg("-Cdebug-assertions=yes")
        .arg("-Cwarnings=all")
        .arg(source)
        .status()?;

    let duration = start.elapsed();

    if exit_code != 0 {
        early_error(exit_code, "Compilation failed");
    }

    let after = get_resident_set_size();

    if before > MAX_MEMORY || after > (MAX_MEMORY * RESIDENT_SET_SIZE_THRESHOLD) {
        early_error(exit_code, "Memory usage is too high");
    }

    if duration.as_secs() > TIMEOUT {
        early_error(exit_code, "Compilation took too long");
    }

    Ok(())
}
```
