```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/time.h>

// Custom data structure for network connections
typedef struct {
    int id; // Unique identifier for the connection
    char *status; // Status of the connection (open/closed)
    time_t lastUpdateTimestamp; // Timestamp of the last update
    void *buffer; // Buffer for incoming data
} networkConnection_t;

// Array to store all active connections
static networkConnection_t *connections = NULL;

// Mutex lock to ensure thread safety during status updates
static pthread_mutex_t connectionsMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to safely allocate memory for a new connection
void allocNewConnection(networkConnection_t **connection) {
    *connection = malloc(sizeof(networkConnection_t));
    if (*connection == NULL) {
        printf("Error: Failed to allocate memory for new connection.\n");
        return;
    }
}

// Function to initialize a new connection with default values
void initNewConnection(networkConnection_t *connection) {
    connection->id = -1;
    connection->status = "closed";
    connection->lastUpdateTimestamp = 0;
    connection->buffer = NULL;
}

// Function to update the status of a connection
void updateConnectionStatus(networkConnection_t *connection, const char *newStatus) {
    pthread_mutex_lock(&connectionsMutex);
    if (strcmp(connection->status, newStatus) != 0) {
        connection->status = newStatus;
        connection->lastUpdateTimestamp = time(NULL);
    }
    pthread_mutex_unlock(&connectionsMutex);
}

// Function to free the memory associated with a connection
void freeConnection(networkConnection_t *connection) {
    if (connection != NULL) {
        free(connection->buffer);
        free(connection);
    }
}
