// Define the record structure
typedef struct {
    double value;
} record;

// Function to read key-value pairs from a file and initialize an array of records
record* init_records(char* file_path, int* num_records) {
    // Check if the file exists and is readable
    FILE* fp = fopen(file_path, "r");
    if (fp == NULL) {
        printf("Error: unable to read file %s\n", file_path);
        return NULL;
    }

    // Initialize variables for the number of records and the array of records
    *num_records = 0;
    record* records = NULL;

    // Loop through each line in the file and extract the key-value pair
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Parse the key-value pair from the line
        int key = 0;
        double value = 0.0;
        sscanf(line, "%d,%lf", &key, &value);

        // Check if the key is within the expected range and unique
        if (key < 0 || key > 1000 || (records && key_exists(records, *num_records, key))) {
            printf("Error: invalid key %d\n", key);
            continue;
        }

        // Add the key-value pair to the array of records
        if (*num_records == 0) {
            // Allocate memory for the first record
            records = malloc(sizeof(record));
            if (records == NULL) {
                printf("Error: unable to allocate memory for records\n");
                return NULL;
            }
        } else {
            // Reallocate memory for the array of records
            records = realloc(records, (*num_records + 1) * sizeof(record));
            if (records == NULL) {
                printf("Error: unable to reallocate memory for records\n");
                return NULL;
            }
        }

        // Initialize the record with the given value
        records[*num_records].value = value;
        (*num_records)++;
    }

    // Sort the array of records by key in ascending order
    qsort(records, *num_records, sizeof(record), compare_records);

    // Set each record's value to a random value within the given range (1.0 to 100.0)
    for (int i = 0; i < *num_records; i++) {
        records[i].value = ((double)rand() / RAND_MAX) * 98.0 + 1.0;
    }

    // Return the array of records
    return records;
}

// Function to check if a key exists in an array of records
int key_exists(record* records, int num_records, int key) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            return 1;
        }
    }
    return 0;
}

// Function to compare two records by their keys in ascending order
int compare_records(const void* a, const void* b) {
    record* record_a = (record*)a;
    record* record_b = (record*)b;
    return record_a->key - record_b->key;
}
