void safe_write_records_to_file(const char *filename, const struct record *records, size_t num_records) {
    /* Allocate memory for the serialized data */
    void *buffer = malloc(num_records * sizeof(*records));
    if (!buffer) {
        return NULL;
    }

    /* Serialize the records into the buffer */
    size_t written = serialize_records(buffer, num_records, records);
    if (written == 0) {
        free(buffer);
        return NULL;
    }

    /* Write the serialized data to the file */
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        free(buffer);
        return NULL;
    }
    size_t result = fwrite(buffer, 1, written, fp);
    fclose(fp);
    if (result != written) {
        free(buffer);
        return NULL;
    }

    /* Free the memory allocated for the serialized data */
    free(buffer);

    /* Return success */
    return records + num_records;
}
