To ensure thread safety while maintaining high performance, you can use a combination of techniques such as:

* Using atomic operations to update the shared variables that are accessed by multiple threads simultaneously.
* Implementing a lock mechanism to synchronize access to the shared variables between threads.
* Avoiding race conditions by using appropriate data structures and algorithms that can handle concurrency.
* Implementing a memory pool mechanism to reuse memory blocks to minimize memory allocation overhead.
* Using cache-aware algorithms to optimize performance for frequently accessed data.

Here is an example of how you can implement these techniques in your code:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <pthread.h>

// Define a structure to hold the records
typedef struct {
    int key;
    long offset;
} Record;

// Define an array of offsets and keys
static long *offsets = NULL;
static int *keys = NULL;

// Define a lock for synchronizing access to the shared variables
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to safely allocate memory for an array of offsets and keys
void safe_alloc(int size) {
    if (offsets == NULL && keys == NULL) {
        offsets = (long *)malloc(size * sizeof(long));
        keys = (int *)malloc(size * sizeof(int));
        if (offsets == NULL || keys == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    } else {
        offsets = (long *)realloc(offsets, size * sizeof(long));
        keys = (int *)realloc(keys, size * sizeof(int));
        if (offsets == NULL || keys == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
    }
}

// Function to safely initialize an array of records
void safe_init(Record *records, int size) {
    for (int i = 0; i < size; i++) {
        records[i].key = i;
        records[i].offset = 0;
    }
}

// Function to safely update an array of records
void safe_update(Record *records, int size) {
    for (int i = 0; i < size; i++) {
        records[i].offset += 1;
    }
}

// Function to safely free the memory allocated for the arrays of offsets and keys
void safe_free() {
    if (offsets != NULL && keys != NULL) {
        free(offsets);
        free(keys);
        offsets = NULL;
        keys = NULL;
    }
}

// Function to serialize the initialized records into a binary file
void serialize(Record *records, int size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Write the number of records to the file
    fwrite(&size, sizeof(int), 1, fp);

    // Write each record's key and offset to the file
    for (int i = 0; i < size; i++) {
        Record *record = &records[i];
        fwrite(record->key, sizeof(int), 1, fp);
        fwrite(record->offset, sizeof(long), 1, fp);
    }

    // Close the file
    fclose(fp);
}

// Function to deserialize the binary file back into the initialized records
void deserialize(Record *records, int size, const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Read the number of records from the file
    int read_size;
    fread(&read_size, sizeof(int), 1, fp);
    if (read_size != size) {
        fprintf(stderr, "Invalid record count\n");
        return;
    }

    // Read each record's key and offset from the file
    for (int i = 0; i < size; i++) {
        Record *record = &records[i];
        fread(record->key, sizeof(int), 1, fp);
        fread(record->offset, sizeof(long), 1, fp);
    }

    // Close the file
    fclose(fp);
}

// Function to compress and serialize the initialized records into a binary file
void compress_serialize(Record *records, int size, const char *filename) {
    // Compress the data using zlib
    Bytef *compressed = (Bytef *)malloc(size * sizeof(int));
    uLongf compressed_len = size * sizeof(int);
    deflateInit(&c_stream, Z_DEFAULT_COMPRESSION);
    deflateReset(&c_stream);
    deflateSetHeader(&c_stream, Z_DEFLATED, Z_DEFAULT_STRATEGY);
    deflateWrite(&c_stream, records, size * sizeof(int));
    deflateEnd(&c_stream);

    // Write the compressed data to a file
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return;
    }
    fwrite(compressed, 1, compressed_len, fp);
    fclose(fp);

    // Free the memory allocated for the compressed data
    free(compressed);
}

// Function to decompress and deserialize the binary file back into the initialized records
void decompress_deserialize(Record *records, int size, const char *filename) {
    // Allocate memory for the decompressed data
    Bytef *decompressed = (Bytef *)malloc(size * sizeof(int));

    // Read the compressed data from a file
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("fopen");
        return;
    }
    uLongf decompressed_len = size * sizeof(int);
    fread(decompressed, 1, decompressed_len, fp);
    fclose(fp);

    // Decompress the data using zlib
    inflateInit(&d_stream);
    inflateReset(&d_stream);
    inflateSetHeader(&d_stream, Z_DEFLATED, Z_DEFAULT_STRATEGY);
    inflateWrite(&d_stream, decompressed, decompressed_len);
    inflateEnd(&d_stream);

    // Write the decompressed data to a file
    fwrite(decompressed, 1, decompressed_len, fp);
    fclose(fp);

    // Free the memory allocated for the decompressed data
    free(decompressed);
}
```

