#include <stdio.h>
#include <errno.h>
#include <limits.h>
#include <pthread.h>

typedef struct {
    int key;
} record_t;

void *init_records(int num_records, int min_key, int max_key, bool use_random) {
    // Validate input parameters
    if (num_records < 0 || min_key > max_key) {
        errno = EINVAL;
        return NULL;
    }

    // Calculate total memory required for the arrays
    size_t record_size = sizeof(record_t);
    size_t offset_array_size = num_records * sizeof(long);
    size_t key_array_size = num_records * sizeof(int);
    size_t total_memory_required = offset_array_size + key_array_size + num_records * record_size;

    // Check if memory limit is exceeded
    long memory_limit = 1024 * 1024 * 1024; // 1 GB
    if (total_memory_required > memory_limit) {
        errno = ENOMEM;
        return NULL;
    }

    // Allocate memory for the arrays and records
    long *offset_array = malloc(offset_array_size);
    int *key_array = malloc(key_array_size);
    record_t *records = malloc(num_records * record_size);

    // Check if memory allocation failed
    if (offset_array == NULL || key_array == NULL || records == NULL) {
        errno = ENOMEM;
        return NULL;
    }

    // Initialize the arrays and records
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i * sizeof(record_t);
        key_array[i] = use_random ? rand() % max_key : min_key + i;
        records[i].key = key_array[i];
    }

    // Return a pointer to the allocated records array on success
    return records;
}

int main(void) {
    record_t *records = init_records(10, 0, INT_MAX, true);
    if (records == NULL) {
        printf("Error: %s\n", strerror(errno));
        return 1;
    }

    // Use the allocated records array here...

    free(records);
    return 0;
}
```

