    // Initialize the memory pool manager for efficient memory allocation and deallocation
    struct memory_pool *memory_pool = malloc(sizeof(struct memory_pool));
    if (!memory_pool) {
        printf("Error: Failed to allocate memory for memory pool\n");
        free(image_data->images);
        free(image_data);
        exit(1);
    }
    memory_pool->memory = malloc(sizeof(struct image_data) * num_images);
    if (!memory_pool->memory) {
        printf("Error: Failed to allocate memory for memory pool\n");
        free(memory_pool);
        free(image_data->images);
        free(image_data);
        exit(1);
    }
    memory_pool->size = sizeof(struct image_data) * num_images;

    // Return the initialized image data list and memory pool manager
    return image_data;
}

// Free the image data list and memory pool manager
void free_image_data(image_list *image_data, struct memory_pool *memory_pool) {
    // Release the memory for the image data structures
    if (image_data->images) {
        free(image_data->images);
        image_data->images = NULL;
    }

    // Release the memory for the memory pool manager
    if (memory_pool) {
        if (memory_pool->memory) {
            free(memory_pool->memory);
            memory_pool->memory = NULL;
        }
        free(memory_pool);
        memory_pool = NULL;
    }
}

// Safely allocate and initialize memory for the image data structures
void *safe_malloc(size_t size) {
    // Acquire the lock on the mutex to prevent concurrent access to the memory pool manager
    pthread_mutex_lock(&memory_pool_mutex);

    // Allocate memory for the image data structure
    void *image_data = malloc(size);
    if (!image_data) {
        printf("Error: Failed to allocate memory for image data\n");
        pthread_mutex_unlock(&memory_pool_mutex);
        exit(1);
    }

    // Release the lock on the mutex to allow other threads to access the memory pool manager
    pthread_mutex_unlock(&memory_pool_mutex);

    // Return the allocated image data structure
    return image_data;
}

// Safely free the memory for the image data structures
void safe_free(void *ptr) {
    // Acquire the lock on the mutex to prevent concurrent access to the memory pool manager
    pthread_mutex_lock(&memory_pool_mutex);

    // Free the allocated memory for the image data structure
    if (ptr) {
        free(ptr);
        ptr = NULL;
    }

    // Release the lock on the mutex to allow other threads to access the memory pool manager
    pthread_mutex_unlock(&memory_pool_mutex);
}

// Generate random values within specified ranges for coordinates, IDs, and labels
int generate_random_values(float *coordinates, int *ids, char *labels) {
    // Define the ranges for the random values
    float coordinate_range = 200.0;
    int id_range = 100;
    char label_range[26] = "abcdefghijklmnopqrstuvwxyz";

    // Generate random values within the specified ranges
    for (int i = 0; i < 3; i++) {
        coordinates[i] = ((float)rand() / RAND_MAX) * coordinate_range - 100.0;
    }
    for (int i = 0; i < 100; i++) {
        ids[i] = rand() % id_range + 1;
    }
    for (int i = 0; i < 26; i++) {
        labels[i] = label_range[rand() % strlen(label_range)];
    }

    // Return 0 if successful, or -1 if failed
    return 0;
}

// Initialize the image data list and memory pool manager
image_list *initialize_image_data() {
    // Define the number of images to be generated
    int num_images = 100;

    // Allocate memory for the image data list and initialize it
    image_list *image_data = malloc(sizeof(image_list) * num_images);
    if (!image_data) {
        printf("Error: Failed to allocate memory for image data\n");
        exit(1);
    }

    // Initialize the memory pool manager for efficient memory allocation and deallocation
    struct memory_pool *memory_pool = malloc(sizeof(struct memory_pool));
    if (!memory_pool) {
        printf("Error: Failed to allocate memory for memory pool\n");
        free(image_data);
        exit(1);
    }
    memory_pool->memory = malloc(sizeof(struct image_data) * num_images);
    if (!memory_pool->memory) {
        printf("Error: Failed to allocate memory for memory pool\n");
        free(memory_pool);
        free(image_data);
        exit(1);
    }
    memory_pool->size = sizeof(struct image_data) * num_images;

    // Initialize the image data structures and generate random values within specified ranges for coordinates, IDs, and labels
    for (int i = 0; i < num_images; i++) {
        image_data[i].image_data = safe_malloc(sizeof(struct image_data));
        if (!image_data[i].image_data) {
            printf("Error: Failed to allocate memory for image data\n");
            free_image_data(image_data, memory_pool);
            exit(1);
        }
        generate_random_values((float *)&image_data[i].image_data->coordinates, (int *)&image_data[i].image_data->ids, (char *)&image_data[i].image_data->labels);
    }

    // Return the initialized image data list and memory pool manager
    return image_data;
}

// Free the image data list and memory pool manager
void free_image_data(image_list *image_data, struct memory_pool *memory_pool) {
    // Release the memory for the image data structures
    if (image_data) {
        free(image_data);
        image_data = NULL;
    }

    // Release the memory for the memory pool manager
    if (memory_pool) {
        if (memory_pool->memory) {
            free(memory_pool->memory);
            memory_pool->memory = NULL;
        }
        free(memory_pool);
        memory_pool = NULL;
    }
}

// Start the image processing pipeline
void start_image_processing() {
    // Define the number of threads to be used for processing images
    int num_threads = 4;

    // Initialize the image data list and memory pool manager
    image_list *image_data = initialize_image_data();

    // Create a thread pool to process images in parallel
    pthread_t thread_pool[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&thread_pool[i], NULL, image_processing_thread, (void *)image_data);
    }

    // Wait for all threads to finish processing images
    void *status;
    for (int i = 0; i < num_threads; i++) {
        pthread_join(thread_pool[i], &status);
    }

    // Free the image data list and memory pool manager
    free_image_data(image_data, NULL);
}

// Image processing thread function
void *image_processing_thread(void *image_data) {
    // Define the number of images to be processed by this thread
    int num_images = 25;

    // Cast the image data to the appropriate type
    image_list *image_data_ptr = (image_list *)image_data;

    // Process each image in parallel using the image processing algorithm
    for (int i = 0; i < num_images; i++) {
        // Perform image processing operations on the current image
        printf("Processing image %d\n", i);

        // Update the status of the current image
        image_data_ptr[i].status = PROCESSED;
    }

    // Return NULL to indicate that this thread has finished its work
    return NULL;
}

int main() {
    start_image_processing();
    return 0;
}']

