// Function to refresh multiple dialog fields in an AngularJS application using a resource ID and a URL
function refreshDialogFields(resourceId, url) {
    // Get the list of dialog fields to refresh from the resource ID
    let dialogFields = getDialogFieldsFromResourceId(resourceId);

    // Iterate through all dialog fields and refresh them if they match any of the field names to refresh
    for (let i = 0; i < dialogFields.length; i++) {
        let dialogFieldName = dialogFields[i].name;
        if (fieldNamesToRefresh.includes(dialogFieldName)) {
            // Send a message to the parent window with the field name and the URL
            let message = {
                type: 'refreshDialogField',
                data: {
                    fieldName: dialogFieldName,
                    url: url
                }
            };
            parent.postMessage(message);

            // If the result of the message is successful, update the dialog field with the result
            let response = await getResponseFromParentWindow();
            if (response.status === 'success') {
                let value = response.data;
                setDialogFieldValue(dialogFieldName, value);
            }
        }
    }
}
