    if (num_sensors > MAX_NUM_SENSORS) {
        return NULL;
    }
    Sensor* sensors = malloc(sizeof(Sensor) * num_sensors);
    if (!sensors) {
        fprintf(stderr, "Failed to allocate memory for sensors: %s\n", strerror(errno));
        return NULL;
    }
    memset(sensors, 0, sizeof(Sensor) * num_sensors);
    return sensors;
}

// Function to generate random coordinates within the specified range
