    float coordinate = ((float)rand()) / RAND_MAX;
    if (coordinate < MIN_COORDINATE || coordinate > MAX_COORDINATE) {
        return get_random_coordinate();
    }
    return coordinate;
}

// Function to generate random IDs within the specified range
int get_random_id() {
    int id = ((int)rand()) % (MAX_ID - MIN_ID + 1);
    if (id < MIN_ID || id > MAX_ID) {
        return get_random_id();
    }
    return id;
}

// Function to generate random labels within the specified set of characters
char* get_random_label() {
    char label[10];
    for (int i = 0; i < 10; i++) {
        int index = ((int)rand()) % strlen(LABELS);
        label[i] = LABELS[index];
    }
    return strdup(label);
}

// Function to update a sensor's data
void update_sensor(Sensor* sensor, float temperature, float pressure) {
    if (!sensor) {
        return;
    }
    sensor->temperature = temperature;
    sensor->pressure = pressure;
}

// Function to free memory allocated for a sensor array
void free_sensors(Sensor* sensors) {
    if (!sensors) {
        return;
    }
    for (int i = 0; i < MAX_NUM_SENSORS; i++) {
        Sensor* sensor = &sensors[i];
        if (sensor->data.temperature || sensor->data.pressure) {
            free(sensor);
        }
    }
}
