bool serialize_records(const char* filename, const record* records, size_t count) {
    if (filename == NULL || records == NULL || count <= 0) {
        return false;
    }

    // Open the file for writing in binary mode
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return false;
    }

    // Write the array of records to the file
    size_t written = fwrite(records, sizeof(record), count, fp);
    if (written != count) {
        perror("fwrite");
        fclose(fp);
        return false;
    }

    // Close the file
    if (fclose(fp)) {
        perror("fclose");
        return false;
    }

    return true;
}

// Define a function to deserialize an array of records from disk
bool deserialize_records(const char* filename, record** records) {
    if (filename == NULL || records == NULL) {
        return false;
    }

    // Open the file for reading in binary mode
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("fopen");
        return false;
    }

    // Determine the size of the file
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);

    // Allocate memory for the array of records
    *records = malloc(file_size);
    if (*records == NULL) {
        perror("malloc");
        fclose(fp);
        return false;
    }

    // Read the file into the array of records
    size_t read = fread(*records, sizeof(record), file_size / sizeof(record), fp);
    if (read != file_size / sizeof(record)) {
        perror("fread");
        free(*records);
        *records = NULL;
        fclose(fp);
        return false;
    }

    // Close the file
    if (fclose(fp)) {
        perror("fclose");
        free(*records);
        *records = NULL;
        return false;
    }

    return true;
}

