        return NULL;
    }

    // Allocate memory for the resulting array of records
    record* result = malloc(sizeof(record) * key_count);
    if (result == NULL) {
        perror("malloc");
        return NULL;
    }

    // Initialize the resulting array of records to default values
    size_t i = 0;
    for (size_t j = 0; j < key_count; ++j) {
        result[j].key = 0;
        result[j].offset = 0;
    }

    // Iterate through the array of records and find matching keys
    for (i = 0; i < count && i < key_count; ++i) {
        bool found = false;
        for (size_t j = 0; j < key_count; ++j) {
            if (records[i].key == keys[j]) {
                result[j] = records[i];
                found = true;
                break;
            }
        }
        if (!found) {
            i++;
        }
    }

    return result;
}

// Define a function to free the memory allocated by query_records()
void free_query_result(record* result) {
    if (result != NULL) {
        // Free the memory allocated for the array of records
        free(result);
    }
}

