// JavaScript function to copy a specified number of bytes from a list of buffered data chunks and return the copied data in a new buffer
function copyBufferChunks(chunks, chunkSize, numBytesToCopy) {
    const totalLength = chunks.reduce((acc, curr) => acc + curr.length, 0);
    if (totalLength < numBytesToCopy) {
        return null;
    }

    const newBuffer = Buffer.allocUnsafe(numBytesToCopy);
    let copiedBytes = 0;
    while (copiedBytes < numBytesToCopy) {
        const chunk = chunks[0];
        const bytesLeftInChunk = chunk.length - copiedBytes;
        const bytesToCopyFromChunk = Math.min(bytesLeftInChunk, numBytesToCopy - copiedBytes);
        newBuffer.copy(chunk, copiedBytes, 0, bytesToCopyFromChunk);
        copiedBytes += bytesToCopyFromChunk;
    }

    return newBuffer;
}']

