#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>
#include <sqlite3.h>

struct record {
    int id;
};

struct data {
    long *offsets;
    int *keys;
    struct record *records;
    size_t num_records;
};

void init_data(struct data *d) {
    d->num_records = 1000;
    d->offsets = (long *)malloc(sizeof(long) * d->num_records);
    d->keys = (int *)malloc(sizeof(int) * d->num_records);
    d->records = (struct record *)malloc(sizeof(struct record) * d->num_records);
    for (size_t i = 0; i < d->num_records; i++) {
        d->offsets[i] = i;
        d->keys[i] = rand() % 1000;
        d->records[i].id = i;
    }
}

void update_data(struct data *d) {
    for (size_t i = 0; i < d->num_records; i++) {
        d->offsets[i]++;
        d->keys[i]++;
        d->records[i].id++;
    }
}

void free_data(struct data *d) {
    free(d->offsets);
    free(d->keys);
    free(d->records);
}

int main() {
    struct data d;
    init_data(&d);
    update_data(&d);
    while (true) {
        sleep(1);
        update_data(&d);
    }
    return 0;
}

void get_employee_info(struct data *d, int id) {
    sqlite3 *db = NULL;
    sqlite3_stmt *stmt = NULL;
    const char *query = "SELECT name, city, address FROM Employees WHERE supervisor_id=?";
    if (sqlite3_open("employees.db", &db) != SQLITE_OK) {
        fprintf(stderr, "Error: unable to open database\n");
        return;
    }
    sqlite3_prepare_v2(db, query, -1, &stmt, NULL);
    if (sqlite3_bind_int(stmt, 1, id) != SQLITE_OK) {
        fprintf(stderr, "Error: unable to bind parameters\n");
        return;
    }
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        const char *name = (const char *)sqlite3_column_text(stmt, 0);
        const char *city = (const char *)sqlite3_column_text(stmt, 1);
        const char *address = (const char *)sqlite3_column_text(stmt, 2);
        printf("%s: %s, %s\n", name, city, address);
    }
    sqlite3_finalize(stmt);
    sqlite3_close(db);
}

void get_employee_info_threaded(struct data *d, int id) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, (void *)get_employee_info, d) != 0) {
        fprintf(stderr, "Error: unable to create thread\n");
        return;
    }
}

int main() {
    struct data d;
    init_data(&d);
    get_employee_info_threaded(&d, 12345);
    while (true) {
        sleep(1);
        update_data(&d);
    }
    return 0;
}']

