                         '0' + rand() % 10, 'A' + rand() % 26);
            free(records[i].entries[j]->string);
            records[i].entries[j]->string = new_string;
        }
    }
}

// function to safely free an array of keys
void free_keys(char **keys, size_t num_keys) {
    if (num_keys > MAX_KEYS) {
        printf("Error: too many keys provided\n");
        return;
    }

    for (size_t i = 0; i < num_keys; i++) {
        free(keys[i]);
    }
}

// function to safely free an array of records
