#include <stdio.h>
#include <pthread.h>

// Define the record structure with 3 fields: offset, key, and value
typedef struct {
    long offset;
    int key;
    double value;
} record;

// Define the maximum size of the array as a configurable parameter
#define MAX_SIZE 1000

// Define the minimum size of each allocation block as a configurable parameter
#define MIN_BLOCK_SIZE 1024

// Define the maximum size of each allocation block as a configurable parameter
#define MAX_BLOCK_SIZE 65536

// Define the range of random values for offset, key, and value
#define OFFSET_RANGE -1000000, 1000000
#define KEY_RANGE 1, 100
#define VALUE_RANGE -1.0e6, 1.0e6

// Define the array of records to be managed by the function
static record* records = NULL;

// Define the number of records currently allocated
static size_t num_records = 0;

// Define the lock for thread-safe operations on the array of records
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for an array of records
void* allocate_records(size_t num_records) {
    // Lock the mutex to prevent concurrent access to the array of records
    pthread_mutex_lock(&lock);

    // If the number of records is greater than the current allocation size, double the allocation size
    if (num_records > MAX_SIZE) {
        num_records = MAX_SIZE;
    }

    // Allocate memory for the array of records
    record* new_records = (record*)malloc(sizeof(record) * num_records);
    if (!new_records) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // If there is already an array of records allocated, copy the existing records to the new allocation
    if (records) {
        memcpy(new_records, records, sizeof(record) * num_records);
    }

    // Update the number of records and the pointer to the array of records
    num_records = num_records;
    records = new_records;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    return records;
}

// Function to initialize an array of records with random values
void* initialize_records(size_t num_records) {
    // Lock the mutex to prevent concurrent access to the array of records
    pthread_mutex_lock(&lock);

    // If there is no array of records allocated, allocate memory for it
    if (!records) {
        allocate_records(num_records);
    }

    // Initialize each record with a random offset, key, and value within the specified range
    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = rand() % OFFSET_RANGE + 1;
        records[i].key = rand() % KEY_RANGE + 1;
        records[i].value = (double)rand() / RAND_MAX * VALUE_RANGE;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to update an existing record in the array with a new offset, key, and value
void* update_record(size_t index, long offset, int key, double value) {
    // Lock the mutex to prevent concurrent access to the array of records
    pthread_mutex_lock(&lock);

    // If there is no array of records allocated, allocate memory for it
    if (!records) {
        allocate_records(1);
    }

    // Update the record at the specified index with the new offset, key, and value
    records[index].offset = offset;
    records[index].key = key;
    records[index].value = value;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to free the memory allocated for an array of records
void* free_records() {
    // Lock the mutex to prevent concurrent access to the array of records
    pthread_mutex_lock(&lock);

    // If there is an array of records allocated, free its memory
    if (records) {
        free(records);
        records = NULL;
    }

    // Reset the number of records to 0
    num_records = 0;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}
```
This implementation defines a `record` structure with 3 fields: `offset`, `key`, and `value`. It also defines a maximum size for the array of records as a configurable parameter, and a minimum and maximum size for each allocation block. The function `allocate_records()` allocates memory for an array of records using `malloc()`, and initializes the number of records to 0. The function `initialize_records()` initializes each record in the array with a random offset, key, and value within the specified range. The function `update_record()` updates an existing record in the array with a new offset, key, and value. Finally, the function `free_records()` frees the memory allocated for an array of records using `free()`.

