        node *node1 = malloc(sizeof(node));
        node1->value = floats[i];
        node1->next = NULL;
        nodes[i] = node1;

        for (int j = i + 1; j < num_elements; j++) {
            if (nodes[j]->value == nodes[i]->value) {
                continue;
            }

            node *node2 = malloc(sizeof(node));
            node2->value = chars[j];
            node2->next = NULL;
            nodes[j] = node2;
        }
    }

    // Link nodes together based on their integer values in ascending order
    for (int i = 0; i < num_elements - 1; i++) {
