// Define structure for data record
typedef struct {
    int key;
    float temperature;
    long offset;
} data_record;

// Define function to read initial offset values from external configuration file
int read_offset_values(char *filename, long **offsets) {
    // Open file and check for errors
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    // Read number of offset values from first line of file
    int num_offsets;
    char line[1024];
    fgets(line, 1024, file);
    sscanf(line, "%d", &num_offsets);

    // Allocate memory for offset values and initialize to zero
    *offsets = (long *)calloc(num_offsets, sizeof(long));
    if (*offsets == NULL) {
        perror("Error allocating memory for offsets");
        return 1;
    }

    // Read offset values from file and store in array
    int i = 0;
    while (fgets(line, 1024, file)) {
        sscanf(line, "%ld", &(*offsets)[i]);
        i++;
    }

    // Close file and return success
    fclose(file);
    return 0;
}

// Define function to generate random values within specified ranges
int generate_random_values(long *offsets, int num_offsets, int *keys, float *temperatures) {
    // Initialize seed for random number generator
    srand(time(NULL));

    // Loop through each offset value and generate corresponding key and temperature values
    for (int i = 0; i < num_offsets; i++) {
        keys[i] = rand() % 100 + offsets[i];
        temperatures[i] = rand() % 100 / 10.0 + offsets[i];
    }

    // Return success
    return 0;
}

// Define function to allocate memory for and initialize data arrays
int allocate_data(long **offsets, int *keys, float **temperatures) {
    // Allocate memory for offset values array
    *offsets = (long *)calloc(num_offsets, sizeof(long));
    if (*offsets == NULL) {
        perror("Error allocating memory for offsets");
        return 1;
    }

    // Allocate memory for key values array
    *keys = (int *)calloc(num_offsets, sizeof(int));
    if (*keys == NULL) {
        perror("Error allocating memory for keys");
        return 1;
    }

    // Allocate memory for temperature values array
    *temperatures = (float *)calloc(num_offsets, sizeof(float));
    if (*temperatures == NULL) {
        perror("Error allocating memory for temperatures");
        return 1;
    }

    // Initialize data arrays with random values
    generate_random_values(*offsets, num_offsets, *keys, *temperatures);

    // Return success
    return 0;
}

// Define function to validate generated data records
int validate_data(data_record *records, int num_records) {
    // Loop through each record and check that key is within range and temperature is within range
    for (int i = 0; i < num_records; i++) {
        if (records[i].key < 0 || records[i].key > 100) {
            fprintf(stderr, "Error: Key %d out of range\n", records[i].key);
            return 1;
        }
        if (records[i].temperature < 0.0 || records[i].temperature > 100.0) {
            fprintf(stderr, "Error: Temperature %f out of range\n", records[i].temperature);
            return 1;
        }
    }

    // Return success
    return 0;
}

// Define function to update sensor reading using HTTP PUT method
int update_sensor_reading(char *id, data_record *records, int num_records) {
    // Open connection to server and check for errors
    curl_global_init();
    CURL *curl = curl_easy_init();
    if (curl == NULL) {
        perror("Error initializing cURL");
        return 1;
    }

    // Set URL for PUT request
    char url[1024];
    sprintf(url, "http://example.com/api/sensor/%s", id);

    // Set headers and data for PUT request
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    char *data = json_encode(records, num_records);

    // Perform PUT request and check for errors
    CURLcode res = curl_easy_setopt(curl, CURLOPT_URL, url);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: cURL failed with code %d\n", res);
        return 1;
    }
    res = curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: cURL failed with code %d\n", res);
        return 1;
    }
    res = curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: cURL failed with code %d\n", res);
        return 1;
    }

    // Perform PUT request and check for errors
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: cURL failed with code %d\n", res);
        return 1;
    }

    // Close connection to server
    curl_easy_cleanup(curl);

    // Return success
    return 0;
}

// Define function to encode data records as JSON
char *json_encode(data_record *records, int num_records) {
    // Initialize JSON object
    json_t *root = json_object();

    // Add key and temperature values to JSON object
    json_object_set_new(root, "key", json_integer(records[0].key));
    json_object_set_new(root, "temperature", json_real(records[0].temperature));

    // Return JSON string
    return json_dumps(root, 0);
}
