    char** strings = malloc(num_strings * sizeof(char*));
    if (!strings) {
        fprintf(stderr, "Failed to allocate memory for strings\n");
        exit(1);
    }
    memset(strings, 0, num_strings * sizeof(char*));
    return strings;
}

// Allocate memory for an array of data structures and initialize them with default values
data_t* allocate_data(int num_records) {
    data_t* records = malloc(num_records * sizeof(data_t));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }
    memset(records, 0, num_records * sizeof(data_t));
    return records;
}

// Initialize an array of records with default values
