    record_t* records = allocate_data(num_records);
    for (int i = 0; i < num_records; i++) {
        records[i].value = 0;
        records[i].str = NULL;
    }
    return records;
}

// Update a record in the array with new values
void update_record(record_t* records, int index, int value, char* str) {
    assert(index >= 0 && index < num_records);
    records[index].value = value;
    records[index].str = str;
}

// Free the memory allocated for an array of doubles
void free_doubles(double* doubles, int num_doubles) {
    free(doubles);
}

// Free the memory allocated for an array of strings
void free_strings(char** strings, int num_strings) {
    free(strings);
}

// Free the memory allocated for an array of data structures
void free_data(data_t* records, int num_records) {
    free(records);
}
