const { Buffer } = require('buffer');

/**
 * Copies a specified number of bytes from a list of buffered data chunks and returns the copied data in a new buffer.
 * @param {Buffer[]} buffers A list of buffered data chunks.
 * @param {Number} numBytes The number of bytes to copy.
 * @returns {Buffer} A new buffer containing the copied data.
 */
function copyData(buffers, numBytes) {
    // Create a new buffer to store the copied data
    const newBuff = Buffer.allocUnsafe(numBytes);

    // Copy data from each chunk into the new buffer
    let copiedBytes = 0;
    for (let i = 0; i < buffers.length && copiedBytes < numBytes; i++) {
        const chunk = buffers[i];
        const copySize = Math.min(chunk.length, numBytes - copiedBytes);
        newBuff.copy(chunk, copiedBytes, 0, copySize);
        copiedBytes += copySize;
    }

    return newBuff;
}
