// Function to initialize a new item with values from an external data storage system
Item* init_item(long offset, float weight) {
    Item *new_item = malloc(sizeof(Item));
    if (!new_item) {
        perror("Failed to allocate memory for item");
        return NULL;
    }
    new_item->offset = offset;
    new_item->weight = weight;
    memset(&new_item->buffer, 0, sizeof(char[1024]));
    return new_item;
}

// Function to initialize a new collection with default capacity
Collection* init_collection() {
    Collection *new_collection = malloc(sizeof(Collection));
    if (!new_collection) {
        perror("Failed to allocate memory for collection");
        return NULL;
    }
    new_collection->items = malloc(sizeof(Item) * DEFAULT_CAPACITY);
    if (!new_collection->items) {
        perror("Failed to allocate memory for item array");
        free(new_collection);
        return NULL;
    }
    new_collection->num_items = 0;
    new_collection->capacity = DEFAULT_CAPACITY;
    pthread_mutex_init(&new_collection->mutex, NULL);
    return new_collection;
}

// Function to add a new item to the collection
void add_item(Collection *collection, long offset, float weight, char buffer[]) {
    // Check if the collection is full and needs to be resized
    if (collection->num_items == collection->capacity) {
        resize_collection(collection);
    }
    // Initialize a new item with values from external data storage system
    Item *new_item = init_item(offset, weight);
    if (!new_item) {
        perror("Failed to initialize item");
        return;
    }
    strncpy(new_item->buffer, buffer, 1024); // maximum buffer size is 1024 bytes
    pthread_mutex_lock(&collection->mutex);
    collection->items[collection->num_items++] = *new_item;
    pthread_mutex_unlock(&collection->mutex);
}

// Function to resize the collection when it reaches its capacity
void resize_collection(Collection *collection) {
    int new_capacity = collection->capacity * 2;
    Item *new_items = realloc(collection->items, sizeof(Item) * new_capacity);
    if (!new_items) {
        perror("Failed to resize item array");
        return;
    }
    collection->items = new_items;
    collection->capacity = new_capacity;
}

// Function to check if an offset and weight are within the specified ranges
