['Here is a suggested implementation of the C function that dynamically manages memory for an array of `record` structures, with thread safety and efficient memory management:
```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Logging library for debug information (optional)
#include "logging.h"

struct record {
    int value;
};

struct record_array {
    struct record *records;
    size_t capacity; // Current number of records in the array
    size_t size; // Number of records currently in use
    pthread_mutex_t lock; // Lock for thread safety
};

void init_record_array(struct record_array *ra, int max_records) {
    ra->records = malloc(max_records * sizeof(struct record));
    if (!ra->records) {
        // Handle error
    }
    ra->capacity = max_records;
    ra->size = 0;

    // Initialize the lock for thread safety
    pthread_mutex_init(&ra->lock, NULL);
}

void add_record(struct record_array *ra, int value) {
    pthread_mutex_lock(&ra->lock);
    if (ra->size >= ra->capacity) {
        // Resize the array to double its current size
        struct record *new_records = realloc(ra->records, 2 * ra->capacity * sizeof(struct record));
        if (!new_records) {
            pthread_mutex_unlock(&ra->lock);
            // Handle error
        }
        ra->records = new_records;
        ra->capacity *= 2;
    }
    ra->records[ra->size].value = value;
    ra->size++;
    pthread_mutex_unlock(&ra->lock);
}

void get_record(struct record_array *ra, int index) {
    pthread_mutex_lock(&ra->lock);
    if (index >= ra->size || index < 0) {
        // Handle out-of-range index error
    }
    int value = ra->records[index].value;
    pthread_mutex_unlock(&ra->lock);
    return value;
}

void free_record_array(struct record_array *ra) {
    if (ra->records != NULL) {
        free(ra->records);
    }
    // Clean up the lock for thread safety
    pthread_mutex_destroy(&ra->lock);
}
```
In this implementation, we define a `struct record` to represent each record in the array, and a `struct record_array` to hold an array of records. The `init_record_array()` function initializes the record array with a specified maximum number of records, and the `add_record()` function adds a new record to the end of the array if there is space. The `get_record()` function returns the value of a record at a specified index in the array, and the `free_record_array()` function frees the memory allocated for the record array.

