#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Struct to represent a coordinate with x and y values
typedef struct coordinate {
    int x;
    int y;
} coordinate_t;

// Struct to represent a location with a single coordinate pair
typedef struct location {
    coordinate_t coord;
} location_t;

// Function to dynamically allocate memory for and initialize an array of 'double' precision floating-point numbers
double* allocate_double_array(size_t size) {
    double* arr = (double*)malloc(sizeof(double) * size);
    if (!arr) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        arr[i] = 0.0;
    }

    return arr;
}

// Function to dynamically allocate memory for and initialize an array of 'struct coordinate' pairs
coordinate_t* allocate_coordinate_array(size_t size) {
    coordinate_t* arr = (coordinate_t*)malloc(sizeof(coordinate_t) * size);
    if (!arr) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        arr[i].x = 0;
        arr[i].y = 0;
    }

    return arr;
}

// Function to dynamically allocate memory for and initialize an array of 'location' structures
location_t* allocate_location_array(size_t size) {
    location_t* arr = (location_t*)malloc(sizeof(location_t) * size);
    if (!arr) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        arr[i].coord.x = 0;
        arr[i].coord.y = 0;
    }

    return arr;
}

// Function to safely allocate, initialize, update, and free memory for the allocated arrays
void manage_allocated_memory(double** double_arr, size_t double_size, coordinate_t** coord_arr, size_t coord_size, location_t** loc_arr, size_t loc_size) {
    // Allocate and initialize memory for the 'double' precision floating-point numbers array
    *double_arr = allocate_double_array(double_size);
    if (!*double_arr) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Allocate and initialize memory for the 'struct coordinate' pairs array
    *coord_arr = allocate_coordinate_array(coord_size);
    if (!*coord_arr) {
        printf("Error: Memory allocation failed\n");
        free(*double_arr);
        return;
    }

    // Allocate and initialize memory for the 'location' structures array
    *loc_arr = allocate_location_array(loc_size);
    if (!*loc_arr) {
        printf("Error: Memory allocation failed\n");
        free(*double_arr);
        free(*coord_arr);
        return;
    }

    // Set the value of each location's coordinate's x and y fields to random values within given ranges
    srand(time(NULL));
    for (int i = 0; i < loc_size; i++) {
        (*loc_arr)[i].coord.x = rand() % 10 + 1;
        (*loc_arr)[i].coord.y = rand() % 10 + 1;
    }
}

// Function to safely free the allocated memory for the arrays
void manage_freed_memory(double* double_arr, coordinate_t* coord_arr, location_t* loc_arr) {
    // Free the memory for the 'location' structures array
    if (loc_arr) {
        free(loc_arr);
    }

    // Free the memory for the 'struct coordinate' pairs array
    if (coord_arr) {
        free(coord_arr);
    }

    // Free the memory for the 'double' precision floating-point numbers array
    if (double_arr) {
        free(double_arr);
    }
}
```

