// Function to dynamically allocate and initialize memory for an array of locations
location_t* alloc_locations(size_t num_locations) {
    // Check if the number of locations is valid
    if (num_locations == 0) {
        return NULL;
    }

    // Allocate memory for the array of locations
    location_t* locations = malloc(sizeof(location_t) * num_locations);
    if (locations == NULL) {
        perror("Failed to allocate memory for locations");
        return NULL;
    }

    // Initialize each location in the array with random coordinates within specified bounding boxes
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_locations; ++i) {
        coordinate_t* coord = malloc(sizeof(coordinate_t));
        if (coord == NULL) {
            perror("Failed to allocate memory for coordinates");
            free(locations);
            return NULL;
        }

        coord->x = rand() % 2000 - 1000;
        coord->y = rand() % 2000 - 1000;

        locations[i].coords = coord;
        locations[i].length = 1;
    }

    return locations;
}

// Function to free the memory allocated for an array of locations
void free_locations(location_t* locations) {
    // Check if the input is valid
    if (locations == NULL) {
        return;
    }

    // Free each location in the array and its associated coordinate pair
    for (size_t i = 0; i < locations->length; ++i) {
        free(locations[i].coords);
    }

    // Free the memory allocated for the array of locations
    free(locations);
}

// Function to update a location in an array of locations
void update_location(location_t* locations, size_t index) {
    // Check if the input is valid
    if (locations == NULL || index >= locations->length) {
        return;
    }

    // Update the coordinate pair for the specified location in the array
    coordinate_t* coord = malloc(sizeof(coordinate_t));
    if (coord == NULL) {
        perror("Failed to allocate memory for coordinates");
        return;
    }

    coord->x = rand() % 2000 - 1000;
    coord->y = rand() % 2000 - 1000;

    locations[index].coords = coord;
}

// Function to restrict the coordinates of a location in an array of locations to predefined bounding boxes
void restrict_location(location_t* locations, size_t index) {
    // Check if the input is valid
    if (locations == NULL || index >= locations->length) {
        return;
    }

    coordinate_t* coord = locations[index].coords;

    // Restrict the x and y values of the coordinate pair to within the specified bounding boxes
    coord->x = restrict_value(coord->x, -1000, 1000);
    coord->y = restrict_value(coord->y, -1000, 1000);
}

// Function to free the memory allocated for an array of locations and clear its contents
void clear_locations(location_t* locations) {
    // Check if the input is valid
    if (locations == NULL) {
        return;
    }

    // Free each location in the array and its associated coordinate pair
    for (size_t i = 0; i < locations->length; ++i) {
        free(locations[i].coords);
    }

    // Clear the length of the array of locations
    locations->length = 0;
}

// Function to restrict a value to within a specified range
int restrict_value(int value, int lower_bound, int upper_bound) {
    // Check if the input is valid
    if (lower_bound > upper_bound) {
        return -1;
    }

    // Return the restricted value
    return (value < lower_bound) ? lower_bound : ((value > upper_bound) ? upper_bound : value);
}
