```c
// Source file: record_manager.c
#include "record_manager.h"

// Define the record pool
static struct Record records[MAX_RECORDS];

// Define a flag to indicate whether the record pool is initialized
static bool initialized = false;

// Define a mutex to ensure thread safety when modifying the record pool
#define MUTEX_INIT_VAL 1
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

bool record_manager_init(void) {
    // Check if the record pool is already initialized
    if (initialized) {
        return false;
    }

    // Initialize the record pool
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].offset = -1;
        records[i].key = -1;
        records[i].value = NAN;
        records[i].str_value = NULL;
    }

    // Set the initialized flag to true
    initialized = true;

    return true;
}

struct Record* record_manager_alloc(long offset, int key, double value, const char *str_value) {
    // Check if the record pool is initialized
    if (!initialized) {
        return NULL;
    }

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find a free record in the pool
    int i = 0;
    while (i < MAX_RECORDS && records[i].offset != -1) {
        i++;
    }

    // If no free record is found, return NULL
    if (i == MAX_RECORDS) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Allocate memory for the string value
    char *str_alloc = malloc(strlen(str_value) + 1);
    if (!str_alloc) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Copy the string value to the allocated memory
    strcpy(str_alloc, str_value);

    // Initialize the record
    records[i].offset = offset;
    records[i].key = key;
    records[i].value = value;
    records[i].str_value = str_alloc;

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    return &records[i];
}

bool record_manager_free(struct Record *record) {
    // Check if the record pool is initialized
    if (!initialized) {
        return false;
    }

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the record in the pool
    int i = 0;
    while (i < MAX_RECORDS && records[i].offset != -1) {
        if (records[i].offset == record->offset && records[i].key == record->key &&
                records[i].value == record->value && strcmp(records[i].str_value, record->str_value) == 0) {
            break;
        }
        i++;
    }

    // If the record is not found, return false
    if (i == MAX_RECORDS || records[i].offset == -1) {
        pthread_mutex_unlock(&mutex);
        return false;
    }

    // Free the string value
    free(record->str_value);

    // Set the record to a free state
    record->offset = -1;
    record->key = -1;
    record->value = NAN;
    record->str_value = NULL;

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    return true;
}

bool record_manager_update(struct Record *record, long new_offset, int new_key, double new_value, const char *new_str_value) {
    // Check if the record pool is initialized
    if (!initialized) {
        return false;
    }

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the record in the pool
    int i = 0;
    while (i < MAX_RECORDS && records[i].offset != -1) {
        if (records[i].offset == record->offset && records[i].key == record->key &&
                records[i].value == record->value && strcmp(records[i].str_value, record->str_value) == 0) {
            break;
        }
        i++;
    }

    // If the record is not found, return false
    if (i == MAX_RECORDS || records[i].offset == -1) {
        pthread_mutex_unlock(&mutex);
        return false;
    }

    // Free the old string value
    free(record->str_value);

    // Allocate memory for the new string value
    char *str_alloc = malloc(strlen(new_str_value) + 1);
    if (!str_alloc) {
        pthread_mutex_unlock(&mutex);
        return false;
    }

    // Copy the new string value to the allocated memory
    strcpy(str_alloc, new_str_value);

    // Update the record
    records[i].offset = new_offset;
    records[i].key = new_key;
    records[i].value = new_value;
    records[i].str_value = str_alloc;

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    return true;
}

void record_manager_destroy(struct RecordManager *record_manager) {
    // Check if the record pool is initialized
    if (!initialized) {
        return;
    }

    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Free all records in the pool
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].offset != -1) {
            free(records[i].str_value);
            records[i].offset = -1;
            records[i].key = -1;
            records[i].value = NAN;
            records[i].str_value = NULL;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}
