// Function to resize the hash table when it reaches a predefined load factor
void resize_hash_table(HashTable *ht, int new_num_buckets) {
  // Allocate memory for the new array of 'HashTableNode' structures
  HashTableNode *new_nodes = (HashTableNode*) malloc(new_num_buckets * sizeof(HashTableNode));
