  // Check if there is an existing record with the same key in the hash table
  HashTableNode *node = &ht->nodes[index];
  while (node && node->record) {
    if (node->record->key == key) {
      return;
    }
    node = node->next;
  }

  // If there is no existing record with the same key, allocate memory for a new 'Record' structure and insert it into the hash table
  Record *record = (Record*) malloc(sizeof(Record));
  if (!record) {
    return;
  }
  record->key = key;
  record->offset = offset;

  // Check if there is a collision in the same bucket
  if (node && node->next) {
    // If there is a collision, insert the new record after the existing one
    HashTableNode *prev = node;
    while (prev->next && prev->next->record) {
      prev = prev->next;
    }
    prev->next = (HashTableNode*) malloc(sizeof(HashTableNode));
    if (!prev->next) {
      free(record);
      return;
    }
    prev->next->record = record;
    prev->next->next = NULL;
  } else {
    // If there is no collision, insert the new record at the head of the bucket
    node->record = record;
    node->next = NULL;
  }

  // Update the load factor and resize the hash table if necessary
  ht->load_factor++;
  if (ht->load_factor > MAX_LOAD_FACTOR) {
    int new_num_buckets = ht->num_buckets * RESIZE_MULTIPLIER;
    resize_hash_table(ht, new_num_buckets);
  }
}

// Function to retrieve a record from the hash table using open addressing with linear probing to handle collisions
Record* get_record(HashTable *ht, int key) {
  // Compute the hash value for the key
