  // Check if there is an existing record with the same key in the hash table
  HashTableNode *node = &ht->nodes[index];
  while (node && node->record) {
    if (node->record->key == key) {
      return node->record;
    }
    node = node->next;
  }

  // If there is no existing record with the same key, return null
  return NULL;
}

// Function to delete a record from the hash table using open addressing with linear probing to handle collisions
void delete_record(HashTable *ht, int key) {
  // Compute the hash value for the key
  int index = key % ht->num_buckets;

  // Check if there is an existing record with the same key in the hash table
  HashTableNode *node = &ht->nodes[index];
