['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int id;
} record;

void initialize_records(record **records, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid size\n");
        exit(EXIT_FAILURE);
    }
    *records = malloc(size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        (*records)[i].value = rand() % 100; // Random value between 0 and 99
        (*records)[i].id = i + 1;
    }
}

void sort_records(record **records, int size) {
    quicksort(*records, 0, size - 1);
}

void quicksort(record *arr, int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quicksort(arr, low, pi - 1);
        quicksort(arr, pi + 1, high);
    }
}

int partition(record *arr, int low, int high) {
    record pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j].value <= pivot.value) {
            i++;
            record temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
    i++;
    record temp = arr[i];
    arr[i] = arr[high];
    arr[high] = temp;
    return i;
}

void binary_search(record *records, int size, int target) {
    int low = 0;
    int high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (records[mid].value < target) {
            low = mid + 1;
        } else if (records[mid].value > target) {
            high = mid - 1;
        } else {
            printf("Found the target at index %d\n", mid);
            return;
        }
    }
    printf("Target not found in the database\n");
}

int main() {
    int size;
    scanf("%d", &size);
    record *records = NULL;
    initialize_records(&records, size);
    sort_records(&records, size);
    binary_search(records, size, 30); // Search for a value of 30 in the database
    return 0;
}
```
