// Define the maximum number of records
#define MAX_RECORDS 1000

// Define the data structure to store records
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define the buffer size for each record
#define RECORD_SIZE sizeof(Record)

// Define the buffer size for the entire collection of records
#define COLLECTION_SIZE MAX_RECORDS * RECORD_SIZE

// Define the lock used to protect the collection of records
pthread_mutex_t record_lock;

// Define the function to allocate memory for a new record
Record* alloc_record() {
    Record* record = malloc(RECORD_SIZE);
    assert(record != NULL);
    return record;
}

// Define the function to initialize a new record with default values
void init_record(Record* record) {
    record->offset = 0;
    record->key = 0;
    record->value = 0.0;
}

// Define the function to update an existing record
void update_record(Record* record, long offset, int key, double value) {
    record->offset = offset;
    record->key = key;
    record->value = value;
}

// Define the function to free the memory for a record
void free_record(Record* record) {
    free(record);
}

// Define the function to allocate and initialize a new collection of records
Record** alloc_collection() {
    Record** collection = malloc(COLLECTION_SIZE);
    assert(collection != NULL);
    for (int i = 0; i < MAX_RECORDS; i++) {
        init_record(collection[i]);
    }
    return collection;
}

// Define the function to free the memory for a collection of records
void free_collection(Record** collection) {
    free(collection);
}

// Define the function to lock the record collection for reading or writing
void lock_record_collection() {
    pthread_mutex_lock(&record_lock);
}

// Define the function to unlock the record collection for reading or writing
void unlock_record_collection() {
    pthread_mutex_unlock(&record_lock);
}

// Define the function to add a new record to the collection
int add_record(Record** collection, long offset, int key, double value) {
    // Lock the record collection for writing
    lock_record_collection();

    // Find an empty slot in the collection
    int i = 0;
    while (i < MAX_RECORDS && collection[i] != NULL) {
        i++;
    }

    // Return error if no empty slots found
    if (i == MAX_RECORDS) {
        unlock_record_collection();
        return -1;
    }

    // Allocate memory for the new record and initialize it with default values
    Record* new_record = alloc_record();
    init_record(new_record);

    // Update the new record with the given offset, key, and value
    update_record(new_record, offset, key, value);

    // Add the new record to the collection
    collection[i] = new_record;

    // Unlock the record collection for writing
    unlock_record_collection();

    return i;
}

// Define the function to update an existing record in the collection
int update_record(Record** collection, long offset, int key, double value) {
    // Lock the record collection for reading or writing
    lock_record_collection();

    // Find the record with the given offset and key
    int i = 0;
    while (i < MAX_RECORDS && collection[i] != NULL && (collection[i]->offset != offset || collection[i]->key != key)) {
        i++;
    }

    // Return error if the record is not found
    if (i == MAX_RECORDS || collection[i] == NULL) {
        unlock_record_collection();
        return -1;
    }

    // Update the existing record with the given offset, key, and value
    update_record(collection[i], offset, key, value);

    // Unlock the record collection for reading or writing
    unlock_record_collection();

    return i;
}

// Define the function to remove an existing record from the collection
int remove_record(Record** collection, long offset, int key) {
    // Lock the record collection for writing
    lock_record_collection();

    // Find the record with the given offset and key
    int i = 0;
    while (i < MAX_RECORDS && collection[i] != NULL && (collection[i]->offset != offset || collection[i]->key != key)) {
        i++;
    }

    // Return error if the record is not found
    if (i == MAX_RECORDS || collection[i] == NULL) {
        unlock_record_collection();
        return -1;
    }

    // Free the memory for the existing record
    free_record(collection[i]);

    // Shift all records after the found record by one position to fill the gap
    for (int j = i + 1; j < MAX_RECORDS; j++) {
        if (collection[j] != NULL) {
            collection[j - 1] = collection[j];
            collection[j] = NULL;
        }
    }

    // Unlock the record collection for writing
    unlock_record_collection();

    return i;
}

// Define the function to query an existing record from the collection
int query_record(Record** collection, long offset, int key) {
    // Lock the record collection for reading or writing
    lock_record_collection();

    // Find the record with the given offset and key
    int i = 0;
    while (i < MAX_RECORDS && collection[i] != NULL && (collection[i]->offset != offset || collection[i]->key != key)) {
        i++;
    }

    // Return error if the record is not found
    if (i == MAX_RECORDS || collection[i] == NULL) {
        unlock_record_collection();
        return -1;
    }

    // Unlock the record collection for reading or writing
    unlock_record_collection();

    return i;
}

// Define the function to print a record from the collection
void print_record(Record** collection, int index) {
    // Lock the record collection for reading
    lock_record_collection();

    // Check if the record is found in the collection
    if (index >= 0 && index < MAX_RECORDS && collection[index] != NULL) {
        printf("Record %d: Offset = %ld, Key = %d, Value = %.2f\n", index, collection[index]->offset, collection[index]->key, collection[index]->value);
    } else {
        printf("Record not found in the collection\n");
    }

    // Unlock the record collection for reading
    unlock_record_collection();
}
