void aes_encrypt(const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    // Generate a random IV for encryption and create the key schedule
    unsigned char iv[AES_BLOCK_SIZE];
    rand_bytes(iv, AES_BLOCK_SIZE);
    AES_KEY_SCHEDULE ks;
    AES_set_encrypt_key(plaintext, AES_256, &ks);

    // Initialize the encryption process with the IV and key schedule
    unsigned char temp[AES_BLOCK_SIZE];
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        temp[i] = iv[i];
    }
    AES_encrypt(temp, ciphertext, &ks);

    // Encrypt the plaintext message using CBC mode with PKCS#7 padding
    for (int i = 0; i < plaintext_len; i++) {
        plaintext[i] ^= temp[i % AES_BLOCK_SIZE];
        ciphertext[i] = plaintext[i];
    }
}

