    unsigned char temp[AES_BLOCK_SIZE];
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        plaintext[i] ^= iv[i];
    }
    AES_decrypt(plaintext, temp, &ks);
    for (int i = 0; i < ciphertext_len; i++) {
