    record->offset = (float)(rand() % 1000000000LL - 500000000LL); // Random offset between -5 and +5 billion
    record->key = (char)(rand() % 256 + 1); // Random key between 1 and 256
    record->value = (long long)(rand() % 1500000000LL - 750000000LL); // Random value between -7.5 billion and +7.5 billion
}

// Function to update a record with new values
void update_record(Record* record, float offset, char key, long long value) {
    record->offset = offset;
    record->key = key;
    record->value = value;
}

