bool add_record(RecordList *list, Record *record) {
    if (list->count == 1000) { // Maximum number of records reached
        return false;
    }
    list->records[list->count] = *record;
    list->count++;
    return true;
}

// Function to remove a record from the list
bool remove_record(RecordList *list, Record *record) {
    int index = -1;
    for (int i = 0; i < list->count; i++) {
        if (list->records[i].offset == record->offset && list->records[i].key == record->key && list->records[i].value == record->value) {
            index = i;
            break;
        }
    }
    if (index < 0) { // Record not found
        return false;
    }
    for (int i = index; i < list->count - 1; i++) {
        list->records[i] = list->records[i + 1];
    }
    list->count--;
    return true;
}

// Function to find a record in the list based on its offset and key
Record* find_record(RecordList *list, float offset, char key) {
    for (int i = 0; i < list->count; i++) {
        if (list->records[i].offset == offset && list->records[i].key == key) {
            return &list->records[i];
        }
    }
    return NULL;
}

// Function to safely free memory for a list of records
void free_record_list(RecordList *list) {
    if (list) {
        for (int i = 0; i < list->count; i++) {
            free_record(&list->records[i]);
        }
        free(list);
    }
}
