                data.X = Random.NextDouble(); // Random value between 0 and 1
                data.ID = Random.Next(INT_MAX); // Random integer between 0 and INT_MAX
                data.Label = 'A' + Random.Next(26); // Random ASCII character between 'A' and 'Z'
            }
        }

        // Define a function to free the allocated memory for an array of 'SensorData' structures
