// Define a struct for the record type
typedef struct {
    float value;
    char *str;
} Record;

// Function to dynamically allocate memory for and initialize three arrays: one for 'float' precision floating-point numbers, one for 'char' strings, and one for 'record' structures.
int init_arrays(Record **records, float **floats, char ***strings) {
    // Set the number of elements in each array to 100
    int num_elements = 100;

    // Allocate memory for the record array
    *records = (Record *)malloc(num_elements * sizeof(Record));
    if (*records == NULL) {
        return -1;
    }

    // Allocate memory for the float and string arrays
    *floats = (float *)calloc(num_elements, sizeof(float));
    if (*floats == NULL) {
        free(*records);
        return -1;
    }

    *strings = (char **)calloc(num_elements, sizeof(char*));
    if (*strings == NULL) {
        free(*records);
        free(*floats);
        return -1;
    }

    // Initialize the record array
    for (int i = 0; i < num_elements; i++) {
        (*records)[i].value = rand() / (float)RAND_MAX; // Generate a random float value between 0 and 1

        // Allocate memory for the string
        size_t strlen = 20;
        char *str = (char *)malloc(strlen);
        if (str == NULL) {
            free(*records);
            free(*floats);
            free(*strings);
            return -1;
        }

        // Generate a random string of length 20
        for (int j = 0; j < strlen; j++) {
            int rand_char = rand() % 26 + 'a'; // Generate a random character between 'a' and 'z'
            str[j] = rand_char;
        }

        // Store the string in the record
        (*records)[i].str = strdup(str);
        free(str);
    }

    return 0;
}

// Function to handle memory allocation failures gracefully
void handle_error() {
    printf("Memory allocation failed!\n");
    exit(-1);
}
