    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].offset = rand() % (maxOffset - minOffset + 1) + minOffset;
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
        records[i].value = (double)(rand() % (maxValue - minValue + 1)) / RAND_MAX * (maxValue - minValue) + minValue;
    }

    return records;
}

// Function to update a record's value
void updateRecord(Record* record, long newOffset, int newKey, double newValue) {
    // Check if the record is NULL
    if (!record) {
        printf("Invalid record specified\n");
        return;
    }

    // Update the record's fields with the new values
    record->offset = newOffset;
    record->key = newKey;
    record->value = newValue;
}

// Function to free the memory allocated for an array of records
void freeRecords(Record* records) {
    // Check if the records are NULL
    if (!records) {
        printf("Invalid records specified\n");
        return;
    }

    // Free the memory allocated for the records
    free(records);
}

// Function to safely allocate, initialize, update, and free the memory for an array of records
void manageRecords(int numRecords, long minOffset, long maxOffset, int minKey, int maxKey, double minValue, double maxValue) {
    // Allocate memory for the array of records and initialize it with random values within the specified ranges
    Record* records = initRecords(numRecords, minOffset, maxOffset, minKey, maxKey, minValue, maxValue);

