// Define functions for memory allocation and deallocation using an existing memory pool manager
void *allocate_memory(size_t size, void **pool) {
    // Allocate memory from the memory pool
    void *ptr = malloc(size);
    if (!ptr) {
        printf("Failed to allocate memory\n");
        return NULL;
    }

    // Add allocated memory to the memory pool
    ptr = realloc(*pool, (*pool == NULL ? size : (*pool + size)));
    if (!ptr) {
        printf("Failed to add memory to pool\n");
        free(ptr);
        return NULL;
    }

    // Update memory pool pointer
    *pool = ptr;
}

void deallocate_memory(void **pool, size_t size) {
    // Remove allocated memory from the memory pool
    void *ptr = realloc(*pool, (*pool - size));
    if (!ptr) {
        printf("Failed to remove memory from pool\n");
        return;
    }

    // Free memory
    free(ptr);
}

// Define functions for thread safety in multi-threaded environments
void *lock_memory(void **pool, size_t size) {
    // Lock the memory pool to prevent concurrent access
    void *ptr = realloc(*pool, (*pool + size));
    if (!ptr) {
        printf("Failed to lock memory\n");
        return NULL;
    }

    // Update memory pool pointer
    *pool = ptr;
}

void unlock_memory(void **pool, size_t size) {
    // Unlock the memory pool to allow concurrent access
    void *ptr = realloc(*pool, (*pool - size));
    if (!ptr) {
        printf("Failed to unlock memory\n");
        return;
    }

    // Update memory pool pointer
    *pool = ptr;
}

// Define functions for error handling
void handle_error(int ret, const char *msg) {
