Here is a possible implementation of the C function to manage a dynamic array of `record` structures:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Define the record structure
typedef struct {
  long offset;
  int key;
  double value;
} record;

// Define the dynamic array of records
typedef struct {
  record *records;
  size_t capacity;
  size_t size;
} record_array;

// Initialize the record array with random values within specified ranges
void initialize_records(record_array *arr, size_t num_records) {
  for (size_t i = 0; i < num_records; i++) {
    arr->records[i].offset = rand() % 1000000 - 500000;
    arr->records[i].key = rand() % 100 + 1;
    arr->records[i].value = (double)rand() / RAND_MAX * 2 - 1.0e6;
  }
}

// Allocate memory for the record array
record_array *allocate_records(size_t num_records) {
  record_array *arr = (record_array *)malloc(sizeof(record_array));
  if (!arr) {
    perror("Error allocating memory for records");
    return NULL;
  }

  arr->records = (record *)malloc(num_records * sizeof(record));
  if (!arr->records) {
    free(arr);
    perror("Error allocating memory for record array");
    return NULL;
  }

  arr->capacity = num_records;
  arr->size = 0;

  return arr;
}

// Free the memory used by the record array
void free_records(record_array *arr) {
  if (arr) {
    free(arr->records);
    free(arr);
  }
}

// Update a specific record in the record array
void update_record(record_array *arr, size_t index, long offset, int key, double value) {
  if (index >= arr->size) {
    perror("Error: index out of bounds");
    return;
  }

  arr->records[index].offset = offset;
  arr->records[index].key = key;
  arr->records[index].value = value;
}

// Add a new record to the record array
void add_record(record_array *arr, long offset, int key, double value) {
  if (arr->size >= arr->capacity) {
    perror("Error: record array is full");
    return;
  }

  arr->records[arr->size].offset = offset;
  arr->records[arr->size].key = key;
  arr->records[arr->size].value = value;
  arr->size++;
}

// Remove a specific record from the record array
void remove_record(record_array *arr, size_t index) {
  if (index >= arr->size) {
    perror("Error: index out of bounds");
    return;
  }

  for (size_t i = index; i < arr->size - 1; i++) {
    arr->records[i] = arr->records[i + 1];
  }

  arr->size--;
}

// Thread-safe version of the add record function
void thread_safe_add_record(record_array *arr, long offset, int key, double value) {
  pthread_mutex_lock(&arr->lock);
  add_record(arr, offset, key, value);
  pthread_mutex_unlock(&arr->lock);
}

// Thread-safe version of the update record function
void thread_safe_update_record(record_array *arr, size_t index, long offset, int key, double value) {
  pthread_mutex_lock(&arr->lock);
  update_record(arr, index, offset, key, value);
  pthread_mutex_unlock(&arr->lock);
}

// Thread-safe version of the remove record function
void thread_safe_remove_record(record_array *arr, size_t index) {
  pthread_mutex_lock(&arr->lock);
  remove_record(arr, index);
  pthread_mutex_unlock(&arr->lock);
}
