    // If there is no space for a new record, resize the array
    if (num_records == max_num_records) {
        max_num_records += 10;
        records = realloc(records, max_num_records * sizeof(Record));
        if (!records) {
            printf("Error: memory allocation failed\n");
            return;
        }
