void *allocateMemory(int numOffsets, int numKeys, int numRecords, int recordSize) {
    // Calculate the total size of the arrays in bytes
    int arraySize = (numOffsets + numKeys + numRecords) * sizeof(int);
    int recordArraySize = numRecords * recordSize;
    int totalSize = arraySize + recordArraySize;

    // Allocate memory for the arrays
    void *memory = malloc(totalSize);
    if (memory == NULL) {
