    for (int i = 0; i < size; i++) {
        timestamps[i] = rand() % 1000 + 10; // Random long value between 10 and 1000
        readings[i] = (rand() % 400) / 10.0 - 20.0; // Random float value between -20.0 and 40.0
        types[i] = rand() % 3 + 'A'; // Random char value between 'A' and 'C'
