    // Allocate memory for the array of profiles
    *profiles = (struct profile *)malloc(num_profiles * sizeof(struct profile));
    if (*profiles == NULL) {
        printf("Error: Failed to allocate memory for profiles\n");
        exit(1);
    }
}

// Function to initialize user profiles with random values
void init_profiles(int num_profiles, struct profile *profiles) {
    // Initialize the array of profiles with random values
    srand(time(NULL));
    for (int i = 0; i < num_profiles; i++) {
        // Generate a random ID within the specified range
        int id = rand() % 100000 + 1;
        profiles[i].id = id;

        // Generate a random status string within the predefined set of characters
        char *status = (char *)malloc(256);
        for (int j = 0; j < 256; j++) {
            status[j] = 'a' + rand() % ('z' - 'a');
        }
        profiles[i].status = status;
    }
}

// Function to update a single profile with new data
void update_profile(int id, char *status) {
    // Find the profile with the specified ID and update its status
    for (int i = 0; i < num_profiles; i++) {
        if (profiles[i].id == id) {
            profiles[i].status = status;
            return;
        }
    }
}

// Function to free memory allocated for user profiles
void free_profiles(struct profile *profiles) {
    // Free the memory allocated for the array of profiles
    for (int i = 0; i < num_profiles; i++) {
        free(profiles[i].status);
    }
