// Memory allocation functions
void allocate_offset_array(offset_array *arr, size_t capacity) {
    arr->capacity = capacity;
    arr->count = 0;
    arr->data = malloc(sizeof(long) * capacity);
    if (arr->data == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        exit(1);
    }
}

void allocate_key_array(key_array *arr, size_t capacity) {
    arr->capacity = capacity;
    arr->count = 0;
    arr->data = malloc(sizeof(int) * capacity);
    if (arr->data == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        exit(1);
    }
}

void allocate_record_array(record_array *arr, size_t capacity) {
    arr->capacity = capacity;
    arr->count = 0;
    arr->data = malloc(sizeof(struct record) * capacity);
    if (arr->data == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        exit(1);
    }
}

// Initialization functions
