    }
}

void initialize_key_array(key_array *arr) {
    for (size_t i = 0; i < arr->capacity; i++) {
        arr->data[i] = rand() % 1000;
    }
}

void initialize_record_array(record_array *arr) {
    for (size_t i = 0; i < arr->capacity; i++) {
        arr->data[i].value = rand() % 1000;
    }
}

// Update record function
void update_record_array(record_array *arr, int record_index, int value) {
    if (record_index < 0 || record_index >= arr->capacity) {
        printf("Error: Invalid record index\n");
        return;
    }
    arr->data[record_index].value = value;
}

// Free memory functions
