    // Check if file exists and is writable
    FILE* fp = fopen(filename, "a");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

    // Allocate memory for timestamp and sensor reading arrays
    long* timestamps = (long*)malloc(num_sensors * max_readings * sizeof(long));
    double* readings = (double*)malloc(num_sensors * max_readings * sizeof(double));
    if (timestamps == NULL || readings == NULL) {
