// Function to dynamically allocate memory for the arrays and initialize them with default values
void init_data(long **offset_values, int **key_values, float **value_values, data_entry ***entries) {
    // Allocate memory for the offset values array
    *offset_values = malloc(sizeof(long) * 10);
    if (*offset_values == NULL) {
        // Handle allocation failure gracefully
