        fprintf(stderr, "Error: Failed to allocate memory for key values\n");
        return;
    }

    // Initialize the key values array with default values
    for (int i = 0; i < 5; i++) {
        (*key_values)[i] = i * 10;
    }

    // Allocate memory for the value values array
    *value_values = malloc(sizeof(float) * 10);
    if (*value_values == NULL) {
        // Handle allocation failure gracefully
        fprintf(stderr, "Error: Failed to allocate memory for value values\n");
        return;
    }

    // Initialize the value values array with default values
    for (int i = 0; i < 10; i++) {
        (*value_values)[i] = i * 1.5;
    }

    // Allocate memory for the entries array
    *entries = malloc(sizeof(data_entry *) * 10);
    if (*entries == NULL) {
        // Handle allocation failure gracefully
        fprintf(stderr, "Error: Failed to allocate memory for data entries\n");
        return;
    }

    // Initialize the entries array with default values
    for (int i = 0; i < 10; i++) {
        (*entries)[i] = malloc(sizeof(data_entry));
        if ((*entries)[i] == NULL) {
            // Handle allocation failure gracefully
            fprintf(stderr, "Error: Failed to allocate memory for data entry %d\n", i);
            return;
        }

        (*entries)[i]->key = i * 10;
        (*entries)[i]->value = i * 1.5;
        (*entries)[i]->identifier = malloc(sizeof(char) * 16);
        if ((*entries)[i]->identifier == NULL) {
            // Handle allocation failure gracefully
            fprintf(stderr, "Error: Failed to allocate memory for identifier for data entry %d\n", i);
            return;
        }

        snprintf((*entries)[i]->identifier, 16, "Data Entry %d", i);
    }
}

// Function to update the values in the arrays and the entries array
void update_data(long *offset_values, int *key_values, float *value_values, data_entry **entries) {
    // Update the offset values array with new values
    for (int i = 0; i < 10; i++) {
        (*offset_values)[i] += 500;
    }

    // Update the key values array with new values
    for (int i = 0; i < 5; i++) {
        (*key_values)[i] *= 2;
    }

    // Update the value values array with new values
    for (int i = 0; i < 10; i++) {
        (*value_values)[i] += 1.5;
    }

    // Update the entries array with new data
    for (int i = 0; i < 10; i++) {
        (*entries)[i]->key += 20;
        (*entries)[i]->value += 3.5;
        snprintf((*entries)[i]->identifier, 16, "Data Entry %d", (*entries)[i]->key);
    }
}

// Function to free the memory allocated for the arrays and the entries array
void cleanup_data(long *offset_values, int *key_values, float *value_values, data_entry **entries) {
    // Free the offset values array
    free(*offset_values);

    // Free the key values array
    free(*key_values);

    // Free the value values array
    free(*value_values);

    // Free the entries array
    for (int i = 0; i < 10; i++) {
        free((*entries)[i]->identifier);
        free(*entries);
    }
}
