    if (records == NULL) {
        printf("Error: Failed to allocate memory for %d records\n", numRecords);
        return NULL;
    }

    // Initialize each record in the array with NULL values
    int i;
    for (i = 0; i < numRecords; ++i) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return NULL;
        }
        records[i]->key = 0;
        records[i]->value = 0.0f;
        records[i]->next = NULL;
    }

    return records;
}

// Function to initialize an array of 'Record' structures with random values
void initializeRecords(Record** records, int numRecords) {
    // Generate random integers for the key and float values within the specified ranges
    srand(time(NULL));
    int i;
    for (i = 0; i < numRecords; ++i) {
        records[i]->key = rand() % 50 + 1;
        records[i]->value = ((float)rand() / RAND_MAX) * 200.0f - 100.0f;
    }
}

// Function to update a record in the array with new values
void updateRecord(Record** records, int index, int key, float value) {
    // Check if the index is within the bounds of the array
    if (index < 0 || index >= numRecords) {
        printf("Error: Invalid index %d\n", index);
        return;
    }

    records[index]->key = key;
    records[index]->value = value;
}

// Function to free the memory allocated for an array of 'Record' structures
void freeRecords(Record** records, int numRecords) {
    // Free each record in the array
    int i;
    for (i = 0; i < numRecords; ++i) {
        free(records[i]);
    }

    // Free the memory allocated for the array of records pointers
    free(records);
}

// Function to read data from an external JSON file and initialize the records accordingly
void readJsonData(Record** records, int numRecords) {
    // Open the JSON file for reading
    FILE* fp = fopen("data.json", "r");
    if (fp == NULL) {
        printf("Error: Failed to open JSON file\n");
        return;
    }

    // Parse the JSON data in the file and initialize the records accordingly
    while (!feof(fp)) {
        char line[1024];
        fgets(line, 1024, fp);

        // Parse the key-value pair from the JSON object
        int key = atoi(strtok(line, ":"));
        float value = atof(strtok(NULL, ","));

        // Update the record with the new values
        updateRecord(records, key - 1, key, value);
    }

    fclose(fp);
}

int main() {
    // Allocate memory for an array of 'Record' structures
    int numRecords = 5;
    Record** records = allocateRecords(numRecords);
    if (records == NULL) {
        return 1;
    }

    // Initialize the array with random values
    initializeRecords(records, numRecords);

    // Read data from an external JSON file and update the records accordingly
    readJsonData(records, numRecords);

    // Free the memory allocated for the arrays
    freeRecords(records, numRecords);

    return 0;
}
```
