['Here is an example implementation of the given programming task using C:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <assert.h>

// Define data structures
typedef struct {
    float x, y;
} Coordinate;

typedef struct {
    int id;
    char label[10];
} Item;

typedef struct {
    Item *item;
    long offset;
} Record;

// Define functions for managing memory allocation and initialization
void allocate_memory(int num_items, int num_records) {
    // Allocate memory for the arrays
    Coordinate *coordinates = malloc(num_items * sizeof(Coordinate));
    Item *items = malloc(num_items * sizeof(Item));
    Record *records = malloc(num_records * sizeof(Record));

    // Initialize the arrays
    for (int i = 0; i < num_items; ++i) {
        coordinates[i].x = 0.0f;
        coordinates[i].y = 0.0f;
        items[i].id = 0;
        memset(items[i].label, 0, sizeof(items[i].label));
    }
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = 0;
        records[i].item = NULL;
    }
}

void initialize_arrays(int num_items, int num_records) {
    // Generate random values for the arrays
    srand(time(NULL));
    for (int i = 0; i < num_items; ++i) {
        coordinates[i].x = rand() / (float)RAND_MAX * 10.0f;
        coordinates[i].y = rand() / (float)RAND_MAX * 10.0f;
        items[i].id = i + 1;
        memset(items[i].label, 'A' + (rand() % 26), sizeof(items[i].label));
    }
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand() / (float)RAND_MAX * 10.0f;
        records[i].item = &items[rand() % num_items];
    }
}

void update_arrays(int num_items, int num_records) {
    // Update the arrays with new values
    for (int i = 0; i < num_items; ++i) {
        coordinates[i].x += 1.0f;
        coordinates[i].y += 1.0f;
        items[i].id += 1;
        memset(items[i].label, 'A' + (rand() % 26), sizeof(items[i].label));
    }
    for (int i = 0; i < num_records; ++i) {
        records[i].offset += 1.0f;
        records[i].item = &items[rand() % num_items];
    }
}

void free_memory(int num_items, int num_records) {
    // Free the allocated memory
    free(coordinates);
    free(items);
    free(records);
}

// Define functions for managing error handling and graceful termination
void handle_error(const char *message) {
