    exit(EXIT_FAILURE);
}

void handle_termination() {
    fprintf(stdout, "Terminating program...\n");
    exit(EXIT_SUCCESS);
}

// Define functions for managing the lifecycle of the allocated resources
int main(int argc, char *argv[]) {
    // Parse command-line arguments and environment variables
    if (argc < 2) {
        handle_error("Invalid number of command-line arguments");
    }
    int num_items = atoi(argv[1]);
    int num_records = atoi(argv[2]);
    if (num_items > 1000 || num_records > 1000) {
        handle_error("Invalid number of items or records");
    }

    // Allocate memory for the arrays and initialize them
    allocate_memory(num_items, num_records);
    initialize_arrays(num_items, num_records);

    // Update the arrays with new values and free the allocated memory
    update_arrays(num_items, num_records);
    free_memory(num_items, num_records);

    // Handle error handling and graceful termination
    handle_termination();
    return 0;
}
