    data->sensor_values = malloc(sizeof(double) * 5);
    data->timestamps = malloc(sizeof(uint32_t) * 5);
    data->metadata_strings = malloc(sizeof(char*) * 5);
    data->offset_values = malloc(sizeof(long) * 5);
    data->sensor_readings = malloc(sizeof(int) * 5);

    // Initialize the memory for each array
    memset(data->sensor_values, 0, sizeof(double) * 5);
    memset(data->timestamps, 0, sizeof(uint32_t) * 5);
    memset(data->metadata_strings, 0, sizeof(char*) * 5);
    memset(data->offset_values, 0, sizeof(long) * 5);
    memset(data->sensor_readings, 0, sizeof(int) * 5);
}

// Free memory for the five arrays
void free_sensor_memory(sensor_data* data) {
    // Free memory for each array
    free(data->sensor_values);
    free(data->timestamps);
    free(data->metadata_strings);
    free(data->offset_values);
    free(data->sensor_readings);
