// Ensure thread safety if multiple threads are accessing or modifying these resources
#define THREAD_SAFE 1

// Dynamically allocate memory for five arrays: double, uint32_t, char, long, and int
void* thread_safe_allocate_sensor_memory(size_t num_sensors) {
    #ifdef THREAD_SAFE
        return malloc(sizeof(double) * 5 + sizeof(uint32_t) * 5 + sizeof(char*) * 5 + sizeof(long) * 5 + sizeof(int) * 5);
