// Implement functions to manage the lifecycle of these allocated resources by providing functions to safely allocate, initialize, update, and free the allocated memory
void* allocate_sensor_readings(size_t num_sensors) {
    // Allocate memory for an array of `sensor_reading` structures containing a single float value representing sensor readings and a character string as unique identifiers
    sensor_reading** readings = malloc(sizeof(sensor_reading*) * num_sensors);
    for (size_t i = 0; i < num_sensors; i++) {
