    temperature->fahrenheit = (temperature->celsius * 9.0f / 5.0f) + 32.0f;

    // Initialize pressure structure
    pressure->kilopascals = generate_random_value(900.0f, 1100.0f);
    pressure->inches_mercury = (pressure->kilopascals / 100.0f) + 30.0f;

