// Struct to represent sensor data
struct SensorData {
    double temperature;
    double humidity;
    double pressure;
};

// Function to allocate memory for arrays of sensor readings
void* allocate_sensor_data(size_t num_sensors) {
    void* data = malloc(num_sensors * sizeof(struct SensorData));
    if (data == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    return data;
}

// Function to initialize arrays of sensor readings with random values within specified ranges
void initialize_sensor_data(void* data, size_t num_sensors) {
    struct SensorData* sensor_data = (struct SensorData*)data;
    for (size_t i = 0; i < num_sensors; i++) {
        // Generate random values within specified ranges for temperature, humidity, and pressure
        sensor_data[i].temperature = ((double)rand() / RAND_MAX) * (-50.0 - 50.0) + 50.0;
        sensor_data[i].humidity = ((double)rand() / RAND_MAX) * (100.0 - 0.0) + 0.0;
        sensor_data[i].pressure = ((double)rand() / RAND_MAX) * (1050.0 - 950.0) + 950.0;
    }
}

// Function to update arrays of sensor readings with new values
void update_sensor_data(void* data, size_t num_sensors) {
    struct SensorData* sensor_data = (struct SensorData*)data;
    for (size_t i = 0; i < num_sensors; i++) {
        // Generate new random values within specified ranges for temperature, humidity, and pressure
        sensor_data[i].temperature = ((double)rand() / RAND_MAX) * (-50.0 - 50.0) + 50.0;
        sensor_data[i].humidity = ((double)rand() / RAND_MAX) * (100.0 - 0.0) + 0.0;
        sensor_data[i].pressure = ((double)rand() / RAND_MAX) * (1050.0 - 950.0) + 950.0;
    }
}

// Function to safely allocate and initialize memory for arrays of sensor readings
void* safe_allocate_sensor_data(size_t num_sensors) {
    void* data = malloc(num_sensors * sizeof(struct SensorData));
    if (data == NULL) {
        perror("Error allocating memory");
        return NULL;
    }
    initialize_sensor_data(data, num_sensors);
    return data;
}

// Function to safely update arrays of sensor readings with new values
void safe_update_sensor_data(void* data, size_t num_sensors) {
    if (data == NULL) {
        fprintf(stderr, "Error: Data is null\n");
        return;
    }
    update_sensor_data(data, num_sensors);
}

// Function to safely free allocated memory for arrays of sensor readings
void safe_free_sensor_data(void* data) {
    if (data == NULL) {
        fprintf(stderr, "Error: Data is null\n");
        return;
    }
    free(data);
}
