    double temperature;
    double humidity;
    double pressure;
};

// Class to manage sensor data
class SensorManager {
    private List<SensorData> _sensorData;

    public SensorManager(int numSensors) {
        // Initialize list of sensor data with given number of sensors
        _sensorData = new List<SensorData>(numSensors);
        for (int i = 0; i < numSensors; i++) {
            _sensorData.Add(new SensorData());
        }
    }

    // Function to update sensor data with new values
    public void UpdateSensorData() {
        foreach (var sensor in _sensorData) {
            // Generate new random values within specified ranges for temperature, humidity, and pressure
            sensor.temperature = ((double)rand() / RAND_MAX) * (-50.0 - 50.0) + 50.0;
            sensor.humidity = ((double)rand() / RAND_MAX) * (100.0 - 0.0) + 0.0;
            sensor.pressure = ((double)rand() / RAND_MAX) * (1050.0 - 950.0) + 950.0;
        }
    }

    // Function to get all sensor data
    public List<SensorData> GetAllSensorData() {
        return _sensorData;
    }
}
