### C++ Solution

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

struct SensorReading {
    long timestamp;
    float temperature;
    float humidity;
    float pressure;
};

vector<SensorReading> buffer;

void add_sensor_reading(SensorReading reading) {
    if (buffer.size() >= 10) {
        buffer.erase(buffer.begin());
    }
    buffer.push_back(reading);
}

void update_sensor_reading(long timestamp, float temperature, float humidity, float pressure) {
    SensorReading reading = {timestamp, temperature, humidity, pressure};
    add_sensor_reading(reading);
}

SensorReading get_latest_sensor_reading() {
    if (buffer.size() == 0) {
        return {0, 0.0f, 0.0f, 0.0f};
    } else {
        return buffer[buffer.size() - 1];
    }
}

SensorReading get_oldest_sensor_reading() {
    if (buffer.size() == 0) {
        return {0, 0.0f, 0.0f, 0.0f};
    } else {
        return buffer[0];
    }
}

int get_num_sensor_readings() {
    return buffer.size();
}

void load_sensor_data(string filename) {
    ifstream input_file(filename);
    string line;
    while (getline(input_file, line)) {
        vector<string> tokens = split(line, ',');
        long timestamp = stol(tokens[0]);
        float temperature = stof(tokens[1]);
        float humidity = stof(tokens[2]);
        float pressure = stof(tokens[3]);
        SensorReading reading = {timestamp, temperature, humidity, pressure};
        update_sensor_reading(reading);
    }
}

int main() {
    string filename = "data.csv";
    load_sensor_data(filename);
    SensorReading latest = get_latest_sensor_reading();
    cout << "Latest sensor reading: " << latest.timestamp << ", " << latest.temperature << "C, " << latest.humidity << "%, " << latest.pressure << "hPa" << endl;
    SensorReading oldest = get_oldest_sensor_reading();
    cout << "Oldest sensor reading: " << oldest.timestamp << ", " << oldest.temperature << "C, " << oldest.humidity << "%, " << oldest.pressure << "hPa" << endl;
    int num_readings = get_num_sensor_readings();
    cout << num_readings << " sensor readings found in buffer." << endl;
    return 0;
}
```

