        return -1;
    }

    // Loop through the array of items and store the indices of the elements with the same ID or label
    for (int i = 0; i < num_items; i++) {
        id_indices[i] = indices[i];
        label_indices[i] = indices[i];
    }

    // Loop through the array of items again and check if any two elements have the same ID or label
    for (int i = 0; i < num_items; i++) {
        for (int j = i + 1; j < num_items; j++) {
            if (id_indices[i] == id_indices[j] || label_indices[i] == label_indices[j]) {
                return 0; // Return false if any two elements have the same ID or label
            }
        }
    }

    free(id_indices);
    free(label_indices);
    return 1; // Return true if no two elements have the same ID or label
}

// Function to measure and print the time taken to perform Union-Find checks in milliseconds
void union_find_checks(Item *items, int num_items) {
    clock_t start = clock();
