            } else {
                printf("Union-Find check between items %d and %d: not disjoint\n", i, j);
            }
        }
    }
    clock_t end = clock();
    double time_taken = (double)(end - start) / CLOCKS_PER_SEC * 1000;
    printf("Time taken to perform Union-Find checks: %.3lf milliseconds\n", time_taken);
}
