    // Initialize each location with random values within specified ranges
    for (int i = 0; i < num_locations; i++) {
        locations[i].coordinate = rand() % 200 - 100.0;
        locations[i].id = rand() % 100 + 1;
        locations[i].label = 'A' + (rand() % 5);
    }
