    // Update each location with new values
    for (int i = 0; i < num_locations; i++) {
        locations[i].coordinate += rand() % 200 - 100.0;
        locations[i].id = rand() % 100 + 1;
        locations[i].label = 'A' + (rand() % 5);
    }
}

// Define a function to free the array of locations
void free_locations(location* locations, int num_locations) {
    // Free the memory allocated for each location
    for (int i = 0; i < num_locations; i++) {
        free(locations[i]);
    }
}

// Define a function to handle memory allocation failures
void handle_allocation_failure() {
    // Log the error message and exit the program
    printf("Memory allocation failed\n");
    exit(EXIT_FAILURE);
}

