    // Initialize an array of 10 locations
    location* locations = malloc(10 * sizeof(location));
    if (locations == NULL) {
        handle_allocation_failure();
    }

    // Initialize the array of locations with random values
    init_locations(locations, 10);

    // Update the array of locations with new values
    update_locations(locations, 10);

    // Free the memory allocated for the array of locations
    free_locations(locations, 10);

