Here is an example implementation of the C function for managing a dynamic sensor data bundle for an embedded system:
```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>

// Configuration options
#define MAX_SENSORS 1000
#define MIN_READING -100.0
#define MAX_READING 100.0
#define MIN_TIMESTAMP 1672531200
#define MAX_TIMESTAMP (time(NULL) + 86400)
#define DEVICE_IDS "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

// Structure to represent a sensor reading
typedef struct {
    float reading;
    int timestamp;
    char device_id[3];
} SensorReading;

// Function to load sensor data from a file and validate it
int loadSensorData(const char* filename, SensorReading** readings, size_t* num_readings) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        return -1;
    }

    // Allocate memory for the sensor readings
    *num_readings = 0;
    SensorReading* readings_ptr = (SensorReading*)malloc(MAX_SENSORS * sizeof(SensorReading));
    if (!readings_ptr) {
        return -1;
    }

    // Read the sensor data from the file
    while (fscanf(fp, "%d %s %f", &readings_ptr[*num_readings].timestamp, readings_ptr[*num_readings].device_id,
                  &readings_ptr[*num_readings].reading) == 3) {
        // Validate the input
        if (readings_ptr[*num_readings].timestamp < MIN_TIMESTAMP || readings_ptr[*num_readings].timestamp > MAX_TIMESTAMP) {
            return -1;
        }
        if (readings_ptr[*num_readings].reading < MIN_READING || readings_ptr[*num_readings].reading > MAX_READING) {
            return -1;
        }
        if (strchr(DEVICE_IDS, readings_ptr[*num_readings].device_id[0]) == NULL) {
            return -1;
        }

        // Increment the number of valid sensor readings
        (*num_readings)++;
    }

    // Allocate memory for the sensor data
    *readings = (SensorReading*)malloc(*num_readings * sizeof(SensorReading));
    if (!*readings) {
        return -1;
    }

    // Copy the valid sensor readings into the allocated memory
    memcpy(*readings, readings_ptr, (*num_readings) * sizeof(SensorReading));

    // Clean up
    free(readings_ptr);
    fclose(fp);

    return 0;
}

// Function to update a sensor reading in the data bundle
int updateSensorReading(SensorReading* readings, size_t num_readings, int timestamp, float reading) {
    // Find the index of the corresponding sensor reading
    for (size_t i = 0; i < num_readings; i++) {
        if (readings[i].timestamp == timestamp) {
            readings[i].reading = reading;
            return 0;
        }
    }

    // If the timestamp is not found, return an error
    errno = EINVAL;
    return -1;
}

// Function to free the memory allocated for the sensor data
void freeSensorData(SensorReading* readings) {
    if (readings != NULL) {
        free(readings);
    }
}
```
The function `loadSensorData` loads sensor data from a file and validates it. It allocates memory for the sensor readings using `malloc`, reads the data from the file, and copies the valid sensor readings into the allocated memory. If any of the input values are out of range or if there is an error reading the file, the function returns -1 and sets `errno` to `EINVAL`.

