// Define the functions to manage the lifecycle of allocated resources
void allocate_resources() {
    // Allocate memory for the arrays of long offsets, int keys, and record structures
    long* long_offsets = (long*)MEMORY_POOL_ALLOC(memory_pool, MAX_RECORDS * sizeof(long));
    int* int_keys = (int*)MEMORY_POOL_ALLOC(memory_pool, MAX_RECORDS * sizeof(int));
    sensor_record* records = (sensor_record*)MEMORY_POOL_ALLOC(memory_pool, MAX_RECORDS * sizeof(sensor_record));

    // Initialize the arrays with random values within specified ranges
    for (int i = 0; i < MAX_RECORDS; i++) {
        long_offsets[i] = MIN_OFFSET + (rand() % (MAX_OFFSET - MIN_OFFSET));
        int_keys[i] = MIN_KEY + (rand() % (MAX_KEY - MIN_KEY));
        records[i].value = MIN_RECORD_VALUE + (rand() % (MAX_RECORD_VALUE - MIN_RECORD_VALUE));
    }

    // Return the allocated arrays
    return long_offsets, int_keys, records;
}

void free_resources(long* long_offsets, int* int_keys, sensor_record* records) {
    // Free the memory allocated for the arrays of long offsets, int keys, and record structures
    MEMORY_POOL_FREE(memory_pool, long_offsets);
    MEMORY_POOL_FREE(memory_pool, int_keys);
    MEMORY_POOL_FREE(memory_pool, records);
}

void update_resources(long* long_offsets, int* int_keys, sensor_record* records) {
    // Update the arrays with new values within specified ranges
    for (int i = 0; i < MAX_RECORDS; i++) {
        long_offsets[i] = MIN_OFFSET + (rand() % (MAX_OFFSET - MIN_OFFSET));
        int_keys[i] = MIN_KEY + (rand() % (MAX_KEY - MIN_KEY));
        records[i].value = MIN_RECORD_VALUE + (rand() % (MAX_RECORD_VALUE - MIN_RECORD_VALUE));
    }
}

// Define the function to handle errors gracefully and prevent resource leaks
void error_handler(const char* message) {
    // Log the error message using the logging module
    LOGGING_MODULE_LOG(logging_module, LOG_ERROR, "Error: %s", message);

    // Free the memory allocated for the arrays of long offsets, int keys, and record structures
    MEMORY_POOL_FREE(memory_pool, long_offsets);
    MEMORY_POOL_FREE(memory_pool, int_keys);
    MEMORY_POOL_FREE(memory_pool, records);

    // Exit the program with an error code
    exit(EXIT_FAILURE);
}

int main() {
    // Declare variables for the allocated arrays of long offsets, int keys, and record structures
    long* long_offsets = NULL;
    int* int_keys = NULL;
    sensor_record* records = NULL;

    // Initialize the memory pool and logging module
    MEMORY_POOL_INIT(memory_pool);
    LOGGING_MODULE_INIT(logging_module, "Logging Module");

    // Allocate and initialize the arrays of long offsets, int keys, and record structures
    allocate_resources(&long_offsets, &int_keys, &records);

