    service = init_js_service(service);

    // Define the variables for the thread and mutex locks
    pthread_t thread;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Create a new thread to handle the sensor data streams and JavaScript service component
    pthread_create(&thread, NULL, handle_sensor_streams, (void*)service);

    // Define the variables for the loop counter and the delay between updates
    int i = 0;
    int delay = 1000;

    // Loop until a keyboard interrupt is received
    while (1) {
        // Check if the thread has completed
        if (pthread_tryjoin_np(thread, NULL)) {
            break;
        }

        // Update the arrays with new values within specified ranges
        update_resources(long_offsets, int_keys, records);

        // Delay between updates
        usleep(delay);
    }

    // Free the memory allocated for the arrays of long offsets, int keys, and record structures
    free_resources(long_offsets, int_keys, records);

    // Exit the program successfully
    return EXIT_SUCCESS;
}

// Define the functions to handle the sensor data streams and JavaScript service component
void* handle_sensor_streams(void* arg) {
    // Cast the argument as a pointer to the js_service struct
    js_service* service = (js_service*)arg;

    // Loop until a keyboard interrupt is received
    while (1) {
        // Check if the thread has completed
        if (pthread_tryjoin_np(thread, NULL)) {
            break;
        }

        // Acquire the mutex lock
        pthread_mutex_lock(&lock);

        // Update the arrays with new values within specified ranges
        update_resources(long_offsets, int_keys, records);

        // Send the updated data to the JavaScript service component
        send_data(service, long_offsets, int_keys, records);

        // Release the mutex lock
        pthread_mutex_unlock(&lock);
    }

    // Exit the thread successfully
    return NULL;
}

// Define the functions to send data to the JavaScript service component
void send_data(js_service* service, long* long_offsets, int* int_keys, sensor_record* records) {
    // Serialize the data into a JSON object
    json_object* data = json_serialize(long_offsets, int_keys, records);

    // Send the data to the JavaScript service component using the sendData function
    js_service_send_data(service, data);
}

// Define the functions to serialize and deserialize the data into JSON objects
json_object* json_serialize(long* long_offsets, int* int_keys, sensor_record* records) {
    // Create a new JSON object
    json_object* root = json_object_new();

    // Add the arrays of long offsets, int keys, and record structures to the JSON object
    json_object_object_add(root, "longOffsets", json_array_new(long_offsets));
    json_object_object_add(root, "intKeys", json_array_new(int_keys));
    json_object_object_add(root, "records", json_array_new(records));

    // Return the JSON object
    return root;
}

void json_deserialize(json_object* root) {
    // Extract the arrays of long offsets, int keys, and record structures from the JSON object
    long* long_offsets = json_array_get_value(root->longOffsets);
    int* int_keys = json_array_get_value(root->intKeys);
    sensor_record* records = json_array_get_value(root->records);

    // Update the arrays with the new values within specified ranges
    for (int i = 0; i < MAX_RECORDS; i++) {
        long_offsets[i] = MIN_OFFSET + (rand() % (MAX_OFFSET - MIN_OFFSET));
        int_keys[i] = rand() % MAX_KEYS;
        records[i].value = (float)((rand() % 100) / 10.0);
    }
}
