typedef struct record {
    long offset;
    int key;
    double value;
} record_t;

void init_random(long min, long max) {
    srand(time(NULL));
    random_range = (max - min) + 1;
}

int generate_random_offset() {
    return rand() % random_range + min;
}

int generate_random_key() {
    return rand() % 100 + 1;
}

double generate_random_value() {
    return (rand() % INT64_MAX) * 0.000001 - 0.5;
}

void allocate_and_initialize(int num_records, record_t **records) {
    // Allocate memory for the arrays
    *records = (record_t *)malloc(num_records * sizeof(record_t));
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the arrays with random values
    init_random(-1000000, 1000000);
    for (int i = 0; i < num_records; i++) {
        (*records)[i].offset = generate_random_offset();
        (*records)[i].key = generate_random_key();
        (*records)[i].value = generate_random_value();
    }
}

void update(record_t *records, int num_records) {
    // Update the records with new random values
    init_random(-1000000, 1000000);
    for (int i = 0; i < num_records; i++) {
        (*records)[i].offset = generate_random_offset();
        (*records)[i].key = generate_random_key();
        (*records)[i].value = generate_random_value();
    }
}

void free_allocated_memory(record_t **records) {
    // Free the allocated memory for the arrays
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}
