        char *key_str = strtok(NULL, " ");
        char *value_str = strtok(NULL, " ");
        if (!offset_str || !key_str || !value_str) {
            printf("Error: invalid format in config file %s\n", config_file);
            return -1;
        }

        long offset = atol(offset_str);
        int key = atoi(key_str);
        double value = atof(value_str);

        if (offset < -1000000 || offset > 1000000) {
            printf("Error: offset out of range in config file %s\n", config_file);
            return -1;
        }

        if (key < 1 || key > 100) {
            printf("Error: key out of range in config file %s\n", config_file);
            return -1;
        }

        if (value < -1.0e6 || value > 1.0e6) {
            printf("Error: value out of range in config file %s\n", config_file);
            return -1;
        }

        offset_array[num_records] = offset;
        key_array[num_records] = key;
        value_array[num_records] = value;
        num_records++;
    }

    // Close the configuration file
    fclose(fp);

    // Allocate memory for the record array and populate it with the arrays
    Record *record_array = malloc(sizeof(Record) * num_records);
    if (!record_array) {
        printf("Error: failed to allocate memory for record array\n");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        record_array[i].offset = offset_array[i];
        record_array[i].key = key_array[i];
        record_array[i].value = value_array[i];
    }

    // Return the pointer to the record array
    return record_array;
}

