    // Allocate memory for the double precision floating-point numbers array
    double *numbers = malloc(sizeof(double) * num_points);
    if (!numbers) {
        printf("Error: Failed to allocate memory for numbers\n");
        return;
    }

    // Initialize the double precision floating-point numbers with random values within the specified range
    for (size_t i = 0; i < num_points; i++) {
        numbers[i] = min_value + ((double)rand() / (double)(RAND_MAX)) * (max_value - min_value);
    }

    // Allocate memory for the char strings array
    char **strings = malloc(sizeof(char *) * num_points);
    if (!strings) {
        printf("Error: Failed to allocate memory for strings\n");
        free(numbers);
        return;
    }

    // Initialize the char strings with unique identifiers
    for (size_t i = 0; i < num_points; i++) {
        strings[i] = malloc(sizeof(char) * 16);
        if (!strings[i]) {
            printf("Error: Failed to allocate memory for string %lu\n", i);
            free(numbers);
            free(strings);
            return;
        }
        snprintf(strings[i], 16, "%lu", i);
    }

    // Allocate memory for the data_point array and initialize it with the random values and identifiers
    data_point *data = malloc(sizeof(data_point) * num_points);
    if (!data) {
        printf("Error: Failed to allocate memory for data points\n");
        free(numbers);
        free(strings);
        return;
    }
    for (size_t i = 0; i < num_points; i++) {
        data[i].value = numbers[i];
        data[i].string = strings[i];
    }

