// Function to dynamically allocate and initialize an array of records
int allocateAndInitializeRecords(Record **records, int numRecords) {
    if (numRecords <= 0) {
        return -1;
    }
    *records = malloc(sizeof(Record) * numRecords);
    if (*records == NULL) {
        return -2;
    }
    for (int i = 0; i < numRecords; i++) {
        initializeRecord(&(*records)[i]);
    }
    return 0;
}

// Function to update the value of a record
void updateRecordValue(Record *record) {
    // Generate a random number within the range [1, 10]
    int randomValue = rand() % 10 + 1;
    record->value = randomValue;
}

// Function to check if a point is within a given range
int isPointWithinRange(const Point *point, float minX, float maxX, float minY, float maxY) {
    // Check if the point's coordinates are within the given range
    return (point->x >= minX && point->x <= maxX && point->y >= minY && point->y <= maxY);
}

// Function to dynamically allocate and initialize an array of polygons
int allocateAndInitializePolygons(Polygon **polygons, int numPolygons) {
    if (numPolygons <= 0) {
        return -1;
    }
    *polygons = malloc(sizeof(Polygon) * numPolygons);
    if (*polygons == NULL) {
        return -2;
    }
    for (int i = 0; i < numPolygons; i++) {
        // Initialize the polygon's number of points to zero
        (*polygons)[i].numPoints = 0;
        // Allocate memory for the polygon's points array
        (*polygons)[i].points = malloc(sizeof(Point *) * (*polygons)[i].numPoints);
        if ((*polygons)[i].points == NULL) {
            return -3;
        }
    }
    return 0;
}

// Function to generate a random point within the given range
Point generateRandomPoint(float minX, float maxX, float minY, float maxY) {
    // Generate a random X and Y coordinate within the given range
    int x = rand() % (maxX - minX + 1) + minX;
    int y = rand() % (maxY - minY + 1) + minY;
    Point point;
    point.x = x;
    point.y = y;
    return point;
}

// Function to add a new point to a polygon
void addPointToPolygon(Polygon *polygon, const Point *point) {
    // Check if the polygon's points array is full
    if (polygon->numPoints == polygon->points->size) {
        return;
    }
    // Add the new point to the polygon's points array
    polygon->points[polygon->numPoints++] = malloc(sizeof(Point));
    memcpy(polygon->points[polygon->numPoints - 1], point, sizeof(Point));
}

// Function to update a record with a new value and add a new point to a polygon if necessary
void updateRecordValueAndAddPointToPolygon(Record *record, const Point *point) {
