// Define a function to dynamically allocate memory for an array of 'data_point' structures
data_point *allocate_data_points(size_t n) {
    data_point *array = (data_point *)malloc(n * sizeof(data_point));
    if (array == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    for (int i = 0; i < n; ++i) {
        array[i].value = 0.0;
        strcpy(array[i].string, ""); // specify the default value of the string
    }
    return array;
}

// Define a function to insert a node into the linked list
void insert_node(node **head_ref, int key, data_point *data) {
    // Create a new node
    node *new_node = (node *)malloc(sizeof(node));
    if (new_node == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    new_node->key = key;
    new_node->data = data;
    new_node->next = NULL;

    // If the linked list is empty, return the new node
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    // Insert the new node at the end of the linked list
    node *temp = *head_ref;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = new_node;
}

// Define a function to read data points from an external CSV file and populate the structures accordingly
void read_data_points(const char *filename, node **head_ref) {
    // Open the CSV file
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Could not open file %s\n", filename);
        exit(1);
    }

    // Define a buffer to store data points from the CSV file
    char buffer[1024];

    // Read each line of the CSV file
    while (fgets(buffer, 1024, file) != NULL) {
        // Parse the line and extract the key and value
        int key;
        double value;
        sscanf(buffer, "%d,%lf", &key, &value);

        // Allocate memory for the data point structure
        data_point *data = allocate_data_points(1);
        if (data == NULL) {
            printf("Memory allocation failed!\n");
            exit(1);
        }

        // Fill in the data point structure with the parsed key and value
        data->value = value;
        strcpy(data->string, ""); // specify the default value of the string

        // Insert the node into the linked list
        insert_node(head_ref, key, data);
    }

    // Close the CSV file
    fclose(file);
}

// Define a function to free memory allocated for the linked list
void free_list(node **head_ref) {
    node *temp = *head_ref;
    while (temp != NULL) {
        node *next = temp->next;
        free(temp);
        temp = next;
    }
}
