Here's a sample C function to manage the lifecycle of a dynamic record set with versioning, merging, and efficient memory management:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a struct to represent a single record
struct Record {
    int key;
    long offset;
};

// Define a struct to represent the entire dynamic record set
struct RecordSet {
    // The array of offsets for each record
    long *offsets;

    // The array of keys for each record
    int *keys;

    // The array of records
    struct Record *records;

    // The number of records in the set
    size_t numRecords;

    // The current version of the record set
    unsigned long version;
};

// Function to allocate a new record set with a given capacity
struct RecordSet* allocateRecordSet(size_t capacity) {
    struct RecordSet *recordSet = (struct RecordSet*) malloc(sizeof(struct RecordSet));
    if (!recordSet) return NULL;

    // Allocate memory for the offsets, keys, and records arrays
    recordSet->offsets = (long*) calloc(capacity, sizeof(long));
    recordSet->keys = (int*) calloc(capacity, sizeof(int));
    recordSet->records = (struct Record*) calloc(capacity, sizeof(struct Record));

    // Initialize the number of records and version to 0
    recordSet->numRecords = 0;
    recordSet->version = 0;

    return recordSet;
}

// Function to free a record set and its associated memory
void freeRecordSet(struct RecordSet *recordSet) {
    if (recordSet) {
        // Free the offsets, keys, and records arrays
        free(recordSet->offsets);
        free(recordSet->keys);
        free(recordSet->records);

        // Free the record set struct itself
        free(recordSet);
    }
}

// Function to add a new record to the set and update the version
void addRecord(struct RecordSet *recordSet, int key, long offset) {
    if (recordSet->numRecords == recordSet->capacity) {
        // If the capacity is reached, double it
        size_t newCapacity = recordSet->capacity * 2;
        recordSet->offsets = realloc(recordSet->offsets, newCapacity);
        recordSet->keys = realloc(recordSet->keys, newCapacity);
        recordSet->records = realloc(recordSet->records, newCapacity);

        // Update the capacity and resize the arrays
        recordSet->capacity = newCapacity;
    }

    // Set the offset for the new record
    recordSet->offsets[recordSet->numRecords] = offset;

    // Set the key for the new record
    recordSet->keys[recordSet->numRecords] = key;

    // Increment the number of records
    recordSet->numRecords++;

    // Update the version to indicate a change has been made
    recordSet->version++;
}

// Function to remove a record from the set and update the version
void removeRecord(struct RecordSet *recordSet, int key) {
    // Find the index of the record with the given key
    size_t index = 0;
    while (index < recordSet->numRecords && recordSet->keys[index] != key) {
        index++;
    }

    // If the record was found, remove it by shifting all records after it down by one
    if (index < recordSet->numRecords) {
        for (size_t i = index; i < recordSet->numRecords - 1; i++) {
            recordSet->offsets[i] = recordSet->offsets[i + 1];
            recordSet->keys[i] = recordSet->keys[i + 1];
        }

        // Decrement the number of records and update the version
        recordSet->numRecords--;
        recordSet->version++;
    }
}

// Function to merge two sets of records into one set without causing excessive memory fragmentation or performance degradation
void mergeRecordSets(struct RecordSet *recordSet1, struct RecordSet *recordSet2) {
    // If either set is empty, return early
    if (recordSet1->numRecords == 0 || recordSet2->numRecords == 0) {
        return;
    }

    // Allocate a new set with the sum of both sets' capacities
    size_t capacity = recordSet1->capacity + recordSet2->capacity;
    struct RecordSet *newRecordSet = allocateRecordSet(capacity);

    // Copy the records from both sets into the new set
    for (size_t i = 0; i < recordSet1->numRecords; i++) {
        addRecord(newRecordSet, recordSet1->keys[i], recordSet1->offsets[i]);
    }

    for (size_t i = 0; i < recordSet2->numRecords; i++) {
        addRecord(newRecordSet, recordSet2->keys[i], recordSet2->offsets[i]);
    }

    // Free the old sets and replace them with the new one
    freeRecordSet(recordSet1);
    freeRecordSet(recordSet2);

    *recordSet1 = *newRecordSet;
}

// Function to serialize a record set into a binary format
void serializeRecordSet(struct RecordSet *recordSet, FILE *file) {
    // Write the version number to the file
    fwrite(&recordSet->version, sizeof(unsigned long), 1, file);

    // Write the number of records in the set to the file
    size_t numRecords = recordSet->numRecords;
    fwrite(&numRecords, sizeof(size_t), 1, file);

    // Write each record's offset and key to the file
    for (size_t i = 0; i < numRecords; i++) {
        long offset = recordSet->offsets[i];
        int key = recordSet->keys[i];

        fwrite(&offset, sizeof(long), 1, file);
        fwrite(&key, sizeof(int), 1, file);
    }
}

// Function to deserialize a record set from a binary format
void deserializeRecordSet(struct RecordSet *recordSet, FILE *file) {
    // Read the version number from the file
    fread(&recordSet->version, sizeof(unsigned long), 1, file);

    // Read the number of records in the set from the file
    size_t numRecords;
    fread(&numRecords, sizeof(size_t), 1, file);

    // Set the capacity and version to the deserialized values
    recordSet->capacity = numRecords;
    recordSet->version = recordSet->version;

    // Allocate memory for the offsets and keys
    recordSet->offsets = malloc(numRecords * sizeof(long));
    recordSet->keys = malloc(numRecords * sizeof(int));

    // Read each record's offset and key from the file
    for (size_t i = 0; i < numRecords; i++) {
        long offset;
        int key;

        fread(&offset, sizeof(long), 1, file);
        fread(&key, sizeof(int), 1, file);

        recordSet->offsets[i] = offset;
        recordSet->keys[i] = key;
    }
}
