        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        // Set the value of each record's int field to a random value within a given range
        record->value = rand() % 100;

        (*records)[i] = record;
    }
}

// Define the function to free memory allocated by alloc_memory
void free_memory(long *offset, int *key, Record **records) {
    // Free memory for the offset array
    free(*offset);
    *offset = NULL;

    // Free memory for the key array
