        free((*records)[i]);
    }

    free(*records);
    *records = NULL;
}

// Define the function to handle concurrent access safely without data corruption or race conditions
void concurrent_access(long *offset, int *key, Record **records) {
    // Implement a mechanism to lock the memory allocated by alloc_memory
    pthread_mutex_lock(&memory_mutex);

    // Perform operations on the memory allocated by alloc_memory
    for (int i = 0; i < 1000; i++) {
        Record *record = (*records)[i];
        record->value = rand() % 100;
    }

    // Unlock the memory allocated by alloc_memory
    pthread_mutex_unlock(&memory_mutex);
}

int main(void) {
    long *offset;
    int *key;
    Record **records;

    // Initialize the memory for the arrays
    alloc_memory(&offset, &key, &records);

    // Perform concurrent access on the memory allocated by alloc_memory
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, concurrent_access, offset, key, records);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated by alloc_memory
    free_memory(&offset, &key, &records);

    return 0;
}
