// Define a structure for the node data
typedef struct Node {
    int value;
    struct Node* next;
    // Additional metadata fields
} Node;

// Define a function to initialize and populate the linked list
Node* initList(int minVal, int maxVal, bool circular, bool freeMem) {
    // Allocate memory for the head node
    Node* head = (Node*) malloc(sizeof(Node));
    if (!head) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize the head node with a random value within the specified range
    head->value = rand() % (maxVal - minVal + 1) + minVal;
    head->next = NULL;

    Node* curr = head;
    for (int i = 0; i < maxVal; ++i) {
        // Allocate memory for the next node
        Node* newNode = (Node*) malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            break;
        }

        // Initialize the next node with a random value within the specified range
        newNode->value = rand() % (maxVal - minVal + 1) + minVal;
        newNode->next = NULL;

        // Add the new node to the list
        curr->next = newNode;
        curr = curr->next;
    }

    if (circular) {
        head->next = head;
    }

    if (!freeMem) {
        return head;
    } else {
        free(head);
        return NULL;
    }
}

// Define a function to print the linked list
void printList(Node* head) {
    Node* curr = head;
    while (curr != NULL) {
        printf("%d ", curr->value);
        curr = curr->next;
    }
    printf("\n");
}

// Define a function to free the allocated memory for the linked list
void freeList(Node* head) {
    Node* curr = head;
    while (curr != NULL) {
        Node* temp = curr->next;
        free(curr);
        curr = temp;
    }
}

int main() {
    // Initialize and populate the linked list with random values
    int minVal = 10, maxVal = 20;
    bool circular = false, freeMem = true;
    Node* head = initList(minVal, maxVal, circular, freeMem);
    if (head == NULL) {
        fprintf(stderr, "Error: Initialization failed\n");
        return 1;
    }

    // Print the linked list
    printList(head);

    // Free the allocated memory for the linked list
    freeList(head);

    return 0;
}
