using System;
using UnityEngine;

public class DataProcessor
{
    private readonly long[] _offsetValues;
    private readonly int[] _keyValues;
    private readonly Node[] _nodeStructures;

    public DataProcessor(string inputFilePath)
    {
        // Read initial values for the offset and key arrays from the provided file.
        // If any of the values are invalid or missing, use default values.
        try
        {
            var inputValues = File.ReadAllLines(inputFilePath);
            _offsetValues = new long[inputValues.Length];
            _keyValues = new int[inputValues.Length];

            for (var i = 0; i < inputValues.Length; i++)
            {
                var inputValue = inputValues[i];
                if (string.IsNullOrEmpty(inputValue))
                {
                    _offsetValues[i] = long.MinValue;
                    _keyValues[i] = int.MinValue;
                }
                else
                {
                    _offsetValues[i] = long.Parse(inputValue);
                    _keyValues[i] = (int)_offsetValues[i];
                }
            }
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error reading input file: {e.Message}");
            _offsetValues = new long[0];
            _keyValues = new int[0];
        }

        // Dynamically allocate and initialize memory for the node structures.
        var numNodes = _keyValues.Length;
        _nodeStructures = new Node[numNodes];
        for (var i = 0; i < numNodes; i++)
        {
            _nodeStructures[i] = new Node(_keyValues[i], null);
        }
    }

    // Generate a random float value within the specified range.
    public static float GenerateRandomFloat(float minValue, float maxValue)
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    // Generate a random integer value within the specified range.
    public static int GenerateRandomInt(int minValue, int maxValue)
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    // Return an array containing the current offset values.
    public long[] GetOffsetValues()
    {
        return _offsetValues;
    }

    // Return an array containing the current key values.
    public int[] GetKeyValues()
    {
        return _keyValues;
    }

    // Return an array containing the current node structures.
