// Initialize an empty record map
RecordMap* initialize_record_map() {
    RecordMap* map = (RecordMap*)malloc(sizeof(RecordMap));
    if (!map) {
        printf("Failed to allocate memory for record map\n");
        return NULL;
    }
    map->records = NULL;
    map->num_records = 0;
    return map;
}

// Add a new record to the record map
void add_record(RecordMap* map, char* key, void* data) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        printf("Failed to allocate memory for record\n");
        return;
    }
    record->data = (char*)malloc(sizeof(char)*strlen(key));
    strcpy(record->data, key);
    record->size = strlen(key);
    map->records = realloc(map->records, (map->num_records+1)*sizeof(Record));
    if (!map->records) {
        printf("Failed to allocate memory for records\n");
        return;
    }
    map->records[map->num_records] = record;
    map->num_records++;
}

// Get a record from the record map by key
Record* get_record(RecordMap* map, char* key) {
    for (int i=0; i<map->num_records; i++) {
        if (strcmp(map->records[i]->data, key) == 0) {
            return map->records[i];
        }
    }
    return NULL;
}

// Serialize a record to the binary format
void serialize_record(Record* record, char** buffer) {
    size_t data_size = strlen(record->data);
    *buffer = (char*)malloc(sizeof(char)*(data_size+1));
    if (!*buffer) {
        printf("Failed to allocate memory for serialized record\n");
        return;
    }
    memcpy(*buffer, record->data, data_size);
    (*buffer)[data_size] = '\0';
}

// Deserialize a record from the binary format
void deserialize_record(char* buffer, size_t size, Record** record) {
    *record = (Record*)malloc(sizeof(Record));
    if (!*record) {
        printf("Failed to allocate memory for deserialized record\n");
        return;
    }
    (*record)->data = (char*)malloc(size);
    memcpy((*record)->data, buffer, size);
    (*record)->size = size;
}
```
