// Struct to represent a node in the array
typedef struct {
  int value;
  char* string;
} Node;

// Function to generate a random password with specified length
char* generatePassword(int length) {
  char* password = malloc(length + 1);
  for (int i = 0; i < length; ++i) {
    password[i] = 'A' + rand() % ('z' - 'A' + 1);
  }
  password[length] = '\0';
  return password;
}

// Function to generate an IV for CBC mode encryption
char* generateIV(int length) {
  char* iv = malloc(length);
  RAND_bytes((unsigned char*)iv, length);
  return iv;
}

// Function to encrypt a string using AES-CBC and PKCS7 padding
void encryptString(const char* plaintext, const char* password, char** ciphertext) {
  // Generate a random IV for CBC mode encryption
  char* iv = generateIV(16);

  // Encrypt the string using AES-CBC with PKCS7 padding
  EVP_CIPHER_CTX* ctx;
  int len = strlen(plaintext);
  unsigned char* cipher = malloc((len + 1) * sizeof(unsigned char));
  size_t cipherLen, blockSize;

  // Initialize the encryption context
  EVP_EncryptInit(&ctx, EVP_aes_256_cbc(), NULL, password);
  EVP_CIPHER_CTX_set_padding(ctx, EVP_CIPH_PKCS7_PADDING);

  // Encrypt the plaintext string and get the ciphertext length
  EVP_EncryptUpdate(&ctx, cipher, &cipherLen, (unsigned char*)plaintext, len);

  // Get the block size of the encryption algorithm
  blockSize = EVP_CIPHER_CTX_block_size(ctx);

  // Pad the plaintext string with PKCS7 padding
  unsigned char* paddedPlaintext = malloc((len + blockSize) * sizeof(unsigned char));
  memset(paddedPlaintext, 0x10, len);
  memcpy(paddedPlaintext + len, (unsigned char*)plaintext, len);

  // Encrypt the padded plaintext string and get the final ciphertext length
  EVP_EncryptUpdate(&ctx, cipher, &cipherLen, paddedPlaintext, len + blockSize);

  // Get the IV for CBC mode encryption
  unsigned char* iv = malloc(16 * sizeof(unsigned char));
  memcpy(iv, EVP_CIPHER_CTX_iv_noconst(ctx), 16);

  // Free the encryption context and other memory allocations
  EVP_EncryptFree(&ctx);
  free(paddedPlaintext);

  // Return the ciphertext string and IV as a single malloc'd buffer
  *ciphertext = malloc((cipherLen + 16) * sizeof(unsigned char));
  memcpy(*ciphertext, iv, 16);
  memcpy(*ciphertext + 16, cipher, cipherLen);
}

// Function to decrypt a string using AES-CBC and PKCS7 padding
void decryptString(const char* ciphertext, const char* password, char** plaintext) {
  // Get the IV for CBC mode encryption
  unsigned char* iv = malloc(16 * sizeof(unsigned char));
  memcpy(iv, ciphertext, 16);

  // Decrypt the ciphertext string using AES-CBC with PKCS7 padding
  EVP_CIPHER_CTX* ctx;
  int len = strlen(ciphertext) - 16;
  unsigned char* plain = malloc((len + 1) * sizeof(unsigned char));
  size_t plainLen, blockSize;

  // Initialize the decryption context
  EVP_DecryptInit(&ctx, EVP_aes_256_cbc(), NULL, password);
  EVP_CIPHER_CTX_set_padding(ctx, EVP_CIPH_PKCS7_PADDING);

  // Decrypt the ciphertext string and get the plaintext length
  EVP_DecryptUpdate(&ctx, plain, &plainLen, (unsigned char*)ciphertext + 16, len);

  // Get the block size of the decryption algorithm
  blockSize = EVP_CIPHER_CTX_block_size(ctx);

  // Unpad the plaintext string with PKCS7 padding
  unsigned char* unpaddedPlaintext = malloc((plainLen + blockSize) * sizeof(unsigned char));
  memset(unpaddedPlaintext, 0x10, plainLen);
  memcpy(unpaddedPlaintext + plainLen, (unsigned char*)plain, plainLen);

  // Decrypt the unpadded plaintext string and get the final plaintext length
  EVP_DecryptUpdate(&ctx, plain, &plainLen, unpaddedPlaintext, plainLen + blockSize);

  // Free the decryption context and other memory allocations
  EVP_DecryptFree(&ctx);
  free(unpaddedPlaintext);

  // Return the plaintext string as a malloc'd buffer
  *plaintext = malloc((plainLen + 1) * sizeof(unsigned char));
  memcpy(*plaintext, (char*)plain, plainLen);
}
