        int id = MIN_ID + rand() % (MAX_ID - MIN_ID);
        char label = LABELS[rand() % strlen(LABELS)];

        // Store the generated values in the corresponding fields of the sensor data structure
        sensors[i].coord = coord;
        sensors[i].id = id;
        sensors[i].label = label;
    }
}

// Define a function to safely free an array of sensors
void free_sensors(sensor_data_t *sensors) {
    if (sensors != NULL) {
        free(sensors);
        sensors = NULL;
    }
}

int main() {
