double parseDouble(char* str) {
    // Parse double value from string
    char* endptr = NULL;
    double value = strtod(str, &endptr);
    if (endptr == str || *endptr != '\0') {
        printf("Invalid double value: %s\n", str);
        return 0.0;
    }
    return value;
}

// Function to parse a label from a string
char* parseLabel(char* str) {
    // Find start of label
    char* start = strchr(str, '(');
    if (start == NULL) {
        printf("Invalid label format: %s\n", str);
        return "";
    }
    start++;

    // Find end of label
    char* end = strrchr(start, ')');
    if (end == NULL) {
        printf("Invalid label format: %s\n", str);
        return "";
    }

    // Create new string for label
    int length = end - start;
    char* label = malloc(sizeof(char) * (length + 1));
    strncpy(label, start, length);
    label[length] = '\0';

    return label;
}

// Function to print usage information for the program
void printUsageInformation() {
