typedef struct sensor_data {
    float temperature;
    double time;
    char* sensor_id;
} sensor_data_t;

void init_sensor_data(int num_sensors, int num_records, sensor_data_t** data) {
    // Allocate memory for the two arrays of temperature values and sensor IDs.
    float* temperatures = malloc(num_sensors * sizeof(float));
    char** sensor_ids = malloc(num_sensors * sizeof(char*));

    if (temperatures == NULL || sensor_ids == NULL) {
        // Handle memory allocation failure.
        printf("Error: failed to allocate memory for sensor data.\n");
        return;
    }

    for (int i = 0; i < num_sensors; i++) {
        temperatures[i] = rand() % 100;
        sensor_ids[i] = malloc(10 * sizeof(char));
        snprintf(sensor_ids[i], 10, "Sensor %d", i + 1);
    }

    // Allocate memory for the array of 'sensor_data' structures.
    *data = calloc(num_records, sizeof(sensor_data_t));

    if (*data == NULL) {
        // Handle memory allocation failure.
        printf("Error: failed to allocate memory for sensor data.\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        (*data)[i].temperature = temperatures[rand() % num_sensors];
        (*data)[i].time = rand() % 10000;
        (*data)[i].sensor_id = sensor_ids[rand() % num_sensors];
    }
}

void update_sensor_data(int num_records, sensor_data_t** data) {
    // Update the temperature values and time stamps in the 'sensor_data' structures.
    for (int i = 0; i < num_records; i++) {
        (*data)[i].temperature += rand() % 10 - 5;
        (*data)[i].time += rand() % 1000;
    }
}

void free_sensor_data(int num_sensors, int num_records, sensor_data_t** data) {
    // Free the memory allocated for the two arrays of temperature values and sensor IDs.
    for (int i = 0; i < num_sensors; i++) {
        free((*data)[i].sensor_id);
    }

    free(*data);
}
