```C
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int key;
    char* description;
} record;

void init_records(int size, long seed, bool use_fixed_seed) {
    // Allocate memory for the arrays
    long* offset_array = (long*)malloc(size * sizeof(long));
    int* key_array = (int*)malloc(size * sizeof(int));
    record* record_array = (record*)malloc(size * sizeof(record));
    char** description_array = (char**)malloc(size * sizeof(char*));
    long* timestamp_array = (long*)malloc(size * sizeof(long));

    if (!offset_array || !key_array || !record_array || !description_array || !timestamp_array) {
        // Memory allocation failed, print an error message and exit gracefully.
        fprintf(stderr, "Error: Failed to allocate memory for arrays.\n");
        exit(1);
    }

    // Initialize the arrays with random values based on the seed value.
    srand(seed);
    for (int i = 0; i < size; ++i) {
        offset_array[i] = rand() % 100 + 1;
        key_array[i] = rand() % 100 + 1;
        record_array[i].key = rand() % 100 + 1;
        description_array[i] = malloc(1024 * sizeof(char));
        strcpy(description_array[i], "This is a random description.");
        if (use_fixed_seed) {
            timestamp_array[i] = seed;
        } else {
            timestamp_array[i] = time(NULL);
        }
    }

    // Free allocated memory when the function is done with it.
    free(offset_array);
    free(key_array);
    for (int i = 0; i < size; ++i) {
        free(description_array[i]);
    }
    free(record_array);
    free(timestamp_array);
}
