    for (int i = 0; i < 1000; i++) {
        coordinates[i] = RAND_FLOAT(-100.0, 100.0);
        ids[i] = RAND_INT(1, 100);
        labels[i] = RAND_CHAR_SET("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ");
