        printf("Error: unable to allocate memory for records\n");
        free(array);
        return NULL;
    }

    // Zero-initialize the records
    memset(array->records, 0, size * sizeof(Record));

    // Set the array's count and capacity
    array->count = 0;
    array->capacity = size;

    return array;
}

// Define the function to add a new record to the array
void array_add(Array *array, int id, char *name, double value) {
    // Check if the array is full
    if (array->count == array->capacity) {
        printf("Error: unable to add record to array\n");
        return;
    }

    // Add the new record
    Record *record = &(array->records[array->count]);
    record->id = id;
    strcpy(record->name, name);
    record->value = value;
    array->count++;
}

// Define the function to update an existing record in the array
void array_update(Array *array, int id, char *name, double value) {
    // Find the index of the record to update
    size_t i;
    for (i = 0; i < array->count; i++) {
        if (array->records[i].id == id) {
            break;
        }
    }

    // Check if the record was found
    if (i == array->count) {
        printf("Error: unable to find record with ID %d\n", id);
        return;
    }

    // Update the record
    Record *record = &(array->records[i]);
    strcpy(record->name, name);
    record->value = value;
}

// Define the function to delete an existing record from the array
void array_delete(Array *array, int id) {
    // Find the index of the record to delete
    size_t i;
    for (i = 0; i < array->count; i++) {
        if (array->records[i].id == id) {
            break;
        }
    }

    // Check if the record was found
    if (i == array->count) {
        printf("Error: unable to find record with ID %d\n", id);
        return;
    }

    // Shift all records after the deleted one
    for (size_t j = i + 1; j < array->count; j++) {
        Record *record = &(array->records[j]);
        record->id--;
        strcpy(record->name, "");
        record->value = 0.0;
    }

    // Decrement the count of records
    array->count--;
}

// Define the function to free all memory allocated for the array
void array_free(Array *array) {
    // Check if the array is valid
    if (array == NULL || array->records == NULL) {
        return;
    }

    // Free the memory allocated for the records
    free(array->records);
    array->records = NULL;

    // Zero-initialize the count and capacity of the array
    array->count = 0;
    array->capacity = 0;

    // Free the memory allocated for the array structure
    free(array);
}
```
This function includes several helper functions to allocate, initialize, update, and delete records in an array. It also includes a function to free all memory allocated for the array. The `array_new` function takes a size parameter that determines the capacity of the array. The `array_add` function adds a new record to the end of the array, while the `array_update` function updates an existing record in the array. The `array_delete` function deletes an existing record from the array by shifting all records after it down and decrementing the count of records. The `array_free` function frees all memory allocated for the array.

