['```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define data structures
typedef struct {
    long offset;
    int key;
    float value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
} RecordArray;

// Function to safely allocate memory for a record array
RecordArray* createRecordArray(size_t capacity) {
    // Allocate memory for the array of records
    RecordArray* arr = (RecordArray*) malloc(sizeof(RecordArray));
    if (!arr) {
        return NULL;
    }

    // Allocate memory for the record structs
    arr->records = (Record*) calloc(capacity, sizeof(Record));
    if (!arr->records) {
        free(arr);
        return NULL;
    }

    // Set the capacity and count of the array
    arr->capacity = capacity;
    arr->count = 0;

    return arr;
}

// Function to safely free memory for a record array
void destroyRecordArray(RecordArray* arr) {
    if (arr) {
        // Free the record structs
        free(arr->records);

        // Free the array of records
        free(arr);
    }
}

// Function to add a new record to the end of the array
int addRecord(RecordArray* arr, long offset, int key, float value) {
    if (!arr || arr->count == arr->capacity) {
        return 0;
    }

    // Set the fields of the new record
    Record* record = &arr->records[arr->count];
    record->offset = offset;
    record->key = key;
    record->value = value;

    arr->count++;
    return 1;
}

// Function to update an existing record in the array
int updateRecord(RecordArray* arr, size_t index, long offset, int key, float value) {
    if (!arr || index >= arr->count) {
        return 0;
    }

    // Set the fields of the new record
    Record* record = &arr->records[index];
    record->offset = offset;
    record->key = key;
    record->value = value;

    return 1;
}

// Function to initialize a record array with random values within given ranges
void initRecordArray(RecordArray* arr, long offsetMin, long offsetMax, int keyMin, int keyMax, float valueMin, float valueMax) {
    for (size_t i = 0; i < arr->capacity; i++) {
        Record* record = &arr->records[i];
        record->offset = randomLong(offsetMin, offsetMax);
        record->key = randomInt(keyMin, keyMax);
        record->value = randomFloat(valueMin, valueMax);
    }
}

// Function to generate a random long within a specified range
long randomLong(long min, long max) {
    assert(min <= max);
    return (long)(rand() % (max - min + 1)) + min;
}

// Function to generate a random int within a specified range
int randomInt(int min, int max) {
    assert(min <= max);
    return (int)(rand() % (max - min + 1)) + min;
}

// Function to generate a random float within a specified range
float randomFloat(float min, float max) {
    assert(min <= max);
    return (float)(rand() % (max - min + 1)) + min;
}
