// Structure for sensor data
typedef struct {
    float coordinate;
    int id;
    char label;
} sensor_data;

// Function to dynamically allocate memory for and initialize three arrays:
// one for 'float' coordinates, one for 'int' IDs, and one for 'char' labels.
void allocate_sensor_data(int size) {
    // Allocate memory for the coordinate array
    float *coordinates = (float *)malloc(size * sizeof(float));
    if (!coordinates) {
        fprintf(stderr, "Failed to allocate memory for coordinates\n");
        return;
    }

    // Initialize the coordinate array with random values between -100.0 and 100.0
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        coordinates[i] = ((float)rand() / RAND_MAX) * 200.0 - 100.0;
    }

    // Allocate memory for the ID array
    int *ids = (int *)malloc(size * sizeof(int));
    if (!ids) {
        fprintf(stderr, "Failed to allocate memory for IDs\n");
        free(coordinates);
        return;
    }

    // Initialize the ID array with random values between 1 and 100
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        ids[i] = ((int)rand() % 99) + 1;
    }

    // Allocate memory for the label array
    char *labels = (char *)malloc(size * sizeof(char));
    if (!labels) {
        fprintf(stderr, "Failed to allocate memory for labels\n");
        free(coordinates);
        free(ids);
        return;
    }

    // Initialize the label array with random values from a predefined set of characters
    srand(time(NULL));
    char predefined_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (int i = 0; i < size; i++) {
        labels[i] = predefined_chars[rand() % strlen(predefined_chars)];
    }

    // Allocate memory for the sensor data array
    sensor_data *sensor_data_array = (sensor_data *)malloc(size * sizeof(sensor_data));
    if (!sensor_data_array) {
        fprintf(stderr, "Failed to allocate memory for sensor data\n");
        free(coordinates);
        free(ids);
        free(labels);
        return;
    }

    // Initialize the sensor data array with the values from the coordinate, ID, and label arrays
    for (int i = 0; i < size; i++) {
        sensor_data_array[i].coordinate = coordinates[i];
        sensor_data_array[i].id = ids[i];
        sensor_data_array[i].label = labels[i];
    }
}

// Function to safely free the allocated memory for the three arrays and the sensor data array.
void free_sensor_data(sensor_data *sensor_data_array) {
    if (sensor_data_array != NULL) {
        free(sensor_data_array);
        sensor_data_array = NULL;
    }
}

// Function to safely update the values of the coordinate, ID, and label arrays.
void update_sensor_data(sensor_data *sensor_data_array) {
    // Update the coordinate array with new random values between -100.0 and 100.0
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        sensor_data_array[i].coordinate = ((float)rand() / RAND_MAX) * 200.0 - 100.0;
    }

    // Update the ID array with new random values between 1 and 100
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        sensor_data_array[i].id = ((int)rand() % 99) + 1;
    }

    // Update the label array with new random values from a predefined set of characters
    srand(time(NULL));
    char predefined_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (int i = 0; i < size; i++) {
        sensor_data_array[i].label = predefined_chars[rand() % strlen(predefined_chars)];
    }
}

// Main function to demonstrate the use of the allocate_sensor_data and free_sensor_data functions.
int main() {
    int size = 10;
    sensor_data *sensor_data_array = NULL;

    // Allocate memory for the sensor data array
    allocate_sensor_data(size);

    // Print the values of the coordinate, ID, and label arrays
    printf("Coordinate Array: ");
    for (int i = 0; i < size; i++) {
        printf("%f ", sensor_data_array[i].coordinate);
    }
    printf("\nID Array: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", sensor_data_array[i].id);
    }
    printf("\nLabel Array: ");
    for (int i = 0; i < size; i++) {
        printf("%c ", sensor_data_array[i].label);
    }
    printf("\n");

    // Update the values of the coordinate, ID, and label arrays
    update_sensor_data(sensor_data_array);

    // Print the updated values of the coordinate, ID, and label arrays
    printf("Updated Coordinate Array: ");
    for (int i = 0; i < size; i++) {
        printf("%f ", sensor_data_array[i].coordinate);
