    void *ptr = malloc(size);
    if (!ptr) {
        printf("Error: failed to allocate %zu bytes of memory\n", size);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void *ptr) {
    if (ptr) {
        free(ptr);
    }
}

