    for (size_t i = 0; i < num_items; ++i) {
        // Initialize each item with a random coordinate, id, and label
        items[i].coordinate = (float)rand() / RAND_MAX * 200.0 - 100.0;
        items[i].id = rand() % 100 + 1;
        items[i].label = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"[rand() % 26];
    }
}

// Define the function to update an item
void update_item(item_t *item, size_t index) {
    // Update the coordinate and label of the item at the given index
    item->coordinate = (float)rand() / RAND_MAX * 200.0 - 100.0;
    item->label = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"[rand() % 26];
}

// Define the function to free an item
void free_item(item_t *item) {
    if (item) {
        free(item);
    }
}

// Define the main function
int main() {
    // Set the number of items to be allocated
    size_t num_items = 100;

    // Allocate memory for the arrays
    float *coordinates = allocate_memory(num_items * sizeof(float));
    int *ids = allocate_memory(num_items * sizeof(int));
    char *labels = allocate_memory(num_items * sizeof(char));

    // Initialize the items
    init_items(coordinates, num_items);
    init_items(ids, num_items);
    init_items(labels, num_items);

    // Update an item at a random index
    size_t index = rand() % num_items;
    update_item(&coordinates[index], index);
    update_item(&ids[index], index);
    update_item(&labels[index], index);

    // Free the memory for the arrays
    free_memory(coordinates);
    free_memory(ids);
    free_memory(labels);

    return 0;
}
