```c
#include <stdlib.h>
#include <string.h>

struct record {
    int value;
};

void* initialize_arrays(size_t num_offsets, size_t num_keys, size_t num_records, long offset_range) {
    // Check for negative input values and return NULL if any are found.
    if (num_offsets < 0 || num_keys < 0 || num_records < 0 || offset_range < 0) {
        return NULL;
    }

    // Allocate memory for the arrays.
    long* offsets = malloc(sizeof(long) * num_offsets);
    int* keys = malloc(sizeof(int) * num_keys);
    struct record* records = malloc(sizeof(struct record) * num_records);

    // If memory allocation fails, free any previously allocated memory and return NULL.
    if (offsets == NULL || keys == NULL || records == NULL) {
        if (offsets != NULL) {
            free(offsets);
        }
        if (keys != NULL) {
            free(keys);
        }
        if (records != NULL) {
            free(records);
        }
        return NULL;
    }

    // Initialize the arrays with random values.
    for (size_t i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % offset_range;
    }
    for (size_t i = 0; i < num_keys; i++) {
        keys[i] = rand() % INT_MAX;
    }
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % INT_MAX;
    }

    // Return a pointer to the initialized arrays.
    return records;
}
```
