// Function to generate a random alphanumeric string of length 10
char* get_random_string(void) {
    // Generate a random seed using /dev/urandom
    long rand_seed = -1;
    ssize_t retval = getrandom(&rand_seed, sizeof(long), GRND_RANDOM);
    if (retval < 0) {
        perror("getrandom");
        return NULL;
    }

    // Generate a random alphanumeric string using srand and rand functions
    srand(rand_seed);
    char* random_string = malloc(11 * sizeof(char));
    for (int i = 0; i < 10; ++i) {
        int rand_val = rand() % 26 + 97; // 'a' to 'z' range
        if (rand_val >= 97 && rand_val <= 122) {
            random_string[i] = rand_val;
        } else {
            random_string[i] = rand() % 10 + 48; // '0' to '9' range
        }
    }
    random_string[10] = '\0';

    return random_string;
}

// Function to initialize the arrays of long, int, and record structures
void* init_arrays(int num_records, size_t offset_size, size_t key_size, size_t record_size) {
    if (num_records < 0 || offset_size < 0 || key_size < 0 || record_size < 0) {
        return NULL;
    }

    // Allocate memory for the arrays of long, int, and records structures
    void* array_offset = malloc(num_records * offset_size);
    if (array_offset == NULL) {
        perror("malloc");
        return NULL;
    }
    memset(array_offset, 0, num_records * offset_size);

    void* array_key = malloc(num_records * key_size);
    if (array_key == NULL) {
        perror("malloc");
        free(array_offset);
        return NULL;
    }
    memset(array_key, 0, num_records * key_size);

    void* array_record = malloc(num_records * record_size);
    if (array_record == NULL) {
        perror("malloc");
        free(array_offset);
        free(array_key);
        return NULL;
    }
    memset(array_record, 0, num_records * record_size);

    // Initialize the string in each record to a unique, randomly generated alphanumeric string of length 10
    for (int i = 0; i < num_records; ++i) {
        struct record* rec = (struct record*)((char*)array_record + i * record_size);
        char* random_string = get_random_string();
        if (random_string == NULL) {
            perror("get_random_string");
            free(array_offset);
            free(array_key);
            free(array_record);
            return NULL;
        }
        rec->string = random_string;
    }

    return array_offset;
}
