#include <string.h>
#include <time.h>

// Define the structure for each record
typedef struct {
    int value;
    long offset;
    int key;
} Record;

// Define the metadata structure to link to the records
typedef struct {
    size_t num_records;
    size_t total_memory;
    Record* records;
} Metadata;

void init_data(long max_offset, int max_key, int min_val, int max_val, size_t max_memory) {
    // Allocate memory for the metadata structure
    Metadata* metadata = malloc(sizeof(Metadata));
    if (metadata == NULL) {
        printf("Error: unable to allocate memory for metadata\n");
        return;
    }

    // Initialize the metadata structure
    metadata->num_records = 0;
    metadata->total_memory = 0;
    metadata->records = NULL;

    // Allocate memory for the records
    size_t num_records = (size_t) rand() % max_offset + 1;
    Record* records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: unable to allocate memory for records\n");
        return;
    }

    // Initialize the records with random values within the specified range
    for (size_t i = 0; i < num_records; i++) {
        int value = rand() % (max_val - min_val + 1) + min_val;
        long offset = rand() % max_offset + 1;
        int key = rand() % max_key + 1;
        records[i] = (Record){value, offset, key};
    }

    // Update the metadata structure with the allocated memory and number of records
    metadata->num_records = num_records;
    metadata->total_memory = sizeof(Metadata) + num_records * sizeof(Record);
    metadata->records = records;

    // Check if the total memory allocation exceeds the maximum limit
    if (metadata->total_memory > max_memory) {
        printf("Error: total memory allocation exceeds the maximum limit\n");
        free(metadata);
        return;
    }
}
