    for (size_t i = 0; i < numReadings; ++i) {
        sensorData[i].timestamp = time(NULL);
        sensorData[i].reading = rand() % 1000;
    }

    return sensorData;
}

// Function to append new data to an existing file, without overwriting the existing content
void appendFile(const char* filename, const void* data, size_t size) {
    FILE* logFile = fopen(filename, "a");
    if (logFile == NULL) {
        printf("Error: Failed to open file for writing\n");
        return;
    }

    // Log each initialization step in "sensor_data.log" to help with debugging
    char* line = malloc(size * 2 + 1);
    if (line == NULL) {
        printf("Error: Failed to allocate memory for file line\n");
        fclose(logFile);
        return;
    }
    for (size_t i = 0; i < size; ++i) {
        line[i * 2] = ((char*)data)[i];
        line[i * 2 + 1] = '\n';
    }
    fwrite(line, 1, strlen(line), logFile);
    free(line);

    // Close the file and return
    fclose(logFile);
}
