#include <stdlib.h>
#include <stdio.h>

typedef struct node {
    int value;
    struct node *next;
} node_t;

node_t* init_list(int size) {
    // Allocate memory for the array of nodes
    node_t **nodes = malloc(size * sizeof(node_t*));
    if (!nodes) {
        printf("Error: Insufficient memory to allocate list\n");
        return NULL;
    }

    // Initialize each node in the array with a unique integer value
    for (int i = 0; i < size; i++) {
        nodes[i] = malloc(sizeof(node_t));
        if (!nodes[i]) {
            printf("Error: Insufficient memory to allocate list\n");
            return NULL;
        }
        nodes[i]->value = i + 1;
        nodes[i]->next = NULL;
    }

    // Allocate memory for the linked list of nodes
    node_t *head = malloc(sizeof(node_t));
    if (!head) {
        printf("Error: Insufficient memory to allocate list\n");
        return NULL;
    }
    head->value = 0;
    head->next = NULL;

    // Link the nodes together in a linked list
    for (int i = 1; i < size; i++) {
        nodes[i]->next = nodes[i - 1];
    }

    return head;
}

int insert_node(node_t *head, int position, int value) {
    // Check if the specified position is out of bounds or invalid
    if (position < 0 || position > size) {
        printf("Error: Invalid position to insert node\n");
        return -1;
    }

    // Allocate memory for the new node
    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        printf("Error: Insufficient memory to allocate node\n");
        return -1;
    }

    // Initialize the new node with the specified value
    new_node->value = value;

    // Find the node at the specified position in the linked list
    node_t *curr = head;
    for (int i = 0; i < position - 1; i++) {
        curr = curr->next;
    }

    // Insert the new node after the current node
    new_node->next = curr->next;
    curr->next = new_node;

    return 0;
}
```
This implementation of `init_list` uses a loop to initialize each element in the array of nodes with a unique integer value, and then links them together in a linked list. The function returns the head node of the linked list if successful, or NULL if an error occurs.

