```c
#include <pthread.h>

// Mutex for protecting memory allocation and freeing functions
static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for sensor data
struct SensorData *allocate_sensor_data() {
    struct SensorData *sensor_data = malloc(sizeof(struct SensorData));

    pthread_mutex_lock(&memory_mutex);
    if (sensor_data == NULL) {
        printf("Error: Failed to allocate memory for sensor data.\n");
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }
    pthread_mutex_unlock(&memory_mutex);

    return sensor_data;
}

// Function to initialize sensor data
void initialize_sensor_data(struct SensorData *sensor_data) {
    if (sensor_data == NULL) {
        printf("Error: Invalid argument.\n");
        return;
    }

