            break;
        case HUMIDITY:
            sensor_data->value = fmod(rand() * 20 - 10, 20) + 10; // Generate a random value between 20% and 98%
            break;
    }

    pthread_mutex_unlock(&memory_mutex);
}

// Function to update sensor data
void update_sensor_data(struct SensorData *sensor_data) {
    if (sensor_data == NULL) {
        printf("Error: Invalid argument.\n");
        return;
    }

    pthread_mutex_lock(&memory_mutex);

    switch (sensor_data->type) {
        case TEMPERATURE:
