            break;
    }

    pthread_mutex_unlock(&memory_mutex);
}

// Function to free memory for sensor data
void free_sensor_data(struct SensorData *sensor_data) {
    if (sensor_data == NULL) {
        printf("Error: Invalid argument.\n");
        return;
    }

    pthread_mutex_lock(&memory_mutex);

    free(sensor_data);

    pthread_mutex_unlock(&memory_mutex);
}
```
This code uses a mutex to protect the memory allocation and freeing functions, so that multiple threads can access these functions safely without causing conflicts.

Note that using a mutex can make your program slower because it needs to acquire and release locks, but it is necessary when you have multiple threads accessing shared resources like memory.']

