// Function to check for memory leaks
void check_for_leaks(size_t num_records, size_t num_metadata) {
    // Allocate temporary arrays to hold current and deallocated memory
    struct record* records = malloc(num_records * sizeof(struct record));
    if (!records) {
        return;
    }
    struct metadata* metadata = malloc(num_metadata * sizeof(struct metadata));
    if (!metadata) {
        free(records);
        return;
    }

    // Compare current memory allocation with deallocated memory
    size_t curr_mem = (num_records + num_metadata) * sizeof(struct record) + (num_metadata) * sizeof(struct metadata);
    size_t dealloc_mem = 0;
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value != INT_MAX) {
            dealloc_mem += sizeof(struct record);
        }
        if (metadata[i].index != SIZE_MAX) {
            dealloc_mem += sizeof(struct metadata);
        }
    }

    // Print warning message if there are memory leaks
    if (curr_mem > dealloc_mem) {
        printf("Possible memory leak detected!\n");
    } else {
        printf("Memory management is correct.\n");
    }

    free(records);
    free(metadata);
}
