    if (index >= num_sensors) {
        return;
    }

    // Update the temperature, pressure, and humidity values for the specified sensor
    sensors[index].temperature = temperature;
    sensors[index].pressure = pressure;
    sensors[index].humidity = humidity;
}

// Function to free memory allocated for sensor data structures
void free_sensors(void) {
    // Free the memory allocated for the sensor data structures
    if (sensors) {
        free(sensors);
    }

    // Reset the number of sensors to zero
    num_sensors = 0;
}

