// Function to dynamically allocate memory for arrays of long, int, and double precision values
void allocDataPoints(long** offsetArray, int** keyArray, double** valueArray, int numPoints) {
    // Allocate memory for offset array
    *offsetArray = (long*)malloc(numPoints * sizeof(long));
    if (*offsetArray == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        exit(1);
    }

    // Initialize offset array with default values
    for (int i = 0; i < numPoints; i++) {
        (*offsetArray)[i] = 0;
    }

    // Allocate memory for key array
    *keyArray = (int*)malloc(numPoints * sizeof(int));
    if (*keyArray == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        exit(1);
    }

    // Initialize key array with default values
    for (int i = 0; i < numPoints; i++) {
        (*keyArray)[i] = 0;
    }

    // Allocate memory for value array
    *valueArray = (double*)malloc(numPoints * sizeof(double));
    if (*valueArray == NULL) {
        printf("Error: Failed to allocate memory for value array\n");
        exit(1);
    }

    // Initialize value array with default values
    for (int i = 0; i < numPoints; i++) {
        (*valueArray)[i] = 0.0;
    }
}

// Function to initialize data point structures
void initDataPoints(dataPoint** dataPoints, int numPoints) {
    // Allocate memory for array of data points
    *dataPoints = (dataPoint*)malloc(numPoints * sizeof(dataPoint));
    if (*dataPoints == NULL) {
        printf("Error: Failed to allocate memory for data point structures\n");
        exit(1);
    }

    // Initialize each data point structure with default values
    for (int i = 0; i < numPoints; i++) {
        (*dataPoints)[i].key = 0;
        (*dataPoints)[i].value = 0.0;
        (*dataPoints)[i].string = NULL;
    }
}

// Function to update data point structures with new offset values, keys, and double precision values
void updateDataPoints(long* offsetArray, int* keyArray, double* valueArray, int numPoints) {
    // Update each data point structure with the new offset value, key, and double precision value
    for (int i = 0; i < numPoints; i++) {
        (*dataPoints)[i].offset = *offsetArray[i];
        (*dataPoints)[i].key = *keyArray[i];
        (*dataPoints)[i].value = *valueArray[i];
    }
}

// Function to free memory for arrays of long, int, and double precision values
void freeDataPoints(long* offsetArray, int* keyArray, double* valueArray) {
    // Free memory for offset array
    free(offsetArray);

    // Free memory for key array
    free(keyArray);

    // Free memory for value array
    free(valueArray);
