void manage_records(record* arr, size_t num_records, int min, int max) {
    // Check if the given array of records is NULL or has a zero length
    if (!arr || !num_records) {
        fprintf(stderr, "Error: invalid arguments for managing records\n");
        return;
    }

    // Allocate memory for the array of records and initialize it with default values
