    // Update the existing array of records with the new values
    for (size_t i = 0; i < num_records; ++i) {
        arr[i].value = new_arr[i].value;
        arr[i].offset1 = new_arr[i].offset1;
        arr[i].offset2 = new_arr[i].offset2;
    }

    // Free the memory allocated for the new array of records
    free(new_arr);
