void serialize_records(record* arr, size_t num_records, const char* filename) {
    // Check if the given array of records is NULL or has a zero length
    if (!arr || !num_records) {
        fprintf(stderr, "Error: invalid arguments for serializing records\n");
        return;
    }

    // Open the binary file in write mode
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: failed to open binary file %s for writing\n", filename);
        return;
    }

    // Write the array of records into the binary file
    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&arr[i], sizeof(record), 1, file);
    }

    // Close the binary file
    if (fclose(file)) {
        fprintf(stderr, "Error: failed to close binary file %s\n", filename);
    }
}

