    // Check if the given array of records is NULL or has a zero length
    if (!arr || !num_records) {
        fprintf(stderr, "Error: invalid arguments for deserializing records\n");
        return;
    }

    // Open the binary file in read mode
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: failed to open binary file %s for reading\n", filename);
        return;
    }

    // Read the array of records from the binary file into the given memory location
    size_t bytes_read = 0;
    while (bytes_read < num_records * sizeof(record)) {
        bytes_read += fread(&arr[bytes_read / sizeof(record)], sizeof(record), 1, file);
    }

    // Close the binary file
