```
// Define a function to traverse a DOM tree and return an array of elements that match a given selector
function getElementsBySelector(root, selector) {
    // Create an empty array to store the matched elements
    let elements = [];

    // Recursively traverse the DOM tree starting from the root element
    function traverseDOM(element) {
        // Check if the current element matches the selector
        if (matchesSelector(element, selector)) {
            // Add the matching element to the array of matched elements
            elements.push(element);
        }

        // Recursively traverse the child nodes of the current element
        for (let i = 0; i < element.childNodes.length; ++i) {
            traverseDOM(element.childNodes[i]);
        }
    }

    // Call the recursive function to start traversing the DOM tree
    traverseDOM(root);

    // Return the array of matched elements
    return elements;
}

// Define a function to check if an element matches a given selector
function matchesSelector(element, selector) {
    // Check if the element has the specified tag name
    if (selector.tagName && selector.tagName !== element.tagName.toLowerCase()) {
        return false;
    }

    // Check if the element has the specified class name
    if (selector.className && !element.classList.contains(selector.className)) {
        return false;
    }

    // Check if the element has the specified ID
    if (selector.id && selector.id !== element.id) {
        return false;
    }

    // If all other conditions are met, the element matches the selector
    return true;
}
