// Structures for PDUs and UE IDs
typedef struct {
    int ue_id;
    int rach_config;
} LTE_PHY_RACH_PDU;

typedef struct {
    int key;
    long offset;
} Record;

// Function to generate random values within a given range
int randInt(int min, int max) {
    return min + (rand() % (max - min));
}

// Thread-safe function to add a new PDU to the list
void add_pdu(LTE_PHY_RACH_PDU pdu) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);
    list = realloc(list, (count + 1) * sizeof(Record));
    list[count] = pdu;
    count++;
    pthread_mutex_unlock(&mutex);
}

// Function to initialize the arrays and populate the list of PDUs
void init_pdu(int num_ues, int num_rach_config) {
    // Initialize the offset array
    offsets = malloc(num_ues * sizeof(long));
    for (int i = 0; i < num_ues; i++) {
        offsets[i] = randInt(1, INT_MAX);
    }

    // Initialize the key array
    keys = malloc(num_rach_config * sizeof(int));
    for (int i = 0; i < num_rach_config; i++) {
        keys[i] = randInt(1, INT_MAX);
    }

    // Initialize the list of PDUs
    list = malloc(sizeof(Record));
    count = 0;

    // Generate random values for the RACH preambles
    for (int i = 0; i < num_ues; i++) {
        LTE_PHY_RACH_PDU pdu;
        pdu.ue_id = i + 1;
        pdu.rach_config = randInt(1, INT_MAX);
        add_pdu(pdu);
    }
}

// Function to handle errors in input parameters and ensure thread safety
void error_handler() {
    // Print an error message if the input parameters are invalid
    printf("Error: Invalid input parameters\n");

    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Clear the list of PDUs and reset the count
    free(list);
    count = 0;

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}

// Function to establish and maintain a connection to a remote address using Java Channel APIs
void establish_connection(char* remote_address) {
    // Initialize the channel with the remote address
    channel = java_channel_open(remote_address, "tcp");

    // Check if the channel was successfully opened
    if (channel == NULL) {
        printf("Error: Failed to establish connection\n");
        return;
    }

    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Add a new record to the list with the channel information
    LTE_PHY_RACH_PDU pdu;
    pdu.channel = channel;
    add_pdu(pdu);

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}

// Function to handle connection state changes efficiently
void handle_connection_state_changes() {
    // Check if the channel is still open
    if (java_channel_is_open(channel)) {
        return;
    }

    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Remove the closed channel from the list
    for (int i = 0; i < count; i++) {
        if (list[i].channel == channel) {
            free(list + i);
            break;
        }
    }

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve UE IDs and RACH configurations dynamically from an external database
int* get_rach_config(int num_rach_config) {
    // Initialize the array with the number of RACH configurations
    int* rach_config = malloc(num_rach_config * sizeof(int));

    // Fill the array with random values from the external database
    for (int i = 0; i < num_rach_config; i++) {
        rach_config[i] = randInt(1, INT_MAX);
    }

    return rach_config;
}

// Function to retrieve UE IDs dynamically from an external database
int* get_ue_ids(int num_ues) {
    // Initialize the array with the number of UE IDs
    int* ue_ids = malloc(num_ues * sizeof(int));

    // Fill the array with random values from the external database
    for (int i = 0; i < num_ues; i++) {
        ue_ids[i] = randInt(1, INT_MAX);
    }

    return ue_ids;
}

// Main function to initialize and populate the list of PDUs
int main(int argc, char** argv) {
    // Check if the input parameters are valid
    if (argc < 3) {
        error_handler();
        return 1;
    }

    // Get the number of UE IDs and RACH configurations from the command line arguments
    int num_ues = atoi(argv[1]);
    int num_rach_config = atoi(argv[2]);

    // Initialize the arrays for the offset and key values
    long* offsets;
    int* keys;

    // Get the UE IDs and RACH configurations from an external database
    int* ue_ids = get_ue_ids(num_ues);
    int* rach_config = get_rach_config(num_rach_config);

    // Initialize the list of PDUs
    init_pdu(num_ues, num_rach_config);

    // Establish a connection to a remote address using Java Channel APIs
    establish_connection("127.0.0.1");

    // Handle connection state changes efficiently
    handle_connection_state_changes();

    return 0;
}
