        records[i].key = rand() % 100 + 1;
    }
}

void free_records(record* records, size_t num_records) {
    // Check if memory deallocation failed
    if (!num_records || !records) {
        return;
    }

    free(records);
}

// Dynamic resizing functions
void resize_records(record** records, size_t* num_records, size_t new_size) {
    // Check if memory reallocation failed
    if (!new_size || !(*num_records)) {
        return;
    }

    record* temp = (record*)realloc(*records, sizeof(record) * new_size);
    if (!temp) {
        return;
    }

    *records = temp;
    *num_records = new_size;
}

// Thread-safe functions
void lock_records(record** records, size_t num_records) {
    // Check if mutex allocation failed
    if (!num_records || !(*records)) {
        return;
    }

    pthread_mutex_lock(&(*records)->mutex);
}

void unlock_records(record** records, size_t num_records) {
    // Check if mutex deallocation failed
    if (!num_records || !(*records)) {
        return;
    }

    pthread_mutex_unlock(&(*records)->mutex);
}

// Caching mechanism
void cache_record(record** records, size_t* num_records) {
    // Check if memory allocation failed
    if (!num_records || !(*records)) {
        return;
    }

    // Cache replacement policy (e.g., LRU)
    *records = realloc(*records, sizeof(record) * (*num_records + 1));
}

