// Define data structures for offset values, keys, and records
typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t num_records;
} memory_management_context;

// Define functions to manage the lifecycle of allocated resources
void initialize_memory_management_context(memory_management_context* ctx, size_t num_offsets, size_t num_keys) {
    assert(ctx != NULL);
    ctx->num_records = 0;
    ctx->offsets = malloc(sizeof(long) * num_offsets);
    if (ctx->offsets == NULL) {
        perror("malloc");
        exit(1);
    }
    memset(ctx->offsets, 0, sizeof(long) * num_offsets);
    ctx->keys = malloc(sizeof(int) * num_keys);
    if (ctx->keys == NULL) {
        perror("malloc");
        exit(1);
    }
    memset(ctx->keys, 0, sizeof(int) * num_keys);
}

void free_memory_management_context(memory_management_context* ctx) {
    assert(ctx != NULL);
    if (ctx->offsets != NULL) {
        free(ctx->offsets);
    }
    if (ctx->keys != NULL) {
        free(ctx->keys);
    }
    if (ctx->records != NULL) {
        for (size_t i = 0; i < ctx->num_records; i++) {
            record* rec = ctx->records[i];
            if (rec != NULL) {
                free(rec);
            }
        }
        free(ctx->records);
    }
}

void update_memory_management_context(memory_management_context* ctx, size_t num_records) {
    assert(ctx != NULL);
    if (num_records > ctx->num_records) {
        // reallocate memory for records
        ctx->records = realloc(ctx->records, sizeof(record*) * num_records);
        if (ctx->records == NULL) {
            perror("realloc");
            exit(1);
        }
        memset(ctx->records + ctx->num_records, 0, sizeof(record*) * (num_records - ctx->num_records));
    }
    ctx->num_records = num_records;
}

