        fprintf(stderr, "Invalid number of sensors: %d\n", numSensors);
        return;
    }

    // Update the sensor data structure with new values within specified ranges
    for (int i = 0; i < numSensors; i++) {
        SensorData* current = head;
        while (current != NULL) {
            if (i < MAX_SENSORS) {
                // Generate random values for coordinates, IDs, and labels within specified ranges
                for (int j = 0; j < 3; j++) {
                    current->coordinates[j] = ((float)rand() / RAND_MAX) * 200.0 - 100.0;
