 */
void freeSensorData() {
    // Acquire the mutex lock to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for each sensor data structure
    SensorData* current = head;
    while (current != NULL) {
        free(current);
        current = current->next;
    }

    // Release the mutex lock
