        records[i].value = (rand() % MAX_VALUE) / 10.0 - 5.0;
    }

    // Return the initialized records
    return records;
}

// Safe memory allocation for records
struct Record* safeAllocRecords(int num_records, struct Record** old_records) {
    // Ensure that the number of records is reasonable and does not exceed the maximum allowed
    if (num_records < 0 || num_records > MAX_RECORDS) {
        return NULL;
    }

    // Allocate memory for the new records
    struct Record* new_records = malloc(sizeof(struct Record) * num_records);
    if (!new_records) {
        printf("Error: Failed to allocate memory for %d records\n", num_records);
        return NULL;
    }

    // Initialize the new records with random values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        new_records[i].offset = rand() % MAX_OFFSET + MIN_OFFSET;
        new_records[i].key = rand() % MAX_KEY + MIN_KEY;
        new_records[i].value = (rand() % MAX_VALUE) / 10.0 - 5.0;
    }

    // Free the old records if they exist
    if (*old_records) {
        free(*old_records);
    }

    // Update the pointer to point to the new records
    *old_records = new_records;

    return new_records;
}

// Safe memory deallocation for records
void safeFreeRecords(struct Record** old_records) {
    if (*old_records) {
        free(*old_records);
        *old_records = NULL;
    }
}

