    int key;
    long offset;
} Record;

// Define the hash table for storing records with unique keys
static HashTable* records = NULL;

// Function to allocate and initialize memory for the three arrays
void init_arrays(int num_keys, int range_min, int range_max) {
    // Allocate memory for each array based on the size of the input
    long** offset_arr = (long**)malloc(num_keys * sizeof(long*));
    int** key_arr = (int**)malloc(num_keys * sizeof(int*));
    Record** record_arr = (Record**)malloc(num_keys * sizeof(Record*));

    // Initialize each element with a random integer value within the given range
    for (int i = 0; i < num_keys; ++i) {
        offset_arr[i] = (long*)malloc(sizeof(long));
        key_arr[i] = (int*)malloc(sizeof(int));
        record_arr[i] = (Record*)malloc(sizeof(Record));

        // Generate a random integer value within the given range
        int val = rand() % (range_max - range_min + 1) + range_min;

        // Set the key and offset values for each record
        key_arr[i][0] = i;
        offset_arr[i][0] = val;
        record_arr[i][0].key = i;
        record_arr[i][0].offset = val;
    }

    // Initialize the hash table for storing records with unique keys
    records = (HashTable*)malloc(sizeof(HashTable));
    hash_table_init(records, num_keys);

    // Add each record to the hash table
    for (int i = 0; i < num_keys; ++i) {
        hash_table_insert(records, key_arr[i], record_arr[i]);
    }
}

// Function to free the memory allocated for the three arrays
void free_arrays() {
    // Free the memory allocated for each array
    free(offset_arr);
    free(key_arr);
    free(record_arr);

    // Free the memory allocated for the hash table
    hash_table_free(records);
}

// Function to sort the records based on their keys in ascending order
void sort_records() {
    // Sort the records based on their keys using quicksort algorithm
    quicksort(record_arr, 0, num_keys - 1);
}

// Function to print the contents of the records in a human-readable format
void print_records() {
    // Print the contents of each record in a human-readable format
    for (int i = 0; i < num_keys; ++i) {
        printf("Record %d: key=%d, offset=%ld\n", i, key_arr[i][0], offset_arr[i][0]);
    }
}
```
In this implementation, the `init_arrays` function allocates memory for each array based on the size of the input and initializes each element with a random integer value within the given range. The `free_arrays` function frees the memory allocated for each array. The `sort_records` function sorts the records based on their keys using the quicksort algorithm, and the `print_records` function prints the contents of each record in a human-readable format.

The `hash_table_init` and `hash_table_insert` functions are used to initialize and add records to the hash table, respectively. The `hash_table_free` function is used to free the memory allocated for the hash table.

