// Defines the structure of a record in the collection
typedef struct {
    int value;
} Record;

// Defines the structure of an offset value in the collection
typedef long OffsetValue;

// Defines the structure of a key value in the collection
typedef int KeyValue;

// Defines the structure of a cache entry in the collection
typedef struct {
    Record* records;
    OffsetValue* offset_values;
    KeyValue* keys;
} CacheEntry;

// Represents the cache of previously allocated memory blocks
CacheEntry* cache = NULL;

// The number of entries in the cache
int cache_size = 0;

// Initializes a new collection with the given number of records
void initializeCollection(int num_records) {
    // Allocate memory for the record array
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    assert(records != NULL);

    // Allocate memory for the offset value array
    OffsetValue* offset_values = (OffsetValue*)malloc(2 * num_records * sizeof(OffsetValue));
    assert(offset_values != NULL);

    // Allocate memory for the key value array
    KeyValue* keys = (KeyValue*)malloc(num_records * sizeof(KeyValue));
    assert(keys != NULL);

    // Initialize the record values to random integers within a given range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
    }

    // Set the offset values to be within valid bounds
    for (int i = 0; i < num_records; i++) {
        offset_values[2 * i] = rand() % 1000;
        offset_values[(2 * i) + 1] = offset_values[2 * i];
    }

    // Set the key values to be unique and within a specified range
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 500;
        while (keys[i] == keys[i - 1]) {
            keys[i]++;
        }
    }

    // Create a new cache entry and store the allocated memory
    CacheEntry* entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    assert(entry != NULL);
    entry->records = records;
    entry->offset_values = offset_values;
    entry->keys = keys;

    // Add the new cache entry to the cache
    cache[cache_size++] = entry;
}

// Frees all memory associated with the collection
void freeCollection() {
    for (int i = 0; i < cache_size; i++) {
        CacheEntry* entry = cache[i];
        free(entry->records);
        free(entry->offset_values);
        free(entry->keys);
        free(entry);
    }
}
```
